  [4449] = {
    'Eingesperrt!',
    {'Tötet 8 Geologen der Dunkeleisenzwerge und bringt der Person, die im Plumpsklo in der Sengenden Schlucht eingesperrt ist, 15 Stücke Seidenstoff.', },
    {'Tötet 8 Geologen der Dunkeleisenzwerge und bringt der Person, die im Plumpsklo in der Sengenden Schlucht eingesperrt ist, 15 Stücke Seidenstoff.', },
  },
  [4450] = {
    'Geschäftsbuch aus Tanaris',
    {'Ach, wisst Ihr was? Da fällt mir grade was ein.|n|nWo ich doch immer noch hier drin festsitz: Wollt Ihr nich\' vielleicht \'n kleinen Job für mich fertig machen, den ich angenommen hab, als ich in Tanaris war? Is\' auch ganz einfach... na ja, wenn man nich\' grade hier drin sitzt, jedenfalls.|n|nKrinkle Goldstahl in Gadgetzan war scharf auf so\'n paar Sachen, die hier in der Sengenden Schlucht und an \'n paar anderen Orten gefunden wurden. Vielleicht könnt Ihr Euch ja die Liste einmal ansehen und ihm den Kram dann bringen?|n|nIch schieb Euch sein Geschäftsbuch unter der Tür durch, wenn Ihr interessiert seid. Bringt es ihm zusammen mit dem Zeug, das er will, nachdem Ihr den ganzen Kram eingesammelt habt.', },
    {'Nehmt die Abschrift von Goldstahls Geschäftsbuch und beschafft Euch dann die darin aufgeführten Gegenstände, ehe Ihr Krinkle Goldstahl in Tanaris aufsucht.', },
  },
  [4451] = {
    'Der Schlüssel zur Freiheit',
    {'Der kleine Messingschlüssel sieht recht einfach aus. Das Einzige, was ihn von anderen seiner Art unterscheidet, sind einige Worte, die darauf eingeritzt sind:|n|n"Dunkeleisenplumpsklo - Nicht duplizieren."|n|nIhr habt absolut keine Ahnung, was das heißen soll oder wofür der Schlüssel gut ist.', },
    {'Sucht in der Sengenden Schlucht, bis Ihr etwas findet, wofür man den Schlüssel für Rußschlacks Schuppen verwenden kann, den Ihr gefunden habt.', },
  },
