  [7810] = {
    'Meister der Arena',
    {'Um der Meister der Arena zu werden, bedarf es bestimmt noch weiterer Taten! Vielleicht weiß der Pirat, der das Ereignis in Gurubashi veranstaltet, mehr.', },
    {'Begebt Euch in die Arena des Schlingendorntals und sprecht mit Störtebrecher.', },
  },
