  [7905] = {
    'Der Dunkelmond-Jahrmarkt',
    {'Der Dunkelmond-Jahrmarkt kommt! Nehmt an unseren aufregenden Spielen teil, gewinnt fabulöse Preise und erfahrt, wie es um Eure Zukunft steht!|n|nZögert nicht und Ihr werdet diesen Gutschein gegen kostenfreie Gewinnlose und einen der weltberühmten Abenteuerführer des Dunkelmond-Jahrmarkts einlösen können! Mit ihm werdet Ihr die Schätze, die Ihr auf Euren Reisen findet, leicht identifizieren können.|n|nBringt Euren Gutschein einfach zu Gelvas Rußgatter, der sich innerhalb des Jahrmarkts aufhält.|n|nMomentan befindet sich der Zugang zum Jahrmarkt außerhalb von Goldhain im Wald von Elwynn.', },
    {'Bringt den Gutschein zu Gelvas Rußgatter, der sich innerhalb des Dunkelmond-Jahrmarkts aufhält.', },
  },
  [7906] = {
    'Dunkelmond-Karten: Bestien',
    nil,
    nil,
  },
  [7907] = {
    'Bestienkartenset des Dunkelmond-Jahrmarkts',
    {'Jetzt, da Ihr alle Karten des Bestienkartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: "Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden." Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.', },
    {'Gebt das Bestienkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.', },
  },
  [7908] = {
    'Meister der Arena',
    {'Um der Meister der Arena zu werden, bedarf es bestimmt noch weiterer Taten! Vielleicht weiß der Pirat, der das Ereignis in Gurubashi veranstaltet, mehr.', },
    {'Begebt Euch in die Arena des Schlingendorntals und sprecht mit Störtebrecher.', },
  },
