  [7926] = {
    'Der Dunkelmond-Jahrmarkt',
    {'Der Dunkelmond-Jahrmarkt kommt! Nehmt an spannenden Spielen teil, gewinnt fabulöse Preise, lasst Euch Eure Zukunft deuten!|n|nZögert nicht und Ihr werdet diesen Gutschein gegen kostenfreie Gewinnlose und einen der weltberühmten Abenteuerführer des Dunkelmond-Jahrmarkts einlösen können! Mit ihm werdet Ihr die Schätze, die Ihr auf Euren Reisen findet, leicht identifizieren können.|n|nBringt Euren Gutschein einfach zu Gelvas Rußgatter, der sich innerhalb des Jahrmarkts aufhält.|n|nMomentan befindet sich der Zugang zum Jahrmarkt außerhalb von Donnerfels in Mulgore.', },
    {'Bringt den Gutschein zu Gelvas Rußgatter, der sich innerhalb des Dunkelmond-Jahrmarkts aufhält.', },
  },
  [7927] = {
    'Portalkartenset des Dunkelmond-Jahrmarkts',
    {'Jetzt, da Ihr alle Karten des Portalkartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: "Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden." Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.', },
    {'Gebt das Portalkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.', },
  },
  [7928] = {
    'Kriegsfürstenkartenset des Dunkelmond-Jahrmarkts',
    {'Jetzt, da Ihr alle Karten des Kriegsfürstenkartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: "Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden." Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.', },
    {'Gebt das Kriegsfürstenkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.', },
  },
  [7929] = {
    'Elementarkartenset des Dunkelmond-Jahrmarkts',
    {'Jetzt, da Ihr alle Karten des Elementarkartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: "Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden." Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.', },
    {'Gebt das Elementarkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.', },
