  [7937] = {
    'Euer Schicksal erwartet Euch...',
    {'Reist zum Holzfällerlager des Osttals im Wald von Elwynn und sucht nach Eurem Schicksal.', },
    {'Reist zum Holzfällerlager des Osttals im Wald von Elwynn und sucht nach Eurem Schicksal.', },
  },
  [7938] = {
    'Euer Schicksal erwartet Euch...',
    {'"Euer Schicksal erwartet Euch in den Todesminen."|n|nDas Horoskop, das Sayge Euch überreicht hat, fühlt sich beim Berühren leicht warm an. Haltet Ihr es etwas fester in der Hand, so seht Ihr die Todesminen in Westfalls Ruinen von Mondbruch. Beim Fokussieren auf dieses Bild, windet Ihr Euch durch verwinkelte Passagen bis Ihr ein schimmerndes Portal erreicht... eines, das in das Herz der Minen selbst führt. Beim Durchschreiten taucht eine seltsame Truhe aus dem Nichts auf.', },
    {'Reist zu den Todesminen in Westfall und sucht nach Eurem Schicksal.', },
  },
