  [8570] = {
    'Vergangene Bemühungen in der Kriegshymnenschlucht',
    nil,
    nil,
  },
  [8572] = {
    'Schlachtrüstung des Veteranen',
    {'Die Abzeichen, die Ihr für Eure Erfüllung von Kampf-, Logistik- und taktischen Aufträgen für Burg Cenarius erhalten habt, dienen zu weit mehr als der Angeberei, $N.|n|nIhr solltet deren Wert besser zu schätzen wissen. Da Ihr gegenüber unserer Organisation Loyalität bewiesen habt, kann ich Euch bestimmte Ausrüstungsgegenstände anbieten, die wir lediglich für unsere engsten Verbündeten im Austausch gegen diese Abzeichen bereithalten.', },
    {'Bringt 7 cenarische Gefechtsabzeichen, 4 cenarische Versorgungsabzeichen und 4 cenarische Strategieabzeichen zu Vargus auf Burg Cenarius in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius.', },
  },
  [8573] = {
    'Schlachtrüstung des Feldherrn',
    {'Die Abzeichen, die Ihr für Eure Erfüllung von Kampf-, Logistik- und taktischen Aufträgen für Burg Cenarius erhalten habt, dienen zu weit mehr als der Angeberei, $N.|n|nIhr solltet deren Wert besser zu schätzen wissen. Da Ihr gegenüber unserer Organisation Loyalität bewiesen habt, kann ich Euch bestimmte Ausrüstungsgegenstände anbieten, die wir lediglich für unsere engsten Verbündeten im Austausch gegen diese Abzeichen bereithalten.', },
    {'Bringt 15 cenarische Gefechtsabzeichen, 20 cenarische Versorgungsabzeichen, 20 cenarische Strategieabzeichen und 1 Mal des Cenarius zu Vargus auf Burg Cenarius in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen ehrfürchtigen Ruf beim Zirkel des Cenarius.', },
  },
  [8574] = {
    'Schlachtrüstung des Gefolgsmanns',
    {'Die Abzeichen, die Ihr für Eure Erfüllung von Kampf-, Logistik- und taktischen Aufträgen für Windruferin Prachthorn erhalten habt, dienen zu weit mehr als der Angeberei, $N.|n|nIhr solltet deren Wert besser zu schätzen wissen. Da Ihr gegenüber unserer Organisation Loyalität bewiesen habt, kann ich Euch bestimmte Ausrüstungsgegenstände anbieten, die wir lediglich für unsere engsten Verbündeten im Austausch gegen diese Abzeichen bereithalten.', },
    {'Bringt 15 cenarische Gefechtsabzeichen, 20 cenarische Versorgungsabzeichen, 17 cenarische Strategieabzeichen und 1 Mal von Remulos zu Vargus auf Burg Cenarius in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.', },
  },
  [8575] = {
    'Azuregos\' magisches Buch',
    {'Ihr könnt kein einziges Wort in diesem Buch verstehen. Ihr wisst nicht einmal in welcher Sprache es geschrieben wurde!', },
    {'Bringt Azuregos\' magisches Buch zu Narain Pfauentraum in Tanaris.', },
  },
  [8576] = {
    'Übersetzung des Buchs',
    nil,
    nil,
  },
  [8577] = {
    'Stewvul, ehemals allerbester Freund',
    {'Tja, um irgendetwas übersetzen zu können, brauche ich meine Wahrsagerbrille. Unglücklicherweise wurde sie vor einiger Zeit von meinem Ex-\'Besten Freund für immer\', Stewvul gestohlen. Er hat mir mein Herz fünffach gebrochen und mich dann hier verrotten lassen.|n|nMithilfe meiner Kristallkugel konnte ich seinen momentanen Aufenthaltsort einigermaßen genau bestimmen. Er ist entweder am Graumähnenwall im Silberwald oder in irgend so einer Portaldimension in der Scherbenwelt, die \'grad von der brennenden Legion überrannt wird. Schätze, es liegt jetzt an Euch, ihn ausfindig zu machen und mir meine Brille zurückzubringen, $N!', },
    {'Narain Pfauentraum möchte, dass Ihr seinen Ex-\'Besten Freund für immer\' (B.F.F.I.) Stewvul ausfindig macht. Nehmt ihm die gestohlene Wahrsagerbrille ab und bringt sie Narain zurück.', },
  },
  [8578] = {
    'Wahrsagerbrille? Kein Problem!',
    {'<Ihr hört einen erleichterten Seufzer aus der Kiste.>|n|nIhr wollt nur seine Wahrsagerbrille? Großartig! Kein Problem, gebt mir kurz \'ne Minute, um… Hey! Wo zur verdammten…!|n|nEs gibt eine schlechte und eine verdammt schlechte Nachricht. Die Schlechte ist, dass ich die Brille verloren habe. Die viel schlimmere Nachricht ist, ich habe sie letzten Monat beim Herumstreifen im Geschmolzenen Kern irgendwo liegen lassen. Jep, der Geschmolzene Kern... Tja, so etwas passiert. Tschüss!', },
    {'Findet Narains Wahrsagerbrille und bringt sie Narain Pfauentraum in Tanaris.', },
  },
  [8579] = {
    'Sterbliche Helden',
    nil,
    nil,
  },
  [8580] = {
    'Die Horde braucht Feuerblüten!',
    {'Hey, $C! Ja, Ihr da! Es gibt da massenhaft Feuerblüten, die von der Horde für die Vorbereitungen des Krieges von Ahn\'Qiraj benötigt werden. Vielleicht werden sie ja in so nette Dinge verarbeitet, die dann in die Luft gehen? Vielleicht geben sie sie der Allianz aber auch als Treibstoff für ihre Dampfpanzer? Wer weiß? Nicht Pele\'keiki!|n|nPele\'keiki weiß nur eines... er weiß, dass Ihr ihm helfen und einen Haufen Feuerblüten für ihn sammeln werdet! Oder?', },
    {'Bringt 20 Feuerblüten zu Fledermausreiter Pele\'keiki im Tal der Geister in Orgrimmar.', },
  },
  [8581] = {
    'Die Horde braucht mehr Feuerblüten!',
    {'Bringt 20 Feuerblüten zu Fledermausreiter Pele\'keiki im Tal der Geister in Orgrimmar.', },
    {'Bringt 20 Feuerblüten zu Fledermausreiter Pele\'keiki im Tal der Geister in Orgrimmar.', },
  },
  [8582] = {
    'Die Horde braucht lila Lotus!',
    {'Lila Lotus, $C, ist eine Zutat für nicht wenige Tränke, Elixiere und Öle, von denen uns einige im Krieg von Ahn\'Qiraj von Nutzen sein werden. Wir werden eine stattliche Menge dieser Tränke für die Kriegsanstrengungen herstellen müssen. Ich werde zusätzlich noch experimentieren, um weitere Verwendungsmöglichkeiten für lila Lotus zu finden. Allerdings werde ich dafür eine große Anzahl dieser Pflanzen benötigen.|n|nJetzt zu Eurer Aufgabe. Zieht durch die Felder und sammelt so viel lila Lotus ein, wie Ihr könnt. Wärt Ihr dazu in der Lage?', },
    {'Bringt 20 lila Lotus zu Apothekerin Jezel im Tal der Geister in Orgrimmar.', },
  },
  [8583] = {
    'Die Horde braucht mehr lila Lotus!',
    {'Bringt 20 lila Lotus zu Apothekerin Jezel im Tal der Geister in Orgrimmar.', },
    {'Bringt 20 lila Lotus zu Apothekerin Jezel im Tal der Geister in Orgrimmar.', },
  },
  [8584] = {
    'Fragt mich nie nach meinen Angelegenheiten',
    {'Narain Pfauentraum in Tanaris möchte, dass Ihr mit Dirge Schnetzelhack in Gadgetzan sprecht.', },
    {'Narain Pfauentraum in Tanaris möchte, dass Ihr mit Dirge Schnetzelhack in Gadgetzan sprecht.', },
  },
  [8585] = {
    'Die Insel des Schreckens!',
    {'Dirge Schnetzelhack in Tanaris möchte, dass Ihr Lakmaerans Kadaver sowie 20 Chimaeroklenden beschafft.', },
    {'Dirge Schnetzelhack in Tanaris möchte, dass Ihr Lakmaerans Kadaver sowie 20 Chimaeroklenden beschafft.', },
  },
  [8586] = {
    'Dirges abgefahrene Chimaerokkoteletts',
    {'Mein Rezept is fertig! Was ich jetzt von Euch brauche ist Raketentreibstoff und Tiefsteinsalz. Ich kümmere mich um die Gewürze und das Fleisch, das Ihr mir gebracht habt, sorgt für den Rest.|n|nSobald Ihr mir die benötigten Zutaten gebracht habt, könnt Ihr das fertige Hühnchen zu Narain bringen.', },
    {'Dirge Schnetzelhack in Gadgetzan möchte, dass Ihr ihm 20 Einheiten Goblinraketentreibstoff und 20 Einheiten Tiefsteinsalz bringt.', },
  },
  [8587] = {
    'Rückkehr zu Narain',
    {'Ich bin ein Goblin, der sein Wort hält, Kind. Hier ist Euer 500 Pfund-Hühnchen.|n|nWas ein Gnom mit einem 500 Pfund-Hühnchen möchte, werde ich wohl nie verstehen...|n|n<Dirge grummelt etwas Unverständliches.>|n|nWahrscheinlich um darin zu schlafen... schmutzige Gnome...', },
    {'Bringt das 500 Pfund-Hühnchen zu Narain Pfauentraum in Tanaris.', },
  },
  [8588] = {
    'Die Horde braucht schweres Leder!',
    {'Da wir uns gerade auf den bevorstehenden Krieg vorbereiten, wäre es wahrscheinlich das Beste, wenn wir alle benötigten Güter zuerst beschaffen, meint Ihr nicht? Einer der benötigten Vorräte besteht aus schwerem Leder. Wir verwenden es für fast alles, von Verstärkungen bis hin zu Rüstungen und guten alten Planen.|n|nAllerdings brauchen wir erst einmal mehr davon. Das ist Eure Aufgabe, $C. Wetzt Euer Messer und bringt mir ein Bündel schweres Leder. Alles weitere besprechen wir dann.', },
    {'Bringt 10 Einheiten schweres Leder zu Kürschner Jamani im Tal der Geister in Orgrimmar.', },
  },
  [8589] = {
    'Die Horde braucht mehr schweres Leder!',
    {'Bringt 10 Einheiten schweres Leder zu Kürschner Jamani im Tal der Geister in Orgrimmar.', },
    {'Bringt 10 Einheiten schweres Leder zu Kürschner Jamani im Tal der Geister in Orgrimmar.', },
  },
  [8590] = {
    'Die Horde braucht dickes Leder!',
    {'Ich bin froh, dass Ihr darüber mit mir sprechen möchtet, $C. Es sieht ganz so aus, als ob die Vorbereitungen der Horde für den Krieg in Ahn\'Qiraj in vollem Gange sind. Ihr und ich müssen aber noch unseren Teil leisten.|n|nIch wurde mit der Sammlung einer großen Menge dicken Leders beauftragt, das für die Herstellung von allerlei Kriegsmaterialien benötigt wird. Ich brauche Euch, um für mich loszuziehen und mir welches zu besorgen. Ihr würdet Euch Ehre und das Wohlwollen der Horde verdienen können. Würdet Ihr uns also helfen?', },
    {'Bringt 10 Einheiten dickes Leder zu Unteroffizier Umala im Tal der Geister in Orgrimmar.', },
  },
  [8591] = {
    'Die Horde braucht mehr dickes Leder!',
    {'Bringt 10 Einheiten dickes Leder zu Unteroffizier Umala im Tal der Geister in Orgrimmar.', },
    {'Bringt 10 Einheiten dickes Leder zu Unteroffizier Umala im Tal der Geister in Orgrimmar.', },
  },
  [8592] = {
    'Tiara des Orakels',
    {'Die Zwillingsimperatoren... ihr unaufhörliches Flüstern martert langsam meinen Verstand. Sie verhöhnen mich, wissend, dass ich nicht tiefer in ihr Reich vordringen kann, um meinen Bruder Arygos zu retten.|n|nIn meinen Visionen sehe ich ihre monströsen Fratzen, die mit mächtigen Kronen geschmückt sind. Ich werde meine Vergeltung noch bekommen... ich werde diese Symbole der Qirajimacht in solche verwandeln, die unserem Nutzen gerecht werden.|n|nBringt mir die benötigten Bestandteile, $N. Ich werde Euch dafür ein Kopfstück von unvergleichlicher Macht geben.', },
    {'Bringt Vek\'nilashs Reif, 2 Götzen der Weisen, 5 Silberskarabäen und 5 Knochenskarabäen zu Andorgos in Ahn\'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.', },
  },
  [8593] = {
    'Beinkleider des Orakels',
    {'Ihr möchtet Euch also uns gegenüber bewähren, Sterblicher? Nun gut, vielleicht können wir uns ja gegenseitig helfen.|n|nDer uralte Sandwurm, Ouro, ist ein Geschöpf von legendärer Macht. Man sagt, dass er von dem Alten Gott selbst als Gespött des Lebens erschaffen wurde.|n|nSeine Haut ist unnatürlich... dick, fast unbezwingbar und dennoch flexibel, was ihm ermöglicht, sich mit der Geschwindigkeit und Grazie eines kleineren Lebewesens zu bewegen.|n|nBringt mir eine Probe seiner Haut sowie andere geringfügigere Bestandteile und ich werde mächtige Gamaschen für Euch herstellen.', },
    {'Bringt Ouros intakte Haut, 2 Götzen des Lebens, 5 Goldskarabäen und 5 Tonskarabäen zu Kandrostrasz innerhalb von Ahn\'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.', },
  },
  [8594] = {
    'Mantel des Orakels',
    {'Man sagt unter uns, dass die kunstvoll verzierten Schulterpanzerungen, die von den sterblichen Völkern getragen werden, zu Beginn eine Nachahmung von Drachenflügeln werden sollten.|n|nBringt mir die Bindungen, die von den höchsten Anführern der Qiraji getragen werden und ich werde sie in ein Paar Schulterstücke verarbeiten, die furchteinflößender als die Flügel Nefarians selbst sind!', },
    {'Bringt die Befehlsbindungen der Qiraji, 2 Götzen der Wiedergeburt, 5 Silberskarabäen und 5 Elfenbeinskarabäen zu Andorgos in Ahn\'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen neutralen Ruf bei der Brut Nozdormus.', },
  },
  [8595] = {
    'Sterbliche Helden',
    nil,
    nil,
  },
  [8596] = {
    'Fußlappen des Orakels',
    {'Qirajimagie ist sehr stark und uralt. Die mächtigsten Qiraji handhaben Gegenstände, die so machtvoll sind, dass sie sogar einem Drachen Einhalt gebieten.|n|nBringt mir die Befehlsbindungen der Qiraji sowie andere geringfügigere Bestandteile und ich werde ein Paar mächtige Stiefel für Euch herstellen.|n|nIhr werdet sie im Kampf gegen den Feind als nützlich empfinden.', },
    {'Bringt die Befehlsbindungen der Qiraji, 2 Götzen des Todes, 5 Bronzeskarabäen und 5 Goldskarabäen zu Kandrostrasz in Ahn\'Qiraj. Diese Aufgabe erfordert auch einen neutralen Ruf bei der Brut Nozdormus.', },
  },
  [8597] = {
    'Drachisch für Dummies',
    {'Ich wusste, dass dieses Buch eines Tages nützlich sein würde! Glücklicherweise war ich clever und vorausschauend genug und habe es an einem sicheren Ort verstaut.|n|nKeine Angst, es befindet sich an einem Platz, auf den niemand kommen würde! Ich brauchte einen Gyrokopter, um das erste Mal dorthin zu gelangen. Bedauerlicherweise musste ich auf meinem Rückweg am Strand bruchlanden. Ich verdanke es diesem Unfall, dass ich diese gnomischen Superpsychokräfte erlangt habe!|n|nHaltet nach meinem verunglückten Gyrokopter irgendwo am Landendestrand Ausschau und schwimmt von da aus in Richtung Süden! Ihr werdet die Stelle erkennen, wenn Ihr sie seht!', },
    {'Findet Narain Pfauentraums Buch, das auf einer Insel der Südlichen Meere vergraben ist.', },
  },
  [8598] = {
    'lÖsEGeLd',
    {'<Der Text der Nachricht wurde aus unterschiedlichen, ausgeschnittenen Buchstaben zusammengesetzt und auf das Papier geklebt.>|n|nWir haben dein kostbares Buch, Gnom. Wenn du es jemals wiedersehen willst, dann machst du genau das, was wir dir sagen.|n|n<Dem Ganzen folgt eine ausführliche Liste von Anweisungen, die sich über 3 Seiten zieht.>|n|nBringt das Geld und kommt alleine!', },
    {'Bringt die Lösegeldforderung zu Narain Pfauentraum in Tanaris.', },
  },
  [8599] = {
    'Liebesbrief für Narain',
    {'Es kommt nicht häufig vor, dass ich Besuch bekomme. Genaugenommen hatte ich das letzte Mal einen Besucher, als ich diesen liebreizenden, süßen Gnom nach dem Absturz mit seiner Flugmaschine gerettet habe.|n|n<Meridith starrt gedankenverloren ins Nichts.>|n|nKennt Ihr ihn? Narain? Narain Pfauentraum? Oh, es würde mir so viel bedeuten, wenn ihm jemand eine Nachricht von mir überbringen würde. Ich muss ihm mitteilen, was ich empfinde! Ich weiß, dass es Liebe ist! Ich weiß es einfach!|n|nKönntet Ihr Narain vielleicht eine Nachricht zustellen? Ich wäre Euch für immer zu Dank verpflichtet!', },
    {'Bringt Meridiths Liebesbrief zu Narain Pfauentraum in Tanaris.', },
  },
  [8600] = {
    'Die Horde braucht unverwüstliches Leder!',
    {'Ich glaube, dass die richtige Handhabung eines Messers wichtiger ist als dessen Schneide. Beherrscht man sein Handwerk, kann man auch mit der stumpfsten Klinge schneiden, oder $C? Ihr und ich, wir haben solche Probleme aber nicht, da wir im Besitz der schärfsten Klingen sind.|n|nNaja, egal. Ich habe eine Aufgabe für Euch. Im Auftrag der Horde und im Namen der Kriegsvorbereitungen von Ahn\'Qiraj, möchte ich Euch bitten, mir eine gewisse Anzahl unverwüstliches Leder zu besorgen. Wäre das möglich?', },
    {'Bringt 10 Einheiten unverwüstliches Leder zu Doktor Serratus im Tal der Geister in Orgrimmar.', },
  },
  [8601] = {
    'Die Horde braucht mehr unverwüstliches Leder!',
    {'Bringt 10 Einheiten unverwüstliches Leder zu Doktor Serratus im Tal der Geister in Orgrimmar.', },
    {'Bringt 10 Einheiten unverwüstliches Leder zu Doktor Serratus im Tal der Geister in Orgrimmar.', },
  },
  [8602] = {
    'Schulterstücke des Sturmrufers',
    {'Man sagt unter uns, dass die kunstvoll verzierten Schulterpanzerungen, die von den sterblichen Völkern getragen werden, zu Beginn eine Nachahmung von Drachenflügeln werden sollten.|n|nBringt mir die Bindungen, die von den höchsten Anführern der Qiraji getragen werden und ich werde sie in ein Paar Schulterstücke verarbeiten, die furchteinflößender als die Flügel Nefarians selbst sind!', },
    {'Bringt die Dominanzbindungen der Qiraji, 2 Götzen des Lebens, 5 Goldskarabäen und 5 Kristallskarabäen zu Andorgos in Ahn\'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen neutralen Ruf bei der Brut Nozdormus.', },
  },
  [8603] = {
    'Gewänder des Orakels',
    {'Der unaussprechliche Alte Gott erwacht langsam aus seinem Schlummer unterhalb Ahn\'Qirajs. Das schreckliche Schicksal, das Azeroth erwartet, könnte in Tagen oder auch Jahren Wirklichkeit werden, Zeit spielt für Wesen seiner Macht keine Rolle.|n|nStehen die Sterne günstig, wird er furchtbaren Zorn gegen alle Lebewesen walten lassen. Ihr müsst dem zuvorkommen und einen Weg finden, um seiner Existenz ein Ende zu bereiten.|n|nTut dies und bringt mir ein Stück seiner Hülle. Ich werde Euch eine Rüstung gewähren, die noch kein Sterblicher getragen hat... Rüstung für einen Helden, der einen Gott bezwungen hat!', },
    {'Bringt die Hülle des Alten Gottes, 2 Götzen des Todes, 5 Steinskarabäen und 5 Kristallskarabäen zu Vethsera innerhalb von Ahn\'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf bei der Brut Nozdormus.', },
  },
  [8604] = {
    'Die Horde braucht Wollverbände!',
    {'Seid gegrüßt, $C. Während der Vorbereitungen für den Krieg in Ahn\'Qiraj, bin ich hier, um die Bemühungen der Horde beim Zusammentragen von Wollverbänden zu koordinieren. Auf dem Schlachtfeld können sich unsere Soldaten nicht auf die Gegenwart eines Heilers verlassen, der sie am Leben hält. Glaubt mir, ich weiß das. Daher stellen wir all diese Sanitätskästen für sie zusammen.|n|nSolltet Ihr Zeit haben: Ich brauche sehr viele Wollverbände. Bringt sie hierher zu mir und ich werde sehen, dass Ihr dafür ordnungsgemäß entlohnt werdet.', },
    {'Bringt 20 Wollverbände zu Heiler Fernläufer im Tal der Geister in Orgrimmar.', },
  },
  [8605] = {
    'Die Horde braucht mehr Wollverbände!',
    {'Bringt 20 Wollverbände zu Heiler Fernläufer im Tal der Geister in Orgrimmar.', },
    {'Bringt 20 Wollverbände zu Heiler Fernläufer im Tal der Geister in Orgrimmar.', },
  },
  [8606] = {
    'Lockvogel!',
    {'Narain Pfauentraum in Tanaris möchte, dass Ihr nach Winterquell reist und die Tasche voller Gold, so wie es die Buchnapper angegeben haben, am Übergabepunkt platziert.', },
    {'Narain Pfauentraum in Tanaris möchte, dass Ihr nach Winterquell reist und die Tasche voller Gold, so wie es die Buchnapper angegeben haben, am Übergabepunkt platziert.', },
  },
  [8607] = {
    'Die Horde braucht Magiestoffverbände!',
    {'Ich nehme doch hoffentlich richtig an, dass Ihr mit mir sprecht, weil Ihr mich bei dem Sammelauftrag unterstützen wollt, der mir anvertraut wurde? Gut! Mir ist es egal wie, aber ich wünsche mir wirklich, dass Ihr einige Magiestoffverbände für mich zusammentragt. Ganz frisch hergestellte wären wunderbar, aber nicht unbedingt zwingend. Bringt sie hierher zu mir, $C, dann werde ich sehen, dass Ihr ordnungsgemäß dafür entlohnt werdet.', },
    {'Bringt 20 Magiestoffverbände zu Lady Kahler im Tal der Geister in Orgrimmar.', },
  },
  [8608] = {
    'Die Horde braucht mehr Magiestoffverbände!',
    {'Bringt 20 Magiestoffverbände zu Lady Kahler im Tal der Geister in Orgrimmar.', },
    {'Bringt 20 Magiestoffverbände zu Lady Kahler im Tal der Geister in Orgrimmar.', },
  },
  [8609] = {
    'Die Horde braucht Runenstoffverbände!',
    {'Bringt 20 Runenstoffverbände zu Steingardist Lehmhuf im Tal der Geister in Orgrimmar.', },
    {'Bringt 20 Runenstoffverbände zu Steingardist Lehmhuf im Tal der Geister in Orgrimmar.', },
  },
  [8610] = {
    'Die Horde braucht mehr Runenstoffverbände!',
    {'Bringt 20 Runenstoffverbände zu Steingardist Lehmhuf im Tal der Geister in Orgrimmar.', },
    {'Bringt 20 Runenstoffverbände zu Steingardist Lehmhuf im Tal der Geister in Orgrimmar.', },
  },
  [8611] = {
    'Die Horde braucht magere Wolfsteaks!',
    {'Ich stehe hier nicht nur herum, um etwas Farbe abzubekommen, $C. Es gilt Kriegsvorbereitungen zu treffen. Wenn wir diese Viecher in Ahn\'Qiraj niederschmettern möchten, dann müssen wir bereit sein, und dazu gehört auch Proviant!|n|nIch sammle und salze hier magere Wolfsteaks für den anstehenden Krieg ein. Da ich hier bleiben muss, um mich um alles zu kümmern, bräuchte ich Eure Hilfe. Zieht aus, um Wölfe zu töten, bereitet ihr Fleisch zu mageren Wolfsteaks zu und bringt diese dann zu mir. Alles klar?', },
    {'Bringt 20 magere Wolfsteaks zu Blutwache Rawtar im Tal der Geister in Orgrimmar.', },
  },
  [8612] = {
    'Die Horde braucht mehr magere Wolfsteaks!',
    {'Bringt 20 magere Wolfsteaks zu Blutwache Rawtar im Tal der Geister in Orgrimmar.', },
    {'Bringt 20 magere Wolfsteaks zu Blutwache Rawtar im Tal der Geister in Orgrimmar.', },
  },
  [8613] = {
    'Die Horde braucht Tüpfelgelbschwänze!',
    {'Wär\' heute nicht ein guter Tag zum Angeln? Praktisch, denn es sieht aus, als würde ich hier noch \'ne Menge Fisch brauchen. Die Horde hat mich mit der Sammlung von einem Haufen Tüpfelgelbschwänzen beauftragt. Sie sagen, dass sie sie für ihre Vorbereitungen für den Krieg in Ahn\'Qiraj benötigen. Ich hab\' gesagt, dass ich mein Bestes geben werde. Ich brauche also etwas Unterstützung. Ihr werdet mir doch helfen, $C, oder?', },
    {'Bringt 20 Tüpfelgelbschwänze zu Angler Lin\'do im Tal der Geister in Orgrimmar.', },
  },
  [8614] = {
    'Die Horde braucht mehr Tüpfelgelbschwänze!',
    {'Bringt 20 Tüpfelgelbschwänze zu Angler Lin\'do im Tal der Geister in Orgrimmar.', },
    {'Bringt 20 Tüpfelgelbschwänze zu Angler Lin\'do im Tal der Geister in Orgrimmar.', },
  },
  [8615] = {
    'Die Horde braucht gebackenen Lachs!',
    {'Die Vorbereitungen für den Krieg von Ahn\'Qiraj sind ein immenses Unterfangen, $C. All die Materialien, die hier gesammelt werden, sind gleichermaßen wichtig - ob es Metall für Waffen oder Proviant zum Essen ist. Hat man seit Tagen nichts gegessen, so kann man, wenn es darauf ankommt, auch nicht mehr seine Axt schwingen.|n|nDafür sammeln wir hier so viele Nahrungsmittel wie wir können. Ich sammle zum Beispiel gebackenen Lachs, ein Gericht, das wegen seiner Nahrhaftigkeit und guten Lagerbedingungen gewählt wurde. Könnt Ihr mir bei dieser Aufgabe helfen, $C?', },
    {'Bringt 20 Stück gebackenen Lachs zu Häuptling Scharfklaue im Tal der Geister in Orgrimmar.', },
  },
  [8616] = {
    'Die Horde braucht mehr gebackenen Lachs!',
    {'Bringt 20 Stück gebackenen Lachs zu Häuptling Scharfklaue im Tal der Geister in Orgrimmar.', },
    {'Bringt 20 Stück gebackenen Lachs zu Häuptling Scharfklaue im Tal der Geister in Orgrimmar.', },
  },
  [8618] = {
    'Die Horde braucht mehr sengende Kernsteine!',
    nil,
    nil,
  },
  [8619] = {
    'Urahne Schwermut',
    nil,
    nil,
  },
  [8620] = {
    'Der einzige Weg',
    {'Ich hätte es wissen müssen. Mein Erzfeind, Doktor Weavil, hat wieder seine dreckigen Finger im Spiel! Jetzt, nach Eurem Versagen in Winterquell, hat Doktor Weavil mein Buch zerstört! Wie wollt Ihr jetzt die Welt retten, Held?|n|nDie Nachricht die ich erhalten habe, gab an, dass die einzig bekannte Kopie von "Drachisch für Dummies: Band 2" in 8 Teile zerrissen und im Wind zerstreut wurde! Solltet Ihr diese fehlenden Kapitel irgendwie finden können, dann verwendet diesen magischen Bucheinband, um sie wieder zusammen zu flicken. Kehrt dann zu mir zurück.', },
    {'Findet die 8 verlorenen Kapitel von Drachisch für Dummies und vereint sie mit dem magischen Bucheinband. Bringt das vollständige Buch Drachisch für Dummies: Band 2 zu Narain Pfauentraum in Tanaris.', },
  },
  [8621] = {
    'Fußschützer des Sturmrufers',
    {'Qirajimagie ist sehr stark und uralt. Die mächtigsten Qiraji handhaben Gegenstände, die so machtvoll sind, dass sie sogar einem Drachen Einhalt gebieten.|n|nBringt mir die Dominanzbindungen der Qiraji sowie andere geringfügigere Bestandteile und ich werde ein Paar mächtige Stiefel für Euch herstellen.|n|nIhr werdet sie im Kampf gegen den Feind als nützlich empfinden.', },
    {'Bringt die Dominanzbindungen der Qiraji, 2 Götzen der Weisen, 5 Bronzeskarabäen und 5 Tonskarabäen zu Kandrostrasz in Ahn\'Qiraj. Diese Aufgabe erfordert auch einen neutralen Ruf bei der Brut Nozdormus.', },
  },
  [8622] = {
    'Halsberge des Sturmrufers',
    {'Der unaussprechliche Alte Gott erwacht langsam aus seinem Schlummer unterhalb Ahn\'Qirajs. Das schreckliche Schicksal, das Azeroth erwartet, könnte in Tagen oder auch Jahren Wirklichkeit werden, Zeit spielt für Wesen seiner Macht keine Rolle.|n|nStehen die Sterne günstig, wird er furchtbaren Zorn gegen alle Lebewesen walten lassen. Ihr müsst dem zuvorkommen und einen Weg finden, um seiner Existenz ein Ende zu bereiten.|n|nTut dies und bringt mir ein Stück seiner Hülle. Ich werde Euch eine Rüstung gewähren, die noch kein Sterblicher getragen hat... Rüstung für einen Helden, der einen Gott bezwungen hat!', },
    {'Bringt den Knochenpanzer des Alten Gottes, 2 Götzen der Weisen, 5 Silberskarabäen und 5 Knochenskarabäen zu Vethsera innerhalb von Ahn\'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf bei der Brut Nozdormus.', },
  },
  [8623] = {
    'Diadem des Sturmrufers',
    {'Die Zwillingsimperatoren... ihr unaufhörliches Flüstern martert langsam meinen Verstand. Sie verhöhnen mich, wissend, dass ich nicht tiefer in ihr Reich vordringen kann, um meinen Bruder Arygos zu retten.|n|nIn meinen Visionen sehe ich ihre monströsen Fratzen, die mit mächtigen Kronen geschmückt sind. Ich werde meine Vergeltung noch bekommen... ich werde diese Symbole der Qirajimacht in solche verwandeln, die unserem Nutzen gerecht werden.|n|nBringt mir die benötigten Bestandteile, $N. Ich werde Euch dafür ein Kopfstück von unvergleichlicher Macht geben.', },
    {'Bringt Vek\'lors Diadem, 2 Götzen der Wiedergeburt, 5 Steinskarabäen und 5 Kristallskarabäen zu Andorgos in Ahn\'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.', },
  },
  [8624] = {
    'Gamaschen des Sturmrufers',
    {'Ihr möchtet Euch also uns gegenüber bewähren, Sterblicher? Nun gut, vielleicht können wir uns ja gegenseitig helfen.|n|nDer uralte Sandwurm, Ouro, ist ein Geschöpf von legendärer Macht. Man sagt, dass er von dem Alten Gott selbst als Gespött des Lebens erschaffen wurde.|n|nSeine Haut ist unnatürlich... dick, fast unbezwingbar und dennoch flexibel, was ihm ermöglicht, sich mit der Geschwindigkeit und Grazie eines kleineren Lebewesens zu bewegen.|n|nBringt mir eine Probe seiner Haut sowie andere geringfügigere Bestandteile und ich werde mächtige Gamaschen für Euch herstellen.', },
    {'Bringt die Haut des großen Sandwurms, 2 Götzen des Kampfes, 5 Bronzeskarabäen und 5 Elfenbeinskarabäen zu Kandrostrasz innerhalb von Ahn\'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.', },
  },
  [8625] = {
    'Schulterpolster des Mysteriums',
    {'Man sagt unter uns, dass die kunstvoll verzierten Schulterpanzerungen, die von den sterblichen Völkern getragen werden, zu Beginn eine Nachahmung von Drachenflügeln werden sollten.|n|nBringt mir die Bindungen, die von den höchsten Anführern der Qiraji getragen werden und ich werde sie in ein Paar Schulterstücke verarbeiten, die furchteinflößender als die Flügel Nefarians selbst sind!', },
    {'Bringt die Dominanzbindungen der Qiraji, 2 Götzen des Todes, 5 Steinskarabäen und 5 Bronzeskarabäen zu Andorgos in Ahn\'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen neutralen Ruf bei der Brut Nozdormus.', },
  },
  [8626] = {
    'Fußschützer des Hetzers',
    {'Qirajimagie ist sehr stark und uralt. Die mächtigsten Qiraji handhaben Gegenstände, die so machtvoll sind, dass sie sogar einem Drachen Einhalt gebieten.|n|nBringt mir die Befehlsbindungen der Qiraji sowie andere geringfügigere Bestandteile und ich werde ein Paar mächtige Stiefel für Euch herstellen.|n|nIhr werdet sie im Kampf gegen den Feind als nützlich empfinden.', },
    {'Bringt die Dominanzbindungen der Qiraji, 2 Götzen des Lebens, 5 Steinskarabäen und 5 Knochenskarabäen zu Kandrostrasz in Ahn\'Qiraj. Diese Aufgabe erfordert auch einen neutralen Ruf bei der Brut Nozdormus.', },
  },
  [8627] = {
    'Brustplatte des Rächers',
    {'Der unaussprechliche Alte Gott erwacht langsam aus seinem Schlummer unterhalb Ahn\'Qirajs. Das schreckliche Schicksal, das Azeroth erwartet, könnte in Tagen oder auch Jahren Wirklichkeit werden, Zeit spielt für Wesen seiner Macht keine Rolle.|n|nStehen die Sterne günstig, wird er furchtbaren Zorn gegen alle Lebewesen walten lassen. Ihr müsst dem zuvorkommen und einen Weg finden, um seiner Existenz ein Ende zu bereiten.|n|nTut dies und bringt mir ein Stück seiner Hülle. Ich werde Euch eine Rüstung gewähren, die noch kein Sterblicher getragen hat... Rüstung für einen Helden, der einen Gott bezwungen hat!', },
    {'Bringt den Knochenpanzer des Alten Gottes, 2 Götzen der Weisen, 5 Silberskarabäen und 5 Knochenskarabäen zu Vethsera innerhalb von Ahn\'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf bei der Brut Nozdormus.', },
  },
  [8628] = {
    'Krone des Rächers',
    {'Die Zwillingsimperatoren... ihr unaufhörliches Flüstern martert langsam meinen Verstand. Sie verhöhnen mich, wissend, dass ich nicht tiefer in ihr Reich vordringen kann, um meinen Bruder Arygos zu retten.|n|nIn meinen Visionen sehe ich ihre monströsen Fratzen, die mit mächtigen Kronen geschmückt sind. Ich werde meine Vergeltung noch bekommen... ich werde diese Symbole der Qirajimacht in solche verwandeln, die unserem Nutzen gerecht werden.|n|nBringt mir die benötigten Bestandteile, $N. Ich werde Euch dafür ein Kopfstück von unvergleichlicher Macht geben.', },
    {'Bringt Vek\'lors Diadem, 2 Götzen der Wiedergeburt, 5 Steinskarabäen und 5 Kristallskarabäen zu Andorgos in Ahn\'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.', },
  },
  [8629] = {
    'Beinschützer des Rächers',
    {'Ihr möchtet Euch also uns gegenüber bewähren, Sterblicher? Nun gut, vielleicht können wir uns ja gegenseitig helfen.|n|nDer uralte Sandwurm, Ouro, ist ein Geschöpf von legendärer Macht. Man sagt, dass er von dem Alten Gott selbst als Gespött des Lebens erschaffen wurde.|n|nSeine Haut ist unnatürlich... dick, fast unbezwingbar und dennoch flexibel, was ihm ermöglicht, sich mit der Geschwindigkeit und Grazie eines kleineren Lebewesens zu bewegen.|n|nBringt mir eine Probe seiner Haut sowie andere geringfügigere Bestandteile und ich werde mächtige Gamaschen für Euch herstellen.', },
    {'Bringt die Haut des großen Sandwurms, 2 Götzen des Kampfes, 5 Bronzeskarabäen und 5 Elfenbeinskarabäen zu Kandrostrasz innerhalb von Ahn\'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.', },
  },
  [8630] = {
