  [8856] = {
    'Wüstenüberlebenspaket',
    {'Seitdem ständig neue Rekruten auf Burg Cenarius eintreffen, stehen wir vor dem Problem, sie in der Wüste am Leben zu erhalten. Der ständige Wasserentzug und die zahlreichen giftigen Kreaturen in dieser Gegend sind eine ernstzunehmende Gefahr für die unerfahren Soldaten. Sammelt alles, was notwendig ist, um ein Wüstenüberlebenspaket zusammenzustellen und bringt die erforderlichen Vorräte zu Calandrath auf Burg Cenarius.', },
    {'Bringt 4 Kugeln des Wassers, 4 mächtige Gegengifte und 4 gebackene Lachse zu Calandrath in der Taverne von Burg Cenarius in Silithus.', },
  },
  [8857] = {
    'Geheimnisse des Kolosses - Ashi',
    {'Ich suche nach schlachterprobten Abenteurern, die für mich eine Fragmentprobe vom Koloss des Ashischwarms zu Glotz in Beutebucht bringen. Nein, nein, Ihr braucht Euch nicht einmal in die Nähe dieses Giganten zu wagen. Nehmt einfach eine von meinen Proben und beeilt Euch. Verrottet nutzt sie Glotz nicht viel!', },
    {'Bringt das Fragment vom Koloss des Ashischwarms zu Glotz Widrikus in Beutebucht.', },
  },
  [8858] = {
    'Geheimnisse des Kolosses - Regal',
    {'Ich würde nichts lieber tun, als Schlickfaust dieses verdammte Fragment in sein fettes Maul zu stopfen. Stattdessen stecke ich hier fest und sammle Proben von dieser zu groß geratenen Kakerlake! In Anbetracht ihrer Größe, werde ich hier wohl noch eine Weile beschäftigt sein.|n|nNehmt diese Probe und bringt sie für mich zu Schlickfaust... und beeilt Euch, $C. Er zahlt auch sehr gut!|n|nAlso, ab zur Thoriumspitze in die Sengende Schlucht.', },
    {'Bringt das Fragment vom Koloss des Regalschwarms zu Aufseher Schlickfaust in die Sengende Schlucht.', },
  },
  [8859] = {
    'Geheimnisse des Kolosses - Zora',
    {'Bringt das Fragment vom Koloss des Zoraschwarms zu Lord Maxwell Tyrosus an der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.', },
    {'Bringt das Fragment vom Koloss des Zoraschwarms zu Lord Maxwell Tyrosus an der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.', },
  },
  [8860] = {
    'Neujahrsfeier!',
    {'In Sturmwind wird das neue Jahr ganz groß gefeiert! Den ganzen Tag lang gibt es kostenlosen Hochprozentigen und nachts ein fantastisches Feuerwerk! Das wird sicher ein Riesenspaß... allerdings findet heute auch in Beutebucht eine Neujahrsfeier statt. Ich wette, dort ist sogar noch mehr los!|n|nEgal! Jedenfalls braucht Gastwirtin Allison in Sturmwind eine Ladung Kokelwälder Festtagsspeisen, um alle Partylöwen satt in das neue Jahr zu bringen. Würdet Ihr mir den Gefallen tun und die Vorräte für mich abliefern?|n|nDanke, $N! Ihr findet Gastwirtin Allison in der Güldenen Rose, drüben im Handelsdistrikt von Sturmwind.', },
    {'Bringt die Vorräte von Kokelwälder zu Gastwirtin Allison in Sturmwind.', },
  },
  [8861] = {
    'Neujahrsfeier!',
    {'In Donnerfels wird das neue Jahr ganz groß gefeiert! Den ganzen Tag lang gibt es kostenlosen Hochprozentigen und nachts ein fantastisches Feuerwerk!|n|nDas wird sicher ein Riesenspaß... allerdings findet auch in Beutebucht eine Neujahrsfeier statt. Ich wette, dort ist sogar noch mehr los!|n|nEgal! Jedenfalls braucht Gastwirtin Pala eine Ladung Kokelwälder Festtagsspeisen, um alle Partylöwen satt in das neue Jahr zu bringen. Würdet Ihr mir den Gefallen tun und die Vorräte für mich abliefern?|n|nDanke, $N! Ihr findet Gastwirtin Pala in der Taverne nahe der Brücke zur Anhöhe der Jäger.', },
    {'Bringt die Vorräte von Kokelwälder zu Gastwirtin Pala in Donnerfels.', },
  },
