  [8920] = {
    'Ein aufrichtiges Angebot',
    {'Ich grüße Euch, $C. Eure Haltung verrät mir, dass Ihr bereits ganz schön herumgekommen seid. Ich würde allerdings darauf wetten, dass Euch noch keine Rüstung wie diese untergekommen ist.|n|nWenn Ihr mir einen kleinen Gefallen tut, wäre ich bereit, diese Rüstung gegen ein normales Paar Armschienen einzutauschen.|n|nIch bräuchte eine ziemlich große Menge an Giftproben von den Spinnen und Skorpionen aus Silithus. Bringt es mir zusammen mit einigen Goldmünzen und ich werde den Tausch vornehmen.', },
    {'Sammelt 15 Giftproben aus Silithus und bringt es zusammen mit 20 Gold und einem Paar Armschienen der Ehre zu Mokvar in Orgrimmar zurück.', },
  },
  [8921] = {
    'Der Ektoplasmadestillierer',
    {'Ah, Ihr seid an meinem letzten Projekt interessiert... Dem extradimensionalen Geisterdetektor! Dummerweise sind mir die Geldmittel und Hilfskräfte ausgegangen|n|nIhr sagt, dass Ihr mir aushelfen wollt? Sehr gut! Zunächst müssen wir einen Apparat bauen, der die Essenz des Todes absaugen kann! Einen Ektoplasmadestillierer zu konstruieren wird allerdings nicht ganz einfach sein, $N.|n|nIhr müsst mir einen Arkanitwandler, einige große ewige Essenzen und Steinschuppenöl bringen. Außerdem brauche ich noch Vulkanasche aus den Lavatümpeln in der Brennenden Steppe, um einen Filter zu konstruieren.', },
    {'Kehrt mit einem empfindlichen Arkanitwandler, 4 großen ewigen Essenzen, 10 Flaschen Steinschuppenöl, 25 Einheiten Vulkanasche und 40 Gold im Gepäck zu Mux Manamix in Gadgetzan zurück.', },
  },
  [8922] = {
    'Ein übernatürlicher Apparat',
    {'Ich muss einen Weg finden, mit Anthion Harmon zu sprechen... Oder genauer gesagt mit seinem Geist!|n|nIch kenne da einen Ingenieur, der eine gewisse Faszination für das Übernatürliche hegt. Er behauptet eine Maschine konstruieren zu können, die es ihm erlaubt mit den Toten zu kommunizieren!|n|nDas Blut, dass Ihr gesammelt habt, war für ihn bestimmt. Reist nach Gadgetzan und bringt es ihm als Bezahlung für seine Dienste!', },
    {'Bringt den versiegelten Blutbehälter zu Mux Manamix in Gadgetzan.', },
  },
  [8923] = {
    'Ein übernatürlicher Apparat',
    {'Ihr müsst wirklich verdammt mutig sein. Respekt, dass Ihr immer noch an der Sache dran seid. Oder vielleicht haben die Rüstungsteile, die ich Euch gegeben habe, ja Euer Interesse geweckt. Wo die herkamen gibt\'s noch mehr, wenn Ihr daran interessiert seid, mir erneut auszuhelfen.|n|nDie Giftproben, die Ihr gesammelt habt, sind für einen Bekannten von mir bestimmt, Mux Manamix, ein Ingenieur mit einem gewissen Interesse für das Übernatürliche. Seine neueste Erfindung soll es angeblich ermöglichen, mit den Toten zu kommunizieren! Meine letzte Hoffnung ist es, Anthion zu kontaktieren und mehr über meine Situation herauszufinden.', },
    {'Bringt den versiegelten Giftbehälter zu Mux Manamix in Gadgetzan.', },
  },
  [8924] = {
    'Ektoplasmajagd',
    {'Ein hervorragendes Stück Ingenieurarbeit, wenn ich das mal selbst so sagen darf! Ich fürchte allerdings, dass Ihr weit umherreisen werden müsst, um die Art schemenhafter Untoten zu finden, die wir benötigen.|n|nIhr müsst verstehen, dass verschiedenen Klimabedingungen Einfluss auf die spektrale Struktur der Toten haben. Die gequälten Nachtelfen in Silithus, die Geister der Hochgeborenen in Winterquell und die Geister und Banshees in den Östlichen Pestländern sollten uns mit den verschiedenen Sorten von Ektoplasma versorgen, die wir benötigen. Stellt auf jeden Fall den Destillierer in der Nähe auf, bevor Ihr sie bekämpft.', },
    {'Benutzt den Ektoplasmadestillierer in der Nähe von schemenhaften Untoten, um 12 Einheiten versengtes Ektoplasma in Silithus, 12 Einheiten gefrorenes Ektoplasma in Winterquell und 12 Einheiten stabiles Ektoplasma in den Östlichen Pestländern zu erhalten. Bringt das Ektoplasma dann mitsamt des Ektoplasmadestillierers zu Mux Manamix in Gadgetzan zurück.', },
  },
  [8925] = {
    'Eine portable Energiequelle',
    {'Jetzt brauchen wir nur noch eine stabile und portable Energiequelle, um das Ektoplasma aktiv zu halten. Ich habe Gerüchte über einen machtvollen Elementar namens Magmafürst Bokk gehört, dessen Herz ein mächtiger Magmakern ist - eine schier unerschöpfliche Hitzequelle!|n|nMan sagt, dass er sich irgendwo in der Brennenden Steppe südlich des Schwarzfels herumtreibt. Bringt mir den Magmakern und wir werden genug Saft haben, um den extradimensionalen Geisterdetektor zu betreiben!', },
    {'Findet Magmafürst Bokk in der Brennenden Steppe, nehmt seinen Magmakern an Euch und bringt ihn zu Mux Manamix in Gadgetzan.', },
  },
  [8926] = {
    'Die angemessene Entlohnung',
    {'Ihr habt Euer Wort gehalten und den von Mux konstruierten Apparat beschafft. Ich denke, eine Belohnung wäre nun angebracht, um Euer Interesse daran, meine Haut zu retten, aufrechtzuerhalten. Bringt mir den Gürtel und die Handschuhe, von denen Ihr eine verbesserte Version wünscht. Ich kann Euch versichern, dass die Rüstung, die ich Euch geben werde, von weit höherer Qualität sein wird.', },
    {'Bringt Deliana in Eisenschmiede einen Gürtel des Wildherzens und ein Paar Handschuhe des Wildherzens.', },
  },
  [8927] = {
    'Die angemessene Entlohnung',
    {'Ihr habt große Verlässlichkeit bewiesen, $N. So sehr ich auch darauf vertraue, dass Ihr mir durch diese missliche Situation hindurchhelft, wäre es dennoch weiser, Euch zunächst Euren bisherigen Taten entsprechend zu entlohnen.|n|nIch werde zunächst Euren Gürtel und Eure Handschuhe austauschen. Wenn wir dies bis zum Ende durchstehen, werde ich Euch den Rest der Rüstung übergeben.', },
    {'Bringt Mokvar in Orgrimmar einen Gürtel des Wildherzens und ein Paar Handschuhe des Wildherzens.', },
  },
  [8928] = {
    'Ein verschlagener Händler',
    {'Der Kern sollte uns mit genügend Energie zum Betreiben des Apparates versorgen, jetzt brauchen wir nur noch einen Brennstab, der diese Energie auch weiterleiten kann, ohne dabei zu schmelzen.|n|nIch habe in Winterquell mal einen Wichtel getroffen, der allerlei exotische Waren im Angebot hatte. Er hatte einen elementaren Brennstab, der einfach perfekt gewesen wäre. Ich könnte mich schwarz ärgern, dass ich den nicht gekauft habe.|n|nEr lebt in einer Höhle nahe dem Zugang zur Flüsternden Schlucht. Schleicht Euch hinein und seht zu, dass Ihr ihn findet.|n|nLasst Euch aber nicht von ihm übers Ohr hauen, zahlt ihm nicht mehr als 40 Goldstücke. Den Preis hat er mir damals angeboten!', },
    {'Sucht den Wichtel in der Höhle in der Nähe der Flüsternden Schlucht im Süden von Winterquell. Kauft ihm einen teufelselementaren Brennstab ab und kehrt zu Mux Manamix in Gadgetzan zurück.', },
  },
  [8929] = {
    'Suche nach Anthion',
    {'Tja, wir haben wohl keine andere Wahl, als die Erfindung des Goblins auszuprobieren. Man sagt, dass Anthion von den untoten Horden Stratholmes niedergemetzelt wurde, als er versuchte, durch dessen Tore zu schreiten.|n|nVersucht den Apparat dort zu benutzen und herauszufinden, was auch immer Anthion wusste.', },
    {'Benutzt den extradimensionalen Geisterdetektor am Eingang zu Stratholme und sprecht mit dem Geist von Anthion Harmon.', },
  },
  [8930] = {
    'Suche nach Anthion',
    {'Nun denn, $N. Jetzt müssen wir wohl die Erfindung des Goblins ausprobieren. Man sagt, dass Anthion von den untoten Horden Stratholmes niedergemäht wurde, als er versuchte, durch die Tore zu schreiten.|n|nVersucht den Apparat dort zu benutzen und findet heraus, was Anthion wusste.', },
    {'Benutzt den extradimensionalen Geisterdetektor am Eingang zu Stratholme und sprecht mit dem Geist von Anthion Harmon.', },
  },
  [8931] = {
    'Die angemessene Entlohnung',
    {'Ihr habt Euer Wort gehalten und den von Mux konstruierten Apparat beschafft. Ich denke, eine Belohnung wäre nun angebracht, um Euer Interesse daran, meine Haut zu retten, aufrechtzuerhalten. Bringt mir einen gewöhnlichen Gürtel und Handschuhe, von denen Ihr eine verbesserte Version wünscht.', },
    {'Bringt Deliana in Eisenschmiede einen Bestienjägergürtel und ein Paar Bestienjägerhandschuhe.', },
  },
  [8932] = {
    'Die angemessene Entlohnung',
    {'Ihr habt Euer Wort gehalten und den von Mux konstruierten Apparat beschafft. Ich denke, eine Belohnung wäre nun angebracht, um Euer Interesse daran, meine Haut zu retten, aufrechtzuerhalten. Bringt mir einen gewöhnlichen Gürtel und Handschuhe, von denen Ihr eine verbesserte Version wünscht.', },
    {'Bringt Deliana in Eisenschmiede einen Gürtel des Magisters und ein Paar Handschuhe des Magisters.', },
  },
