  },
  [9041] = {
    'Taillenschutz des Schreckenspanzers',
    {'Solltet Ihr während Euren Kämpfen gegen die Geißel in Naxxramas auf entweihte Rüstungsteile und kampfzerschlissene Plattenstücke stoßen, bringt sie zu mir, und ich werde Euch ein Rüstungsteil anfertigen, das eines Heldens würdig ist.', },
    {'Korfax bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch einen Taillenschutz des Schreckenspanzers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihten Taillenschutz, 8 kampfzerschlissene Plattenstücke, 1 Arkanitbarren und 5 geschmeidige unverwüstliche Bälge.', },
  },
  [9042] = {
    'Armschienen des Schreckenspanzers',
    {'Solltet Ihr während Euren Kämpfen gegen die Geißel in Naxxramas auf entweihte Rüstungsteile und kampfzerschlissene Plattenstücke stoßen, bringt sie zu mir, und ich werde Euch ein Rüstungsteil anfertigen, das eines Heldens würdig ist.', },
    {'Korfax bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Armschienen des Schreckenspanzers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Armschienen, 6 kampfzerschlissene Plattenstücke, 1 Arkanitbarren und 1 Nexuskristall.', },
  },
  [9043] = {
    'Tunika der Erlösung',
    {'Ihr werdet die Überbleibsel von unseren gefallenen Helden bei den Körpern der Obersten von Naxxramas finden. Bringt mir diese entweihten Vermächtnisse, kampfzerschlissene Plattenstücke und die Handwerksmaterialien, die zum Wiederherstellen der verfluchten Rüstung benötigt werden, damit ich Euch eine prächtige Ausstattung anfertigen kann.', },
    {'Kommandant Eligor Morgenbringer bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch eine Tunika der Erlösung anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Tunika, 25 kampfzerschlissene Plattenstücke, 4 Arkanitbarren und 3 geschmeidige unverwüstliche Bälge.', },
  },
  [9044] = {
    'Beinschützer der Erlösung',
    {'Ihr werdet die Überbleibsel von unseren gefallenen Helden bei den Körpern der Obersten von Naxxramas finden. Bringt mir diese entweihten Vermächtnisse, kampfzerschlissene Plattenstücke und die Handwerksmaterialien, die zum Wiederherstellen der verfluchten Rüstung benötigt werden, damit ich Euch eine prächtige Ausstattung anfertigen kann.', },
    {'Kommandant Eligor Morgenbringer bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Beinschützer der Erlösung anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Beinschützer, 20 kampfzerschlissene Plattenstücke, 4 Arkanitbarren und 2 Nexuskristalle.', },
  },
  [9045] = {
    'Kopfstück der Erlösung',
    {'Ihr werdet die Überbleibsel von unseren gefallenen Helden bei den Körpern der Obersten von Naxxramas finden. Bringt mir diese entweihten Vermächtnisse, kampfzerschlissene Plattenstücke und die Handwerksmaterialien, die zum Wiederherstellen der verfluchten Rüstung benötigt werden, damit ich Euch eine prächtige Ausstattung anfertigen kann.', },
    {'Kommandant Eligor Morgenbringer bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch ein Kopfstück der Erlösung anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihtes Kopfstück, 15 kampfzerschlissene Plattenstücke, 5 Arkanitbarren und 2 geschmeidige unverwüstliche Bälge.', },
  },
  [9046] = {
    'Schiftung der Erlösung',
    {'Ihr werdet die Überbleibsel von unseren gefallenen Helden bei den Körpern der Obersten von Naxxramas finden. Bringt mir diese entweihten Vermächtnisse, kampfzerschlissene Plattenstücke und die Handwerksmaterialien, die zum Wiederherstellen der verfluchten Rüstung benötigt werden, damit ich Euch eine prächtige Ausstattung anfertigen kann.', },
    {'Kommandant Eligor Morgenbringer bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch eine Schiftung der Erlösung anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Schiftung, 12 kampfzerschlissene Plattenstücke, 2 Arkanitbarren und 2 Nexuskristalle.', },
  },
  [9047] = {
    'Stiefel der Erlösung',
    {'Ihr werdet die Überbleibsel von unseren gefallenen Helden bei den Körpern der Obersten von Naxxramas finden. Bringt mir diese entweihten Vermächtnisse, kampfzerschlissene Plattenstücke und die Handwerksmaterialien, die zum Wiederherstellen der verfluchten Rüstung benötigt werden, damit ich Euch eine prächtige Ausstattung anfertigen kann.', },
    {'Kommandant Eligor Morgenbringer bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Stiefel der Erlösung anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Stiefel, 12 kampfzerschlissene Plattenstücke, 2 Arkanitbarren und 3 geschmeidige unverwüstliche Bälge.', },
  },
  [9048] = {
    'Handschützer der Erlösung',
    {'Ihr werdet die Überbleibsel von unseren gefallenen Helden bei den Körpern der Obersten von Naxxramas finden. Bringt mir diese entweihten Vermächtnisse, kampfzerschlissene Plattenstücke und die Handwerksmaterialien, die zum Wiederherstellen der verfluchten Rüstung benötigt werden, damit ich Euch eine prächtige Ausstattung anfertigen kann.', },
    {'Kommandant Eligor Morgenbringer bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Handschützer der Erlösung anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Handschützer, 8 kampfzerschlissene Plattenstücke, 1 Arkanitbarren und 5 geschmeidige unverwüstliche Bälge.', },
  },
  [9049] = {
    'Gurt der Erlösung',
    {'Ihr werdet die Überbleibsel von unseren gefallenen Helden bei den Körpern der Obersten von Naxxramas finden. Bringt mir diese entweihten Vermächtnisse, kampfzerschlissene Plattenstücke und die Handwerksmaterialien, die zum Wiederherstellen der verfluchten Rüstung benötigt werden, damit ich Euch eine prächtige Ausstattung anfertigen kann.', },
    {'Kommandant Eligor Morgenbringer bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch einen Gurt der Erlösung anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihten Gurt, 8 kampfzerschlissene Plattenstücke, 1 Arkanitbarren und 3 Nexuskristalle.', },
  },
  [9050] = {
    'Handgelenksschützer der Erlösung',
    {'Ihr werdet die Überbleibsel von unseren gefallenen Helden bei den Körpern der Obersten von Naxxramas finden. Bringt mir diese entweihten Vermächtnisse, kampfzerschlissene Plattenstücke und die Handwerksmaterialien, die zum Wiederherstellen der verfluchten Rüstung benötigt werden, damit ich Euch eine prächtige Ausstattung anfertigen kann.', },
    {'Kommandant Eligor Morgenbringer bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch ein Paar Handgelenksschützer der Erlösung anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Handgelenksschützer, 6 kampfzerschlissene Plattenstücke, 1 Arkanitbarren und 2 geschmeidige unverwüstliche Bälge.', },
  },
  [9051] = {
    'Giftexperiment',
    {'Das Gift, das Ihr mir geholfen habt zu entwickeln, ist für einen bestimmten Zweck gedacht. Die mächtigen Teufelssaurier des Kraters erschweren mir die Jagd und das Überleben. Selbst wenn ich über die nötige Stärke verfügen würde, einen Teufelssaurier zu erlegen, würde einfach nur ein anderer sein Territorium beanspruchen.|n|nNehmt diesen vergifteten Widerhaken und stecht ihn tief in einen lebenden Teufelssaurier. Das Gift sollte ihn ruhigstellen, aber ich bin mir nicht sicher, wie lange es dauern wird, bis es wirkt...', },
    {'Stecht einen Teufelssaurier mit dem Teufelssaurierhaken und kehrt danach zu Torwa Pfadfinder im Krater von Un\'Goro zurück.', },
  },
  [9052] = {
    'Blutblütengift',
    {'Ich würde Euch darum bitten, mir dabei behilflich zu sein, ein spezielles Gift zu entwickeln, um eine der mächtigsten Kreaturen des Kraters ruhigzustellen. Es ist nicht tödlich und nur $Gein:eine:c; $C mit scharfen Augen kann die nötigen Zutaten dafür erspähen.|n|nDie Blutkappenpilze wachsen in den Blutblütensprösslingen, die überall im Krater anzufinden sind. Gorishistachel könnt Ihr von den Insekten erhalten, die in der und um die Wuchernde Narbe herum heimisch sind. Sie befindet sich im südlichen Teil des Kraters.', },
    {'Sammelt 8 Blutkappenpilze und 8 Gorishistachel und kehrt zu Torwa Pfadfinder im Krater von Un\'Goro zurück.', },
  },
  [9053] = {
    'Eine bessere Zutat',
    {'Genau wie ich befürchtet hatte - das Gift ist einfach zu schwach für eine solch mächtige Kreatur.|n|nUm ein Gift von ausreichender Potenz zu entwickeln, werdet Ihr Euch auf den Grund des Tempels von Atal\'Hakkar begeben müssen. Enträtselt dort das Geheimnis des Altars und nehmt dem Wächter eine Fäulnisranke ab. Der Tempel ist gefährlich und es wird vermutlich erforderlich sein, Gefährten mitzubringen.|n|nKehrt zu mir zurück, wenn Ihr fertig seid.', },
    {'Beschafft Euch eine Fäulnisranke von dem Wächter auf dem Grund des Versunkenen Tempels und kehrt zu Torwa Pfadfinder zurück.', },
  },
  [9054] = {
    'Tunika des Gruftpirschers',
    {'Ich habe eine Verwendung für den Panzer der Gruftbestie gefunden. Ich bin in der Lage, ein extrem leichtes und äußerst tödliches Rüstungsset anzufertigen, indem ich die Fragmente von Gruftbestien mit einigen entweihten Rüstungsteilen aus Naxxramas kombiniere.|n|nBringt mir die benötigten Gegenstände und ich werde eine Rüstung für Euch anfertigen, wie man sie auf dieser Welt noch nicht gesehen hat!', },
    {'Jäger Leopold bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch eine Tunika des Gruftpirschers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Tunika, 25 kampfzerschlissene Kettenstücke, 4 Arkanitbarren und 3 geschmeidige unverwüstliche Bälge.', },
  },
  [9055] = {
    'Beinschützer des Gruftpirschers',
    {'Ich habe eine Verwendung für den Panzer der Gruftbestie gefunden. Ich bin in der Lage, ein extrem leichtes und äußerst tödliches Rüstungsset anzufertigen, indem ich die Fragmente von Gruftbestien mit einigen entweihten Rüstungsteilen aus Naxxramas kombiniere.|n|nBringt mir die benötigten Gegenstände und ich werde eine Rüstung für Euch anfertigen, wie man sie auf dieser Welt noch nicht gesehen hat!', },
    {'Jäger Leopold bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Beinschützer des Gruftpirschers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Beinschützer, 20 kampfzerschlissene Kettenstücke, 3 Arkanitbarren und 5 geschmeidige unverwüstliche Bälge.', },
  },
  [9056] = {
    'Kopfstück des Gruftpirschers',
    {'Ich habe eine Verwendung für den Panzer der Gruftbestie gefunden. Ich bin in der Lage, ein extrem leichtes und äußerst tödliches Rüstungsset anzufertigen, indem ich die Fragmente von Gruftbestien mit einigen entweihten Rüstungsteilen aus Naxxramas kombiniere.|n|nBringt mir die benötigten Gegenstände und ich werde eine Rüstung für Euch anfertigen, wie man sie auf dieser Welt noch nicht gesehen hat!', },
