  [11788] = {
    'Eine Schraube lockern',
    {'Okay, denke, wir sind bereit, den vorletzten Angriff zu starten... Bevor Ihr jedoch Mechazod den Garaus machen könnt, müsst Ihr zuerst seine Leutnants auseinandernehmen!|n|nIhr findet Twonkie, ED-210, Max Kawummso und den Zermalmer jeweils an der West-, Nord-, Zentral- und Südstation.|n|nDreht einfach an den Ventilen bei den Stationen herum, um ihr Vorhaben zu sabotieren und sie hervorzulocken. Ihr könnt sie nicht übersehen: Bei jeder Station gibt es ein Drehlicht.', },
    {'Nehmt Twonkie, ED-210, Max Kawummso und den Zermalmer auseinander und meldet Euch anschließend bei Jinky Flügelirre.', },
  },
  [11789] = {
    'Ein Soldat in Not',
    {'Ihr da! Bitte, ich brauche Eure Hilfe. Dieser Soldat wird dem Gift der Gruftbestie erliegen, wenn wir nicht sofort handeln.|n|nIch konnte die Wirkung des Giftes verlangsamen, doch ohne eine angemessene Menge Gegengift kann ich es nicht neutralisieren.|n|nMir wurde eine neue Lieferung Gegengift versprochen, die mit der letzten Sendung der Sturmbrecher aus dem Süden hätte ankommen sollen. Begebt Euch ins Innere ihres Frachtraums und sucht nach einer Kiste mit Material für Erste Hilfe.|n|nBeeilung, $C! Wir können es uns nicht leisten, weitere Männer unnötig sterben zu lassen.', },
    {'Sanitäter Hagedorn außerhalb der Valianzfeste möchte, dass Ihr Euch ins Innere des Laderaums der Sturmbrecher begebt und Hagedorns Gegengift aus einer Kiste mit Vorräten für Erste Hilfe beschafft.', },
  },
  [11790] = {
    'Kultisten unter uns',
    {'Auf diesem Altar befinden sich alle Markierungen des Kults der Verdammten. Es scheint, als hätten Fanatiker vom Festland es bis nach Nordend geschafft. Es wäre vielleicht klug, den Kapitän des Schiffs darüber in Kenntnis zu setzen.|n|nVielleicht befindet er sich über Deck.', },
    {'Sprecht mit Kapitän "Linksdatsch" Gaffelsegel an Deck der Sturmbrecher in der Valianzfeste.', },
  },
  [11791] = {
    'Benachrichtigt Arlos',
    {'Wir müssen General Arlos so schnell wie möglich davon in Kenntnis setzen. Ich kenne den Hauptmann schon eine ganze Weile und, glaubt mir, er ist einer von der vorsichtigeren Sorte.|n|nWer weiß, wie viele Kultisten in anderen Schiffen in unsere Siedlungen hier in Nordend geschmuggelt wurden? Die Sache könnte verheerende Folgen haben.', },
    {'Sprecht mit General Arlos im inneren Bereich der Valianzfeste.', },
  },
  [11792] = {
    'Feinde des Lichts',
    {'Nun macht mal halblang. Ich weiß nicht, wie es Euch geht, $C, aber mich konnten die Worte des Generals nicht so wirklich überzeugen. Sie klangen so unsicher... als wären sie nicht die seinen.|n|nIrgendetwas stimmt hier nicht. All unsere Versuche, gemeinsam an der Sache zu arbeiten, wurden blockiert und verzögert. Es ist an der Zeit, das Ganze etwas selbstständiger anzugehen.|n|nWenn wir mehr über die Kultisten in der Festung herausfinden möchten... dann sollten wir vielleicht denjenigen nachgehen, die sich außerhalb befinden.|n|nBerichten unseres Geheimdienstes zufolge gibt es nördlich von hier eine kleine Gruppe von ihnen, welche die Geißel in ihrem Treiben unterstützt. Findet heraus, ob sie irgendwelche Hinweise bei sich tragen.', },
    {'Herold Vurenn möchte, dass Ihr die Kultisten der Nekrolyten in der Nähe von Fernhain gen Norden der Valianzfeste bekämpft und ihnen das Kommuniqué der Kultisten abnehmt.', },
  },
  [11793] = {
    'Weitere Ermittlungen',
    {'Ich befürchte, dass es sich hier um eine Angelegenheit handelt, die ich einem meiner Agenten übertragen muss... jemanden, der im Geheimen operieren kann. Behaltet das Beweisstück bei Euch und bringt es zu Verteidigerin Yaala im Gasthaus. |n|nSagt ihr, dass ich Euch geschickt habe, und sprecht mit niemanden sonst über diese Sache. Wir wissen nicht, wer alles für den Kult arbeiten könnte.', },
    {'Bringt das Kommuniqué der Kultisten zu Verteidigerin Yaala im Gasthaus der Valianzfeste.', },
  },
  [11794] = {
    'Die Jagd ist eröffnet',
    {'Ich habe es zu meiner persönlichen Angelegenheit gemacht, so viel wie möglich über den hinterlistigen Todeskult herauszufinden, einschließlich ihrer Geheimsprache.|n|nVurenn hatte recht. Die Kultisten sprechen von getarnten Agenten, die sich an verschiedenen Orten innerhalb der Valianzfeste aufhalten sollen: den unteren Docks, dem Gefängnis im Inneren der Festung und der Küche des Gasthauses.|n|nNehmt dieses Okular und verwendet es an den soeben erwähnten Orten. Jeder, der erst vor Kurzem die nekromantischen Kräfte des Kults benutzt hat, wird von einer dunklen Aura umhüllt sein. Kümmert Euch um die Kultisten, bevor etwas Schlimmes geschieht.', },
    {'Verteidigerin Yaala möchte, dass Ihr das Okular des Exorzisten an den drei genannten Orten in der Valianzfeste einsetzt, um die Mitglieder des Kults der Verdammten zu enttarnen und zu töten.', },
  },
  [11795] = {
    'Notfallprotokoll: Sektion 8,2. Absatz C',
    {'Verletzt oder nicht, als Schwadronenkommandant bin ich dafür verantwortlich, die Insignien aller Piloten, die unter meinem Kommando gefallen sind, zu finden und zurückzubringen. In all den Jahren, die ich mit Kurbelzisch geflogen bin, ist es noch nie vorgekommen, dass wir das Siegel eines Piloten nicht zurückgebracht haben.|n|nAufgrund meiner Verletzung wäre es gefährlich für mich, außerhalb der Sicherheit des Wracks umherzustreifen, doch vielleicht wärt Ihr bereit, mir dabei zu helfen, die Insignien zurückzubekommen? In der Zwischenzeit werde ich Vorbereitungen treffen, um meine letzte Pflicht als Schwadronenkommandant zu erfüllen.', },
    {'Beschafft 6 Insignien eines Piloten von Kurbelzisch von den Leichnamen der Aufklärungspiloten von Kurbelzisch und bringt sie zurück zu Iggy "Trudelflug" Zinkenwechsel bei den Siedenden Teichen.', },
  },
  [11796] = {
    'Notfallprotokoll: Sektion 8,2. Paragraph D',
    {'Es gibt nur noch eine Sache zu tun, bevor ich endlich wieder zur Landebahn zurückkehren und meinen Bericht erstatten kann. Laut Abschnitt 8.2, Paragraph D des Notfallprotokolls muss ich so viele Wrackteile wie nur möglich beseitigen, um zu verhindern, dass unsere Technologie in feindliche Hände gerät.|n|nIch werde Euch meine Fackel geben, wenn Ihr mir dabei helfen wollt, diesen letzten Dienst zu erfüllen. Ich will gar nicht daran denken, was die Goblins der Horde alles anstellen würden, wenn sie diese Maschinen in die Finger bekämen.', },
    {'Iggy "Trudelflug" Zinkenwechsel möchte, dass Ihr die Wracks im Osten, Süden und Nordwesten beseitigt.', },
  },
  [11797] = {
    'Die Belagerung',
    {'Aber, aber, aber. Es ist gut zu sehen, dass Arlos schwere Geschütze auffährt.|n|nVersteht mich nicht falsch - unsere Jungs geben ihr Bestes, doch kämpfte jemand Eures Kalibers an ihrer Seite, stünden die Chancen sehr gut, dass sich die Schlacht zu unseren Gunsten wendet. Ich bin mir nicht sicher, wie lange wir noch gegen diese untoten Neruber durchhalten können.|n|nWas würdet Ihr davon halten, dort hinauszugehen und ein paar dieser Kriecher für mich zu töten? Zeigt den Jungs, wie\'s gemacht wird.', },
    {'Unteroffizier Hammerberg möchte, dass Ihr 6 Gruftkriecher auf den Sanden von Nasam außerhalb der Valianzfeste tötet.', },
  },
  [11798] = {
    'Der Ritzelmeister',
    {'Ritzelmeister Mechazod ist wahnsinnig! Er meint, er schenke uns Unsterblichkeit, indem er den sogenannten \'Fluch des Fleisches\' entfernt, doch was er in Wahrheit aus uns macht, sind mechanische Sklaven!|n|n$N, wir sind uns ziemlich sicher, dass er sich immer noch in der Pumpstation draußen in der Mitte des Teiches gen Osten aufhält.|n|nDas letzte Mal, als wir ihn sahen, war er ganz oben im Führerhäuschen. Geht dort hoch und untersucht sein Zeug.|n|nIhr müsst Euch Mechazod stellen, wenn die Gnome... nein, wenn überhaupt jemand überleben soll!', },
    {'Untersucht das Handbuch des Ritzelmeisters und bringt Mechazods Kopf zu Kurbelzisch Vollgas zurück.', },
  },
