  [13034] = {
    'Der Zeuge und der Held',
    {'Als ich meine Reisen in Nordend angetreten hatte, besuchte ich die Boreanische Tundra und traf zum ersten Mal mit den Taunka zusammen. Dort erzählte mir Windzähmerin Barah die Geschichte von Sturmhuf und seinem Kampf gegen den Nordwind, dem uralten Gegner seines Volkes.|n|nIch machte mich auf zu den Sturmgipfeln, um mehr über diesen Helden in Erfahrung zu bringen, aber seltsamerweise scheinen die Leute in Tunka\'lo nichts über ihn zu wissen.|n|nVielleicht werden uns die eigenen Aufzeichnungen des Camps mehr Aufschluss darüber geben. Findet und lest die historischen Schriftrollen, die verteilt im ganzen Lager aufbewahrt werden und berichtet mir anschließend, was Ihr erfahren habt.', },
    {'Xarantaur im Camp Tunka\'lo möchte, dass Ihr Euch die erste, zweite und dritte historische Schriftrolle durchlest.', },
  },
  [13035] = {
    'Lokens Lakaien',
    {'Für meinen Bruder war der Angriff auf die Terrasse der Schöpfer keine halbherzige Aktion: Er entsandte eine Legion von Eisenzwergen und einige seiner mächtigsten Leutnants dorthin.|n|nBenutzt das Horn der Sturmgipfel, um die Irdenen zu Hilfe zu rufen und Lokens Diener zu vernichten.|n|nIm Inneren der Halle des Formers gen Norden werdet Ihr den Riesen Eisenfaust finden. Die anderen befinden sich tiefer im Inneren der Terrasse der Schöpfer, jenseits der Treppen im Nordwesten.', },
    {'Thorim möchte, dass Ihr Eisenfaust in der Halle des Formers erschlagt. Außerdem sollt Ihr Halefnir den Zischenden und Duronn den Runenbesetzten auf der Terrasse der Schöpfer töten.', },
  },
  [13036] = {
    'Ehre über alles',
    {'Es war ein langer, beschwerlicher Weg bis zu unserer Errettung, $Gjunger:junge:c; $C. Wir sind bei unseren Kämpfen durch ganze Kontinente, ja sogar Welten gezogen, um an diesen Punkt zu gelangen. Jetzt stehen wir vor unserer größten Herausforderung: Die Vernichtung des Lichkönigs und seiner Geißel.|n|nAber leider müssen wir diese Schlacht getrennt voneinander durchstehen. Die Horde und die Allianz stehen kurz vor einem Krieg und können uns keine Unterstützung zusichern. Wir müssen in unserer Sache unnachgiebig bleiben! Was bleibt uns auch anderes übrig?|n|nWerdet Ihr Euch unserer Sache anschließen? Lasst uns Eure Stärke zuteilwerden, $C! Mein Kommandant Entari erwartet Euch auf seinem Posten.', },
    {'Meldet Euch bei Kreuzzugskommandant Entari in der Argentumvorhut in Eiskrone.', },
  },
  [13037] = {
    'Erinnerungen an Sturmhuf',
    {'Als mir der bronzene Drachenschwarm die Unsterblichkeit schenkte und mich auf den Weg des Zeugen schickte, vertraute mir Nozdormu den Lehrenhammer an.|n|nDie Reaktion des Hammers auf Euren Fund sagt mir, dass die Zeit hier nicht richtig verlaufen ist und wir die richtige Zeitlinie wiederherstellen müssen.|n|nWir müssen sie finden. Im Nordwesten liegt die Frostschollentiefe, eine uralte Begräbnishöhle der Krieger von Tunka\'lo. Sucht den Geist von Häuptling Schnellspeer, Sturmhufs Bruder. Fragt ihn, was ihm vom Kampf seines Bruders gegen den Nordwind in Erinnerung geblieben ist.', },
    {'Sprecht mit Häuptling Schnellspeer in der Frostschollentiefe und kehrt dann zu Xarantaur ins Camp Tunka\'lo zurück.', },
  },
  [13038] = {
    'Verzerrungen in der Zeit',
    {'Dieses Grab der Tunka\'lo-Krieger sollte ein ruhevoller Ort sein, der vor den Schrecken der Elemente geschützt ist.|n|nDie Frostschollentiefe wurde von einer seltsamen Kraft befallen, die die Geister der Gefallenen in Unruhe versetzt und die Erinnerungen an mein Leben durcheinander bringt.|n|nEs ist, als würden unsere Taten und Erinnerungen aus der Geschichte getilgt.|n|nZu Lebzeiten war dieses Totem ein Zeichen meiner Autorität. Es ist die letzte wirkliche Verbindung, die ich noch zu dieser Welt habe. Nehmt es und nutzt es, um die Ruhe dieses Grabes wiederherzustellen, und bringt es danach ins Camp Tunka\'lo zurück.', },
    {'Nutzt das Totem des Häuptlings, um 4 Frostschollenklüfte zu schließen, und bringt es danach zu Xarantaur ins Camp Tunka\'lo.', },
  },
  [13039] = {
    'Die Vorhut verteidigen',
    {'Wir können nicht in dem Tempo weitermachen. Sobald die Bresche in die Luft gesprengt wurde, öffneten sich die Fluttore. Seitdem fällt die Geißel über uns her, und es nimmt kein Ende!|n|nWir brauchen jede fähige Hand, um die Angreifer abzuwehren. Geht da raus und leistet Euren Beitrag, Freund. Tötet so viele Monster, wie Ihr nur könnt!', },
    {'Kreuzfahrerlord Dalfors von der Argentumvorhut in Eiskrone hat Euch gebeten, 15 Neruber der Vergessenen Tiefen zu töten.', },
  },
  [13040] = {
    'Heilmittel für das Unheilbare',
    {'Täglich steigt die Anzahl verwundeter Soldaten. Sie werden von einer Art Gift niedergestreckt, das uns bisher gänzlich unbekannt ist. Was auch immer diese Neruber da in ihren Giftdrüsen haben, es ist unheilbar und bringt den Tod! Bisher konnten wir nur die Verbreitung des Gifts im Körper des Opfers verlangsamen. Wir müssen jedoch ein Heilmittel finden!|n|nWagt Euch in Richtung Nordwesten zum Tal außerhalb des Vorpostens und tötet die Neruber der Vergessenen Tiefen. Nehmt ihre Giftdrüsen und bringt sie zu mir.', },
    {'Vater Gustav aus der Argentumvorhut in Eiskrone bittet Euch, ihm 10 Giftdrüsen der Vergessenen Tiefen zu bringen.', },
  },
  [13041] = {
    'Die Lieferung abfertigen',
    {'Freut mich, dass Ihr hier seid! Eine Lieferung leuchtender Elfenbeinfiguren muss so schnell wie möglich nach Lorenhall geschickt werden und mir fehlt noch ein Chalzedon für das Auge der letzten Statuette.|n|nBringt mir einen davon und ein Juwelierssymbol von Dalaran gehört Euch.', },
    {'Bringt einen Chalzedon zu Jonas Timotheus in Dalaran.', },
  },
  [13042] = {
    'Tief im Inneren des Kellergewölbes',
    {'Tief im Inneren des Kellergewölbes im Nordosten heckt ein verrückter Wissenschaftler, bekannt unter dem Namen Dr. Maböse, etwas aus, das seinem Namen alle Ehre macht.|n|nDer Doktor bekam die Erlaubnis des Lichkönigs, Experimente mit Varguls durchzuführen - den Vrykul, die im Kampf fallen, als unwürdig erachtet werden und dann der Geißel anheim fallen.|n|nWir müssen seiner Arbeit ein Ende machen, meine Wahrsager konnten ihn jedoch nicht aufspüren. Allerdings hat er einen Assistenten.|n|nPrügelt aus seinem Lehrling alle Informationen heraus und lasst ihn dann verschwinden.', },
    {'Die Knochenhexe aus Njorndar bittet Euch, Informationen bezüglich der Pläne von Dr. Maböse aus Lehrling Osterkilgr herauszuprügeln.|n|nTötet den Lehrling anschließend.', },
  },
  [13043] = {
    'Das Ganze ist größer als die Summe seiner Teile',
    {'Ihr öffnet den Folianten und erblickt verschiedene widerwärtige Illustrationen dessen, was der Doktor "die ultimative Waffe" nennt!|n|nDer Prototyp Nergeld ist offenbar der gewaltige Fleischriese, der am Ende der naheliegenden Hallen des Grauens steht.|n|nWürde eine Armee dieser Kreationen gebaut, dann wäre das der sichere Untergang. Wir können nur sicherstellen, dass dies nicht geschieht, indem wir Dr. Maböse vernichten!|n|nVielleicht zeigt sich der Doktor, wenn Ihr die Kontrolle über dieses Konstrukt übernehmt?', },
    {'Besteigt Nergeld und übernehmt die Kontrolle. Verteidigt ihn vor den Bewohnern der Hallen des Grauens, bis sich Dr. Maböse zeigt.|n|nNutzt Nergeld, um den Doktor zu vernichten, und kehrt dann zur Knochenhexe nach Njorndar zurück.', },
  },
  [13044] = {
    'Falls es Überlebende gibt...',
    {'Jenseits des Tals der Echos westlich von hier und auf der anderen Seite der Bresche liegt das erste Lager der Geißel in Eiskrone, das Geißelholme genannt wird. Wir haben dort gut gekämpft und viele Krieger der Geißel getötet, aber letzten Endes wurden wir zum Rückzug gezwungen. Dabei mussten wir viele Soldaten zurücklassen, über deren Schicksal uns nichts bekannt ist.|n|nFalls es Überlebende gibt, müssen wir versuchen, sie zu retten. Wenn Ihr diesen Südostpfad nehmt, gelangt Ihr zu Penumbrius, einem Verbündeten des bronzenen Drachenschwarms und Hüter der Protodrachenbrut. Sucht ihn auf und bittet ihn um Hilfe.', },
    {'Sprecht mit Penumbrius in der Argentumvorhut in Eiskrone.', },
  },
  [13045] = {
    'Ins wilde Grün',
    {'Wir werden tun, was wir können, um Euch zu helfen, $N. Die Protobrut hat sich bereit erklärt, Euch durch die Bresche nach Geißelholme zu fliegen. Rettet alle gefangenen Argentumkreuzfahrer, die Ihr findet. Bringt sie sodann ins Feldlazarett der Vorhut, das sich inmitten dieser Basis befindet.|n|nWählt eine der Argentumhimmelsklauen aus dem Gatter hinter mir aus und fliegt los!|n|nGeißelholme liegt nordwestlich von hier auf der anderen Seite des Tals der Echos, jenseits der großen Bresche.', },
    {'Rettet 3 gefangene Argentumkreuzfahrer aus Geißelholme und bringt sie ins Feldlazarett im Zentrum des Argentumvorpostens. Berichtet Hochlord Tirion Fordring danach von Eurem Erfolg.', },
  },
  [13046] = {
    'Arngrim füttern',
    {'Arngrims Hunger war legendär.|n|nSogar im Tode gleicht sein Gesichtsausdruck dem eines Hungernden. Ihr stellt fest, dass Euer Magen anfängt zu knurren, wenn Ihr ihn auch nur anseht.|n|nEs heißt, dass er im Leben nie wirklich satt war und dass es absolut nichts gab, was er nicht gegessen hätte. Ihr fragt Euch, ob es einen Weg gibt, den alten König zu füttern.|n|nWährend Ihr noch überlegt, fällt einer von Arngrims gewaltigen gefrorenen Zähnen aus, prallt von seinem Bart ab und landet in Eurer Hand.', },
    {'Ihr sollt 5 körperlose Jormungar an Arngrim verfüttern und dann zu Arngrims gefrorenem Abbild in Dun Niffelem zurückkehren.|n|nIhr müsst ins Uralte Wintertal gehen und Arngrims Zahn auf die dort herumstreunenden Jormungar anwenden. Sobald sie eine körperlose Form angenommen haben, müsst Ihr sie bekämpfen, bis sie geschwächt sind.', },
  },
  [13047] = {
    'Die Abrechnung',
    {'Loken hat meine Frau getötet und meine Anhänger gegen mich aufgewiegelt. Er hat mir alles genommen, was ich hatte, doch heute... wird sich das ändern.|n|nHeute werden wir unseren geheiligten Boden zurückerobern. Heute... wird Loken sterben.|n|nTrefft mich auf der Brücke in der Nähe des Tempels der Weisheit gleich südwestlich von Ulduar. Ich werde dies zu Ende bringen, so oder so.|n|nIch brauche Euch als Zeugen. Ihr werdet mir nicht helfen - das ist eine persönliche Angelegenheit.|n|nBenachrichtigt Jokkum, den König der Frostriesen, sobald die Sache erledigt ist. Er ist ein guter Freund und wird wissen, was zu tun ist.', },
    {'Trefft Euch mit Thorim in der Nähe des Tempels der Weisheit. Berichtet König Jokkum in Dun Niffelem, wie der Kampf ausgegangen ist.', },
  },
  [13048] = {
    'Wo die Zeit aus dem Ruder lief',
    {'Der Lehrenhammer kann uns helfen, den Schaden, den die Zeitlinie genommen hat, zu korrigieren, aber dafür müssen wir erst herausfinden, wo die Geschichte das erste Mal verändert wurde.|n|nDank Häuptling Schnellspeer und Eurer Erkenntnisse aus der Frostschollentiefe wissen wir, dass die Veränderung etwa zur Zeit von Sturmhufs Tod stattfand.|n|nNun müsst Ihr zur Heulenden Senke nördlich des Lagers gehen und die Grabstätten untersuchen, die von den Dienern des Nordwinds schon zerstört wurden. Der Lehrenhammer wird auf die Artefakte aus Sturmhufs Zeit reagieren und sich selbst auf die richtige Zeit einstellen.', },
    {'Setzt den Lehrenhammer bei den Taunka-Relikten ein, um ihn an Sturmhufs Zeit anzupassen. Kehrt zu Xarantaur nach Camp Tunka\'lo zurück, wenn er auf 6 Relikte aus Sturmhufs Zeit eingestimmt wurde.', },
  },
  [13049] = {
    'Die Waffen des Helden',
    {'Noch wurden nicht alle Aufzeichnungen des Lagers manipuliert. Meine Helfer haben mir dabei geholfen, diese Aufzeichnungen mit der wahren Zeitfolge zu finden.|n|nSie stimmen darin überein, dass Sturmhuf ein Ehrenbegräbnis bei den Dorfältesten unten in der Heulenden Senke im Norden bekam.|n|nDie meisten der dortigen Gräber wurden bereits zerstört und ihr Inhalt als Trophäen von den Wesen des Nordwinds entnommen. Begebt Euch in die Senke und versucht, Sturmhufs Rüstung und Speer von den Saaten des Sturms zu erlangen, die diese Dinge für sich beansprucht haben.', },
    {'Findet Sturmhufs Rüstung und Speer und bringt die Gegenstände zu Xarantaur in Camp Tunka\'lo zurück.', },
  },
  [13050] = {
    nil,
    {'Wenn ich die Armee meines Bruders angreifen will, muss ich irgendwie um sie herumkommen.|n|nIch habe meinen Reitdrachen schon vor Jahren freigelassen. Veranus war prächtig, die Anführerin ihrer eigenen Brut - zu der sie jetzt zurückgekehrt ist.|n|nEs wird sehr schwer werden, sie zu finden, aber es gibt vielleicht eine Möglichkeit. Aus Stolz hat sie ihr altes, leeres Nest behalten. Sie ist nur noch vom Namen her eine Brutmutter, da sie das Brutalter bereits überschritten hat.|n|nBringt mir kleine Eier aus den anderen Nestern in der Nähe von Brunnhildar. Ich habe da so eine Idee.', },
    {'Thorim aus dem Tempel der Stürme möchte, dass Ihr ihm 5 kleine Eier von den Protodrachen bringt, die auf den Gipfeln in der Umgebung von Brunnhildar hausen.', },
  },
  [13051] = {
    'Territoriale Vergehen',
    {'Veranus ist stolz wie kein anderes Tier, das ich je gekannt habe. Sie hat noch immer ihr altes Nest und achtet darauf, dass es nicht von einem jüngeren Protodrachen in Besitz genommen wird.|n|nLegt die Eier, die Ihr gesammelt habt, in ihr Nest. Ihr findet es auf dem kleinen Gipfel südöstlich von hier.|n|nIch müsste sie unter Kontrolle haben, bevor sie Euch aus lauter Wut umbringt; zumindest hoffe ich das.', },
    {'Legt die gestohlenen Protodracheneier in das Nest der Brutmutter und kehrt dann zu Thorim in den Tempel der Stürme zurück.', },
  },
  [13052] = {
    'Luftüberwachung',
    {'Ihr wart Wes eine große Hilfe, als Ihr mit ihm diese Flugmaschine wieder zum Laufen gebracht habt.|n|nWenn Ihr uns weiterhin helfen wollt: Es gibt da eine ungewöhnliche, von Nordwesten aufziehende Wettererscheinung. Ich verfüge bereits über einen einsatzbereiten Piloten, aber er braucht leider einen Copiloten.|n|nWenn Ihr Euch dem gewachsen fühlt, könnt Ihr den Flug zum Landeplatz am See nehmen. Sagt Vic, dass ich Euch geschickt habe.', },
    {'Professorin Kalvert möchte, dass Ihr den Flug zum Landeplatz am See nehmt und dort mit Pilot Vic sprecht.', },
  },
  [13053] = {
    'Suche nach Überlebenden',
    {'Gretchen Zischelfunken möchte meine Flugmaschine nutzen, um nach Überlebenden ihrer Expedition zu suchen. Offenbar glaubt sie, dass diese im Dorf im Norden gefangen gehalten werden.|n|nDas Problem ist, dass ich keinen Copiloten habe. Wenn Ihr mir aushelfen wollt, dann zeige ich Euch gern ein oder zwei hilfreiche Tricks.|n|nWas sagt Ihr, $N? Abgemacht?', },
    {'Helft Zak Wackelspross, den Testflug zu beenden.', },
  },
  [13054] = {
    'Der vermisste Fährtenleser',
    {'Ich kann Euch nicht guten Gewissens in die Worghöhle gehen lassen, ohne Euch zu warnen, dass wir zuvor schon jemanden dorthin geschickt haben, der jedoch nicht zurückgekehrt ist.|n|nWir rechnen mit dem Schlimmsten, aber vielleicht ist er auch noch am Leben. Solltet Ihr ihm helfen können, zu uns zurückzukehren, wären wir Euch sehr dankbar - Fährtenleser Val\'zij ist einer unserer wenigen Jäger.', },
    {'Sucht in Gimoraks Bau östlich der Absturzstelle Grom\'ash nach Fährtenleser Val\'zij.', },
  },
  [13055] = {
    'Höhlenmedizin',
    {'Wie schön, ein freundliches Gesicht zu sehen, vielleicht das Letzte, das ich seh\'n werde.|n|nEiner dieser Jormungar hat mich gestochen, bevor ich entkommen konnte. Mein Körper fühlt sich schon ganz taub an, Mann.|n|nIch brauch\'ne Giftdrüse, um ein Gegengift herzustellen, und außerdem einige der Höhlenpilze, die hier wachsen... sie werden das Gift verlangsamen.|n|nBitte beeil dich - hab nich\' mehr viel Zeit.', },
    {'Fährtenleser Val\'zij hält sich in Gimoraks Bau auf und möchte, dass Ihr ihm 1 Giftdrüse der Jormungar und 8 Höhlenpilze bringt.', },
  },
  [13056] = {
    'Für Rache ist immer Zeit',
    {'Ich müsste vorerst zurechtkommen, $N. Aber ich möchte dich noch um \'nen Gefallen bitten.|n|nIch wäre diesen Würmern nie in die Hände gefallen, wenn meine Windnatter Heesha nicht vom gemeinsten Worg, den ich seit langer Zeit gesehen habe, getötet worden wäre.|n|nMach dir um mich keine Sorgen; mir wird es besser gehen, wenn der Worg keinen Atemzug mehr von sich gibt. Du solltet ihn weiter drinnen in der Höhle finden', },
    {'Fährtenleser Val\'zij möchte, dass Ihr Gimorak in Gimoraks Bau tötet.', },
  },
  [13057] = {
    'Die Terrasse der Schöpfer',
    {'Es ist Zeit, $N. Ich bin jetzt bereit, mich Loken zu stellen.|n|nBegeben wir uns nun zur Terrasse der Schöpfer, wo wir auf die Truppen meines Bruders treffen werden. Der Narr wird noch bereuen, sich je mit mir angelegt zu haben.', },
    {'Findet Thorim an der südöstlichen Kante der Terrasse der Schöpfer gleich nordwestlich von Dun Niffelem.', },
  },
  [13058] = {
    'Die Windrichtung ändern',
    {'Zu guter Letzt haben wir alles, was wir brauchen, um das wieder gut zu machen, was der Nordwind und seine Anhänger angerichtet haben. Ihr habt den Lehrenhammer auf Sturmhuf selbst und seine Zeit ausgerichtet.|n|nHier, nehmt wieder den Hammer an Euch, geht zum Tempel des Lebens, schlüpft mit seiner Hilfe in Sturmhufs Rolle und stellt Euch dem Nordwind. Doch wisset: Um die Zeitlinie wieder herzustellen, muss Sturmhuf sterben, sobald der Nordwind geschwächt ist.|n|nSobald dies geschehen ist, müsst Ihr das Horn des Elementarfurors an Euch bringen und mit ihm den Nordwind vernichten.', },
    {'Reist mithilfe des Lehrenhammers in der Zeit zurück, schlüpft in Sturmhufs Rolle und stellt Euch dem Nordwind. Beschafft Euch das Horn des Elementarfurors, sobald Sturmhuf gestorben ist und es fallengelassen hat, und benutzt es, um den Nordwind zu erledigen. Kehrt danach zu Xarantaur ins Camp Tunka\'lo zurück.', },
  },
  [13059] = {
    'Rache für die Vargul',
    {'Ich habe zur Herrin des Schwertes gebetet, auf dass jemand kommen und meinen Gegner vernichten möge. Than Illskar muss dafür büßen, was er mir angetan hat!|n|nIch war einst der Champion von Than Ufrang dem Mächtigen. Während meines Kampfes um die Vormachtstellung in Valhalas hat mich Illskar mit dunkler Magie sabotiert, woraufhin ich verloren habe und zu dem wurde, was ich jetzt bin.|n|nDer Than und seine Champions befinden sich unten im Kreis des Leidens. Fordert ihn in meinem Namen heraus. Besiegt ihn.|n|nBringt ihm die Qualen bei, die auch ich ertragen muss!', },
    {'Bethod Feigr im Kellergewölbe wünscht, dass Ihr sein Schwert zu Boden werft, um Than Illskar im Kreis des Leidens herauszufordern und zu töten.', },
  },
  [13060] = {
    'Wenn alles andere versagt',
    {'Also... also ich denke nicht, dass wir in diesen Bergen gut Fuß fassen werden.|n|nGlaubt mir, ich bin sicherlich niemand, der schnell aufgibt... doch wenn ich an gefrorene Motoren, gemeine Vrykulweiber, territoriale Möchtegerndrachen und das halbe Dutzend anderer Widerlinge in der Gegend denke, dann muss ich wirklich sagen: daraus wird nichts.|n|nLasst Euch davon jedoch nicht entmutigen! Nur weil wir nicht Fuß fassen können, heißt das noch lange nicht, dass wir Euch nicht dorthin bekommen werden... Reisen ohne Wiederkehr sind ziemlich einfach, wenn man die Sache nur richtig angeht.|n|n<Ricket deutet mit einem Nicken in Richtung einiger in der Nähe befindlicher Raketen.>', },
    {'Sprecht mit Ricket, um mithilfe von Rickets D16-angetriebenem Lieferungsgerät tiefer in das Gebiet der Sturmgipfel vorzudringen.', },
  },
  [13061] = {
    'Bereit für den Ruhm',
    {'Das war\'s dann also. Ich werde mich jetzt um Euren Bären kümmern, Ihr werdet ihn nicht mehr benötigen. Der große Drakkensryd wird Eure nächste Herausforderung sein.|n|nSagt Euren Freunden Lebewohl und bringt alles ins Reine, bevor Ihr loszieht. Denn Ihr werdet entweder siegreich zurückkehren... oder gar nicht.', },
    {'Sprecht mit Lok\'lira der Greisin in Brunnhildar.', },
  },
  [13062] = {
    'Lok\'liras Abschiedsgeschenk',
    {'Ihr wart uns eine großartige Mitstreiterin, $N. Doch nun kommt Eure wahre Prüfung. Dazu werdet Ihr Können, Mut und ein wenig Glück benötigen.|n|n<Lok\'lira flicht eine Haarsträne in Euer Haar ein.>|n|nNun könnt Ihr nicht mehr versagen, Schwester. Sprecht mit Gretta der Schiedsfrau. Sie wird sich um Eure Abreise kümmern.', },
    {'Sprecht mit Gretta der Schiedsfrau in Brunnhildar.', },
  },
  [13063] = {
    'Für würdig befunden',
    {'Ihr hattet dort Erfolg, wo viele versagten, Schwester. Ob es nun Eurer Stärke, Eurem Mut oder einfach nur Eurem Glück zu verdanken ist, wird sich noch zeigen.|n|nGeht zurück zum Dorf und sucht nach Astrid Bjornrittar. Erzählt ihr, was Ihr erreicht habt. Doch seid gewarnt: Sie ist nicht so leicht zu beeindrucken.', },
    {'Brijana möchte, dass Ihr nach Brunnhildar geht und mit Astrid Bjornrittar sprecht.', },
  },
  [13064] = {
    'Rivalität unter Geschwistern',
    {'Sif? Bist du es wirklich?|n|nNein? Nur $Gein:eine:r; $R? Aber einen Augenblick lang...|n|nGenug davon! Die Visionen meiner Sif haben mich schon viel zu lange gequält. Es wird Zeit, sie zu rächen und ihr Andenken zu ehren.|n|nMein Bruder muss bezahlen!', },
    {'Thorim möchte, dass Ihr Euch seine Geschichte anhört.', },
  },
  [13065] = {
    'Urahne Ohanzee',
    nil,
    nil,
  },
  [13066] = {
    'Urahne Yurauk',
    nil,
    nil,
  },
  [13067] = {
    'Urahne Chogan\'gada',
    nil,
    nil,
  },
  [13068] = {
    'Eine Erzählung von Heldenmut',
    {'Ist es möglich, dass Ihr die Lobpreisungen an unseren verschollenen Helden gehört habt?|n|nKreuzfahrer Bridenbrad hat den Angriff gegen die Geißel an der Zerbrochenen Front unterstützt, als die Armee der Untoten über sie hereinbrach. Die Masse der Verbündeten floh, aber Bridenbrad allein kehrte zurück und trug mehr als ein Dutzend Männer in Sicherheit, einen nach dem anderen, inmitten des Gemetzels.|n|n$C, er ist seitdem nicht wieder zurückgekehrt. Man hat gesehen, wie er weit nach Nordosten zog, Richtung Stille Nachtwache. Bringt ihn wieder hierher, damit ich ihm für seinen Mut Respekt zollen kann.', },
    {'Hochlord Tirion Fordring auf dem Kreuzfahrerturm wünscht, dass Ihr den Helden Kreuzfahrer Bridenbrad in der Stillen Nachtwache im Nordosten der Eiskrone aufspürt. Seine Feuergrube wird aus der Luft gesehen wahrscheinlich der deutlichste Hinweis auf seinen Aufenthaltsort sein.', },
  },
  [13069] = {
    'Schießt sie ab!',
    {'Jotunheim verfügt über Luftabwehr, sowohl Protodrachenreiter als auch Harpunenkanonen. Sie haben diese an ihren nördlichen und westlichen Verteidigunszonen konzentriert, weil sie dort am verwundbarsten sind.|n|nLasst uns ihre Verteidigung gegen sie selber richten!|n|n<Der Springer starrt Euch mit seinem einen Auge durchdringend an und kichert hysterisch.>|n|nBringt eine Harpunenkanone auf den Plattformen, welche die Klippen auf jeder Seite von Valhalas gen Südwesten überragen, unter Eure Kontrolle. Kümmert Euch um die Protodrachen und ihre Reiter. Schießt sie ab!', },
    {'Der Springer beim Schattengewölbe möchte, dass Ihr eine Schnellfeuerharpune von Jotunheim dazu verwendet, 15 Protodrachen von Jotunheim mitsamt ihren Reitern abzuschießen.', },
  },
  [13070] = {
    'Eine Kaltfront nähert sich',
    {'Der Frost des Todes regt sich im Westen und droht, unsere Herzen und Seelen in dieser Ödnis einzufrieren, uns an ihren dunklen Meister zu binden. Aber wir werden nicht weichen und wir werden kämpfen!|n|nDie Vorbereitungen sind angelaufen. Meldet Euch bei Belagerungsmeister Fezzik am Haupttor für Euren Auftrag.', },
    {'Meldet Euch bei Belagerungsmeister Fezzik bei der Argentumvorhut in Eiskrone.', },
  },
  [13071] = {
    'Ekel mag Feuer!',
    {'Ekel mag Feuer! Ekel mag Protodrachen!|n|n<Die Monstrosität klatscht aufgeregt in die Hände.>|n|nKleiner $N jetzt gehen nach Jotunheim un\' stehlen schöne Protodrache in Njorndar. Lass\' Protodrache schöööne Feuers auf Häuser von Jotunheim machen!', },
    {'Ekel im Schattengewölbe möchte, dass Ihr einen Protodrachen von Njorndar stehlt und ihn benutzt, um 8 Vrykulgebäude in der weiteren Jotunheimregion in Brand zu setzen.|n|nDie Festung Balargarde kann aufgrund ihrer Beschaffenheit nicht in Flammen gesetzt werden.', },
  },
  [13072] = {
    'Ein Held verbleibt',
    {'Ich weiß, warum Ihr gekommen seid... sie haben Euch geschickt um mich zurückzubringen, aber das darf nicht geschehen. Ich trage die Seuche des Todes in mir, $C, und werde mein Schicksal nicht mit jenen teilen, die mir nahe stehen. Nein, ich werde hier bleiben. |n|nIch bedaure nur, was aus mir werden wird, wenn der Tod Besitz von mir ergriffen hat. Den Tod selbst fürchte ich nicht, aber ich verabscheue den Gedanken daran, dem Verräter Arthas zu dienen.|n|nVerlasst mich... und stellt sicher, dass niemand anderes nach mir suchen wird. Ihr würdet mir einen wahren Undienst erweisen, wenn Ihr jemanden der Seuche, die ich trage, aussetzen würdet.', },
    {'Bringt die Neuigkeiten von Kreuzfahrer Bridenbrads Schicksal zu Hochlord Tirion Fordring in den Kreuzfahrerturm.', },
  },
  [13073] = {
    'Eine Bitte an den Bewahrer',
    {'Es gibt jene in dieser Welt, die auf Kräfte stoßen, die frei sind von den Grenzen unserer sterblichen Hüllen - Kräfte der Wiederherstellung, des Lebens und des Lichts. Und Bridenbrad? Das ist kein durchschnittlicher Mann... sein Heldenmut und seine Hingabe sind ein leuchtendes Vorbild. Wir können nur hoffen, dass eines dieser Wesen einschreiten wird und diesen Helden vor einem Schicksal, das schlimmer als der Tod ist, bewahren wird.|n|nGeht nun und sprecht mit der Erzdruidin Lilliandra in der Argentumvorhut... erbittet den Zugang zur Mondlichtung und ersucht Bewahrer Remulos um Hilfe.', },
    {'Hochlord Tirion Fordring im Kreuzfahrerturm hat Euch gebeten, dass Ihr bei der Erzdruidin Lilliandra Zugang erbittet und mit Bewahrer Remulos redet.', },
  },
  [13074] = {
    'Hoffnung im Smaragdgrünen Alptraum',
    {'Was wir brauchen, gibt es nur im Smaragdgrünen Traum... Eicheln, die mit einem mächtigen, regenerativen Zauber durchtränkt sind. Viele Orte in diesem heiligen Sumpf sind eng mit dem Traum verbunden und mein Schrein ist einer davon.|n|nIch werde Euch in den Traum schicken, um ein paar jener Eicheln zu besorgen. Seid aber gewarnt, $C, denn diese Methode, den Traum zu betreten, ist gefährlich, und es ist recht wahrscheinlich, dass Ihr von Alpträumen heimgesucht werdet.|n|nBeeilt Euch und findet ein paar Eicheln. Verlasst anschließend meinen Schrein oder kneift Euch selbst in den Arm, um in unsere Welt zurückzukehren.', },
    {'Bewahrer Remulos auf der Mondlichtung hat Euch aufgetragen, den Smaragdgrünen Traum zu betreten und 3 Smaragdgrüne Eicheln zu besorgen.|n|nVerlasst die nähere Umgebung des Schreins von Remulos, um nach Azeroth zurückzukehren.', },
  },
  [13075] = {
    'Remulos\' Segen',
    {'Ich werde ein Portal öffnen, das Euch zu dem Druiden, der Euch hergesandt hat, zurückbringen wird. Meine besten Wünsche begleiten Euch und Euren Kreuzfahrer. Ich hoffe, diese Eichel wird ihn läutern und somit vor dem abscheulichen Schicksal der Seuche bewahren können.|n|nLebt wohl, $R.', },
    {'Kehrt mit der Smaragdeichel zu Kreuzfahrer Bridenbrad in die Stille Nachtwache in Eiskrone zurück.', },
  },
  [13076] = {
    'Es bleibt noch Zeit',
    {'Ich fühle mich erfrischt... erneuert... aber die Seuche hält mich immer noch in ihrer eisigen Umklammerung. Ich bin Euch dennoch auf ewig dankbar für die Mühen, die Ihr für mich, einen völlig Fremden, auf Euch genommen habt. Zumindest habt Ihr mir so einige wertvolle Stunden verschafft, während derer ich nicht als grässlicher Untoter die Welt verpeste.|n|nIch danke Euch, $C. Bitte richtet auch Tirion meinen Dank aus und lasset ihn wissen, dass es mir eine Ehre war, an seiner Seite zu dienen.', },
    {'Kehrt zu Hochlord Tirion Fordring in den Kreuzfahrerturm zurück und berichtet ihm von den Effekten der Smaragdeichel.', },
  },
  [13077] = {
    'Die Berührung eines Aspekts',
    {'Die Drachenkönigin, Alexstrasza, besitzt Magien über das gesamte Sein. In der Vergangenheit hat sie große Feuer benutzt, um Untote zu verbrennen und frisches, neues Leben an ihrer Stelle zu erschaffen. Ihre Kräfte sind vielleicht in der Lage, auch unseren Bridenbrad zu retten.|n|nAlexstrasza hat sich im Wyrmruhtempel in der Drachenöde eingerichtet. Bitte geht zu Ihr und bittet sie demütigst in meinem Namen um Hilfe.', },
    {'Erbittet die Hilfe von Alexstrasza der Lebensbinderin im Wyrmruhtempel.', },
  },
  [13078] = {
    'Dahlias Tränen',
    {'In dieser dunklen Stunde werde ich nicht diejenige sein, die einen Helden des Lichts im Stich lässt.|n|nWir werden etwas Heiliges brauchen, um auf die Rettung Eures Bridenbrads hoffen zu können... Das Überbleibsel eines frommen Wesens, das Opfer eben dieser Seuche wurde.|n|nGeht nun zum heiligen Boden in den Gängen außerhalb meines Rubindrachenschreins, dorthin, wo der Kampf stattfinden wird. Meine Rubinhüter werden herabfliegen und den Boden unter untoten Füßen mit Flammen überziehen. Ihr werdet dann Zeuge neuen Lebens sein. Dieses neue Leben wird auch Dahlias Tränen bergen - bringt sie mir.', },
    {'Alexstrasza die Lebensbinderin im Wyrmruhtempel verlangt von Euch, dass Ihr Dahlias Tränen aus dem Boden bergt, der von den Flammen der Rubinbehüter frisch geläutert ist.', },
  },
  [13079] = {
    'Alexstraszas Segen',
    {'Ihr müsst verstehen, $Gjunger :junge :r; $R, dass das Läutern eines Körpers zugunsten des Lebens etwas ist, das durchaus in meiner Macht liegt... die Seuche des Untodes zu entfernen, ohne den Körper in Mitleidenschaft zu ziehen, entzieht sich jedoch meiner Kontrolle.|n|nWenn dieser Bridenbrad das Leuchtfeuer des Lichts ist, wie Ihr es beschwört, wird er vielleicht die Läuterung überstehen und sich erholen, aber ich kann nicht mit Gewissheit sagen, ob dies die Erlösung sein wird, nach der Ihr strebt. Nehmt sie und geht mit all meinem Segen.', },
    {'Bringt den Atem von Alexstrasza zu Kreuzfahrer Bridenbrad in die Stille Nachtwache in Eiskrone.', },
  },
  [13080] = {
    'Die Hoffnung stirbt zuletzt',
    {'<Bridenbrad erhebt die Hand zum Gruße, während er wieder zu Atem kommt.>|n|nEs war fast so schmerzhaft, wie es ausgesehen hat, aber es fühlte sich an, als wäre ein Teil der Verderbnis aus meinem Körper gebrannt worden. Anscheinend ist die Seuche jedoch so einfach nicht zu bezwingen.|n|n$C, danke für alles, was Ihr getan habt. Eure selbstlosen Taten haben meine Hoffnung genährt, dass es noch immer viel Gutes in der Welt gibt...Ich kann nun gehen, ohne Furcht davor, dass die Dunkelheit in meiner Abwesenheit obsiegen wird.|n|nIhr könnt nun ohne Bedenken gehen.', },
    {'Kehrt zu Hochlord Tirion Fordring in den Kreuzfahrerturm zurück und berichtet ihm von den Effekten des Atems von Alexstrasza.', },
  },
  [13081] = {
    'Der Wille der Naaru',
    {'Ich bin dankbar für alles, was Ihr für uns getan habt, $N. Ich habe noch einen letzten Auftrag für Euch... ein letztes Glimmen der Hoffnung für einen Paladin, der jede Erlösung verdient, die wir ihm bieten können.|n|nGeht nun nach Shattrath und sprecht mit dem Naaru A\'dal. Er ist seit langem ein Leuchtfeuer des Lichts und mächtiger Verbündeter der Paladine. Berichtet ihm von Bridenbrad und erbittet jede Hilfe, die er Euch zu geben vermag.|n|nIch kann nicht genug betonen, wie wichtig es ist, dass Ihr Euch beeilt... Ich befürchte, dass unserem Kreuzfahrer nicht mehr viel Zeit in dieser Welt verbleibt.', },
    {'Erbittet die Hilfe von A\'dal in Shattrath in den Wäldern von Terokkar.', },
  },
  [13082] = {
    'A\'dals Segen',
    {'Ich bin erfreut, dass Ihr zu mir gekommen seid, $N. Ich weiß von Kreuzfahrer Bridenbrad und von Euren Reisen, um ihn zu erretten. Bridenbrads Heldenmut hat eine bemerkenswerte Selbstlosigkeit in Euch zum Vorschein gebracht, und das ist an sich schon ein Wunder.|n|nDas Licht wird sich um die Seinen kümmern. Ich werde Bridenbrad meinen Segen zuteilwerden lassen, auf dass er die Verderbnis des Untodes nicht länger zu ertragen braucht. Ich werde Euch zurück nach Dalaran schicken und Ihr werdet zu ihm zurückkehren. Wisset, dass ich stets bei Euch sein werde.', },
    {'Kehrt zu Kreuzfahrer Bridenbrad in die Stille Nachtwache in Eiskrone zurück.', },
  },
  [13083] = {
    'Licht im Dunkeln',
    {'<Kreuzfahrer Bridenbrads Wappenrock liegt am Boden der Truhe und beginnt leicht zu flattern, als der heulende Wind seinen Weg hineinfindet.>|n|nTirion wird dieses letzte Überbleibsel des großen Kreuzfahrers an sich nehmen wollen.', },
    {'Bringt Kreuzfahrer Bridenbrads Wappenrock zu Hochlord Tirion Fordring in den Kreuzfahrerturm.', },
  },
  [13084] = {
    'Demoliert Jotunheim',
    {'Lasst uns doch mal sehen, ob wir noch weiter die Entschlossenheit der Vrykul schwächen können, $N.|n|nIch möchte, dass Ihr jeden Tag nach Jotunheim geht und ihre Banner verbrennt. Das mag sich nach einer unbedeutenden Sache anhören, aber wenn sie ihre Heimatstadt jeden Tag demoliert sehen, wird dies ihre Moral weit mehr schwächen, als es jede physische Gewaltmaßnahme je könnte.|n|nZumindest aber... kann es nicht schaden.', },
    {'Herzog Lankral beim Schattengewölbe möchte, dass Ihr 10 Banner der Vrykul verbrennt.', },
  },
  [13085] = {
    'Vaelen ist zurückgekehrt',
    {'Ich habe soeben diesen inkompetenten Narren, Vaelen den Geschundenen, gesehen, wie er in das Schattengewölbe geschlichen ist.|n|nGeht und stellt sicher, dass er seinen Fehler wieder gutmacht und mir meine Todesritter zurückbringt!', },
    {'Redet mit Vaelen dem Geschundenen im Schattengewölbe.', },
  },
  [13086] = {
    'Die letzte Verteidigungslinie',
    {'Ich habe die Verteidigungen der Basis aktiviert, $C! Auf jedem der vier Türme der Vorhut ist eine einziehbare Kanone des Argentumkreuzzugs angebracht, von Vater Gustav persönlich geweiht. Ihr müsst zu einer der Kanonen fliegen und sie bemannen. Benutzt sie, um den Ansturm der Geißel zu vernichten, den der Lichkönig hergesandt hat.|n|nEine Warnung noch, die Geißel wird zweifelsohne ihre Frostwyrms schicken, um die Türme zu belagern. Blast sie vom Himmel! Wenn sie die Türme und Wälle der Basis zerstören, sind wir geliefert!', },
    {'Benutzt eine Argentumkanone, um 100 Angreifer der Geißel zu vernichten. Außerdem müsst Ihr 3 Frostbrutzerstörer töten.|n|nSolltet Ihr erfolgreich sein, kehrt zu Belagerungsmeister Fezzik zurück.', },
  },
  [13087] = {
    'Kochkunst des Nordens',
    {'Also was machen wir denn da, wenn Ihr keinen Eintopf für mich habt? Ich hab\' HUNGER! Ihr könnt mir zumindest ein wenig kühles Fleisch bringen, damit ich mir selbst \'nen Eintopf machen kann! Wenn Ihr das macht, dann kann ich Euch ein Rezept geben, damit Ihr Euren eigenen machen könnt. JETZT GEHT UND BRINGT MIR EIN BISSCHEN FLEISCH!', },
    {'Bringt 4 Stück kühles Fleisch zu Brom Bräugießer in Valgarde. Jede Bestie in Nordend verfügt über dieses Fleisch.', },
  },
  [13088] = {
    'Kochkunst des Nordens',
    {'Wir haben eine Menge neuer Rekruten hier und die Jungs sind hungrig! Wenn Ihr mir ein wenig kühles Fleisch für einen Eintopf besorgen könntet, würde ich Euch beibringen, wie Ihr selbst einen für Euch kochen könnt.', },
    {'Bringt Rollick MacKreel in der Valianzfeste 4 Stück kühles Fleisch. Alle Bestien in Nordend verfügen über dieses Fleisch.', },
  },
  [13089] = {
    'Kochkunst des Nordens',
    {'Nichts wärmt die Knochen besser, als ein aus lebenden Wesen zubereiteter Eintopf. Bringt mir etwas von dem kühlen Fleisch der hiesigen jämmerlichen Bestien und ich werde Euch zeigen, wie man einen warmen Eintopf zubereitet.', },
    {'Bringt 4 Stück kühles Fleisch zu Thomas Kolichio im Hafen der Vergeltung. Alle Bestien in Nordend verfügen über dieses Fleisch.', },
  },
  [13090] = {
    'Kochkunst des Nordens',
    {'Die Krieger der Kriegshymnenoffensive brauchen etwas in ihren Bäuchen, um stark zu bleiben. Falls Ihr mir ein wenig kühles Fleisch von den Rhinozerossen oder den anderen Bestien besorgt, könnte ich ein bisschen Eintopf für sie kochen. Wenn Ihr mir helft, werde ich Euch das Rezept verraten.', },
    {'Bringt Orn Zarthuf in der Kriegshymnenfeste 4 Stück kühles Fleisch. Alle Bestien in Nordend verfügen über dieses Fleisch.', },
  },
  [13091] = {
    'Die Kunst, ein Wasserschrecken zu sein',
    {'Die Wasserschleuse vor meiner Höhle wimmelt nur so von Elementaren, die von den Vrykulzauberern erst noch gezähmt werden müssen. Ich werde Euch einen Trick zeigen, wie man für kurze Zeit Besitz von ihnen ergreifen kann, und Ihr werdet sie dafür einsetzen, Chaos und Zerstörung in Jotunheim anzurichten!|n|n<Die Banshee-verseuchte Vrykul entzieht der Luft Magie und berührt Eure Stirn.>|n|nGeht nun und öffnet die Tür zur Schleuse. Ein Wasserschrecken wird hervorkommen und Ihr werdet ihn kontrollieren, um unsere Feinde zu zerstören!', },
    {'Die Knochenhexe in Njorndar möchte, dass Ihr Besitz von einem Wasserschrecken ergreift und ihn dazu benutzt, 10 Vrykul in der Umgebung von Jotunheim zu töten.|n|nIn Frage kommende Vrykul sind Schlafwächter, Krieger von Jotunheim, Wassermagier der Mjordin, Speerschwestern von Njorndar und Varguls von Valhalas.', },
  },
  [13092] = {
    'In den Knochen lesen',
    {'Einer der Vorteile davon, Besitz von dieser Kreatur zu ergreifen, ist, dass ich Zugriff auf all ihre Kräfte habe. Als Knochenhexe und Runenleserin hat sie die Macht, Knochen auszuwerfen und daraus jemandes Schicksal zu lesen.|n|n<Die Knochenhexe schmunzelt.>|n|nGut für Euch, dass es in meiner Macht steht, das Resultat zu beeinflussen.|n|nBringt mir die Knochen von Vrykul, die Ihr hier in Jotunheim tötet, und ich werde sie so werfen, dass Ihr Euer Schicksal bestimmen könnt.', },
    {'Die Knochenhexe in Njorndar hat Euch aufgetragen, 15 Vrykulknochen zu besorgen.', },
  },
  [13093] = {
    'In den Knochen lesen',
    nil,
    nil,
  },
  [13094] = {
    'Schämen sie sich denn nicht?',
    {'Erzmagier Berinand hat mir seine Forschungsergebnisse über das Arkanomikon geliehen - eine Art Karte, die Malygos versucht zusammenzufügen.|n|nIch habe den Fehler begangen, mich mit einer Gruppe Abenteurer der Horde darüber zu unterhalten, und nun ist es weg!|n|nSie müssen es gewesen sein, $C. Bitte beschafft das Buch.', },
    {'Abbild von Kriegsmagierin Kaitlyn möchte, dass Ihr Berinands Forschungsergebnisse beschafft.', },
  },
  [13095] = {
    'Schämen sie sich denn nicht?',
    {'Erzmagier Berinand hat mir seine Forschungsergebnisse über das Arkanomikon geliehen - eine Art Karte, die Malygos versucht zusammenzufügen.|n|nIch habe den Fehler begangen, mich mit einer Gruppe Abenteurer der Allianz darüber zu unterhalten, und nun ist es weg!|n|nSie müssen es gewesen sein, $C. Bitte beschafft das Buch.', },
    {'Abbild von Kriegsmagierin Kaitlyn möchte, dass Ihr Berinands Forschungsergebnisse beschafft.', },
  },
  [13096] = {
    'Gal\'darah muss bezahlen',
    {'Hast du\'s gesehen, Mann?|n|nEs muss wohl das Furchtbarste gewesen sein, das ich jemals gesehen hab\'. Der große Akali: vor meinen Augen getötet. Schrecklich...|n|nIch habe geschworen, mich nicht in die Sache hier verwickeln zu lassen. Ich soll nur beobachten. Doch das kann so nicht hingenommen werden! Gal\'darah muss dafür bezahlen!|n|nGeh nach Gundrak und such ihn auf. Komm zu mir zurück, sobald Akalis Tod gerächt wurde, Mann.', },
    {'Tol\'mar in Dubra\'Jin möchte, dass Ihr Gal\'darah in Gundrak erschlagt.', },
  },
  [13097] = {
    'Offene Rechnungen',
    {'Der Prophet von Akali mag diese Welt zwar nicht mehr belästigen, doch es gibt noch immer Arbeit zu tun.|n|nAkalis Blut - ein Großteil davon - hat jemand anderem Macht verliehen und es ist dieser jemand, von dem die eigentliche Gefahr ausgeht.|n|nSchnell, $N, macht Euch von Gundrak aus in nördliche Richtung nach Dubra\'Jin und sprecht mit Tol\'mar. Er wird Euch diesbezüglich weitere Anweisungen geben können.', },
    {'Har\'koa möchte, dass Ihr mit Tol\'mar in Dubra\'jin sprecht.', },
  },
  [13098] = {
    'Für die Nachwelt',
    {'Gundrak ist verloren, Mann.|n|nDie Geschichte wird sich vor deinen Augen wiederholen. Wenn Trolle sich gegen ihre eigenen Götter wenden, dann ist\'s das sichere Ende. Es ist nur eine Frage der Zeit.|n|nWenn wir die Ereignisse bis ins Detail erfassen können, dann würde sich vielleicht verhindern lassen, dass zukünftige Generationen denselben dunklen Weg einschlagen.|n|nWenn du mutig genug bist, dann geh nach Gundrak und such nach Hinweisen darüber, was dazu geführt hat, dass das Reich der Drakkari so enden musste.', },
    {'Chronistin Bah\'Kini in Dubra\'Jin möchte, dass Ihr nach Gundrak geht und 6 Geschichtstafeln der Drakkari sammelt.', },
  },
  [13099] = {
    'Nur ma\' nachsehen',
    {'Unten aus Gundrak waren fürchterliche Geräusche zu hören. In letzter Zeit sind sie lauter geworden und auch häufiger zu hören.|n|nMeine langjährige Schülerin konnte von ihrem Posten westlich von Gundrak aus die Ereignisse erfassen. Hättet Ihr vielleicht Zeit, bei Ihr nachzusehen, was los ist?', },
    {'To\'kini möchte, dass Ihr mit Bah\'kini in Dubra\'Jin sprecht.', },
  },
  [13100] = {
    'Energieerfüllter Pilzhackbraten',
    {'Wir haben eine wichtige Lieferung zu machen! Orton Bennet bei Kuriositäten & Meer braucht einen Pilzhackbraten.|n|nBeschafft also einige energieerfüllte Pilze aus der Kanalisation von Dalaran und ein wenig kühles Fleisch und bereitet sie in Eurer Bratenform zu. Liefert den fertigen Hackbraten bei Orton ab.', },
    {'Benutzt Eure Bratenform, um aus 4 energieerfüllten Pilzen aus der Kanalisation von Dalaran und 2 Stück kühlem Fleisch einen Pilzhackbraten herzustellen und bringt das Resultat zu Orton Bennet bei Kuriositäten & Meer auf dem Runenweberplatz in Dalaran.', },
  },
  [13101] = {
    'Versammlung im Zauberkasten',
    {'Arille Azurblick im Zauberkasten hat bald eine Versammlung bei sich und braucht so fix wie möglich ein Festmahl!|n|nIhr müsst einige nordische Eintöpfe und einen Krug Wein aus dem Käseladen namens "Noch ein Gläschen" in der Mitte von Dalaran beschaffen. Der Besitzer des Käseladens schuldet mir den Wein - Ihr werdet ihn irgendwo im Laden finden.|n|nBringt die Eintöpfe und den Wein zu Arille.', },
    {'Bringt 4 nordische Eintöpfe, die Ihr selbst gekocht habt, und einen Krug Wein aus dem Käseladen in Dalaran zu Arille Azurblick im Zauberkasten auf dem Runenweberplatz in Dalaran.', },
  },
  [13102] = {
    'Kanaleintopf',
    {'Ajay Grün, der Gastwirt in der Kanalisation von Dalaran, braucht einen Gemüseeintopf für seine Kunden, da ihnen dort unten das Essen ausgeht.|n|nSammelt 4 Kristallsangkarotten aus dem Kristallsangwald, gebt sie gemeinsam mit 4 Stück kühlem Fleisch in einen Kochtopf und lasst die Zutaten kochen.|n|nDen Kristallsangwald könnt Ihr über die Portalkammer in der östlichen Ecke des Runenweberplatzes erreichen.|n|nBringt den Gemüseeintopf zu Ajay, sobald er fertig gekocht ist.', },
    {'Gebt 4 Kristallsangkarotten aus dem Kristallsangwald gemeinsam mit 4 Stück kühlem Fleisch in einen Kochtopf und lasst die Zutaten kochen.|n|nBringt den fertigen Gemüseeintopf anschließend zu Gastwirt Ajay Grün in die Kanalisation von Dalaran.', },
  },
  [13103] = {
    'Käse für Leuchtegold',
    {'Ranid Leuchtegold im Lederladen in Dalaran hatte plötzlich ein heftiges Verlangen nach Wein und Käse.|n|nIm Laden "Noch ein Gläschen" in der Mitte von Dalaran gibt es ein Regal mit Käse - holt Euch etwas davon und sammelt dann noch einige halbvolle Weingläser ein, die überall in Dalaran verstreut herumstehen. Danach sollt Ihr den Wein in eine Flasche füllen und diesen dann gemeinsam mit dem Käse Ranid servieren.|n|nWir denken, dass er den Unterschied nicht bemerken wird.', },
    {'Kombiniert die leere Käseplatte mit reifem Dalaranlimburger aus dem Käseladen "Noch ein Gläschen" und mit 6 halbvollen Dalaranweingläsern, die auf den Tischen in Dalaran gefunden werden können.|n|nBringt die Wein- und Käseplatte anschließend zu Ranid Leuchtegold im Lederladen auf dem Handelsmarkt der Magier.', },
  },
  [13104] = {
    'Noch einmal in die Bresche, Held',
    {'Die Vorhut ist gesichert. Wir haben das Tal der Echos zurückerobert und die Netzwälle, die den Zugang zur Bresche blockiert hatten, eingerissen. Jetzt ist die Zeit reif, Geißelholme anzugreifen und unsere Präsenz in Eiskrone zu festigen. Die Kriegsfront bewegt sich weiter!|n|nIch habe den Schwarzen Wächter um seine Hilfe bei unserem Angriff auf Geißelholme gebeten. Seine Kenntnisse der Geißel werden sich als unschätzbar wichtig für unsere Anstrengungen erweisen.|n|nGeht nun und meldet Euch bei ihm am Zelt außerhalb der Bresche, nordwestlich von hier.', },
    {'Meldet Euch beim Schwarzen Wächter im Tal der Echos gleich außerhalb der Bresche.', },
  },
  [13105] = {
    'Noch einmal in die Bresche, Held',
    {'Die Vorhut ist gesichert. Wir haben das Tal der Echos zurückerobert und die Netzwälle, die den Zugang zur Bresche blockiert hatten, eingerissen. Jetzt ist die Zeit reif, Geißelholme anzugreifen und unsere Präsenz in Eiskrone zu festigen. Die Kriegsfront bewegt sich weiter!|n|nIch habe den Schwarzen Wächter um seine Hilfe bei unserem Angriff auf Geißelholme gebeten. Seine Kenntnisse der Geißel werden sich als unschätzbar wichtig für unsere Anstrengungen erweisen.|n|nGeht nun und meldet Euch bei ihm am Zelt außerhalb der Bresche, nordwestlich von hier.', },
    {'Meldet Euch beim Schwarzen Wächter im Tal der Echos gleich außerhalb der Bresche.', },
  },
  [13106] = {
    'Die Schwarzwacht',
    {'Die Geißel verfügt über eine große Einrichtung, genannt die Fleischwerke, die zur Produktion von Monstrositäten und Fleischriesen dient. Wenn wir sie ausschalten könnten, würden wir den Lichkönig eines Gutteils seiner Armee berauben.|n|nIch habe Dunkelreiterin Arly in die Gegend entsandt. Sie hat westlich von Corp\'rethar auf einem Höhenrücken eine kleine Basis errichtet, die Schwarzwacht, von wo aus sie die Fleischwerke überblicken kann. Ich habe gehört, dass der Argentumkreuzzug jemanden entsandt hat, um ihre Bemühungen dort zu koordinieren, aber die Dunkelreiterin wird wissen, was zu tun ist.', },
    {'Sprecht mit Dunkelreiterin Arly in der Schwarzwacht in Eiskrone.', },
  },
  [13107] = {
    'Senfwürstchen!',
    {'Erzmagier Pentarus sieht sich gelegentlich gerne ein Kampfballspiel an und möchte auch gehen, doch er braucht für die Reise etwas zu essen.|n|nIhr müsst seinen Picknickkorb mit 4 selbstgekochten Rhinowürstchen und 4 Zweigen wilden Senfs füllen; letzterer ist in den grasbewachsenen Bereichen der Stadt zu finden.|n|nBringt ihm seinen Picknickkorb, damit er bereit für das große Spiel ist.', },
    {'Füllt den leeren Picknickkorb mit 4 Rhinowürstchen, die Ihr selbst gekocht habt, und 4 Zweigen wilden Senfs, der in den grasbewachsenen Bereichen der Stadt zu finden ist.|n|nBringt den Picknickkorb anschließend zu Erzmagier Pentarus bei Krasus\' Landeplatz in Dalaran.', },
  },
  [13108] = {
    'Koste es, was es wolle!',
    {'So oder so, Loken wird sterben.|n|nSelbst wenn ich ihm alle Gliedmaßen einzeln herausreißen muss, wird er schon bald für seine Taten büßen.|n|nSolltet Ihr vor mir auf ihn treffen, so mögen der Ruhm und die Ehre für seine Niederlage Euer sein.|n|nKehrt zu mir mit seiner verlogenen Zunge zurück und erhaltet dafür meinen Dank und Segen.', },
    {'König Jokkum in Dun Niffelem wünscht, dass Ihr die Hallen der Blitze betretet und Loken besiegt. Danach sollt Ihr mit Lokens Zunge zu König Jokkum zurückkehren.', },
  },
  [13109] = {
    'Diametral entgegengesetzt',
    {'Ich muss offen zu Euch sein, $Gkleiner:kleine:r; $R. Meine Leute sind nicht mehr dieselben, seit unsere Bande mit Thorim gebrochen sind.|n|nAls ihr Anführer wünsche ich mir nichts sehnlicher, als dass ihre Herzen heil werden und unsere Freundschaft mit dem Sturmherren erneuert wird. Mit Eurem Sieg über Fjorn habt ihr einen Schritt auf diesem Weg getan. Ich wünschte, Ihr würdet einen weiteren Schritt wagen...|n|nIn den Hallen der Blitze sitzt jemand, der selbst mächtiger als Fjorn ist und sich an unserer Existenz stört. Volkhan wird nicht eher ruhen, bis entweder er oder wir ausgelöscht sind.', },
    {'König Jokkum in Dun Niffelem wünscht, dass Ihr die Hallen der Blitze betretet und Volkhan besiegt.', },
  },
  [13110] = {
    'Die rastlosen Toten',
    {'Nicht all unsere Soldaten haben es lebend aus Geißelholme herausgeschafft. Viele wurden getötet und in entartete Reflexionen ihres früheren Selbst verwandelt. Das ist der Weg der Geißel. Für jene armen Verdammten gibt es keinen ewigen Frieden. Wir müssen ihren Seelen Ruhe verschaffen.|n|nReist durch die Bresche nach Geißelholme und tötet die skelettartigen wiedererweckten Kreuzfahrer. Sprenkelt dieses Weihwasser über ihre Gebeine, so dass ihre Seelen befreit werden können.', },
    {'Vater Gustav im Tal der Echos in Eiskrone möchte, dass Ihr die Überreste von wiedererweckten Kreuzfahrern mit Weihwasser benetzt, um 10 ruhelose Seelen zu befreien.', },
  },
  [13111] = {
    'Einzigartig',
    {'Hör zu, Mann.|n|nAuf den ersten Blick sieht es so aus, als würde es sich hierbei wieder um die alte Leier handeln: Trolle, die verbotene Kräfte anzapfen und genau die Wesen zerstören, die sie eigentlich anbeten sollten.|n|nIn dem Fall stimmt es zwar auch, doch an diesen Drakkari ist etwas Besonderes dran. Wenn das, was ich herausgefunden habe, stimmt, dann gibt es in Gundrak einen ganz besonderen Golem - einen Golem, wie er noch nie zuvor erschaffen wurde!|n|nDu willst ein Abenteuer, Mann? Dann geh nach Gundrak und bring mir ein Stück dieses Golems, damit ich es untersuchen kann.', },
    {'Chronistin Bah\'Kini in Dubra\'Jin möchte, dass Ihr nach Gundrak geht und ein Fragment des Kolosses der Drakkari beschafft.', },
  },
  [13112] = {
    'Energieerfüllter Pilzhackbraten',
    {'Orton Bennet bei Kuriositäten & Meer braucht \'nen Pilzhackbraten.|n|nBeschafft also \'n paar energieerfüllte Pilze aus der Kanalisation von Dalaran und etwas kühles Fleisch und bereitet sie in Eurer Bratenform zu. Das Resultat liefert Ihr dann bei Orton ab.|n|nWenn der Rat mir nur erlauben würd\', meine Gnomspezialität aufzutischen, ich würd\' ihnen schon zeigen, was wirklich lecker ist!', },
    {'Benutzt Eure Bratenform, um aus 4 energieerfüllten Pilzen aus der Kanalisation von Dalaran und 2 Stück kühlem Fleisch einen Pilzhackbraten herzustellen und bringt das Resultat zu Orton Bennet bei Kuriositäten & Meer auf dem Runenweberplatz in Dalaran.', },
  },
  [13113] = {
    'Versammlung im Zauberkasten',
    {'Kannst du dir das vorstellen? Die Horde hat Kannibalismus für illegal erklärt... das ist einfach nicht richtig, sag ich dir! Ich schätze mal, dass ich mich auf meine Arbeit konzentrieren sollte, wenn wir schon eine Bestellung haben.|n|nArille Azurblick im Zauberkasten hat viele Besucher bei sich, Mann. Er braucht einige nordische Eintöpfe und einen Krug Wein aus dem Käseladen in der Mitte von Dalaran.|n|nBring also den Wein und den Eintopf zu Arille.', },
    {'Bringt 4 nordische Eintöpfe und einen Krug Wein aus dem Käseladen in Dalaran zu Arille Azurblick im Zauberkasten auf dem Runenweberplatz in Dalaran.', },
  },
  [13114] = {
    'Kanaleintopf',
    {'Wir haben eine neue Bestellung. Der Gastwirt in der Kanalisation von Dalaran braucht einen Gemüseeintopf, weil seine Kunden nich\' so viel zu essen haben, Mann.|n|nDer hat deswegen nach einem Gemüseeintopf gefragt, da er meinen letzten Eintopf mit dem Gnom drin nicht so gern gemocht hat. Besorg dir 4 Kristallsangkarotten aus dem Kristallsangwald, koch sie gemeinsam mit 4 Stück kühlem Fleisch und bring das Resultat anschließend zu Ajay.|n|nDu kannst den Wald über die Portalkammer in der östlichen Ecke des Runenweberplatzes erreichen.', },
    {'Gebt 4 Kristallsangkarotten aus dem Kristallsangwald gemeinsam mit 4 Stück kühlem Fleisch in einen Kochtopf und lasst die Zutaten kochen.|n|nBringt den Gemüseeintopf anschließend zu Gastwirt Ajay Grün in die Kanalisation von Dalaran.', },
  },
  [13115] = {
    'Käse für Leuchtegold',
    {'Ranid Leuchtegold im Lederladen verlangt es ordentlich nach Wein und Käse. Warum er keinen leckeren Gnom mag, versteh ich nicht.|n|nHol dir den Käse aus dem Käseladen in der Mitte von Dalaran und die halbvollen Weingläser, die auf den Tischen in der Stadt stehen. Geh danach zu Ranid und servier ihm Wein und Käse.|n|nDen Wein könnte man sozusagen als "Auslese" bezeichnen, Mann.', },
    {'Kombiniert die leere Käseplatte mit reifem Dalaranlimburger aus dem Käseladen "Noch ein Gläschen" und mit 6 halbvollen Dalaranweingläsern, die auf den Tischen in Dalaran gefunden werden können.|n|nBringt die Wein- und Käseplatte anschließend zu Ranid Leuchtegold im Lederladen auf dem Handelsmarkt der Magier.', },
  },
  [13116] = {
    'Senfwürstchen!',
    {'Erzmagier Pentarus schaut sich gerne sein verrücktes Kampfballspiel an, doch dafür braucht er auch was zu essen.|n|nDu musst seinen Picknickkorb mit 4 gekochten Rhinowürstchen und 4 Zweigen wilden Senfs füllen; letzterer ist in den grasbewachsenen Ecken der Stadt zu finden.|n|nFüll seinen Korb mit den leckeren Senfwürstchen auf, Mann.', },
    {'Füllt den leeren Picknickkorb mit 4 selbstgekochten Rhinowürstchen und 4 Zweigen wilden Senfs, der in den grasbewachsenen Bereichen der Stadt zu finden ist.|n|nBringt den Picknickkorb anschließend zu Erzmagier Pentarus bei Krasus\' Landeplatz in Dalaran.', },
  },
  [13117] = {
    'Wo kommen sie her?',
    {'Die unermüdlichen Lakaien des Lichkönigs arbeiten Tag und Nacht an der Erschaffung zahlloser neuer Monstrositäten und Fleischriesen da unten in den Fleischwerken.|n|nAber das war noch nicht alles. Mehr und mehr skelettene Arbeiter tauchen auf und beschleunigen die Arbeit noch zusätzlich.|n|nWenn wir nicht herausfinden, wo sie herkommen und wie sie so schnell arbeiten können, werden wir überrannt, bevor wir die Initiative übernehmen können. Sucht im Südosten und findet die Quelle dieser Skelette!', },
    {'Untersucht einen Beschwörungsaltar im östlichen Teil der Fleischwerke und berichtet dann Dunkelreiterin Arly bei der Schwarzwacht davon.', },
  },
  [13118] = {
    'Die Reinigung von Geißelholme',
    {'Die Geißel hat ihre Armeen gegen den Argentumkreuzzug gesandt und ist zurückgeschlagen worden. Was sie jetzt macht, nennt sich "zuschlagen und niederbrennen". Alle Gefangenen, die sie in Geißelholme gefangen halten, werden hingerichtet und als Diener des Lichkönigs wiederbelebt.|n|nOhne Zweifel wird der Argentumkreuzzug wünschen, dass Ihr seine Soldaten in Ehren verabschiedet. Etwas Derartiges werde ich nicht von Euch verlangen. Um zu siegen, müssen wir die Geißel unterschiedslos ausmerzen.|n|nZieht nach Geißelholme, nordwestlich durch die Bresche, und mäht alle nieder, die sich Euch in den Weg stellen.', },
    {'Der Schwarze Wächter im Tal der Echos möchte, dass Ihr 3 Hohepriester der Vergessenen Tiefen, 3 Unterkönige der Vergessenen Tiefen und 8 wiedererweckte Kreuzfahrer tötet.', },
  },
  [13119] = {
    'Zerstört die Altäre',
    {'Sie beschwören also ihre Arbeiter und Krieger an diesen Altären?|n|nDie werden als Erstes verschwinden müssen. Der Meisterbeschwörer sollte einen Stab haben, mit dem er das Portal aktivieren kann. Wenn Ihr ihn also tötet und seinen Stab nehmt, dann könnt Ihr mit ihm das Beschwörungsportal überladen und dessen Altar zerstören.|n|nFührt diese Prozedur bei allen vier Altären durch und kehrt zu mir zurück, sobald sie zerstört wurden.', },
    {'Tötet Meisterbeschwörer Zarod und benutzt seinen Beschwörerstab, um den ersten, zweiten, dritten und vierten Beschwörungsaltar zu zerstören. Habt Ihr diese Aufgabe erledigt, kehrt zu Dunkelreiterin Arly bei der Scharzwacht zurück.', },
  },
  [13120] = {
    'Todesblick',
    {'Die Fleischwerke sind eine gewaltige Operation, und es wird schwer, alles, was sich dort abspielt, im Auge zu behalten. Zum Glück habe ich einen Plan.|n|n<Arly holt eine Kugel aus den Falten ihres Umhangs hervor und zeigt sie Euch.>|n|nDies ist eine Kugel des Todesblicks. Mit ihr können wir die Aktionen der Geißel verfolgen und entscheiden, wie wir am besten zuschlagen.|n|nLegt diese Kugeln auf die Halterungen, die in drei äußerst wichtigen Bereichen zu finden sind: im Monstrositäten- und Fleischriesenlabor gen Südwesten und auch in der Gegend um den riesigen grünen Kessel weit im Westen.', },
    {'Benutzt die Kugel des Todesblicks, um Kugeln in die Kugelhalterung des Monstrositätenlabors, des Fleischriesenlabors und des Kesselbereichs zu legen. Kehrt anschließend zu Dunkelreiterin Arly in die Schwarzwacht zurück.', },
  },
  [13121] = {
    'Durch das Innere Auge',
    {'Wir müssen die Werkzeuge des Lichkönigs gegen ihn richten, wenn wir unseren nächsten Schritt in die Wege leiten wollen.|n|nHinter den Bergen im Südwesten liegt die Feste Kul\'galar. In ihr halten sich die Orakel von Jotunheim auf, die Befehle von ihrem Meister empfangen und andere durch das Auge des Lichkönigs ausspionieren.|n|nEs ist jenes Auge, zu dem Ihr Euch durchkämpfen müsst. Obwohl man es nicht dazu verwenden kann, den Schleier um die Eiskronenzitadelle zu durchdringen, solltet Ihr dennoch Wertvolles mit seiner Hilfe herausfinden können, so dass wir wissen werden, wie wir am besten weiter vorgehen.', },
    {'Die Knochenhexe in Njorndar hat Euch beauftragt, das Auge des Lichkönigs zu benutzen, um an Informationen zu gelangen.', },
  },
  [13122] = {
    'Der Geißelstein',
    {'Ein Geißelstein ist ein Gegenstand, der allen Einheiten der Geißel bei Geburt oder Erschaffung übergeben wird. Es verleiht dem Träger gewisse Vorteile, aber was wichtiger ist, gewährt den Anführern der Geißel jederzeit Einblick in den Aufenthaltsort und die Bewegungen all ihrer Einheiten.|n|nMit genügend Geißelsteinen sollte ich in der Lage sein, die Bewegungen anderer Geißeleinheiten in Eiskrone zu überwachen.|n|nSammelt alle Geißelsteine, die Ihr finden könnt, während Ihr Geißelkrieger in Geißelholme tötet. Kehrt zu mir zurück, wenn eure Taschen voll sind.', },
    {'Der Schwarze Wächter im Tal der Echos möchte, dass Ihr ihm 15 Geißelsteine bringt.', },
  },
  [13124] = {
    'Der Kampf geht weiter',
    {'Malygos und seine Handlanger werden von Tag zu Tag stärker. Jetzt hat man auch noch unsere jüngste Angriffseinheit gefangen genommen und hält sie im Oculus fest.|n|nWir müssen versuchen, sie zu befreien! Belgaristrasz und seine Gefährten sind für uns unerlässlich.', },
    {'Raelorasz möchte, dass Ihr Belgaristrasz und seine Gefährten aus dem Oculus befreit.', },
  },
  [13125] = {
    'Die Luft steht still',
    {'Ihr müsst die Herren von Geißelholme besiegen, wenn dieser Ort vom Würgegriff der Geißel befreit werden soll.|n|nSalranax der Zerfleischer steht dem Tempel auf der ersten Ebene von Geißelholme vor. In der Nähe von Salranax findet Ihr den Hohepriester Yath\'amon, der beim Geisterturm auf der zweiten Ebene predigt. Unterkönig Talonox hält bei der Schreckensgrube Hof, die obere Straße hinauf.|n|nSie sind alle herausragende Gegner und sollten mit Bedacht angegangen werden. Benutzt dieses Kriegshorn, wenn Ihr Hilfe brauchen solltet. Die Todesritter von Acherus werden kommen.', },
    {'Der Schwarze Wächter beim Tal der Echos in Eiskrone will, dass Ihr Salranax den Zerfleischer, Unterkönig Talonox und Hohepriester Yath\'amon tötet.', },
  },
  [13126] = {
    'Vereinte Front',
    {'Von jetzt ab werden wir unsere Kräfte vereinen müssen, um weiter voranzukommen.|n|nVaros über uns versteckt sich hinter einem undurchdringlichen Schild. Um zu ihm zu gelangen, müsst Ihr die Zentrifugenkonstrukte zerstören, die diesen Schild mit Energie versorgen.|n|nJeder von uns kann Euch Drachen des jeweiligen Schwarms zur Verfügung stellen. Sie werden Euch helfen, ihn zu enthüllen.', },
    {'Belgaristrasz möchte, dass Ihr 10 Zentrifugenkonstrukte zerstört, um Varos\' Schild zu beseitigen. Danach müsst Ihr Varos Wolkenwanderer besiegen.', },
  },
  [13127] = {
    'Magierlord Urom',
    {'Zwischen uns und unserem ultimativen Ziel hier steht nur noch ein Hindernis. Sein Name ist Urom.|n|nEr bewacht den dritten Ring über uns. Nehmt Euch vor seiner mächtigen Zauberei in Acht.|n|nStreckt ihn nieder. Lasst ihn dafür büßen, dass er dem Feind die Treue geschworen hat!', },
    {'Belgaristrasz möchte, dass Ihr Magierlord Urom im Oculus besiegt.', },
  },
  [13128] = {
    'Schlacht in den Wolken',
    {'Die Zeit ist gekommen, Euch Eregos zu stellen.|n|nEr bezieht seine Kraft aus den Energien, mit deren Verteidigung er beauftragt wurde... er trinkt aus dem Brunnen des großen Aspekts Malygos.|n|nJedoch können wir dank des Sieges über den Magierlord nun die volle Kraft unserer Drachen entfesseln. Eregos wird Euch sicherlich unterliegen, wenn Ihr sie weise einsetzt.', },
    {'Belgaristrasz möchte, dass Ihr Eregos im Oculus tötet.', },
  },
  [13129] = {
    'Psychospielchen',
    {'<Kurzel reißt einen langen Streifen ihrer Bluse heraus und drückt ihn Euch in die Hand.>|n|nHier, $R, nehmt. Taucht den Stoff in die Überreste von Novos dem Beschwörer.|n|nWir finden schon noch raus, was die Anführer der Geißel antreibt.', },
    {'Kurzel möchte, dass Ihr den Fetzen von Kurzels Bluse auf die Reste von Novos dem Beschwörer anwendet und anschließend den sekretbefleckten Stoff zu ihr in die Feste Drak\'Tharon bringt.', },
  },
  [13130] = {
    'Der Stein, der eine Revolution auslöste',
    {'Wenn Ihr Geißelholme heute betrachtet, mögt Ihr lediglich eine ranzige Grube der Verwesung sehen, aber eines Tages wird es ein Ort voll Pracht und Ehre sein. Hochlord Fordring hat den Namen "Festung der Gerechtigkeit" auserkoren.|n|nNun, selbst der Bau einer uneinnehmbaren Festung wie der Eiskronenzitadelle hat mit einem einzelnen Stein begonnen. Und so beginnt unsere Suche nach dem Stein, der eine Revolution auslösen wird.|n|nReist nach Kristallsang, südlich von hier, und sucht das Unbändige Dickicht im Osten. Sobald Ihr dort seid, sammelt kristallines Kernholz vom Boden des Dickichts und elfisches Mauerwerk von den Ruinen von Shandaral.', },
    {'Kreuzzugsarchitekt Silas im Tal der Echos in Eiskrone möchte, dass Ihr 10 Stämme kristallines Kernholz und 10 Stücke altes elfisches Mauerwerk sammelt.', },
  },
  [13131] = {
    'Schrott in der Truhe',
    {'Seh dir das nur an! Meine Truhe war noch nie sou leer.|n|nMeine Jungs machten Luftsprünge, als sie all die Beude sah\'n, und nu? Seh sie dir nur mal an! Nichts als Knochengerippe!|n|nWeiter drinnen gibt es mehr als genug Beude und sie ist nicht von der verfluchten Sorte, darauf würd ich wetten!|n|nBring mir die Beude und ich werde dich reich belounen, Kumpel.', },
    {'Brigg im Turm Utgarde möchte, dass Ihr 5 blitzblanke Silberbarren, 3 glänzende Schmuckstücke, 2 goldene Kelche und eine Jadestatue beschafft.', },
  },
  [13132] = {
    'Die Rache ist mein!',
    {'Glück allein hat mich vor dem Schicksal meiner Kumpel bewahrt. Bei dem Trubel wurde ich umgestoßen - war von Anfang an ein wenig angeheitert gewesen. Also, ich hab dann hochgeguckt und sah, wie sich die ersten von ihnen verwandelten...|n|nDa stand so\'n riesen Kerl mit jeder Menge Wachen, der sich das alles ansah. Sie sangen den Namen Ymiron... Wenn Ihr ihn umbringt, werden meine Kumpel vielleicht befreit.', },
    {'Brigg im Turm Utgarde möchte, dass Ihr König Ymiron tötet.', },
  },
  [13133] = {
    'Findet den Held aus alter Zeit',
    {'Rasch, $N, geht in den Südwesten zu den Hallen der Vorfahren!|n|nDort werdet Ihr auf die schlummernden Mjordin stoßen. Weckt sie, bis Ihr Iskalder gefunden habt. Dann setzt dieses Amulett bei ihm ein und bringt ihn zu mir.|n|nGeht jetzt. Die Zeit ist knapp!', },
    {'Die Knochenhexe aus Njorndar möchte, dass Ihr mit Iskalder zurückkehrt.', },
  },
  [13134] = {
    'Lasst ihr Blut fließen',
    {'Die Geißel kann ihre Fleischmonster nicht ohne Blut und Balsamierungsflüssigkeit erschaffen, da die Teile geschützt und funktionsfähig bleiben müssen. Wenn wir ihnen diese Materialien nehmen würden, bräche ihre Armee auseinander und wir könnten ihre Schöpfungen mit Leichtigkeit zerstören.|n|nIn allen Laboren, in denen Fleischriesen und Monstrositäten zusammengeflickt werden, werdet Ihr Bottiche mit Balsamierungsflüssigkeit sowie riesige Kugeln voller Blut finden. Zerstört sie und bringt all jenen, die Euch aufhalten wollen, den Tod!', },
    {'Dunkelreiterin Arly aus der Schwarzwacht möchte, dass Ihr 5 Bottiche mit Balsamierungsflüssigkeit und 5 Blutkugeln zerstört.', },
  },
  [13135] = {
    'Es könnte uns alle umbringen',
    {'Südöstlich von hier, am Ostrand des Kristallsangwaldes, befindet sich ein Gebiet, das man Unbändiges Dickicht nennt. Die verschiedensten Kreaturen leben dort, jedoch alle von ihnen teilen die Eigenschaft der Bindung an magische Energien. Jedes von ihnen enthält reine, kristallisierte Energie, die uns alle töten könnte, wenn sie je instabil würde!|n|nBegebt Euch ins Unbändige Dickicht und tötet seine Bewohner, um die kristallisierte Energie zu erhalten. Wir benötigen Treibstoff, sie müssen sterben - von welcher Seite man es auch betrachtet, für uns ist es von Vorteil.', },
    {'Kreuzzugsingenieur Spitzpatrick aus dem Tal der Echos in Eiskrone möchte, dass Ihr 8 Stücke kristallisierte Energie besorgt.', },
  },
  [13136] = {
    'Gezackte Splitter',
    {'Ihr habt diesen gezackten, dunklen, brüchigen Splitter aus dem Körper eines Ghul gezogen. Die metallische Klinge ist nicht glatt und wurde vermutlich von einer ungeübten Hand geschmiedet oder aus einem größeren Stück herausgebrochen.|n|nIhr erinnert Euch, ähnliche Splitter in den Körper aller Ghule, die Euch in den Fleischwerken begegnet sind, gesehen zu haben, daher fragt Ihr Euch, warum ihre Schöpfer überhaupt Metall verwendet haben. Möglicherweise fällt Kreuzfahrer Olakin Sainrith dazu etwas ein, wenn Ihr ihm die Splitter aus mehreren Ghulen bringt.', },
    {'Bringt Kreuzfahrer Olakin Sainrith in der Schwarzwacht 10 gezackte Splitter.', },
  },
  [13137] = {
    'Nicht so ehrenhafter Kampf',
    {'Auf dem höchsten Gipfel im Südwesten über Jotunheim liegt die Kriegsnarbenwarte. Dieser Ort ist den Vrykul heilig und hier tragen sie neben Valhalas gern ihre ehrenhaften Kämpfe aus.|n|nWir werden einen nicht so ehrenhaften Kampf dort besuchen.|n|nRuft Eure Gefährten zusammen und fliegt zum Turm. Entzündet das Signalfeuer, wenn Ihr bereit seid, und ich werde in Iskalders Gestalt erscheinen.|n|nWir werden kämpfen, Ihr werdet siegen, und Vardmadra wird gewiss anwesend sein, um sich den Kampf anzusehen!', },
    {'Die Knochenhexe aus Njorndar möchte, dass Ihr Iskalder auf der Kriegsnarbenwarte besiegt.', },
  },
  [13138] = {
    'Ich schmelze... schmelze!',
    {'<Olakin wendet einen der Splitter in seiner gepanzerten Hand.>|n|nMit genug Energie dahinter könnten sie Rüstungen durchdringen. Wir müssen herausfinden, woraus sie bestehen und was der Lichkönig mit ihnen vorhat.|n|nIm Osten in der Nähe der Eiskronenzitadelle liegt Malykriss. Aus den wenigen Berichten, die uns vorliegen, geht hervor, dass es voller Ausrüstung zum Verhütten und Schmieden ist. Bringt die Splitter dorthin und schmelzt sie in einem der offenen Hochöfen auf der untersten Ebene von Malykriss ein. Sobald das Metall eingeschmolzen und verändert ist, können wir es identifizieren.', },
    {'Benutzt die Tasche mit gezackten Splittern in der Nähe eines der Hochöfen auf der untersten Ebene von Malykriss. Kehrt mit dem verhütteten Metallbarren zum Kreuzfahrer Olakin Sainrith bei der Schwarzwacht zurück.', },
  },
  [13139] = {
    'Im gefrorenen Herzen Nordends',
    {'Liefert Vater Gustavs Bericht bei Hochlord Tirion Fordring in der Argentumvorhut in Eiskrone ab.', },
    {'Liefert Vater Gustavs Bericht bei Hochlord Tirion Fordring in der Argentumvorhut in Eiskrone ab.', },
  },
  [13140] = {
    'Die Runenschmiede von Malykriss',
    {'Die Splitter, die Ihr gefunden habt, können nur von einem Ort stammen: aus Malykriss. Hier, östlich von Corp\'rethar, finden alle Metallarbeiten des Lichkönigs statt.|n|nVerwirrend daran ist, dass man kein Metall benötigt, um die Monstrositäten oder Fleischriesen zusammenzuflicken oder um die Skelettdiener zu beschwören. Findet die Skelettrunenschmiede auf der untersten Ebene von Malykriss und nehmt die Platten, die sie bearbeiten, an Euch. Wir müssen herausfinden, warum dieses Metall in den Fleischwerken Verwendung findet.', },
    {'Bringt Kreuzfahrer Olakin in der Schwarzwacht 5 runenverzierte Saronitplattenrüstungen.', },
  },
  [13141] = {
    'Die Schlacht um den Kreuzfahrerturm',
    {'<Hochlord Fordring hält ein Banner des Argentumkreuzzugs in den Händen.>|n|nDieses Banner ist unvergleichlich, $N. Es enthält einen mächtigen Segen, der große Teile verseuchten Landes reinigen kann.|n|nIhr müsst es durch die Bresche in den Nordwesten in ein Gebiet bringen, das die Geißel spöttisch Kreuzfahrerturm nennt. Stellt das Banner auf die Schädel unserer am Kreuzfahrerturm gefallenen Brüder und verteidigt es gegen alle Angriffe. Sobald das Land gereinigt ist, kehrt Ihr zu Vater Gustav zurück.|n|nGeht jetzt, $N, und habt keine Furcht.', },
    {'Begebt Euch zum Kreuzfahrerturm und platziert das gesegnete Banner des Kreuzzugs auf dem Haufen Kreuzfahrerschädel. Verteidigt das Banner gegen den Angriff der Geißel, bis das Land auf dem Turm gereinigt ist. Kehrt dann zu Vater Gustav ins Tal der Echos in Eiskrone zurück.', },
  },
  [13142] = {
    'Rache der Banshee',
    {'Die Zeit ist gekommen, $N. Ihr müsst mit Euren Freunden den Fürsten der Festung Balargarde, den Meister von Jotunheim, Oberthan Balargarde, herausfordern.|n|nAm höchsten Punkt der Festung, die sich am Südwestrand von Jotunheim befindet, werdet Ihr auf ein Horn stoßen. Blast hinein und lasst all jene, die unerschütterlich genug sind, Eure Herausforderung hören.|n|nBalargarde wird keine andere Wahl haben, als sich Euch zu stellen. Und ich... Verzeihung, Vardmadra wird dort sein, um das Urteil zu fällen.|n|n<Die von einer Banshee besessene Vrykul stößt ein bellendes Lachen aus.>', },
    {'Die Knochenhexe aus Njorndar möchte, dass Ihr für sie Rache nehmt, indem Ihr Oberthan Balargarde herausfordert und besiegt.', },
  },
  [13143] = {
    'Neuer Rekrut',
    {'Eins nach dem anderen. Ich habe ein paar geschmeidige Pirscher auf den Bollwerken östlich von hier gesehen. Sie hatten uns gedient, bevor wir uns von Arthas losrissen. Außerdem sind sie so ziemlich die besten Kundschafter, die es gibt, wenn man sie mit dem Auge der Herrschaft nur ein wenig antreibt.|n|nFliegt dorthin, findet einen der Pirscher, setzt ihm ein wenig zu, wendet dann dieses Siegel der Schwarzen Klinge auf ihn an und er wird Euch gehorchen. Führt ihn anschließend zur Spitze der Felsen nordöstlich von hier und er wird seinen Weg zu mir finden.', },
    {'Vereth der Gewiefte auf der Anhöhe des Leidens wünscht, dass Ihr einen unterworfenen geschmeidigen Pirscher zur Spitze der Felsen nordöstlich der Anhöhe des Leidens bringt.', },
  },
  [13144] = {
    'Zwei Geißeln mit einem Skelett schlagen',
    {'Einige ihrer Kreationen haben die Arbeiter in den Fleischwerken bereits fertiggestellt. Im Moment sind die Kreaturen noch an die Säulen rund um die Kante des Labors gekettet, aber wenn wir nicht schnell etwas unternehmen werden sie mit den Armeen des Lichkönigs marschieren.|n|nAus den auf dem Boden der Fleischwerke verteilten Knochenhaufen ragen gierig greifende Arme heraus. Diese Arme gehören zu Skeletten, die mit der Macht des Feuers belegt sind. Findet und befreit diese Skelette, bringt sie in die Nähe der fertigen Monstrositäten und genießt die Vorstellung!', },
    {'Dunkelreiterin Arly an der Schwarzwacht möchte, dass Ihr 3 angekettete Monstrositäten mit brennenden Skeletten zerstört.', },
  },
  [13145] = {
    'Die Unheilvolle Festung',
    {'Wir müssen wissen, mit was wir es zu tun haben.|n|nBringt mithilfe des Auges der Herrschaft einen geschmeidigen Pirscher unter Eure Kontrolle und erkundet die Gegend. Als ich hierher geflogen bin, habe ich ein paar Stellen gesehen, die Ihr für mich genauer untersuchen sollt: die Warte im Nordosten, das Gebiet der Arbeiter im Südosten, die große Schmiede in der Nähe des Zentrums und den Ritualbereich im Südwesten.|n|nDer Pirscher kann weit springen und Stürze aus größerer Höhe machen ihm nichts aus. Nutzt dies zu Eurem Vorteil und die Bollwerke werden kein Hindernis mehr darstellen.', },
    {'Vereth der Gewiefte auf der Anhöhe des Leidens wünscht, dass Ihr mithilfe eines geschmeidigen Pirschers Malykriss erkundet.', },
  },
  [13146] = {
    'Jede Menge Großzügigkeit',
    {'Wir müssen für ein wenig Tumult sorgen, um diese Todesritter von ihren Anführern wegzubekommen. Ich nehme an, dass, sollten wir ihre Untergebenen dort unten beseitigen, sie ihren Operationen mehr Aufmerksamkeit widmen müssten.|n|nMonstrositäten sind leichte Beute - langsam, berechenbar und was am allerwichtigsten ist: sie sind dumm. Nutzt ihr Vertrauen zu den Pirschern, um die Geißelbomben, die überall in dem Gebiet herumliegen, zu ihnen zu schleifen. Ihr werdet sie anzünden können, lange bevor die Monstrositäten überhaupt herausfinden, wie ihnen geschieht.', },
    {'Vereth der Gewiefte möchte, dass Ihr nach Malykriss geht und mithilfe der Eisenkette des geschmeidigen Pirschers eine Geißelbombe zu einer schwerfälligen Schreckensgestalt zieht. Tötet auf diese Weise 4 schwerfällige Schreckensgestalten.', },
  },
  [13147] = {
    'Kuppler',
    {'Der Hauptunterschied zwischen Vargul und niederen untoten Günstlingen ist, dass die Vargul noch über so viel Verstand verfügen, um es zu verabscheuen, als Arbeiter herangezogen zu werden. Niemals wird es einem Vargul gefallen, an der Seite von Skeletten oder Ghulen arbeiten zu müssen.|n|nWir werden uns diese Abneigung zunutze machen und Zwietracht zwischen den Umbralschlägern und den anderen Untoten in Malykriss säen. Das sollte die Produktion abbremsen und die Todesritter zum Babysitting zwingen.|n|nSollte einfach zu machen sein - ein paar Steine auf die Schläger, sobald sie sich den niederen Untoten nähern, werden genügen.', },
    {'Vereth der Gewiefte auf der Anhöhe des Leidens möchte, dass Ihr einen geschmeidigen Pirscher benutzt, um in Malykriss Steine auf Umbralschläger zu werfen, sobald sie sich niederen Untoten nähern. Kehrt zurück, sobald Ihr 5 Kämpfe provoziert habt.', },
  },
  [13148] = {
    'Halskettenreparatur',
    {'Bei der kaputten Halskette liegt eine Rechnung, auf der steht: "Eigentum von Jonas Timotheus - Cartier & Co., edle Juwelierwaren - Handelsmarkt der Magier - Dalaran".|n|nVielleicht solltet Ihr sie reparieren und zu ihm zurückbringen.', },
    {'Repariert die Halskette mit einem einzigen Chalzedon und bringt sie zu Jonas Timotheus im Juwelierladen auf dem Handelsmarkt der Magier in Dalaran.', },
  },
  [13149] = {
    'Illusionen bannen',
    {'Der ewige Drachenschwarm möchte Prinz Arthas hinters Licht führen und auf diese Weise die Geschichte verändern.|n|nWenn er sich davon überzeugen lässt, dass keines der Körner hier verseucht ist, dann wird er seine verhängnisvolle Entscheidung niemals treffen und die Einwohner Stratholmes am Leben lassen.|n|nWendet diesen arkanen Disruptor auf alle Kornkisten an, die Euch verdächtig erscheinen.', },
    {'Chromie möchte, dass Ihr den arkanen Disruptor auf die verdächtigen Kisten im Stratholme der Vergangenheit anwendet und sie anschließend am Eingang von Stratholme trefft.', },
  },
  [13150] = {
    nil,
    {'Unten am Apparat ist eine Rechnung, laut der "Jonas Timotheus - Juwelier" in Dalaran der Besitzer ist. Wenn Ihr ihn reparieren und zu ihm zurückbringen würdet, vielleicht würde er Euch dann belohnen.', },
    {'Repariert den Apparat und bringt ihn zu Jonas Thimotheus im Juwelierladen in Dalaran.', },
  },
  [13151] = {
    'Die Eskorte des Königs',
    {'Schon bald wird Arthas vor einem verzweifelten Dilemma stehen und eine folgenschwere Entscheidung treffen.|n|nIch muss Euch bitten, den Prinzen bei seiner Ausmerzaktion in Stratholme zu begleiten.|n|nArthas muss lebend durch Stratholme kommen und Ihr müsst dafür sorgen, dass er Mal\'Ganis besiegt!', },
    {'Chromie möchte, dass Ihr Arthas bei seiner Ausmerzaktion in Stratholme begleitet. Ihr sollt wieder mit ihr sprechen, nachdem Mal\'Ganis besiegt ist.', },
  },
  [13152] = {
    'Ein Besuch beim Doktor',
    {'Sie haben diese Ghule also unten im Sanktum der Reanimation mit zerbrochenen Saronitsplittern ausgestattet? Wir müssen dem ein Ende setzen, bevor sie diese Ghule gegen unsere Truppen einsetzen.|n|nFindet den Eingang zum Sanktum der Reanimation im Gebiet um das Fleischriesenlabor in den Fleischwerken. Dort hält das Ghulgenie Doktor Sabnok seine schaurigste Schöpfung \'Flicken\' fest. Befreit Flicken von seinen Ketten und helft ihm, sich am Doktor zu rächen. Möge seine eigene Kreatur sein Untergang sein.', },
    {'Dunkelreiterin Arly von der Schwarzwacht möchte, dass Ihr den Metallpflock, an den \'Flicken\' im Sanktum der Reanimation gekettet ist, zerstört und diesem helft, sich an Doktor Sabnok zu rächen.', },
  },
  [13153] = {
    'Die Krieger schützen',
    {'$N, gut, Euch zu sehen. Wir müssen uns beeilen, solange sich die Schlacht etwas gelegt hat, und unsere Vorräte aufstocken. Meine Untersuchungen deuten darauf hin, dass die Rüstungen der kürzlich in den Eiswasserfällen erschlagenen Soldaten mit unglaublichen Mengen Energie erfüllt werden. Man hat beobachtet, wie die Horde in dieser Gegend Rüstungen einsammelt.|n|nBegebt Euch zu den Eiswasserfällen und erschlagt jeden Anhänger der Horde, der Euch dort über den Weg läuft. Bringt ihre energieerfüllten Rüstungen wieder zu mir zurück.|n|nWenn Ihr keine Hordler finden könnt, dann vielleicht die Rüstung eines Abenteurers, der von den Elementaren getötet wurde.', },
    {'Zauberin Kaylana in der Tausendwinterfestung möchte, dass Ihr zu den Eiswasserfällen geht und den Hordlern dort 10 magieerfüllte Rüstungen abnehmt.', },
  },
  [13154] = {
    'Pfeil und Knochen',
    {'Drachen sind unglaubliche Wesen! Nun, zumindest ihre Knochen! Ich habe unsere Bogenschützen mit Pfeilspitzen aus Drachenknochen ausgerüstet. Unglücklicherweise ist es seit dem Massaker bei Angrathar fast unmöglich geworden, Knochen aus der Drachenöde zu bekommen.|n|nIm Schattenwald am westlichen Rand von Tausendwinter gibt es jedoch genug Knochen, um uns über die Runden zu helfen.|n|nGeht also dorthin und bringt so viele Knochensplitter zurück, wie Ihr nur finden könnt!|n|nMan hat Diener der Horde dabei beobachtet, wie sie Knochensplitter in der Gegend einsammeln. Tötet sie!', },
    {'Bogenmacher Randolph in der Tausendwinterfestung möchte, dass Ihr in den Schattenwald geht und den Hordlern dort 10 Köcher mit Drachenknochenpfeilen abnehmt.', },
  },
  [13155] = {
    'Vereth der Gewiefte',
    {'Ich habe schon Gerüchte über Malykriss und Arthas\' neuen Todesritterorden gehört, bin jedoch davon ausgegangen, dass es sich dabei nur um etwas handelt, das dazu dienen soll, die Lücke wieder aufzufüllen. Ihre Zahl lässt jedoch darauf schließen, dass er versucht, einen Zahn zuzulegen.|n|nWir haben vor nicht allzu langer Zeit einen unserer Besten nach Malykriss entsandt - Vereth den Gewieften. Ihr solltet ihn auf der Anhöhe des Leidens gleich westlich von Malykriss im Hof der Knochen antreffen.|n|nVersucht, auf Eurem Weg dorthin nicht zu viel Aufmerksamkeit auf Euch zu ziehen.', },
    {'Meldet Euch bei Vereth dem Gewieften auf der Anhöhe des Leidens in Eiskrone.', },
  },
  [13156] = {
    'Ein seltenes Kraut',
    {'Du meine Güte, es ist ziemlich frisch hier oben! Erinnert mich an die stürmischen Gipfel von Kaarinos auf Argus. Doch bei all dem Schnee und Eis können sich unsere Soldaten schnell eine Erkältung einfangen.|n|nGeht hinaus in die Lebendige Steppe in Tausendwinters Südwesten und bringt mir zehn der Kräuterbeutel der Horde, die Ihr dort finden könnt. Ich werde sie zu einer Medizin zermahlen, die gegen die Kälte schützen wird.|n|nDiener der Horde waren damit beschäftigt, die Pflanzen in der Gegend zu sammeln. Wenn Ihr sie seht, dann zögert nicht und erschlagt sie und nehmt ihnen die Kräuter ab!', },
    {'Anachoret Tessa in der Tausendwinterfestung möchte, dass Ihr in die Lebendige Steppe geht und den Hordlern dort 10 Kräuterbeutel der Horde abnehmt.', },
  },
  [13157] = {
    'Der Kreuzfahrerturm',
    {'Ihr könnt stolz darauf sein, dass Ihr es wart, der der Argentumdämmerung dazu verholfen hat, in Eiskrone Fuß zu fassen, $N. Der Kreuzfahrerturm bietet dem Lichkönig und seinen missratenen Günstlingen nun direkt die Stirn.|n|nHochlord Fordring und die Kreuzfahrer, die überlebt haben, erwarten Eure Ankunft beim Kreuzfahrerturm. Durchquert erneut die Bresche und sucht den Hochlord auf!', },
    {'Sucht den Hochlord Tirion Fordring beim Kreuzfahrerturm in Eiskrone auf.', },
  },
  [13158] = {
    'Diskretion ist der Schlüssel',
    {'Hört mir zu, $R.|n|nMir wurde soeben mitgeteilt, dass sich in der Violetten Festung ein Zwischenfall ereignet hat. Es scheint, als würde der blaue Drachenschwarm eine groß angelegte Invasion Dalarans in die Wege leiten!|n|nIch möchte, dass Ihr Euch umgehend zum Gefängnis aufmacht und mit Aufseher Alturas sprecht. Er wird Euch die Einzelheiten erklären.|n|nDas ist nicht alles: Die Sache muss mit äußerster Diskretion behandelt werden. Wir müssen versuchen, die Einwohner Dalarans wenn möglich nicht zu beunruhigen. Habe ich mich klar ausgedrückt?|n|nSehr gut. Nun geht!', },
    {'Rhonin möchte, dass Ihr zur Violetten Festung in Dalaran geht und mit Aufseher Alturas sprecht.', },
  },
  [13159] = {
    'Eindämmung',
    {'Hier ist der Gefängnisschlüssel.|n|nMeine Männer und ich werden als letzte Verteidigungslinie hier bleiben, falls Ihr dem Angriff nicht standhalten könnt.|n|nSprecht auf jeden Fall mit Leutnant Sinclari. Sie wird Euch Zugang zu den Verteidigungsvorrichtungen des Gefängnisses beschaffen.|n|nBeeilt Euch, $R. Es bleibt nur wenig Zeit. Die Wenigen, die ich zurückgelassen habe, werden ohne Eure Hilfe nicht lange durchhalten. Meldet Euch wieder bei mir, sobald die Invasoren erfolgreich zurückgeschlagen wurden.', },
    {'Aufseher Alturas möchte, dass Ihr die Violette Festung betretet und den Invasionsstreitkräften des blauen Drachenschwarms ein Ende bereitet. Ihr sollt Euch wieder bei ihm melden, sobald Cyanigosa getötet wurde.', },
  },
  [13160] = {
    'Eine überwältigende Aussicht',
    {'Gargoyles eignen sich sehr gut als Kundschafter und können tödlich sein, wenn man ihnen den Angriff aus der Luft überlässt, doch haben sie einen offensichtlichen Schwachpunkt. Die meisten von ihnen müssen längere Zeit in Steinform verbringen, um sich zu erholen und die Energie zu sammeln, die sie brauchen, um ihre schweren Körper durch die Luft zu bewegen.|n|nAls ich durch das von Euch benutzte Auge geblickt habe, sind mir Dutzende von Eishautwachposten aufgefallen, die an den östlichen und südlichen Innenwänden ruhten. Benutzt den Jäger, um zu ihnen hinauf zu gelangen und vernichtet sie, während sie schlafen.', },
    {'Vereth der Gewiefte möchte, dass Ihr die Hebefähigkeiten des geschmeidigen Pirschers benutzt, um 12 schlafende Eishautwachposten zu zerstören.', },
  },
  [13161] = {
    'Der Reiter des Unheiligen',
    {'Es ist Zeit, dass wir damit anfangen, den Kopf des Ganzen zu beseitigen.|n|nIch diente ziemlich lange neben Rokir. Er kennt die unheiligen Künste besser als jeder andere Todesritter, den ich getroffen habe, und er ist genauso skrupellos. Nehmt es nicht zu leicht.|n|nRokirs Stärken treten dann am stärksten hervor, wenn er sich auf seinem eigenen Grund und Boden befindet. Leider haben wir in dieser Hinsicht keine andere Wahl. Bleibt jedoch auf den Beinen, um seinen untoten Dienern aus dem Weg zu gehen, und Ihr solltet siegreich hervorgehen.|n|nSeid flink, $C, und nehmt die Sache nicht zu leicht.', },
    {'Vereth der Gewiefte auf der Anhöhe des Leidens wünscht, dass Ihr Rokir, den Reiter des Unheiligen, tötet.', },
  },
  [13162] = {
    'Die Reiterin des Frostes',
    {'Saph... So einen Todesritter wie sie gibt es kein zweites Mal. Sie wird Euch mit sanften Worten übergießen und während Ihr Euch absolut sicher seid, dass kein Funken Boshaftigkeit in ihr steckt, wird sie Euch durchlöchern - weiterhin ein Lächeln auf den Lippen. Unterschätzt sie nicht.|n|nIch mache mir keine Sorgen, dass Ihr Saph besiegen könnt, doch werdet bloß nicht zu übermütig. Ihre Stärke liegt darin, ihre Opfer in falscher Zuversicht zu wiegen und sie kurz darauf mit einem heftigen Frosthagel in tausend Einzelteile zu zerschießen.|n|nSeid immer auf der Hut und unterschätzt sie nicht.', },
    {'Vereth der Gewiefte auf der Anhöhe des Leidens wünscht, dass Ihr Saph, die Reiterin des Frostes tötet.', },
  },
  [13163] = {
    'Der Reiter des Blutes',
    {'Baelok ist einer der wenigen Vrykul, den ich jemals in den Rängen aufsteigen sah, und das war größtenteils seiner schieren Brutalität zu verdanken. Wenn die Konkurrenz erst einmal tot ist, gibt es um einiges weniger, mit dem man konkurrieren müsste.|n|nEure Gruppe muss sich verteilen und so viel Abstand voneinander halten wie Ihr es die Situation zulässt, wenn der Kampf beginnt. Er wird nicht zögern, Eure Lebensenergie zu rauben, also werdet Ihr ihn so oft wie möglich daran hindern müssen.|n|nIch vertraue auf Euch. Seht zu, dass er stirbt.', },
    {'Vereth der Gewiefte auf der Anhöhe des Leidens möchte, dass Ihr Baelok, den Reiter des Blutes, tötet.', },
  },
  [13164] = {
    'Blutbanns Schicksal',
    {'Nun, da die Reiter der Heerschar des Leids tot sind, ist die Zeit gekommen, ihrem wahren Anführer ein Ende zu bereiten: Orbaz Blutbann.|n|nMograine war hier, als Ihr weg wart, und hat mir gesagt, dass er herausgefunden hat, wo sich Orbaz versteckt hält. Unter der Eiskronenzitadelle befindet sich eine riesige Grube - und Orbaz befindet sich am Rand dieser Grube.|n|nEinige der stärksten Agenten der Schwarzen Klinge wurden schon ausgesandt - holt also Hilfe und auf mit Euch in den Kampf. Es ist Zeit, dass Blutbann stirbt.', },
    {'Vereth auf der Anhöhe des Leidens hat Euch ausgesandt, um Orbaz Blutbann zu töten.', },
  },
  [13165] = {
    'Acherus zurückerobern',
    {'Der Dunstschleier hat sich gelüftet. Nun kann ich genauso klar sehen wie an dem Tag, als ich den Aschenbringer in mein eigenes Herz rammte, um meines Vaters verfluchte Seele zu befreien – dies ist meine letzte Erinnerung an mein Leben als freier Mann.|n|nWir müssen Acherus von der Geißel zurückerobern, wenn unser Orden in dieser neuen Welt überleben will. Ich habe Euch gezeigt, wie man ein schwarzes Tor beschwören kann. Das Tor wird Euch zurück nach Acherus befördern, wenn Ihr es ruft, $N. Ruft es herbei und trefft mich dort. Die erste Schlacht der Ritter der Schwarzen Klinge ist in vollem Gange!', },
    {'Benutzt Euren Zauber \'Schwarzes Tor\' und kehrt nach Acherus, der Schwarzen Festung, zurück. Meldet Euch bei Hochlord Darion Mograine, sobald Ihr dort seid.', },
  },
  [13166] = {
    'Die Schlacht um die Schwarze Festung',
    {'Die Hallen des Befehls wurden gesichert, doch der Lichkönig hat uns ein kleines Geschenk im Herzen von Acherus zurückgelassen. Der zusammengenähte Schrecken Flickwerk und eine Horde von Monstrositäten haben die zweite Ebene in ihre Kontrolle gebracht.|n|nBenutzt den Teleporter, um auf die zweite Ebene zu gelangen, und zerstört die restlichen Streitkräfte der Geißel. Greift Flickwerk auf keinen Fall alleine an! Ihr müsst das Ungetüm mit anderen Todesrittern von Acherus bekämpfen!|n|nGeht, $N. Meine Kraft wird Euch tragen!', },
    {'Vernichtet 10 Diener der Geißel und helft, Flickwerk zu vernichten. Kehrt zu Hochlord Darion Mograine zurück, solltet Ihr erfolgreich sein.', },
  },
  [13167] = {
    'Tod dem Verräterkönig',
    {'Anub\'arak der Verräterkönig ist im einst stolzen unterirdischen Azjol-Nerub zuhause.|n|nNach seinem Verrat hat er unser Heimatland entstellt und verdorben und es schließlich zu dem erbärmlichen Haufen Dreck gemacht, zu dem es heute geworden ist. Er herrscht über eine Armee untoter Neruber, die wie ihr Anführer dem Lichkönig die Treue geschworen haben.|n|nSetzt der Herrschaft des Verräterkönigs ein Ende, $C. damit würdet Ihr unseren beiden Völkern einen großen Dienst erweisen.|n|nBringt mir Anub\'araks Panzer, wenn Ihr schaffen solltet, was noch keiner vor Euch geschafft hat.', },
    {'Kilix der Entwirrer in der Grube von Narjun hat Euch damit beauftragt, Anub\'arak in Azjol-Nerub zu besiegen. Danach sollt Ihr Kilix Anub\'araks zerbrochenen Panzer zurückbringen.', },
  },
  [13168] = {
    'Abschiedsgeschenke',
    {'Schaut, was wir hier haben... Augen der Herrschaft. Normalerweise tut der Kult alles nur Erdenkliche, um diese Dinger geheim zu halten, aber vermutlich haben sie ziemlich wenig Rückzugsmöglichkeiten, wenn wir sie in ihrem eigenen Haus erschlagen.|n|nDie Augen erlauben es jedem Wesen von relativer Macht, die Handlungen eines untoten Dieners präzise zu kontrollieren. Wie Ihr Euch vorstellen könnt, kann dies im Falle des typischen unbeholfenen Ghuls oder Skeletts extrem praktisch sein.|n|nHabt Ihr Lust, es einmal auszuprobieren? Benutzt eines der Augen bei einem der gefangenen Schatten.', },
    {'Keritose Blutklinge im Schattengewölbe möchte, dass Ihr eins der Augen der Herrschaft benutzt, um die Kontrolle über einen gefangenen Eidolonwächter zu übernehmen.', },
  },
  [13169] = {
    'Der beste Freund des Untoten',
    {'Unter den Untoten in der Saronitmine gen Süden ist es üblich, ihre Seuchenhunde hungern zu lassen, um sie besonders aggressiv zu halten. Benutzt den Schemen, um nahe heranzukommen und füttert einige der Hunde. Ich verspreche Euch, Ihr werdet fortan keinerlei Schwierigkeiten mehr mit ihnen haben. Vielleicht werden sie sich ihrem Wohltäter sogar anschließen.|n|nKommt den Dingern jedoch nicht zu nahe, bevor Ihr sie gefüttert habt. Ihre Nasen lassen sich von Eurem Schemen nicht so leicht hinters Licht führen.', },
    {'Keritose Blutklinge im Schattengewölbe wünscht, dass Ihr mithilfe des Eidolonwächters 18 hungernde Seuchenhunde füttert.', },
  },
  [13170] = {
    'Ehre ist was für Schwächlinge',
    {'Ghule sind sehr zerbrechlich, wenn es hart auf hart kommt, und die Aufklärer in der Saronitmine den Weg hinunter in Richtung Südwesten sind da keine Ausnahme. Mithilfe eines Schattens sollte es Euch eigentlich nicht schwerfallen, ranzuschleichen und ihre Aufklärer geräuschlos auszuschalten.|n|nBeseitigt so viele Aufklärer, wie Ihr in angemessener Zeit erwischen könnt... Ihre Reihen sollen gelichtet werden, bevor wir das nächste Mal angreifen.', },
    {'Keritose Blutklinge im Schattengewölbe hätte gerne, dass Ihr 20 ruhelose Aufklärer tötet.', },
  },
  [13171] = {
    'Schickt sie zurück',
    {'Meine Hauptsorge ist die Saronitmine, die sich den Weg hinunter in Richtung Südwesten befindet. Sie holen unglaubliche Mengen an Erz aus dieser Mine und ich würde schon gerne wissen, was sie damit vorhaben. Um das herauszufinden, fangen wir damit an, ihre Verteidigung zu schwächen.|n|nMir sind mehrere Kristalle aufgefallen, die in der ganzen Basis verteilt stehen, und nehme an, dass es sich hier um irgendwelche Verteidigungsanlagen handelt, ähnlich den Ziggurats. Zerstört mithilfe des Eidolonwächters jeden Kristall, den Ihr finden könnt.', },
    {'Keritose Blutklinge im Schattengewölbe hat Euch ausgesandt, um 10 Eindämmungskristalle der Geißel zu bannen.', },
  },
  [13172] = {
    'Chaos säen',
    {'Effektives Werkzeug, nicht wahr? Sehr gut gemacht, wie Ihr ihre Verteidigung geschwächt habt, $C. Nun können wir den Hauptangriff vorantreiben.|n|nDer Plan ist einfach und direkt - wir wollen alles beseitigen, was sich bewegt, und die Verwirrung ausnutzen, um ein paar Informationen in die Hände zu bekommen.|n|nSagt mir Bescheid, wenn Ihr bereit seid, und ich werde Euch einen Skelettgreif besorgen.', },
    {'Keritose Blutklinge im Schattengewölbe hat Euch ausgesandt, um 80 Untote im Tränenbruch abzuschlachten. Sprecht mit ihm, um Euch einen Skelettgreifen für den Angriff zu sichern.', },
  },
  [13173] = {
    'Das Durcheinander nutzen',
    {'Uns ist es gelungen, eine ganze Reihe von Arbeitern in die Finger zu bekommen. Sie sollten sich gut eignen.|n|nIch möchte, dass Ihr eins der Augen benutzt, um einen Arbeiter in die Mine zu schicken. Wenn das ganze Lager in Aufruhr ist, sollte es ihnen unmöglich sein, Euch von einem der anderen Arbeiter zu unterscheiden, die nach dem Angriff umherlaufen.|n|nFindet denjenigen, der für die ganze Operation zuständig ist und macht Euch an die Arbeit. Mit etwas Glück werden wir recht schnell herausfinden, wohin das Saronit verschickt wird. Ich werde Euch durch das Auge hindurch beobachten.', },
    nil,
  },
  [13174] = {
    'Das Durcheinander nutzen',
    {'Den Betrieb zum Stillstand zu bringen ist nur die eine Hälfte des Plans. Das andere wichtige Ziel an dieser Stelle ist es, herauszufinden, wohin all das Saronit geschickt wird. Uns sind ein paar Orte bekannt, an denen es wieder auftaucht, doch bei der Menge, die sie aus dem Boden holen, liegt die Vermutung nahe, dass da ein viel größeres Projekt läuft.|n|nSeid Ihr einmal in der Mine, so nehmt alle Dokumente mit, die Ihr finden könnt. Solltet Ihr den Ort mit einem der Greifen angreifen, so könnt Ihr Euch fallenlassen, sobald Ihr die Arbeit erledigt habt.', },
    {'Keritose Blutklinge im Schattengewölbe verlangt ein Dokument des Tränenbruchs, ein Geschäftsbuch des Tränenbruchs, eine Karte des Tränenbruchs und einen Zeitplan des Tränenbruchs.', },
  },
  [13175] = {
    'Die Kontrolle zurückgewinnen',
    nil,
    nil,
  },
  [13176] = {
    'Die Lieferung vorbereiten',
    nil,
    nil,
  },
  [13177] = {
    'Keine Gnade für die Gnadenlosen',
    {'Willkommen in der Tausendwinterfestung, $N. Eure Mission hier ist einfach: Besiegt zehn der besten Kämpfer, die die Horde zu bieten hat. Nun geht! Zum Sieg der Allianz!', },
    {'Hauptmann Zanneth in der Tausendwinterfestung möchte, dass Ihr 10 Mitglieder der Horde tötet.', },
  },
  [13178] = {
    'Tötet sie alle!',
    {'Willkommen in der Tausendwinterfestung, $N. Kriegsherr Garrosh verlangt nur eins: tötet sie alle!|n|nKehrt wieder zu mir zurück, wenn zehn der stärksten Mitglieder der Allianz tot sind.', },
    {'Kommandant Dardosh in der Tausendwinterfestung möchte, dass Ihr 10 Mitglieder der Allianz tötet.', },
  },
  [13179] = {
    'Keine Gnade für die Gnadenlosen',
    {'Willkommen in Tausendwinter, $N. Eure Mission hier ist einfach: Besiegt zehn der besten Kämpfer, die die Horde zu bieten hat. Nun geht! Zum Sieg der Allianz!', },
    {'Hauptmann Zanneth in Tausendwinter möchte, dass Ihr 10 Mitglieder der Horde tötet.', },
  },
  [13180] = {
    'Tötet sie alle!',
    {'Willkommen in Tausendwinter, $N. Kriegsherr Garrosh verlangt nur eins: tötet sie alle!|n|nKehrt wieder zu mir zurück, wenn zehn der stärksten Mitglieder der Allianz tot sind.', },
    {'Kommandant Dardosh in Tausendwinter möchte, dass Ihr 10 Mitglieder der Allianz tötet.', },
  },
  [13181] = {
    'Sieg in Tausendwinter',
    {'Hauptmann Zanneth mag vielleicht zufrieden damit sein, einen Haufen Hordeleichen vor sich liegen zu haben, doch die Kontrolle über die Tausendwinterfestung zu erlangen, ist für die Expedition Valianz von äußerster Wichtigkeit. Kümmert Euch darum, dass sie weiterhin in unseren Händen bleibt.|n|nGlaubt jedoch bloß nicht, dass wir Euch einfach so herumstehen lassen werden, während Eure Mitstreiter die Drecksarbeit für Euch erledigen. Wenn Ihr bis zum Ende der Schlacht nicht mindestens ein Rekrut zweiten Grades seid, dann braucht Ihr nicht zurückkommen.', },
    {'Gewinnt einen Kampf auf dem Schlachtfeld in Tausendwinter und kehrt dann zu Taktikoffizier Ahbramis zurück. Ihr müsst an der Schlacht teilgenommen haben, um für den Sieg belohnt zu werden.', },
  },
  [13182] = {
    'Vergesst die Eier nicht!',
    {'In ganz Azjol-Nerub liegen Eier verteilt, die von den Nerubern der Geißel gehegt und gepflegt werden und schon bald schlüpfen werden. Sie werden ihre Zahl noch zusätzlich mehren.|n|nEs würde nicht viel nützen, wenn alle Untoten aus den Höhlen getilgt und diese faulen Eier ausschlüpfen würden, nur damit sie an ihre Stelle treten.|n|nKümmert Euch auf jeden Fall darum, dass unsere uralte Heimat von allen Eiern der Geißel gereinigt wird, während Ihr den Ort erkundet, der einst Azjol-Nerub gewesen ist.', },
    {'Kilix der Entwirrer in der Grube von Narjun möchte, dass Ihr Azjol-Nerub betretet und 6 Eier der Geißelneruber zerstört.', },
  },
  [13183] = {
    'Sieg in Tausendwinter',
    {'Dardosh mag es zwar genügen, unsere Feinde zu töten, doch es ist von äußerster Wichtigkeit, dass wir die Tausendwinterfestung kontrollieren. Tut, was auch immer nötig ist, damit Tausendwinter uns gehört.|n|nGlaubt jedoch bloß nicht, dass wir Euch einfach so herumstehen lassen werden, während Eure Mitstreiter die Drecksarbeit für Euch erledigen. Wenn Ihr bis zum Ende der Schlacht nicht mindestens ein Rekrut zweiten Grades seid, dann braucht Ihr nicht zurückkommen.', },
    {'Gewinnt einen Kampf in einem Schlachtfeld von Tausendwinter und kehrt anschließend zu Taktikoffizier Kilrath in Tausendwinter zurück. Ihr müsst an der Schlacht teilgenommen haben, um für den Sieg belohnt zu werden.', },
  },
  [13184] = {
    'Die Nützlichkeit überdauern',
    nil,
    nil,
  },
  [13185] = {
    'Setzt der Belagerung ein Ende',
    {'Ich sie gehört! Die Allianz bald kommen. Mach drei Belagerungsmaschinen kaputt und komm dann wieder zu Murp.', },
    {'Leutnant Murp in der Tausendwinterfestung möchte, dass Ihr 3 Belagerungsmaschinen der Allianz zerstört.', },
  },
  [13186] = {
    'Setzt der Belagerung ein Ende',
    {'Es ist nur eine Frage der Zeit, bis diese Burg von den Streitkräften der Horde belagert wird. Zerstört drei ihrer Belagerungsmaschinen und kehrt anschließend zu mir zurück.', },
    {'Chefdemolierer Legoso in der Tausendwinterfestung möchte, dass Ihr 3 Belagerungsmaschinen der Horde zerstört.', },
  },
  [13187] = {
    'Die Gesichtslosen',
    {'Jedes Mal, wenn mein Volk im Kampf gegen die Streitkräfte der Untoten an Boden verlor, grub es tiefer.|n|nVersehentlich legten sie Diener der Alten Götter frei, Wesen, die nur als die Gesichtslosen bekannt sind.|n|nAm Ende konnten wir nicht an zwei Fronten kämpfen.|n|nMit Eurer Hilfe werden die Gesichtslosen hoffentlich endlich fallen.', },
    {'Seher Ixit möchte, dass Ihr Herold Volazj und die drei Vergessenen an seiner Seite tötet.', },
  },
  [13188] = {
    'Auf den Spuren der Könige',
    {'Ihr seid von nun an für den Rest der Ewigkeit ein Ritter der Schwarzen Klinge, $N, doch wisset: Einst wart Ihr ein Held der Allianz.|n|n<Darion starrt Euch an.>|n|nDieser Orden muss Verbündete finden, wenn er überleben will. Ihr sollt der Repräsentant der Ritter der Schwarzen Klinge sein und Euch der Allianz zeigen.|n|nAuf der Plattform südöstlich von mir befindet sich ein Portal nach Sturmwind. Hier, nehmt diesen Brief - Lord Fordring trug mir auf, ihn Euch zu geben. Ihr sollt ihn König Varian Wrynn bringen. Benutzt das Portal.', },
    {'Bringt den Brief zu König Varian Wrynn, Anhänger der Allianz in Burg Sturmwind in Sturmwind.', },
  },
  [13189] = {
    'Der Segen des Kriegshäuptlings',
    {'Ihr seid von nun an für den Rest der Ewigkeit ein Ritter der Schwarzen Klinge, $N, doch wisset: Einst wart Ihr ein Held der Horde.|n|n<Darion starrt Euch an.>|n|nDieser Orden muss Verbündete finden, wenn er überleben will. Ihr sollt der Repräsentant der Ritter der Schwarzen Klinge sein und Euch der Horde zeigen.|n|nAuf der Plattform südöstlich von mir befindet sich ein Portal nach Orgrimmar. Hier, nehmt diesen Brief - Lord Fordring trug mir auf, ihn Euch zu geben. Ihr sollt ihn dem Kriegshäuptling überbringen. Benutzt das Portal.', },
    {'Bringt den Brief zum Kriegshäuptling der Horde in Orgrimmar.', },
  },
  [13190] = {
    'Alles zu seiner Zeit',
    {'Ahn\'kahet, woher wir einst kamen...|n|nIch träume davon, dass wir eines Tages Tod und Dunkelheit, in deren Griff sich unsere uralte Heimat befindet, überwinden werden. Zu diesem Zweck habe ich einen Plan entworfen, mit dem wir unsere Feinde entmutigen können.|n|nIhre kostbaren Wächter müssen brennen!|n|nLegt ihre Leichen auf die Kohlenpfanne tief im Inneren der Stadt. Der Geruch ihrer verbrannten Überreste wird in der Luft hängen und unseren Feind an seine Schwäche erinnern.|n|nGeht mit Bedacht vor, $C! Ihre untoten Leichen sind äußerst zerbrechlich und werden rasch verrotten.', },
    {'Kilix der Entwirrer in der Grube von Narjun möchte, dass Ihr die Leiche eines Wächters der Ahn\'kahar beschafft und sie auf das Kohlenbecken von Ahn\'kahet in Ahn\'kahet legt.|n|nDiese Quest kann nur auf dem Schwierigkeitsgrad \'Heroisch\' beendet werden.', },
  },
  [13191] = {
    'Verwüster auftanken',
    {'Lok\'tar, $N! Die Schlacht mag vielleicht geschlagen sein, doch wir müssen uns auf den nächsten Angriff der Allianz vorbereiten! Reist zum Flammenkessel im Südosten von Tausendwinter und bringt zehn Stück Immerglut zurück.|n|nDie Glutstücke werden mit Kohle vermengt, um Treibstoff für die Verwüster und Belagerungsmaschinen zu liefern.|n|nWir haben Berichte darüber gehört, dass die Schweine von der Allianz den ganzen Tag über die Glutstücke sammeln. Tötet sie und nehmt sie ihnen weg! Wenn die Anhänger der Allianz die Gegend schon aufgegeben haben, dann macht Euch darauf gefasst, die Feuerelementare in der Gegend zu bekämpfen, bis Ihr welche findet!', },
    {'Belagerungsschmied Starkhuf in der Tausendwinterfestung möchte, dass Ihr zum Flammenkessel geht und den Allianzlern dort 10 Stück Immerglut abnehmt.', },
  },
  [13192] = {
    'Die Wälle schützen',
    {'Hey, Mann. Bei dem Ort hier krieg ich \'ne Gänsehaut, weißt du?|n|nHier spuken viel zu viele Geister rum. Ich will Hoodoobarrieren aufstellen, brauch aber \'n paar Seelen dafür, Mann. Aber nich\' irgendwelche Seelen; nur die eines starken Kämpfers ist dafür gut.|n|nDie Eiswasserfälle im Osten von Tausendwinter haben spezielle Eigenschaften, durch die man \'ne Seele heraussaugen kann. Bring die Allianzler dort um - vielleicht haben sie das Zeug, das wir brauchen.|n|nBring die Rüstungen der Toten hierher zu mir. Wenn da keine Allianzler sin\', dann haben die Elementare vielleicht welche, Mann.', },
    {'Hoodoomeister Fu\'jin in der Tausendwinterfestung möchte, dass Ihr 10 verzauberte Brustplatten der Allianz aus dem Gebiet der Eiswasserfälle beschafft.', },
  },
  [13193] = {
    'Pfeil und Knochen',
    {'Weshalb würden sie mich mit der Aufgabe betreuen, unsere Bogenschützen auszurüsten? Ich war ein Dichter, kein Waldläufer! Tja, jammern hilft nichts. $N, ich brauche Drachenknochen für unsere Pfeilspitzen.|n|nReist zum Schattenwald an der westlichen Seite von Tausendwinter. Seit dem letzten Scharmützel haben die Diener der Allianz die Gegend nach Drachenknochen durchstöbert. Tötet sie und nehmt ihnen die Knochen ab.|n|nWenn das nicht funktionieren sollte, dann könnt Ihr vielleicht welche von den Geistern dort bekommen, wenn Ihr Glück habt. Ich habe gehört, dass sie liebend gerne ihre sterbenden Opfer auf den Knochen aufspießen.', },
    {'Leutnant Vieron Flammenfeder in der Tausendwinterfestung möchte, dass Ihr in den Schattenwald geht und den Allianzlern dort 10 Köcher mit Drachenknochenpfeilen abnehmt.', },
  },
  [13194] = {
    'Mit Rosen heilen',
    {'Zwischen den Schlachten mag einer schon fast daran glauben, dass es Hoffnung auf Frieden in diesem Land gäbe. Leider hat unser Schicksal anderes mit uns vor.|n|nReist zur lebendigen Steppe im Südwesten von Tausendwinter. Ich benötige die dort wachsenden Rosen, um daraus eine Heilsalbe für die Verwundeten herzustellen.|n|nLeider ist die Rose eher selten geworden, weil die Allianz sie zu schnell aberntet. Geht zur lebendigen Steppe, tötet sie und nehmt ihnen ihre Kräuterbeutel ab.|n|nWenn das nicht funktionieren sollte, dann schnappt Euch die Peitscher. Ein paar von denen haben vielleicht welche dabei.', },
    {'Primalist Mulfort möchte, dass Ihr in die Lebendige Steppe geht und den Allianzlern dort 10 Kräuterbeutel der Allianz abnehmt.', },
  },
  [13195] = {
    'Ein seltenes Kraut',
    {'Du meine Güte, es ist ziemlich frisch hier oben! Erinnert mich an die stürmischen Gipfel von Kaarinos auf Argus. Doch bei all dem Schnee und Eis können sich unsere Soldaten schnell eine Erkältung einfangen.|n|nGeht hinaus in die Lebendige Steppe in Tausendwinters Südwesten und bringt mir zehn Kräuterbeutel der Horde. Ich werde sie zu einer Medizin zermahlen, die gegen die Kälte schützen wird.|n|nDiener der Horde waren damit beschäftigt, die Pflanzen in der Gegend zu sammeln. Wenn Ihr sie seht, dann zögert nicht und erschlagt sie und nehmt ihnen ihre Kräuter ab!|n|nDie Peitscher in der Gegend können auch welche bei sich haben.', },
    {'Anachoret Tessa in Tausendwinter möchte, dass Ihr in die Lebendige Steppe geht und den Hordlern dort 10 Kräuterbeutel abnehmt.', },
  },
  [13196] = {
    'Pfeil und Knochen',
    {'Drachen sind unglaubliche Wesen! Nun, zumindest ihre Knochen! Ich habe unsere Bogenschützen mit Pfeilspitzen aus Drachenknochen ausgerüstet. Unglücklicherweise ist es seit dem Massaker bei Angrathar fast unmöglich geworden, Knochen aus der Drachenöde zu bekommen.|n|nIm Schattenwald am westlichen Rand von Tausendwinter gibt es jedoch genug Knochen, um uns über die Runden zu helfen.|n|nGeht also dorthin und bringt so viele Knochensplitter zurück, wie Ihr nur finden könnt!|n|nMan hat Diener der Horde dabei beobachtet, wie sie Knochensplitter in der Gegend einsammeln. Tötet sie!', },
    {'Bogenmacher Randolph in Tausendwinter möchte, dass Ihr in den Schattenwald geht und den Hordlern dort 10 Köcher mit Drachenknochenpfeilen abnehmt.', },
  },
  [13197] = {
    'Verwüster auftanken',
    {'$N! Wurde auch langsam Zeit, dass Ihr auftaucht. Wir mögen zwar die letzte Schlacht verloren haben, doch wir sollten uns noch immer auf die nächste vorbereiten! Reist zum Flammenkessel im südöstlichen Teil von Tausendwinter und beschafft mehrere Stück Immerglut.|n|nDie Glutstücke werden mit Kohle vermengt, um Treibstoff für die Verwüster und Belagerungsmaschinen zu liefern.|n|nOh, eins noch: Falls Ihr zufällig Anhänger der Horde im Flammenkessel sehen solltet, dann zögert nicht, tötet sie und nehmt ihnen die Glutstücke weg. Wir müssen verhindern, dass die Festung in ihrer Kontrolle bleibt!', },
    {'Belagerungsschmied Starkhand in Tausendwinter möchte, dass Ihr zum Flammenkessel geht und den Hordlern dort 10 Stück Immerglut abnehmt.', },
  },
  [13198] = {
    'Die Krieger schützen',
    {'$N, gut, Euch zu sehen. Wir müssen uns auf unseren nächsten Angriff auf die Festung vorbereiten. Meine Untersuchungen deuten darauf hin, dass die Rüstungen der kürzlich in den Eiswasserfällen erschlagenen Soldaten mit unglaublichen Mengen Energie erfüllt werden. Die Horde war damit beschäftigt, in dieser Gegend Rüstungen einzusammeln.|n|nBegebt Euch zu den Eiswasserfällen und erschlagt jeden Anhänger der Horde, der Euch dort über den Weg läuft. Bringt ihre energieerfüllten Rüstungen wieder zu mir zurück.|n|nWenn Ihr keine Hordler finden könnt, dann vielleicht die Rüstung eines Abenteurers, der von den Elementaren getötet wurde.', },
    {'Zauberin Kaylana in Tausendwinter möchte, dass Ihr zu den Eiswasserfällen geht und den Hordlern dort 10 magieerfüllte Rüstungen der Horde abnehmt.', },
  },
  [13199] = {
    'Pfeil und Knochen',
    {'Weshalb würden sie mich mit der Aufgabe betreuen, unsere Bogenschützen auszurüsten? Ich war ein Dichter, kein Waldläufer! Tja, jammern hilft nichts. $N, ich brauche Drachenknochen für unsere Pfeilspitzen.|n|nReist zum Schattenwald an der westlichen Seite von Tausendwinter. Seit dem letzten Scharmützel haben die Diener der Allianz die Gegend nach Drachenknochen durchstöbert. Tötet sie und nehmt ihnen die Knochen ab.|n|nWenn das nicht funktionieren sollte, dann könnt Ihr vielleicht welche von den Geistern dort bekommen, wenn Ihr Glück habt. Ich habe gehört, dass sie liebend gerne ihre sterbenden Opfer auf den Knochen aufspießen.', },
    {'Leutnant Vieron Flammenfeder in Tausendwinter möchte, dass Ihr in den Schattenwald geht und den Allianzlern dort 10 Köcher mit Drachenknochenpfeilen abnehmt.', },
  },
  [13200] = {
    'Verwüster auftanken',
    {'Lok\'tar, $N! Die Schlacht mag vielleicht geschlagen sein, doch wir müssen uns auf den nächsten Angriff der Allianz vorbereiten! Reist zum Flammenkessel im Südosten von Tausendwinter und bringt zehn Stück Immerglut zurück.|n|nDie Glutstücke werden mit Kohle vermengt, um Treibstoff für die Verwüster und Belagerungsmaschinen zu liefern.|n|nWir haben Berichte darüber gehört, dass die Schweine von der Allianz den ganzen Tag über die Glutstücke sammeln. Tötet sie und nehmt sie ihnen weg! Wenn die Anhänger der Allianz die Gegend schon aufgegeben haben, dann macht Euch darauf gefasst, die dortigen Feuerelementare zu bekämpfen, bis Ihr welche findet!', },
    {'Belagerungsschmied Starkhuf in Tausendwinter möchte, dass Ihr zum Flammenkessel geht und den Allianzlern dort 10 Stück Immerglut abnehmt.', },
  },
  [13201] = {
    'Mit Rosen heilen',
    {'So viele unserer Tapferen sind in der Schlacht gefallen, doch noch mehr werden sterben, wenn sie nicht behandelt werden.|n|nReist zur lebendigen Steppe im Südwesten von Tausendwinter. Ich benötige die dort wachsenden Rosen, um daraus eine Heilsalbe für die Verwundeten herzustellen.|n|nLeider ist die Rose eher selten geworden, weil die Allianz sie zu schnell aberntet. Geht zur lebendigen Steppe, tötet sie und nehmt ihnen die Kräuterbeutel ab.|n|nWenn das nicht funktionieren sollte, dann schnappt Euch die Peitscher. Ein paar von denen haben vielleicht welche dabei.', },
    {'Primalist Mulfort in Tausendwinter möchte, dass Ihr in die Lebendige Steppe geht und den Allianzlern dort 10 Kräuterbeutel der Allianz abnehmt.', },
  },
  [13202] = {
    'Die Mauern verhexen',
    {'Hey, Mann. Siehst du, wie die Allianzler sich\'s in ihrer Festung bequem machen?|n|nDenke, die sehen ein wenig zu bequem aus, findste nich\'? Ich will den Ort verhexen, aber ich brauch dafür \'n paar Seelen, Mann. Aber nich\' irgendwelche Seelen; nur die eines starken Kämpfers ist dafür gut.|n|nDie Eiswasserfälle im Osten von Tausendwinter haben spezielle Eigenschaften, durch die man \'ne Seele heraussaugen kann. Bring die Allianzler dort um - die haben das Zeug, das wir brauchen.|n|nBring die Rüstungen der Toten hierher zu mir. Wenn da keine Allianzler sin\', dann haben die Elementare vielleicht welche, Mann.', },
    {'Hoodoomeister Fu\'jin in Tausendwinter möchte, dass Ihr zu den Eiswasserfällen geht und Allianzspielern dort 10 verzauberte Brustplatten der Allianz abnehmt.', },
  },
  [13203] = {
    'Ein Winterhauchgeschenk',
    nil,
    nil,
  },
  [13204] = {
    'Abgefahrene Pilze',
    {'Ein unförmiges Stück pilzähnlichen Fungus fällt von einem besonders übel riechenden, schlammbedeckten Teil des Fleischs der Höhlenbestie. Als Ihr ihn näher betrachtet, werdet Ihr von dessen Gestank überwältigt und weicht angewidert zurück.|n|nIhr wundert Euch, ob die Neruber so etwas appetitlich finden. Ihr steckt den klebrigen Organismus in Eure Tasche und seid fest dazu entschlossen, es herauszufinden...', },
    {'Ihr sollt 6 groteske Pilze von den wilden Höhlenbestien in Ahn\'kahet sammeln und sie bei Kilix dem Entwirrer in der Grube von Narjun abliefern.', },
  },
  [13205] = {
    'Abrüstung',
    {'Glaubt mir, $G Kamerad:Fräulein;, die Waffen der Vrykul sind durchweg gefährlich!|n|nIch habe ihre Schneiden am eigenen Leib erfahren und muss sagen, dass sie etwas Unnatürliches an sich haben. Sie sind täuschend gut ausbalanciert und unverschämt scharf - kurz gesagt einfach tödlich.|n|nGelangt in ihre Festung und krallt Euch zumindest einige dieser Waffen! Vielleicht können wir etwas von ihnen lernen, vielleicht auch nicht.|n|nIm Endeffekt ist es so: Je weniger Äxte sie herumschwingen, desto besser.', },
    {'Verteidiger Mordun möchte, dass Ihr Burg Utgarde betretet und 5 Waffen der Vrykul stehlt.', },
  },
  [13206] = {
    'Abrüstung',
    {'Wir müssen hinter das Geheimnis der Waffen dieser Barbaren kommen!|n|nWenn Ihr nur gesehen hättet, wie leicht sie meine Gefährten in Stücke schnitten, würdet Ihr verstehen, weshalb ich so dränge.|n|nSucht den Ort ab. Sammelt so viele ihrer Waffen, wie Ihr nur tragen könnt.', },
    {'Dunkelläuferin Marrah möchte, dass Ihr 5 Waffen der Vrykul aus Burg Utgarde stehlt und sie ihr in Burg Utgarde bringt.', },
  },
  [13207] = {
    'Die Hallen des Steins',
    {'Also ich bin überrascht, an einem Ort wie diesem andere Abenteurer anzutreffen.|n|nWenn meine Untersuchungen über diese Hallen stimmen, dann sind hier gewaltige Entdeckungen zu machen!|n|nIhr könnt gerne mitkommen, wenn ich mich darauf verlassen kann, dass Ihr mir Rückendeckung gebt.', },
    {'Brann Bronzebart möchte, dass Ihr ihn bei der Suche nach den Geheimnissen, die in den Hallen des Steins verborgen liegen, begleitet.', },
  },
  [13211] = {
    'Das Feuer wird Euch läutern',
    {'Die Geißel benutzt unsere eigenen Gefallenen gegen uns, indem sie sie als Ghule oder Skelette wiederauferstehen lässt oder ihre Körper zerlegt und die Einzelteile benutzt, um neue Monstrositäten herzustellen. Das muss aufhören!|n|nDie Toten sind Helden, die in Verteidigung allen Lebens fielen und ein solch grausiges Schicksal muss ihnen erspart bleiben. Darüber hinaus können wir es uns einfach nicht leisten, ihnen im Feld erneut gegenüberzustehen, als Waffen gegen uns eingesetzt. Nehmt diese Fackel mit Euch in die Fleischwerke und verbrennt alle Leichen, die Ihr im Sanktum der Reanimation oder im Monstrositätenlabor finden könnt.', },
    {'Kreuzfahrer Olakin Sainrith bei der Schwarzwacht möchte, dass Ihr mithilfe Olakins Fackel 7 eitrige Leichen verbrennt.', },
  },
  [13212] = {
    'In die Brüche gegangen',
    {'Die Entführung des Kreuzzüglers Olakin lässt die Streitkräfte des Argentumkreuzzugs beim letzten Sturm auf die Fleischwerke führerlos dastehen. Obwohl für mich ein Kreuzzügler aussieht wie der andere, sehen die Argentumsoldaten das anders.|n|nEs gefällt mir gar nicht, unsere Zeit mit einer Schnitzeljagd zu verschwenden, aber ich habe keine andere Wahl. Unser heldenhafter Kreuzzügler wurde vermutlich schon längst in seine Einzelteile zerlegt und seine Überreste beim Zusammenbau von Monstrositäten verwendet. Geht hinunter in die Fleischwerke, tötet die Schrecken, die unsere Truppen bekämpfen, und bringt Olakins Körperteile zurück.', },
    {'Bergt Olakins Oberkörper, Olakins Beine, Olakins linken Arm und Olakins rechten Arm und bringt sie der Dunkelreiterin Arly in der Schwarzwacht.', },
  },
  [13213] = {
    'Kampf bei Valhalas',
    {'Ich sehe und höre viele Dinge, $N, und etwas sehr Wichtiges ist passiert, seitdem Ihr Oberthan Balgarde besiegt habt: Man will gegen Euch in Valhalas kämpfen!|n|nDie Kampfgrube befindet sich gen Norden. Geht jetzt, nehmt Eure Freunde mit, und sprecht mit Geirrvif der Val\'kyr. Bei den Herausforderern, die sie gegen Euch in den Ring werfen wird, werdet Ihr sicherlich Unterstützung brauchen.|n|nViel Glück.', },
    {'Sprecht mit Geirrvif in Valhalas.', },
  },
  [13214] = {
    'Kampf bei Valhalas: Gefallene Helden',
    {'Wenn Ihr glaubt, soweit zu sein, dann habe ich genau den richtigen Kampf für Euch, um Euch Eure ersten Sporen zu verdienen.|n|nEine andere Gruppe von Außenseitern dachte, sie wären bereit, sich der Härte Valhalas zu stellen. Sie schwangen große Reden und fielen am Ende doch wie all die anderen vor ihnen.|n|nWenn Ihr Euch für so anders haltet - wenn Ihr glaubt, Ihr hättet die Fähigkeiten und die Erfahrung, hier gegen solch sagenumwobene Krieger anzutreten - dann nehmt die Herausforderung bitte an.', },
    {'Geirrvif in Valhalas hat Euch dazu herausgefordert, im Einzelkampf alle sechs gefallenen Helden zu besiegen: Eldreth, Geness Halbseele, Jhadras, Masud, Rith und Talla.|n|nSprecht mit Gjonner dem Erbarmungslosen am südlichen Rand von Valhalas, solltet Ihr erfolgreich sein.', },
  },
  [13215] = {
    'Kampf bei Valhalas: Khit\'rix der Dunkle Meister',
    {'Verschiedene Wesen reisen um die ganze Welt, um sich in Valhalas selbst zu beweisen; einige kommen sogar aus der Unterwelt.|n|nKhit\'rix der Dunkle Meister ist so einer.|n|nEr ist in den Tiefen dieser Erde geboren, dort, wo Wahnsinn herrscht, und er verlangt nach jemandem, der anders als die meisten ist und sich ihm im Ring stellen wird. Ihr werdet genügen.|n|nWagt Ihr es, $R, dem nerubischen Alptraum gegenüberzutreten?', },
    {'Geirrvif in Valhalas hat Euch dazu herausgefordert, Khit\'rix den Dunklen Meister zu vernichten.|n|nSprecht mit Gjonner dem Erbarmungslosen am südlichen Rand von Valhalas, solltet Ihr erfolgreich sein.', },
  },
  [13216] = {
    'Kampf bei Valhalas: Die Rückkehr von Sigrid Eiskind',
    {'Ein alter Feind von Euch ist zurückgekehrt: Sigrid Eiskind. Vielleicht könnt Ihr Euch noch daran erinnern, wie Ihr sie auf der Wilden Klippe besiegt habt?|n|nEgal, sie kann sich noch sehr gut an Euch erinnern. Sie besteht darauf, sich noch einmal beweisen zu dürfen.|n|nIch persönlich denke, dass es eher um Rache geht, doch auch das kann hier nützlich sein.|n|nIch überlasse es Euch, $N. Werdet Ihr Euch einmal mehr Sigrid Eiskind stellen?', },
    {'Geirrvif in Valhalas hat Euch dazu herausgefordert, Sigrid Eiskind zu vernichten.|n|nSprecht mit Gjonner dem Erbarmungslosen am südlichen Rand von Valhalas, solltet Ihr erfolgreich sein.', },
  },
  [13217] = {
    'Kampf bei Valhalas: Massaker!',
    {'Ihr habt es zwar bis hierher geschafft, $N, doch um weiterhin in Valhalas zu kämpfen, müsst Ihr einem gigantischen Schrecken gegenübertreten, wie Ihr ihn Euch gar nicht vorstellen könnt.|n|nIch muss Euch dazu raten, jetzt kehrt zu machen. Massaker ist ein Fleischberg, erschaffen von den grausamsten Köpfen, die im Dienste des Lichkönigs stehen.|n|nIch kann mir nicht vorstellen, wie Eure Freunde und Ihr ihn besiegen wollt. Die Entscheidung liegt jedoch bei Euch.', },
    {'Geirrvif in Valhalas hat Euch dazu herausgefordert, Massaker zu vernichten.|n|nSprecht mit Gjonner dem Erbarmungslosen am südlichen Rand von Valhalas, solltet Ihr erfolgreich sein.', },
  },
  [13218] = {
    'Kampf bei Valhalas: Than Todesstoß',
    {'Die Vrykul von Jotunheim haben nicht übersehen, welches Können Ihr an den Tag legt, $N. Than Banahogg hat ein persönliches Interesse an Euch gezeigt und darauf bestanden, Euer nächster Gegner zu sein.|n|nWenn Ihr Massaker schlimm fandet, dann wäre es wohl besser, wenn Ihr jetzt nach Hause geht. Than Banahoggs Spitzname ist "Todesstoß". Ich denke, Ihr könnt erraten, wie er sich den verdient hat.|n|nAkzeptiert Ihr die Herausforderung des Thans?', },
    {'Geirrvif in Valhalas hat Euch dazu herausgefordert, Than Banahogg den "Todesstoß" zu besiegen.|n|nSprecht mit Gjonner dem Erbarmungslosen am südlichen Rand von Valhalas, solltet Ihr erfolgreich sein.', },
  },
  [13219] = {
    'Kampf bei Valhalas: Letzte Herausforderung',
    {'Ich fürchte, dass Euer Erfolg auch Euer Untergang sein wird, $N.|n|n<Könnte die Val\'kyr noch bleicher werden, dann würde sie das gerade.>|n|nNachrichten über Euren Erfolg in Valhalas sind bis tief in die Eiskronenzitadelle vorgedrungen und haben jemanden wachgerufen, den Ihr lieber nicht kennen möchtet.|n|nPrinz Sandoval höchstpersönlich ist in diesem Augenblick auf dem Weg hierher. Gjonner hat Euch gewarnt und gesagt, dass Ihr wegrennen solltet, und ich kann ihm nicht widersprechen.|n|nWas werdet Ihr tun? Er ist auf dem Weg hierher. Werdet Ihr Euch dem Blutprinzen im letzten Kampf entgegenstellen?', },
    {'Geirrvif in Valhalas hat Euch dazu herausgefordert, Prinz Sandoval zu besiegen.|n|nSprecht mit Gjonner dem Erbarmungslosen am südlichen Rand von Valhalas, solltet Ihr erfolgreich sein.', },
  },
  [13220] = {
    'Olakin wieder zusammensetzen',
    {'Wir können es uns nicht leisten, irgendwelche Zeit zu verlieren und Olakin wieder zusammenzusetzen. Zum Glück bietet Euch die Geißel den perfekten Ort, um ihn wieder zusammenzuflicken.|n|nIn der Nähe des Fleischriesenlabors in den Fleischwerken befindet sich das Sanktum der Reanimation. Sucht in der Gegend nach einer Garnspule und dem Spalter des Doktors. Bringt anschließend Olakins sterbliche Überreste zur großen Platte in der Mitte des Sanktums und macht Euch an die Arbeit.', },
    {'Beschafft Euch eine Garnspule und den Spalter des Doktors. Geht dann zur Steinplatte des Sanktums der Reanimation und versucht, Kreuzfahrer Olakins sterbliche Überreste wiederzubeleben. Kehrt zu Dunkelreiterin Arly in die Schwarzwacht zurück, sobald die Aufgabe vollbracht ist.', },
  },
  [13221] = {
    'Noch bin ich nicht tot!',
    {'Das Licht ist mir hold. Dieser wahrgewordene Alptraum hat mich noch nicht erledigt, doch die Geißel wird mich mit Sicherheit töten und meinen Körper in Stücke reißen und in ihrem \'Werk\' verwenden, wenn es mir nicht gelingt zu entkommen.|n|nAlleine werde ich es nicht schaffen, mein Kind, aber mit Eurer Hilfe könnte ich überleben, auf dass ich der Geißel erneut entgegentreten kann.|n|nWerdet Ihr mir helfen zu entkommen, bevor die Schlächter der Geißel eintreffen, um mich zu erledigen?', },
    {'Bringt Vater Kamaros in Sicherheit und erstattet dann Absalan dem Frommen an Bord der Himmelsbrecher Bericht.', },
  },
  [13222] = {
    'Belagerungsmaschinen verteidigen',
    {'An vorderster Front, $N! Wir starten unseren Angriff auf die Tausendwinterfestung. Diese barbarischen Hordler denken wohl, sie könnten sich feige hinter ihren Mauern verkriechen? Nun, ich denke nicht! Wir werden ihnen zeigen, wie mächtig gnomische Technologie ist, und ihre Mauern zertrümmern!|n|nDoch ohne Mannschaft ist selbst die stärkste Belagerungsmaschine hilflos ausgeliefert. Steuert oder beschützt eine unserer Belagerungsmaschinen - es müssen drei Gebäude der Horde zerstört werden.', },
    {'Chefdemolierer Legoso in Tausendwinter möchte, dass Ihr eine Belagerungsmaschine steuert oder beschützt. Die Maschine muss drei Gebäude zerstören.|n|nSpieler, die den Rang "Gefreiter" oder höher besitzen, können Belagerungsmaschinen in Goblinwerkstätten bauen.', },
  },
  [13223] = {
    'Belagerungsmaschinen verteidigen',
    {'Die Allianz die Festung nicht mehr lange halten wird. Murp würde Mauern kaputt hauen, doch Murp muss im Lager bleiben. Murp wünscht sich, er könnte Allianzler kaputt hauen, die Verwüster von Horde wehtun wollen.|n|nDu, $N! Du gehst anstatt Murp. Beschütz 3 Belagerungsmaschinen, wenn die gerade die Allianzgebäude kaputt machen. Zeig der Allianz wie klug Murp ist!', },
    {'Leutnant Murp in Tausendwinter möchte, dass Ihr eine Belagerungsmaschine steuert oder verteidigt. Die Maschinen müssen 3 Gebäude der Allianz zerstören.|n|nBelagerungsmaschinen können von Spielern der Horde, die einen Rang haben, in Goblinwerkstätten gebaut werden.', },
  },
  [13224] = {
    'Orgrims Hammer',
    {'Der Argentumkreuzzug hat meinen böse zugerichteten Körper von der Zerbrochenen Front hergeschleppt. Was für ein ruhmreicher Kampf, $R. Meine Axt sang, als sie ohne Unterschied Allianzabschaum und Geißler niedermachte.|n|nMeine Zeit ist vorüber. Es wird ein guter Tod sein. Überbringt eine Nachricht für mich, Soldat.|n|nUnsere Basis fliegt außerhalb der Reichweite der Geißel - hoch droben, zwischen Mord\'rethar und Aldur\'thar. Sie wird "Orgrims Hammer" genannt.|n|n<Hork bemüht sich vergeblich, zu salutieren.>|n|nFliegt hoch und geht dem Monstervehikel der Allianz aus dem Weg, der Himmelsbrecher. Sagt Korm... Sagt ihm, dass ich gestorben bin... im Kampf... Für die Horde.', },
    {'Sucht Himmelshäscher Korm Schwarznarbe an Bord der Orgrims Hammer über dem Eiskronengletscher auf.', },
  },
  [13225] = {
    'Die Himmelsbrecher',
    {'Wir steckten bis zum Hals in Einheiten der Geißel und der Horde. Die Schreie der Sterbenden erfüllten das Feld. Es war die reine Folter... erbarmungslos!|n|nMein Körper hat einfach irgendwann aufgegeben und ich fiel. Der Argentumkreuzzug hat mich wieder zurückgeholt. Sie haben mich von der Zerbrochenen Front geholt und hergebracht. Ich werde es aber nicht schaffen. Bitte, gewährt Ihr einem sterbenden Soldaten einen letzten Wunsch, $R? Unsere Basis, die Himmelsbrecher, fliegt über der Eiskrone. Dort werdet Ihr meinen befehlshabenden Offizier, Stabshauptmann Bartlett antreffen. Sagt ihm, dass ich als Soldat der Allianz gestorben bin.', },
    {'Sprecht mit Stabshauptmann Justin Bartlett an Bord der Himmelsbrecher, die über der Eiskrone fliegt.', },
  },
  [13226] = {
    'Der Tag der Abrechnung kommt!',
    {'Alleine können wir den Lichkönig nicht besiegen. Uneinigkeit ist unser Untergang!|n|nIch beschwöre Euch, $G Bruder:Schwester;, folgt dem Ruf. Der Argentumkreuzzug nimmt jeden in seine Reihen auf, der sich als Freiwilliger zur Teilnahme an den Kampfmaßnahmen meldet. Hochlord Tirion Fordring selbst erwartet Euch an der Argentumvorhut! Nehmt Euer Reittier und fliegt zu den südöstlichen Ausläufern der Eiskrone. Dort werdet Ihr Lord Fordring und die Soldaten des Argentumkreuzzugs antreffen.|n|nGeht jetzt, $C, der Tag der Abrechnung steht bevor!', },
    {'Meldet Euch bei Hochlord Tirion Fordring an der Argentumvorhut in Eiskrone.', },
  },
  [13227] = {
    'Der Tag der Abrechnung kommt!',
    {'Alleine können wir den Lichkönig nicht besiegen. Uneinigkeit ist unser Untergang!|n|nIch beschwöre Euch, $G Bruder:Schwester;, folgt dem Ruf. Der Argentumkreuzzug nimmt jeden in seine Reihen auf, der sich als Freiwilliger zur Teilnahme an den Kampfmaßnahmen meldet. Hochlord Tirion Fordring selbst erwartet Euch an der Argentumvorhut! Nehmt Euer Reittier und fliegt zu den südöstlichen Ausläufern der Eiskrone. Dort werdet Ihr Lord Fordring und die Soldaten des Argentumkreuzzugs antreffen.|n|nGeht jetzt, $C, der Tag der Abrechnung steht bevor!', },
    {'Meldet Euch bei Hochlord Tirion Fordring an der Argentumvorhut in Eiskrone.', },
  },
  [13228] = {
    'Die Zerbrochene Front',
    {'Welche Schlacht?! Diese Truppen waren auf Aufklärungsmission!|n|nUnd was soll das Gerede von wegen Allianz?|n|nJetzt hört mir mal zu, $N! Ich muss wissen, was hier vor sich geht und ich muss es JETZT wissen!|n|nBewegt Euch und besorgt mir ein paar Antworten! Durchkämmt das Schlachtfeld und sucht nach Überlebenden - Hinweisen - irgendwas etwas!', },
    {'Korm Schwarznarbe an Bord der Orgrims Hammer möchte, dass Ihr Euch an die Zerbrochene Front begebt und einen sterbenden Berserker dazu befragt, was geschehen ist.', },
  },
  [13229] = {
    'Noch bin ich nicht tot!',
    {'Das Licht ist mir hold. Dieser wahrgewordene Alptraum hat mich noch nicht erledigt, doch die Geißel wird mich mit Sicherheit töten und meinen Körper in Stücke reißen und in ihrem \'Werk\' verwenden, wenn es mir nicht gelingt zu entkommen.|n|nAlleine werde ich es nicht schaffen, $C, aber mit Eurer Hilfe könnte ich überleben, auf dass ich der Geißel erneut entgegentreten kann.|n|nWerdet Ihr mir helfen zu entkommen, bevor die Schlächter der Geißel eintreffen, um mich zu erledigen?', },
    {'Bringt Vater Kamaros in Sicherheit und erstattet dann Bruder Keltan an Bord der Orgrims Hammer Bericht.', },
  },
  [13230] = {
    'Rächt mich!',
    {'Ich kann sie hören, $G Bruder:Schwester;...|n|nDas Stöhnen der verwundeten Allianzler... Sie verspotten mich...|n|nBeendet, was wir hier begonnen haben, $C. Zeigt keine Gnade... Lasst niemanden am Leben.|n|nFür die Horde...', },
    {'Ein sterbender Berserker hat Euch darum gebeten, 5 sterbende Soldaten an der Zerbrochenen Front zu töten. Erstattet Himmelshäscher Korm Schwarznarbe auf der Orgrims Hammer Bericht, sobald dies erledigt ist.', },
  },
  [13231] = {
    'Die Zerbrochene Front',
    {'Was?! Neeeiinn!|n|nWir haben uns doch solche Mühe gegeben, diesen Angriff geheim zu halten. Woher wusste die Horde Bescheid? Die Reserven... Die Männer... Alles verloren? Unfassbar!|n|nUnsere Pläne in Eiskrone basierten darauf, dass das Tor vor der Horde genommen werden würde. Wir müssen uns schnell neu formieren und uns darauf vorbereiten, eine weitere Offensive zu starten.|n|nBegebt Euch zum Schlachtfeld und sucht nach Überlebenden. Versucht, so viele Informationen wie möglich über diese Tragödie zu sammeln.|n|nUnd macht Euch bereit, $N, für einen Krieg - an zwei Fronten...', },
    {'Stabshauptmann Justin Bartlett an Bord der Himmelsbrecher möchte, dass Ihr Euch an die Zerbrochene Front begebt, den sterbenden Soldaten befragt und ihm dann erneut Bericht erstattet.', },
  },
  [13232] = {
    'Tötet mich!',
    {'Sie verspotten uns - selbst noch hier, während sie im Sterben liegen...|n|nIch bitte Euch... Lasst es nicht zu, dass ihr Spott das Letzte sein wird, was ich höre...|n|nTötet mich... erlöst mich von dieser Qual... und führt mich... zum Licht.|n|nGeht zu meinen Gefährten... gewährt ihnen dieselbe Gnade.|n|nHinterlasst der Geißel nichts, das sie wiederbeleben könnte!|n|nIch flehe Euch an...', },
    {'Der sterbende Soldat an der Zerbrochenen Front möchte, dass Ihr 5 sterbende Soldaten erlöst und dann Stabshauptmann Justin Bartlett auf der Himmelsbrecher Bericht erstattet.', },
  },
  [13233] = {
    'Keine Gnade!',
    {'Es ist, wie ich es Euch gesagt habe. Es waren nicht nur leere Worte, im Zorn gesprochen.|n|nWieder und wieder hat die Horde gezeigt, dass sie nichts auf das gibt, was uns am Herzen liegt. Für ihre Sünden gegen das Licht müssen sie mit dem Leben zahlen!|n|nJeder einzelne von ihnen.|n|nStellt Euch nur vor, $N, eine Welt ohne ihren Makel. Malt Euch aus, wie glücklich unsere Kinder aufwachsen könnten. Denkt daran, wie ehrfürchtig Eure Nachkommen Euren Namen aussprechen würden - da sie doch wissen, dass sie all ihr Glück nur Euch zu verdanken haben.|n|nGeht nun und lasst die Vision Realität werden!', },
    {'Stabshauptmann Justin Bartlett an Bord der Himmelsbrecher möchte, dass Ihr in Eiskrone 15 Spieler der Horde tötet.', },
  },
  [13234] = {
    'Sie müssen zahlen!',
    {'Die Zeit ist gekommen!|n|nViel zu lange mussten wir die Selbstgerechtigkeit der Allianz ertragen! Viel zu lange mussten wir uns zurückhalten, haben unsere Welt nicht von Schwachen und Verzweifelten gereinigt.|n|nJetzt endlich werden wir die Erniedrigung beenden! Jetzt werden wir ihnen die wahre Bedeutung von Angst zeigen! Jetzt werden wir der Horde Ehre machen!|n|nHier, in Eiskrone, werden wir die Allianz brechen!|n|nGeht, $C. Geht und bringt sie zur Strecke. Brecht sie! Nehmt ihnen den Willen zu leben!', },
    {'Himmelshäscher Korm Schwarznarbe möchte, dass Ihr 15 Spieler der Allianz in Eiskrone tötet.', },
  },
  [13235] = {
    'Der gigantische Fleischgigant',
    {'Mit der Zerstörung der Fleischwerke und der Vernichtung der Diener des Lichkönigs habt Ihr gute Arbeit geleistet. Nun ist alles, was noch zu tun bleibt, die Vernichtung des Meisterwerks der Fleischwerke - die Vernichtung des Fleischgiganten namens Morbidus.|n|nEs wird kein einfacher Kampf sein, doch das Schattengewölbe hat Markgraf Dhakar mit ein paar Unterstützungstruppen entsandt. Trefft Euch mit ihm beim höchsten Punkt der Fleischwerke am westlichen Rand. Sagt ihm Bescheid, wenn Ihr angriffsbereit seid, und er wird seine Truppen in die Schlacht schicken.', },
    {'Sprecht mit Markgraf Dhakar am westlichen Ende der Fleischwerke, um die Aufmerksamkeit von Morbidus zu erregen. Erstattet der Dunkelreiterin Arly an der Schwarzwacht Bericht, nachdem Ihr Morbidus getötet habt.', },
  },
  [13236] = {
    'Armee der Verdammten',
    {'Ihr meint wohl, Ihr seid ziemlich stark... diese Untoten zu bekämpfen und ihre Knochen mit Euren Kriegsmaschinen zu zerquetschen.|n|nDas ist aber noch gar nichts, verglichen mit der Stärke, derer es bedarf, um sie zu erschaffen.|n|nIch habe selbst gesehen, wie der Prinz es gemacht hat. Ich kann Euch zeigen, wie das geschehen ist... wenn Ihr wollt.', },
    {'Matthias Lehner beim Vorhutslager der Ersten Legion möchte, dass Ihr eine Armee von 100 ghulischen Dienern aufstellt.', },
  },
  [13237] = {
    'Stechen und Stoßen',
    {'Verlasst Euch drauf, während Euer Hauptmann von seinem Hass auf die Rivalen Eurer Allianz abgelenkt ist, richte ich meine volle Aufmerksamkeit auf den wahren Feind hier: den Lichkönig und seine Untergebenen.|n|nUm auch nur darauf hoffen zu können, ihn in seiner Zitadelle zu besiegen, müssen Eure Leute beide Tore erobern und halten.|n|nKonzentrieren wir uns für den Augenblick jedoch auf das Erste. Kehrt zur Front zurück und stoßt durch ihre Verteidigungslinie. Sucht nach irgendwelchen Schwachstellen, die wir ausnützen könnten.|n|nIch erwarte Euren Bericht, $C.', },
    {'Koltira Todesweber an Bord der Orgrims Hammer möchte, dass Ihr Euch an die Zerbrochene Front begebt und 5 bullige Monstrositäten, 5 bösartige Totenbeschwörer und 5 Schattenadepten besiegt.', },
  },
  [13238] = {
    'Zu etwas zu gebrauchen?',
    {'Goblins! Überdrehte Wichtigtuer...|n|nHört mal, $N. Kupferklammer, unser Hausingenieur, besteht darauf, dass er etwas Nützliches gefunden hat, was er mir unbedingt zeigen muss.|n|nIch bin nicht in der Stimmung, mir sein piepsiges Gezeter anzuhören. Das letzte Mal, dass ich ihm Aufmerksamkeit schenkte, hat er glatt eine Stunde lang durchgequäkt. Ich konnte mich gerade noch davon abhalten, ihn mit einem Tritt in Sindragosas Sturz zu befördern!|n|nIhr werdet an meiner Statt gehen und ihm Honig ums Maul schmieren. Lasst es mich wissen, falls er tatsächlich etwas herausgefunden haben sollte.', },
    {'Himmelshäscher Korm Schwarznarbe möchte, dass Ihr mit dem Chefingenieur Kupferklammer an Bord der Orgrims Hammer sprecht.', },
  },
  [13239] = {
    'Verflüchtigung',
    {'Wo soll ich anfangen...? Nun, Ihr müsst wissen, dass ich als Chefingenieur dieses Fahrzeugs Zugang zu allen möglichen nachrichtendienstlichen Berichten habe – ja, ja, es ist wahr, und seit Kurzem interessiere ich mich ganz besonders für die Frostwyrms, die Ihr im Süden gesichtet habt. Ich denke, ich habe einen Plan entwickelt, wie ihnen beizukommen sein könnte... Gut, ein paar Kleinigkeiten müssen noch von Euch erledigt werden, aber eigentlich nur Folgendes: Ihr baut eine Attrappe aus Rüstungsteilen und bestreicht sie mit dieser Lösung hier und dann geht Ihr in Deckung!|n|n... Immer noch da, $R?', },
    {'Chefingenieur Kupferklammer möchte, dass Ihr Kupferklammers flüchtiges Öl an der Zerbrochenen Front benutzt, um 3 Frostbrutvollstrecker anzulocken.|n|nUm das Öl benutzen zu können, müsst Ihr auf dem dortigen Schlachtfeld einen Knochenhaufen, einen zurückgelassenen Helm und eine zurückgelassene Rüstung einsammeln.', },
  },
  [13240] = {
    'Timear prophezeit Zentrifugenkonstrukte in Eurer Zukunft!',
    {'Ihr müsst zum Oculus über Kaltarra reisen, $N.|n|nIch habe eine Situation vorausgesehen, in der Ihr die dortigen Zentrifugenkonstrukte zerstören müsst. Ich kann Euch versichern, dass, solltet Ihr nicht zuerst diese magischen Schöpfungen beseitigen, Eure Gruppe versagen wird.|n|nDies habe ich gesehen und dies müsst Ihr tun.', },
    {'Erzmagier Timear in Dalaran hat vorausgesehen, dass Ihr 10 Zentrifugenkonstrukte zerstören müsst.', },
  },
  [13241] = {
    'Timear prophezeit Berserker der Ymirjar in Eurer Zukunft!',
    {'In nicht allzu ferner Zukunft werden zwischen Euch und dem Sieg lediglich König Ymirons Champions stehen.|n|nIhr werdet zur Festung namens Turm Utgarde tief in den Wäldern des Heulenden Fjords reisen. Ich kann nicht genug betonen, wie wichtig es ist, dass Ihr und Eure Reisegefährten Euch um die dortigen Berserker der Ymirjar kümmert.|n|nSolltet Ihr dies versäumen, ist es gut möglich, dass es Euch zum Verhängnis werden wird, $N!', },
    {'Erzmagier Timear in Dalaran möchte, dass Ihr 7 Berserker der Ymirjar tötet.', },
  },
  [13242] = {
    'Die Dunkelheit regt sich',
    {'Die Dunkelheit regt sich, $N. Etwas Tragisches hat sich ereignet, das niemand außer der Zeitlose selbst voraussehen hätte können. Bald wird Euer Volk von Wut und Hass erfasst werden. Krieg ist am Horizont.|n|nDer rote Drachenschwarm hat alles getan, was in seiner Macht steht. Was als Nächstes passiert, liegt in den Händen der sterblichen Völker Azeroths.|n|nLeider beginnt Eure Reise mit Schmerz. Ein Vater hat heute ein Kind verloren und Ihr müsst die schlimme Nachricht überbringen. Sammelt Saurfangs Rüstung ein und bringt sie zum Ältesten Saurfang zurück.', },
    {'Geht aufs Schlachtfeld hinaus, sucht nach Saurfangs Schlachtrüstung und bringt sie zu Hochfürst Saurfang in der Kriegshymnenfestung in der Boreanischen Tundra.', },
  },
  [13243] = {
    'Timear prophezeit Ewige Agenten in Eurer Zukunft!',
    {'Die Zeitlinie wird vom ewigen Drachenschwarm bedroht. Ohne Euer Eingreifen wird die Zeit zunichtegemacht werden!|n|nIhr müsst in die Höhlen der Zeit gehen und zu einem Zeitpunkt zurückreisen, an dem ein Ereignis namens \'das Ausmerzen von Stratholme\' stattfand.|n|nMir bereitet es Kopfschmerzen, auch nur zu versuchen, in alle möglichen Vergangenheiten zu blicken, doch ich weiß, dass es äußerst wichtig für Euch ist, die ewigen Agenten zu töten.|n|nNur durch ihren Tod wird die wahre Vergangenheit beibehalten und Gegenwart und Zukunft werden davor bewahrt, für immer ungeschehen gemacht zu werden!', },
    {'Erzmagier Timear in Dalaran hat prophezeit, dass Ihr 4 ewige Agenten töten müsst.', },
  },
  [13244] = {
    'Timear prophezeit Titanvorposten in Eurer Zukunft!',
    {'Ganz Azeroth ist in Gefahr. Der verrückte Gott Loken besitzt die Macht, allem ein Ende zu bereiten!|n|nIm Irdischen Wachturm in den Hallen der Blitze stehen Titanvorposten kurz davor, Lokens schrecklichen Willen auszuführen - dem würden unzählige Ahnungslose zum Opfer fallen.|n|nIch habe in die Zukunft geblickt, $N. Ihr seid $Gderjenige, der:diejenige, die; sich darum kümmern wird, dass dies nicht geschieht!', },
    {'Erzmagier Timear in Dalaran hat prophezeit, dass Ihr 7 Titanvorposten töten müsst.', },
  },
  [13245] = {
    'Todesbeweis: Ingvar der Brandschatzer',
    {'Ihr müsst eine Gruppe zusammenstellen und sie nach Burg Utgarde führen. Dort sollt Ihr dann nach Ingvar dem Brandschatzer suchen und ihn töten, bevor er mit seinen Vrykultruppen die nahegelegenen Städten der Allianz und Horde überfallen und plündern kann.|n|nIch brauche seine Axt als Beweis dafür, dass man sich um ihn gekümmert hat. Es wäre ja nicht so, dass ich Euch nicht vertrauen würde. Doch es ist einfach nur klug, sich absolut sicher zu sein, ob die Aufgabe nun erledigt wurde.', },
    {'Erzmagier Lan\'dalock in Dalaran möchte, dass Ihr mit der Axt des Brandschatzers zurückkehrt.|n|nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad \'Heroisch\' abgeschlossen werden.', },
  },
  [13246] = {
    'Todesbeweis: Keristrasza',
    {'Seid Ihr mit der Geschichte von Keristrasza vertraut?|n|nDamit, dass sie maßgeblich daran beteiligt war, Saragosa, Malygos\' Gefährtin, zu töten? Wie er wiederum Keristrasza zur Gemahlin nahm und sie in einen Block aus Eis einschloss?|n|nWir wissen nun, dass Malygos seine Magie dazu benutzt hat, um ihren Willen zu brechen, was sie in den Wahnsinn getrieben hat.|n|n$N, Ihr müsst in den Nexus nach Kaltarra gehen und ihr ein Ende bereiten, bevor sie komplett überläuft.|n|nZwar macht es mich traurig, doch ich muss darauf bestehen, dass Ihr mir ihr Herz als Beweis bringt.', },
    {'Erzmagier Lan\'dalock in Dalaran möchte, dass Ihr mit Keristraszas gebrochenem Herzen zurückkehrt.|n|nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad \'Heroisch\' abgeschlossen werden.', },
  },
  [13247] = {
    'Todesbeweis: Leywächter Eregos',
    {'Der Nexuskrieg tobt weiter und wir müssen etwas unternehmen, um das Blatt zu wenden! Seid Ihr willens, ins Herz der Schlacht zu fliegen, $N?|n|nLeywächter Eregos ist der Beschützer des Kanals, durch den Malygos die magische Energie von Azeroths Leylinien schleust. Würde er getötet, wäre dies ein großer Rückschlag für den Feind.|n|nBitte bringt mir einen seiner Leylinienempfänger, damit wir ihn untersuchen können.', },
    {'Erzmagier Lan\'dalock in Dalaran möchte, dass Ihr mit einem Leylinienempfänger zurückkehrt.|n|nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad \'Heroisch\' abgeschlossen werden.', },
  },
  [13248] = {
    'Todesbeweis: König Ymiron',
    {'König Ymiron im Turm Utgarde ist der Lieblingsvrykul des Lichkönigs. Das alleine ist Grund genug, ihm ein Ende zu bereiten.|n|nDoch sollte er die Hörner erschallen lassen und alle Anführer der Ymirjar sowie der Mjordin zu sich rufen, würden die Vrykul zu einer Macht heranwachsen, die stärker als jede andere Gruppe innerhalb der Geißel wäre!|n|nEs liegt an Euch, $N, dafür zu sorgen, dass dies nicht geschieht. Bringt mir das Medaillon, das er um seinen Hals trägt, damit ich weiß, dass Ymiron keine Gefahr mehr darstellt.', },
    {'Erzmagier Lan\'dalok in Dalaran möchte, dass Ihr mit dem Medaillon der verstorbenen Königin zurückkehrt.|n|nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad \'Heroisch\' abgeschlossen werden.', },
  },
  [13249] = {
    'Todesbeweis: Der Prophet Tharon\'ja',
    {'Einst war die Feste Drak\'Tharon eine stolze Bastion des Drakkarireiches. Nun ist sie nichts weiter als ein Sprungbrett für den Lichkönig in seinem Kampf, Zul\'Drak ein Ende zu bereiten und die Kräfte der Trollgötter an sich zu reißen.|n|nDoch sollten wir ihren Anführer Prophet Tharon\'ja ausschalten, könnten wir vielleicht den Zustrom weiterer Trolle der Geißel verhindern. Das Mindeste, was dabei herauskommen könnte, wäre, dass der Argentumkreuzzug in Zul\'Drak eine Sorge weniger hat.|n|nBringt mir sein Tiki, damit ich weiß, dass der Prophet tot ist.', },
    {'Erzmagier Lan\'dalok in Dalaran möchte, dass Ihr mit dem verzauberten Tiki des Propheten zurückkehrt.|n|nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad \'Heroisch\' abgeschlossen werden.', },
  },
  [13250] = {
    'Todesbeweis: Gal\'darah',
    {'Die Drakkaripropheten von Zul\'Drak haben das undenkbare getan: Sie haben die meisten ihrer Götter getötet und ihre Kraft in sich aufgenommen! Der gefährlichste von allen ist Akalis Hochprophet Gal\'darah.|n|nGal\'darah hält sich in den Tiefen von Gundrak verborgen und hat fast das gesamte Mojo des toten Akali in sich aufgesaugt. Nun ist er kurz davor, mit seinen Anhängern aus der Stadt auszubrechen. Wenn wir ihn jetzt nicht töten, werden wir in einem Meer des Wahnsinns ertrinken und von unvorstellbarer Macht erdrückt!|n|nBeeilt Euch, $N, bringt mir, was von Akalis Mojo übrig geblieben ist.', },
    {'Erzmagier Lan\'dalock in Dalaran möchte, dass Ihr mit den Überresten von Akalis Mojo zurückkehrt.|n|nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad \'Heroisch\' abgeschlossen werden.', },
  },
  [13251] = {
    'Todesbeweis: Mal\'Ganis',
    {'$N, ein Freund innerhalb des bronzenen Drachenschwarms hat mir Informationen zukommen lassen, die wir ausnützen müssen.|n|nDie mysteriösen Geschöpfe der Brennenden Legion namens Schreckenslords werden in Hinblick auf ihre Rasse auch als die Nathrezim bezeichnet. Wenig ist über ihre Heimatwelt bekannt, und selbst das ist nur ein Gerücht.|n|nEs ist jedoch bekannt, dass Mal\'Ganis in der Vergangenheit einen entscheidenden Fehler gemacht hat: er hinterließ ein Artefakt seiner Heimatwelt!|n|nÜber die Höhlen der Zeit müsst Ihr in der Zeit zurückreisen und einem Ereignis beiwohnen, das auch \'das Ausmerzen von Stratholme\' genannt wird. Beschafft das Artefakt.', },
    {'Erzmagier Lan\'dalock in Dalaran möchte, dass Ihr mit dem Artefakt aus der Heimatwelt der Nathrezim zurückkehrt.|n|nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad \'Heroisch\' abgeschlossen werden.', },
  },
  [13252] = {
    'Todesbeweis: Sjonnir der Eisenformer',
    {'Nur wenig ist über das Leiden bekannt, welches \'Fluch des Fleisches\' genannt wird. In den Hallen des Steins gibt es jedoch Informationen zu holen.|n|nSjonnir der Eisenformer scheint sich ziemlich gut mit dem Fluch auszukennen. Wir wissen aus guter Quelle, dass er eine titanische Informationsscheibe bei sich hat, die all unsere Fragen beantworten könnte.|n|nBesorgt mir diese Scheibe, $N, damit wir mehr erfahren können.', },
    {'Erzmagier Lan\'dalock in Dalaran möchte, dass Ihr mit der \'Datenscheibe: Fluch des Fleisches\' zurückkehrt.|n|nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad \'Heroisch\' abgeschlossen werden.', },
  },
  [13253] = {
    'Todesbeweis: Loken',
    {'Loken im Inneren der Hallen der Blitze steht kurz davor, unserer Welt ein Ende zu bereiten. Muss ich noch mehr sagen, $N?|n|nEr sitzt dort und lauscht dem verrückten Geflüster des Alten Gottes, der unter Nordend gefangen ist. Ihr müsst umgehend mit einer Gruppe zu den Sturmgipfeln reisen!|n|nGeht zum Irdischen Wachturm und stellt Euch Loken zum Kampf. Haltet ihn auf, bevor es zu spät ist! Bringt mir seinen Rubinring, damit ich weiß, dass wir wieder sicher sind.', },
    {'Erzmagier Lan\'dalock in Dalaran möchte, dass Ihr mit dem himmlischen Rubinring zurückkehrt.|n|nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad \'Heroisch\' abgeschlossen werden.', },
  },
  [13254] = {
    'Todesbeweis: Anub\'arak',
    {'Die Neruber der Geißel sind eine Plage für unsere Truppen.|n|nHier, über der Welt schwebend, sind wir zwar vor ihnen sicher, doch setzt man seinen Fuß auf das Land unter uns, hat man ständig den Gedanken im Hinterkopf, dass die untoten Neruber aus den Tiefen Azjol-Nerubs jeden Augenblick aus der Erde springen und angreifen könnten.|n|nEs liegt im besten Interesse von uns allen, wenn sie ins Chaos gestürzt werden. Tötet ihren früheren König, den Majordomus des Lichkönigs, den Gruftlord Anub\'arak.|n|nBitte bringt mir seine Krone... es wäre ja nicht so, dass er sie noch trägt.', },
    {'Erzmagier Lan\'dalock in Dalaran möchte, dass Ihr mit der unnützen Krone Anub\'araks zurückkehrt.|n|nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad \'Heroisch\' abgeschlossen werden.', },
  },
  [13255] = {
    'Todesbeweis: Herold Volazj',
    {'Die Neruber von Ahn\'kahet gruben zu tief, als sie versuchten, dem Überfall der Geißel zu entkommen. Sie kamen dem alten Gott in den Tiefen Nordends zu nah.|n|nDer Alte Gott, von ihnen wach gerufen, hetzte seine wild gewordenen Kreaturen auf sie - die Neruber saßen also sprichwörtlich in der Klemme.|n|nHerold Volazj, der Anführer der Streitkräfte des alten Gottes, ist eines der alptraumhaften Wesen, die auch die Gesichtslosen genannt werden. Beseitigt ihn und bringt mir sein verdorrtes Gehirn.|n|nNur bitte ich Euch, dass Ihr versucht, bei Verstand zu bleiben.', },
    {'Erzmagier Lan\'dalock in Dalaran möchte, dass Ihr mit dem siechenden Gehirn des Gesichtslosen zurückkehrt.|n|nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad \'Heroisch\' abgeschlossen werden.', },
  },
  [13256] = {
    'Todesbeweis: Cyanigosa',
    {'Wir werden überfallen! Der blaue Drachenschwarm hat sich in die Violette Festung teleportiert und sie planen, von dort auszubrechen und sich im Rest von Dalaran zu verbreiten!|n|nEs gab schon Berichte von Gefangenen, die dadurch versehentlich befreit wurden. Es würde mich nicht wundern, wenn sie einige von ihnen absichtlich freilassen würden.|n|n$N, könnt Ihr schnell ein Team zusammenstellen und Euch dorthin begeben? Cyanigosa ist die Anführerin der Invasionstruppen. Bringt mir ihren Kopf!', },
    {'Erzmagier Lan\'dalock in Dalaran möchte, dass Ihr mit Cyanigosas Kopf zurückkehrt.|n|nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad \'Heroisch\' abgeschlossen werden.', },
  },
  [13257] = {
    'Vorbote des Krieges',
    {'Champion, der Kriegshäuptling braucht Euch. Über Orgrimmar ist das Kriegsrecht verhängt worden. Alle Handels- und Dienstleistungsaktivitäten wurden eingestellt, während sich der Kriegshäuptling auf einen unvermeidlichen Konflikt vorbereitet.|n|nMehr kann ich Euch nicht sagen - nicht jetzt, nicht hier.|n|nDer Kriegshäuptling befiehlt, dass sich die stärksten Champions in seinem Thronsaal melden. Geht jetzt, $N! Nehmt das Portal zurück nach Orgrimmar und sucht Thrall auf.', },
    {'Meldet Euch bei Thrall in der Feste Grommash in Orgrimmar.', },
  },
  [13258] = {
    'Gelegenheit',
    {'Wir sind kürzlich über Schemata gestolpert, die auf eine Schwachstelle in der Eiskronenzitadelle hinweisen - eine offene Stelle in ihrer Verteidigung, bildlich und wörtlich genommen.|n|nDie Pläne, die gefunden wurden, zeigen eine Öffnung, die mehrere hundert Meter in den Boden geht. Wir sind uns nicht sicher, welchem Zweck sie dient, doch unseren Aufklärungsberichten zufolge ist sie für die Geißel äußerst wichtig.|n|nSprecht mit Unteroffizier Kregga unterhalb der Eiskronenzitadelle. Sie leitet den dortigen Angriff.', },
    {'Sprecht mit Unteroffizier Kregga unterhalb der Eiskronenzitadelle.', },
  },
  [13259] = {
    'Für Überlegenheit sorgen',
    {'Wir haben eine einzige Chance, dieser Zitadelle ein wenig Schaden zuzufügen - sorgen wir also dafür, dass wir\'s richtig machen.|n|nWir sind in den Besitz von schweren Saronitbomben gelangt, die von der Geißel hergestellt wurden. Doch bevor wir sie loslassen können, müssen wir erst die Gegend sichern.|n|nWir werden die Verteidigungsstellungen der Geißel schnell unter Kontrolle bringen müssen, bevor ihre Verstärkung eintrifft.|n|nSteht meinen Männern zur Seite und kommt wieder zurück, wenn Ihr bereit für ein kleines Feuerwerk seid.', },
    {'Unteroffizier Kregga an der Eiskronenzitadelle möchte, dass Ihr 10 bullige Schrecken tötet.', },
  },
  [13260] = {
    'Der Insider',
    {'Obwohl wir keine Gelegenheit auslassen sollten, der Allianz einen Schlag zu versetzen, dürfen wir auf gar keinen Fall die Geißel vergessen.|n|nWir haben zwar nicht genug Männer, um in den nächsten Wochen einen vernünftigen Ausfall in den Gletscher zu wagen, doch sollte uns das nicht davon abhalten, so viel wie möglich über ihre Verteidigung in Erfahrung zu bringen.|n|nIch habe unseren Todesritter gebeten, Euch in dieser Sache zu beraten. Schließlich kennt niemand den Feind besser als sie.|n|nErlaubt mir, Euch Koltira Todesweber vorzustellen.', },
    {'Himmelshäscher Korm wünscht, dass Ihr mit Koltira Todesweber auf der Orgrims Hammer sprecht.', },
  },
  [13261] = {
    'Verflüchtigung',
    {'Wahuu! Es funktioniert! Nicht dass ich irgendwelche Zweifel an meiner übernatürlichen Genialität gehabt hätte... Ich war nur nicht ganz sicher, was für eine Art von Explosion kommen würde... Lasst uns einfach sagen, dass ich froh bin, dass Ihr Euch nicht die Augenbrauen abgefackelt habt... So, nun muss ich dem alten Korm nur zeigen, wie man die Wyrms auftaut. Dann muss er mich befördern zum... zum... zu was-auch-immer nach Chefingenieur kommt! Hier, nehmt noch eine Portion von dem Zeug und kehrt an die Front zurück, ich werde mit Korm reden...|n|nNa? Bewegt Euch!', },
    {'Chefingenieur Kupferklammer möchte, dass Ihr Kupferklammers flüchtiges Öl an der Zerbrochenen Front benutzt, um 3 Frostbrutvollstrecker anzulocken.|n|nUm das Öl benutzen zu können, müsst Ihr auf dem dortigen Schlachtfeld einen Knochenhaufen, einen zurückgelassenen Helm und eine zurückgelassene Rüstung einsammeln.', },
  },
  [13262] = {
    'Jagt es hoch!',
    {'Besser werden wir die Sache hier wohl nicht unter Kontrolle bekommen. Legen wir los, $N.|n|nIch brauche jemanden, der die Lunten an diesen Bomben anzündet, und es sieht so aus, als wärt Ihr derjenige.', },
    {'Geht zu dem nahen Saronitbombenstapel und zündet die Lunte an.', },
  },
  [13263] = {
    'Eine kurze Lunte',
    {'Als Ihr die Lunte entzündet, merkt Ihr, dass sie viel schneller abbrennt, als Ihr erwartet hattet.|n|nDie Bomben sind kurz vor der Explosion und Eure beste Chance zu überleben ist, Euch nach vorne fallen zu lassen und zu hoffen, dass Euch der Sturz nicht tötet.', },
    {'Haltet nach Hinweisen Ausschau, wo auch immer der Sturz Euch hinführt.', },
  },
  [13264] = {
    'Das ist monströs!',
    {'Monstrositäten...|n|nSie können sehr fähige Gegner sein. Ich habe mehr als einmal gesehen, wie sie den Ausgang einer Schlacht gewendet haben. Nur wenige erkennen, dass sie auch sehr fähige Freunde sein können.|n|nSie sind keine großen Denker. Wenn Ihr die Geheimnisse ihrer Erschaffung kennt, dann könnt Ihr ihnen einige Grundbefehle erteilen, die sie nicht hinterfragen werden.|n|nZu Eurem Glück kenne ich diese Geheimnisse.|n|nDieses Set wird die Überreste der Monstrositäten, die Ihr besiegt habt, wiederbeleben. Nehmt es und lernt, es gegen die Geißel am Tor des Todes einzusetzen.', },
    {'Koltira Todesweber auf der Orgrims Hammer möchte, dass Ihr das Monstrositätenwiedererweckungsset benutzt, um eine wiedererweckte Monstrosität zu erschaffen, mit der Ihr dann 15 Eisghule, 15 heimtückische Spuke und 15 auferstandene Soldaten der Allianz töten sollt.', },
  },
  [13265] = {
    'Das Plündern von Stoffen',
    nil,
    nil,
  },
  [13266] = {
    'Ein Leben ohne Reue',
    {'Am Tage meines Todes möchte ich sagen können, dass ich ein Leben ohne Reue geführt habe. Diejenigen, die mein Dahinscheiden betrauern, werden wissen, dass ich ein Kriegshäuptling war, der die besten Entscheidungen für sein Volk getroffen hat.|n|nDoch Varimathras\' und Putress\' Verrat... Alles, wofür wir gearbeitet haben, ist umsonst gewesen.|n|n<Thrall gibt einen langen Seufzer von sich.>|n|nPortale nach Unterstadt werden vorübergehend aktiv sein. Vol\'jin wird auf Euch warten. Ich werde Euch schon bald dort antreffen. Gemeinsam werden wir die Sache wieder bereinigen, $N.', },
    {'Nehmt das Portal nach Unterstadt, das sich in der Feste Grommash befindet, und meldet Euch bei Vol\'jin.', },
  },
  [13267] = {
    'Die Schlacht um Unterstadt',
    {'Ganz Unterstadt steht unter Varimathras\' Kontrolle. Unsere Soldaten stehen bereit und warten auf den Angriffsbefehl des Kriegshäuptlings.|n|nHelft der Horde, Unterstadt zurückzuerobern, und verdient Euch einen Platz unter unseren größten Champions! Erstattet Thrall Bericht, falls Ihr den Angriff überleben solltet.|n|nMeldet Euch beim Kriegshäuptling, sobald Ihr bereit seid loszulegen.', },
    {'Unterstützt Thrall und Sylvanas, Unterstadt für die Horde zurückzuerobern.|n|nMeldet Euch bei Thrall, solltet Ihr erfolgreich sein.', },
  },
  [13268] = {
    'Das Plündern von Stoffen',
    nil,
    nil,
  },
  [13269] = {
    'Das Plündern von Stoffen',
    nil,
    nil,
  },
  [13270] = {
    'Das Plündern von Stoffen',
    nil,
    nil,
  },
  [13271] = {
    'Eine Stimme im Dunklen',
    {'Das Objekt ist überhaupt kein Kristall, sondern etwas Organisches, das in Eis eingeschlossen ist.|n|nAls Ihr es berührt, zuckt Eure Hand vor Schmerz zurück. Es fühlt sich an, als hättet Ihr Euch in die Hand geschnitten, aber es ist keine Wunde zu sehen.|n|nAls Ihr Eure Gedanken sammelt, hört Ihr die Stimme eines Jungen in der Nähe.|n|n"Das hättet Ihr nicht tun sollen."', },
    {'Untersucht die nahe Stimme in Naz\'anak, den Vergessenen Tiefen.', },
  },
  [13272] = {
    'Das Plündern von Stoffen',
    nil,
    nil,
  },
  [13273] = {
    'Dem Kern hinterher',
    {'Da wir nun Norgannons Schale in Händen halten, muss nur noch die zweite Hälfte des Archivschlüssels gefunden werden. Zum Glück habe ich die Forscherliga intensiv nach Hinweisen über den Aufenthaltsort des Kerns suchen lassen.|n|nWeit südöstlich der Bibliothek des Erfinders an den Hängen nördlich von Dun Niffelem befindet sich ein Lager, das meinen Namen trägt. Dort sind diejenigen der Forscherliga stationiert, die nach der zweiten Hälfte des Schlüssels suchen. Bringt mir die Karten und Notizen, die sie angefertigt haben, und die andere Schlüsselhälfte sollte sich finden lassen.', },
    {'Geht zu Branns Basislager und sucht nach Ausgrabungsleiter Khronas Notizen und Ausgrabungsleiter Sorens Karten.', },
  },
  [13274] = {
    'Hüter des Kerns',
    {'Die Aufzeichnungen von Ausgrabungsleiter Soren erzählen uns, dass sich Norgannons Kern in der Obhut einer Schildwache namens Athan befindet - eine von Mimirs Schöpfungen.|n|nSoren meint, dass das Gewölbe, in dem Athan residiert, heutzutage "Lokens Handel" genannt wird.|n|nLoken, wie? Die Irdenen haben seinen Namen erwähnt.|n|nMan sagt, dass sich das Gewölbe südwestlich des zerstörten Lagers der Forscherliga befindet und dass dessen Eingang an einem Berghang mit Aussicht auf das Uralte Wintertal zu finden ist.|n|nFindet diesen Athan und beschafft Euch den Kern. Ich wäre jedoch nicht sonderlich überrascht, wenn Ihr auch kämpfen müsstet.', },
    {'Beschafft Norgannons Kern.', },
  },
  [13275] = {
    'Zeit zum Verstecken',
    {'Ihr hättet das nicht berühren sollen. Nun, da Ihr es getan habt, wird er kommen und nach Euch suchen.|n|nUnd er wird Euch finden. Solange Ihr Euch nicht vor ihm versteckt.|n|nBringt mir Blut von den Gesichtslosen, wenn Ihr leben wollt.', },
    {'Matthias Lehner möchte, dass Ihr ihm 3 Proben Blut des Gesichtslosen bringt.', },
  },
  [13276] = {
    'Das ist monströs!',
    {'Ihr wisst, was zu tun ist, $C.|n|nNehmt dieses Set und erschafft mit den Eingeweiden ihrer Monstrositäten Eure eigene Monstrosität. Lasst sie dann die feindlichen Truppen am Tor angreifen.|n|nIhr tätet gut daran, die Taktik noch zu verfeinern, bevor wir das Tor angreifen.', },
    {'Koltira Todesweber auf der Orgrims Hammer möchte, dass Ihr das Monstrositätenwiedererweckungsset benutzt, um eine wiedererweckte Monstrosität zu erschaffen, mit der Ihr dann 15 Eisghule, 15 heimtückische Spuke und 15 auferstandene Soldaten der Allianz töten sollt.', },
  },
  [13277] = {
    'Gegen die Riesen',
    {'Obwohl es entscheidend sein wird, die Geißel am Boden zu besiegen, dürfen wir nicht das Tor selbst vernachlässigen.|n|nDie Fleischriesen auf den Bollwerken sind in der Lage, große Felsen und Eisbrocken zu schleudern und damit verheerenden Schaden unter der anstürmenden Infanterie anzurichten.|n|nStellt eine Truppe zusammen und erledigt diese Riesen. Wir müssen einfach wissen, wie es um ihre wahre Stärke bestellt ist.|n|nOh... und bringt mir ihre Wirbelsäulen. Wenn meine Erinnerung mich nicht trügt, dann gibt es da einen kleinen Trick, den ich Euch zeigen kann.', },
    {'Koltira Todesweber auf der Orgrims Hammer möchte, dass Ihr ihm 5 pustelige Wirbelsäulen von den pusteligen Schrecken auf Mord\'rethar bringt.', },
  },
  [13278] = {
    'Koprus der Entweihte',
    {'Ich habe Berichte von einem mächtigen Zombie am Tor des Todes erhalten, $C.|n|nEine potentielle Gefahr wie diese können wir nicht ignorieren. Jede Information, die Ihr von einer Auseinandersetzung mit ihm gewinnen könnt, ist besser als das, was wir bisher wissen.|n|nGeht zur westlichen Kammer des Tores und findet diese Kreatur. Kämpft gegen sie und findet eine Schwäche, die wir ausnutzen können.', },
    {'Koltira Todesweber an Bord der Orgrims Hammer möchte, dass Ihr Koprus den Entweihten bei Mord\'rethar tötet.', },
  },
  [13279] = {
    'Grundkenntnisse der Chemie',
    {'<Koltira nimmt die pusteligen Wirbelsäulen und wringt ihre Flüssigkeit in ein Fläschchen.> Eine wenig bekannte Eigenart der Fleischriesen...|n|nIhre Rückenmarksflüssigkeit interagiert auf höchst interessante Art und Weise mit der Seuche, indem sie sie in ätzende Säure verwandelt.|n|nSchüttet man diese von den höher gelegenen Bollwerken, mag das nicht besonders erfreulich für die Truppen unten sein, aber zumindest werden die Opfer nicht wiederauferstehen und sich dem Gegner anschließen.|n|nSchüttet den Inhalt dieses Fläschchens in einen der Seuchenkessel in der westlichen Kammer des Tors des Todes.', },
    {'Koltira Todesweber an Bord der Orgims Hammer möchte, dass Ihr pustelige Rückenmarksflüssigkeit in einen Seuchenkessel in Mord\'rethar gießt.', },
  },
  [13280] = {
    'König der Berge',
    {'Ihr müsst meinen Hüpfboter nur so schnell wie möglich von Ymirheim zum Gipfel dieses Berges dort im Nordwesten bringen, $N!|n|nDieser heimtückische, nichtsnutzige Bumm Donnerbombe arbeitet an seinem eigenen Bot und ich befürchte, dass er beinahe fertig ist. Wir werden ein Rennen bestimmen lassen, wer König der Berge wird!|n|nSteckt unsere Schlachtstandarte in den Knochenhaufen, sobald Ihr oben angekommen seid, und zeigt jedem, dass niemand besser ist, als die Allianz - und meine Ingenieursfertigkeiten!', },
    {'Fetzi Gangzwinger in Ymirheim möchte, dass Ihr ihren Hüpfboter benutzt, um die Schlachtstandarte der Allianz in den Schädelhaufen auf dem Gipfel des Berges zu stecken.', },
  },
  [13281] = {
    'Die Seuche neutralisieren',
    {'Ihr braucht nicht länger meine Hilfe, um die Seuchenkessel des Feindes zu neutralisieren, $R.|n|nBringt die Fleischriesen am Tor des Todes zur Strecke und macht mithilfe ihrer Rückenmarksflüssigkeit den Inhalt der Kessel unwirksam.|n|nIhr führt einen Schlag gegen das zentrale strategische Mittel des Feindes durch. Diese Mission ist wichtig - für unsere Sache unerlässlich und sollte ausgeführt werden, wann auch immer sich die Gelegenheit bietet.|n|nVergesst nicht: Die Riesen und Seuchenkessel befinden sich bei Mord\'rethar.', },
    {'Koltira an Bord der Orgrims Hammer möchte, dass Ihr pustelige Rückenmarksflüssigkeit in einen Kessel bei Mord\'rethar schüttet.|n|nPustelige Rückenmarksflüssigkeit kann dadurch gewonnen werden, indem man das Fleischriesenrückgrat eines pusteligen Schreckens benutzt.', },
  },
  [13282] = {
    'Rückkehr an die Oberfläche',
    {'Ihr solltet nun gehen. Hinter mir findet Ihr ein Portal, das Euch an die Oberfläche bringen wird.|n|nWir werden uns wiedersehen. Er wird nach Euch suchen.|n|nEs ist nur eine Frage der Zeit, bis er Euch findet.', },
    {'Kehrt zu Koltira Todesweber an Bord der Orgrims Hammer zurück.', },
  },
  [13283] = {
    'König der Berge',
    {'Also, $N, Ihr müsst meinen Hüpfboter zum Gipfel dieses Berges dort im Südosten bringen, wie gestern!|n|nDiese weibische, selbstgerechte Fetzi Gangzwinger meint, dass ihr Hüpfboter besser sei als meiner. Ha! Wir werden ein Rennen bestimmen lassen, wer König der Berge wird!|n|nSteckt unsere Schlachtstandarte in den Knochenhaufen, sobald Ihr oben angekommen seid, und zeigt jedem, dass die Horde und meine verrückten Ingenieursfertigkeiten die Besten sind!', },
    {'Bumm Donnerbombe in Ymirheim möchte, dass Ihr seinen Hüpfboter benutzt, um die Schlachtstandarte der Horde in den Schädelhaufen auf dem Gipfel des Berges zu stecken.', },
  },
  [13284] = {
    'Bodenangriff',
    {'Grüße, $C.|n|nUnsere Truppen versuchen schon seit einer ganzen Weile Ymirheim zu erstürmen, doch diese Vrykul sind um einiges grausamer als alle anderen, denen wir bisher begegnet sind. Wenn wir versuchen, über den Pass zu kommen, laufen wir ständig in einen ihrer Hinterhalte, und wir haben viele Männer verloren.|n|nWir würden Euch gerne für Eure Mühen belohnen, falls Ihr dem Kampf beitreten und helfen solltet, meine Einheit sicher nach Ymirheim zu bringen. Sobald wir vor den Toren stehen, werden wir uns verschanzen und darauf warten, dass uns die Verstärkungstruppen einholen.', },
    {'Eskortiert die Truppen der Himmelsbrecher zu den Toren von Ymirheim. Kehrt zu Feldkommandant Koup am Rand des Gletschers im Norden von Ymirheim zurück, nachdem Eure Aufgabe abgeschlossen ist, und holt Eure Belohnung ab.', },
  },
  [13285] = {
    'Den Schlüsselstein schmieden',
    {'Aha! Da ist er ja: der Tempel des Erfindungsreichtums, Sitz von Hüter Mimir höchstpersönlich! Natürlich, dort würde man hingehen, um die zwei Teile des Schlüssels zusammenzufügen.|n|nDen Notizen des Ausgrabungsleiters zufolge ist der Tempel des Erfindungsreichtums einer der höchsten Punkte auf der westlichen Seite der Terrasse der Schöpfer. Das bedeutet, dass sich der Ort ungefähr östlich der Absturzstelle Grom\'ash befinden sollte.|n|nIch treffe Euch im Tempel und wir werden die zwei Teile zusammenfügen.', },
    {'Brann Bronzebart möchte, dass Ihr ihn im Tempel des Erfindungsreichtums trefft und ihm dabei helft, Norgannons Schale und Norgannons Kern zusammenzufügen. Meldet Euch bei Boktar Blutfurie bei der Absturzstelle Grom\'ash, sobald dies getan ist.', },
  },
  [13286] = {
    '... Jede Hilfe, die wir kriegen können',
    {'Schlimme Zeiten, $C...|n|nSo ungern ich das auch tue, ich bin mittlerweile bereit, Hilfe von wirklich jedem anzunehmen - selbst von unserem Todesritter.|n|nGeht zu Thassarian und seht, ob er uns dabei helfen kann, Taktiken gegen die Geißel zu entwickeln, die uns den Sieg bringen können, sobald wir einen weiteren Angriff beginnen können.|n|nWir sind so weit gekommen... wir dürfen jetzt nicht scheitern!', },
    {'Stabshauptmann Justin Bartlett an Bord der Himmelsbrecher möchte, dass Ihr mit Thassarian sprecht.', },
  },
  [13287] = {
    'Stechen und Stoßen',
    {'Wie jemand mit Eurer Erfahrung sicher weiß, gibt es keinen besseren Weg, etwas über seinen Gegner herauszufinden, als sich ihm im Kampf gegenüberzustellen.|n|nObschon Ihr sicher nach dem Ruhm giert, die Eiskronenzitadelle einzunehmen, kann dies jedoch nicht passieren, bevor nicht jedes der Tore des Lichkönigs erobert ist. Vorerst müsst Ihr Eure Anstrengungen auf das erste der Tore konzentrieren...|n|nKehrt zur Zerbrochenen Front zurück. Verwickelt den Gegner in eine Schlacht. Sucht nach einer Schwäche, die wir ausnutzen könnten, und kehrt dann mit einem detaillierten Bericht zu mir zurück.', },
    {'Thassarian auf der Himmelsbrecher möchte, dass Ihr 5 bullige Monstrositäten, 5 bösartige Totenbeschwörer und 5 Schattenadepten bei der Zerbrochenen Front tötet.', },
  },
  [13288] = {
    'Das ist monströs!',
    {'Monstrositäten...|n|nSie können sehr fähige Gegner sein. Ich habe mehr als einmal gesehen, wie sie den Ausgang einer Schlacht gewendet haben. Nur wenige erkennen, dass sie auch sehr fähige Freunde sein können.|n|nSie sind keine großen Denker. Wenn Ihr die Geheimnisse ihrer Erschaffung kennt, dann könnt Ihr ihnen einige Grundbefehle erteilen, die sie nicht hinterfragen werden.|n|nZu Eurem Glück kenne ich diese Geheimnisse.|n|nDieses Set wird die Überreste der Monstrositäten, die Ihr besiegt habt, wiederbeleben. Nehmt es und lernt, es gegen die Geißel am Tor des Todes einzusetzen.', },
    {'Thassarian auf der Himmelsbrecher möchte, dass Ihr das Wiederbelebungsset für Monstrositäten benutzt, um eine wiedererweckte Monstrosität zu erschaffen, mit der Ihr 15 Eisghule, 15 heimtückische Spuke und 15 auferstandene Soldaten der Allianz töten sollt.', },
  },
  [13289] = {
    'Das ist monströs!',
    {'Ihr wisst, was Ihr zu tun habt, $C.|n|nNehmt dieses Set hier und benutzt die Eingeweide ihrer Monstrositäten, um eine eigene zu erschaffen, dann befehlt ihr, die Streitkräfte des Gegners am Tor anzugreifen.|n|nIhr tätet gut daran, vor unserem nächsten Angriff auf das Tor diese Taktik zu verfeinern.', },
    {'Thassarian auf der Himmelsbrecher möchte, dass Ihr das Wiederbelebungsset für Monstrositäten benutzt, um eine wiedererweckte Monstrosität zu erschaffen, mit der Ihr 15 Eisghule, 15 heimtückische Spuke und 15 auferstandene Soldaten der Allianz töten sollt.', },
  },
  [13290] = {
    'Bitte recht aufmerksam',
    {'Chefingenieur Bolzenschlüssel hat sich als unabdingbar auf der Sturmbrecher erwiesen. Ohne seine Genialität lägen wir mittlerweile schon mehrfach über den halben Gletscher verstreut.|n|nDas Problem ist nur, dass er jede einzelne popelige Erfindung oder Entdeckung gleich diskutieren will - obwohl ich die Hälfte sowieso nicht verstehe.|n|nMein Augenmerk muss jetzt aber ausschließlich auf unseren Feinden liegen. Ich kann mir keine Ablenkungen erlauben.|n|nBitte stattet ihm einen Besuch an meiner Stelle ab, $N. Und assistiert ihm, wenn Ihr könnt. Ihr findet ihn unter Deck.', },
    {'Stabshauptmann Bartlett möchte, dass Ihr mit Chefingenieur Bolzenschlüssel in der Himmelsbrecher redet.', },
  },
  [13291] = {
    'Geliehene Technologie',
    {'Ich kapier\'s ja, ich kapier\'s ja. Cappy ist zu beschäftigt, um es sich selber anzusehen. Selbst Schuld!|n|nSeht Ihr, ich habe es geschafft, eine gewisse Lieferung Lösungen vom Feind zu \'leihen\'. Und so sehr ich es auch hasse, mit minderwertiger Goblintechnologie zu hantieren, so bin ich doch versucht, hier mal eine Ausnahme zu machen.|n|nNehmt diese Probe. Ihr müsst für mich einige Feldversuche durchführen, um ihre Nützlichkeit unter Beweis zu stellen, während ich versuche, ein wenig umgekehrte Ingenieurskunst zu betreiben und den Erschaffungsprozess zu duplizieren.|n|nGeht an die Front und sammelt das Material, um eine Attrappe zu bauen, dann benutzt das Öl.', },
    {'Chefingenieur Bolzenschlüssel an Bord der Himmelsbrecher möchte, dass Ihr die geschmuggelte Lösung an der Zerbrochenen Front einsetzt.|n|nUm die Lösung benutzen zu können, benötigt Ihr einen zurückgelassenen Helm, zurückgelassene Rüstung und einen Knochenhaufen, die alle an der Zerbrochenen Front zu finden sind.', },
  },
  [13292] = {
    'Die Lösungslösung',
    {'Oh, ja, ja. Wieder zurück, hmm? Man kann nie genug Training haben, was?|n|nUnd hier ist sie, die Lösung für das ärgerliche Frostwyrmproblem.|n|nVerringert ihre Anzahl, $R. Je mehr Ihr jetzt ausschaltet, desto weniger sitzen uns im Nacken, wenn wir uns aufmachen, die Zitadelle anzugreifen.|n|nViel Glück Euch. Und bringt doch bitte zurück, was Ihr nicht braucht.', },
    {'Chefingenieur Bolzenschlüssel an Bord der Himmelsbrecher möchte, dass Ihr die geschmuggelte Lösung an der Zerbrochenen Front einsetzt.|n|nUm die Lösung benutzen zu können, benötigt Ihr einen zurückgelassenen Helm, zurückgelassene Rüstung und einen Knochenhaufen, die alle an der Zerbrochenen Front zu finden sind.', },
  },
  [13293] = {
    'Auf nach Ymirheim!',
    {'Ihr müsst hinunter nach Ymirheim, der großen Stadt der Frostvrykul im Zentrum von Eiskrone.|n|nUnser Kumpel, Bumm Donnerbombe, ist schon da, im Westen der Stadt und repräsentiert die Kriegshymnenoffensive in einem Wettkampf gegen die Allianz. Es steht sein Hüpfboter gegen ihren in einem Wettkampf um den Titel König der Berge!|n|nLasst uns nicht im Stich, $N. Der Stolz der goblinischen Ingenieurskunst steht auf dem Spiel! Außerdem zählen alle Jungs hier auf dem Schiff auf Euch.|n|nDas, und dann haben wir noch Geld darauf gesetzt, dass Ihr diesen Feiglingen ordentlich in den Hintern tretet!', },
    {'Redet mit Bumm Donnerbombe in Ymirheim.', },
  },
  [13294] = {
    'Gegen die Riesen',
    {'Obwohl es entscheidend sein wird, die Geißel am Boden zu besiegen, dürfen wir nicht das Tor selbst vernachlässigen.|n|nDie Fleischriesen auf den Bollwerken sind in der Lage, große Felsen und Eisbrocken zu schleudern und damit verheerenden Schaden unter der anstürmenden Infanterie anzurichten.|n|nStellt eine Truppe zusammen und erledigt diese Riesen. Wir müssen einfach wissen, wie es um ihre wahre Stärke bestellt ist.|n|nOh... und bringt mir ihre Wirbelsäulen. Wenn meine Erinnerung mich nicht trügt, dann gibt es da einen kleinen Trick, den ich Euch zeigen kann.', },
    nil,
  },
  [13295] = {
    'Grundkenntnisse der Chemie',
    {'<Thassarian nimmt die pusteligen Wirbelsäulen und wringt ihre Flüssigkeit in ein Fläschchen.> Eine wenig bekannte Eigenart der Fleischriesen...|n|nIhre Rückenmarksflüssigkeit interagiert auf höchst interessante Art und Weise mit der Seuche, indem sie sie in ätzende Säure verwandelt.|n|nSchüttet man diese von den höher gelegenen Bollwerken, mag das nicht besonders erfreulich für die Truppen unten sein, aber zumindest werden die Opfer nicht wiederauferstehen und sich dem Gegner anschließen.|n|nSchüttet den Inhalt dieses Fläschchens in einen der Seuchenkessel in der westlichen Kammer des Tors des Todes.', },
    {'Thassarian an Bord der Himmelsbrecher möchte, dass Ihr pustelige Rückenmarksflüssigkeit in einen Seuchenkessel in Mord\'rethar gießt.', },
  },
  [13296] = {
    'Auf nach Ymirheim!',
    {'Ihr müsst runter nach Ymirheim, der großen Frostvrykulstadt im Zentrum von Eiskrone.|n|nFetzi Gangzwinger ist schon da, im Süden der Stadt, und repräsentiert die Expedition \'Valianz\' in einem Wettkampf gegen die Mistkerle der Horde. Es steht Fetzis Hüpfboter gegen ihren in einem Wettkampf um den Titel des Königs der Berge!|n|nLasst uns nicht im Stich, $N. Der Stolz der gnomischen Ingenieurskunst steht auf dem Spiel! Außerdem zählen alle Jungs hier in der Feste auf Euch.|n|nDas, und dann haben wir noch Geld darauf gesetzt, dass Ihr diesen Idioten ordentlich in den Hintern tretet!', },
    {'Sprecht mit Fetzi Gangzwinger in Ymirheim.', },
  },
  [13297] = {
    'Die Seuche neutralisieren',
    {'Ihr braucht nicht länger meine Hilfe, um die Seuchenkessel des Feindes zu neutralisieren, $R.|n|nBringt die Fleischriesen am Tor des Todes zur Strecke und macht mithilfe ihrer Rückenmarksflüssigkeit den Inhalt der Kessel unwirksam.|n|nIhr führt einen Schlag gegen das zentrale strategische Mittel des Feindes durch. Diese Mission ist wichtig - für unsere Sache unerlässlich und sollte ausgeführt werden, wann auch immer sich die Gelegenheit bietet.|n|nVergesst nicht: Die Riesen und Seuchenkessel befinden sich bei Mord\'rethar.', },
    {'Thassarian an Bord der Himmelsbrecher möchte, dass Ihr pustelige Rückenmarksflüssigkeit in einen Kessel bei Mord\'rethar schüttet.|n|nPustelige Rückenmarksflüssigkeit kann dadurch gewonnen werden, indem man das Fleischriesenrückgrat eines pusteligen Schreckens benutzt.', },
  },
  [13298] = {
    'Koprus der Entweihte',
    {'Ich habe Berichte von einem mächtigen Zombie am Tor des Todes erhalten, $C.|n|nEine potentielle Gefahr wie diese können wir nicht ignorieren. Jede Information, die Ihr von einer Auseinandersetzung mit ihm gewinnen könnt, ist besser als das, was wir bisher wissen.|n|nGeht zur westlichen Kammer des Tores und findet diese Kreatur. Kämpft gegen sie und findet eine Schwäche, die wir ausnutzen können.', },
    {'Thassarian an Bord der Himmelsbrecher möchte, dass Ihr Koprus den Entweihten in Mord\'rethar tötet.', },
  },
  [13300] = {
    'Vom Saronit abhängig',
    {'Unsere Leute werden gefangen genommen und als Sklaven in den Saronitminen eingesetzt, der Vrykulfeste in der Mitte von Eiskrone. Der Lichkönig lässt sie Tag und Nacht das unheilige Erz schürfen.|n|nIch habe Hochlord Fordring geschworen, dass wir die armen Kerle da rausholen werden, und genau das werden wir tun.|n|nUnglücklicherweise wurde mir der Befehl erteilt, auf diesem Schiff zu bleiben und der Expedition \'Valianz\' als Botschafter zu dienen. Würdet Ihr sie bitte an meiner Statt retten, $N?', },
    {'Absalan der Fromme an Bord der Himmelsbrecher möchte, dass Ihr 10 Saronitminensklaven rettet.', },
  },
  [13301] = {
    'Bodenangriff',
    {'Grüße, $C.|n|nUnsere Truppen versuchen schon seit einer ganzen Weile Ymirheim zu erstürmen, doch diese Vrykul sind um einiges grausamer als alle anderen, denen wir bisher begegnet sind. Wenn wir versuchen, über den Pass zu kommen, laufen wir ständig in einen ihrer Hinterhalte, und wir haben viele Männer verloren.|n|nWir würden Euch gerne für Eure Mühen belohnen, falls Ihr dem Kampf beitreten und helfen solltet, meine Einheit sicher nach Ymirheim zu bringen. Sobald wir vor den Toren stehen, werden wir uns verschanzen und darauf warten, dass uns die Verstärkungstruppen einholen.', },
    {'Eskortiert die Truppen der Kor\'kron zu den Toren von Ymirheim. Kehrt zu Feldkommandant Xutjja an der Kante des Gletschers im Norden von Ymirheim zurück, nachdem Eure Aufgabe abgeschlossen ist, und holt Eure Belohnung ab.', },
  },
  [13302] = {
    'Vom Saronit abhängig',
    {'Unsere Leute werden gefangen genommen und als Sklaven in den Saronitminen eingesetzt, der Vrykulfeste in der Mitte von Eiskrone. Der Lichkönig lässt sie Tag und Nacht das unheilige Erz schürfen.|n|nIch habe Hochlord Fordring geschworen, dass wir die armen Kerle da rausholen werden, und genau das werden wir tun.|n|nUnglücklicherweise wurde mir der Befehl erteilt, auf diesem Schiff zu bleiben und der Kriegshymnenoffensive als Botschafter zu dienen. Würdet Ihr sie bitte an meiner Statt retten, $N?', },
    {'Bruder Keltan an Bord der Orgrims Hammer möchte, dass Ihr 10 Saronitminensklaven rettet.', },
  },
  [13304] = {
    'Feldreparaturen',
    {'Die Geißel erholt sich noch immer von unserem Angriff, $N. Jetzt ist die Zeit, die Gunst der Stunde zu nutzen und zuzuschlagen.|n|nDas strategisch wichtige Tal unter uns ist weit offen. Wir haben in der südöstlichen Ecke des Tals der Verlorenen Hoffnung ein zerlegtes Verwüsterfahrzeug entdeckt, das sich, so glauben wir, noch in einem funktionsfähigen Zustand befindet.|n|nFalls Ihr die restlichen Teile von den Aasfressern der Geißel beschaffen könntet, solltet Ihr es wieder zum Laufen bringen können. Ein einziger funktionierender Verwüster kann unter den Bodeneinheiten des Feindes verheerenden Schaden anrichten.', },
    {'Koltira Todesweber an Bord der Orgrims Hammer möchte, dass Ihr 5 Verwüsterersatzteile von den aasfressenden Spuken im Tal der Verlorenen Hoffnung beschafft und sie zum defekten Verwüster bringt.', },
  },
  [13305] = {
    'Tut Euer Schlechtestes',
    {'Ihr werdet diese Maschine gegen die Geißel einsetzen? Auf diese Weise werdet Ihr nicht gegen sie gewinnen können.|n|nIhr könnt Hunderte... sogar Tausende von ihnen zerstören, doch gewinnen werdet Ihr nicht - nicht hier draußen.|n|nTrefft mich im Norden, wenn Ihr genug mit Eurer Maschine gespielt habt. Dort gibt es ein altes Militärlager. Was ich Euch zeigen werde, wird Euch einen kleinen Einblick darüber gewähren, wem wir uns hier gegenübersehen.', },
    {'Zerstört mithilfe des Runderneuerten Verwüsters 150 verrottete Ghule, 20 Frostschädelmagier und 2 Knochenriesen im Tal der Verlorenen Hoffnung. Sprecht mit Matthias Lehner im Vorhutslager der Ersten Legion, wenn Ihr die Aufgabe abgeschlossen habt.', },
  },
  [13306] = {
    'Errichtet die Barrikaden',
    {'Sobald unsere Truppen sich hinter Aldur\'thar befinden, werden sie verwundbar durch Attacken vom Eisenwallbollwerk oder dem breiten Gletscher darunter sein.|n|nWir haben weder die Zeit noch das Material, um Befestigungen zu bauen, aber wir können ein paar Barrikaden errichten, um unsere Männer vor Feuer zu schützen und Angriffe der Geißel abprallen zu lassen.|n|nNehmt diesen Barrikadenbausatz mit zum Tal der Gefallenen Helden. Findet die Markierungen, die ich dort gesetzt habe und benutzt den Bausatz, um dort Eure Barrikaden zu errichten.', },
    {'Koltira Todesweber an Bord der Orgrims Hammer möchte, dass Ihr 8 Barrikaden mithilfe Eures Barrikadenbausatzes errichtet.', },
  },
  [13307] = {
    'Blutbespritzte Banner',
    {'Im Tal der Gefallenen Helden und am Eiskronengletscher, im Westen Aldur\'thars, versucht die Geißel, die Gefallenen gegen uns zu verwenden. Die Kommandanten der Geißel haben die Toten aus dem Tal wiedererweckt und sie mit furchterregender Stärke und Leidenschaft erfüllt. Die Banner, die die Geißelanführer in der Gletschergegend bei sich tragen, sind die Quelle dieser Mächte. Tötet die Bannerträger und Ihr werdet die konvertierten Helden, die sie führen, schwächen.|n|nEs obliegt Euch, uns von diesem Hindernis zu befreien und den Widerstand auszudünnen, bevor die Hauptstreitmacht vorrücken kann.', },
    {'Koltira Todesweber an Bord der Orgrims Hammer möchte, dass Ihr 5 Bannerträger der Geißel, 5 Konvertierer der Geißel und 20 konvertierte Helden tötet.', },
  },
  [13308] = {
    'Geistiger Zwang',
    {'<Die Kreatur spricht direkt über Euren Geist mit Euch. Ihre Gedanken sind schmerzhaft und seltsam.>|n|n$R, ich brauche Eure Hilfe. Ich bin genau so wie Eure versklavten Freunde ein Opfer der dem Lichkönig dienenden Ymirjar und ihrer Habsucht. Sie nahmen mich gefangen, als ich die Tiefen verließ, um die Geräusche aus dieser Höhle zu untersuchen, und legten mich in Ketten.|n|nWürdet Ihr mir bitte helfen? Der Vorarbeiter dieser Minen trägt den Schlüssel zu meinen Ketten bei sich. Tötet ihn!|n|n<Ihr könnt ein drängendes Gefühl in Eurem Geist spüren, als würde die Kreatur versuchen, Euch zu zwingen.>', },
    {'Dunkelsprecher R\'khem in den Saronitminen möchte, dass Ihr den Schlüssel des Großknechts beschafft, um so seine Ketten zu öffnen.', },
  },
  [13309] = {
    'Luftangriff',
    nil,
    nil,
  },
  [13310] = {
    'Luftangriff',
    {'Nun gut, Grünschnabel, ich hab\' etwas für dich, damit du nicht völlig nutzlos bist.|n|nEine Einheit von hochtrainierten Spitzeln ist bereit für ihren Abwurf in Ymirheim. Die Vrykul dort haben automatische Speerkanonen aufgestellt, die unsere Transporter in Stücke geschossen haben, also haben wir unsere Ingenieure einen Geschützturm auf der Orgrims Hammer bauen lassen, mit dem Rauchgranaten abgeschossen werden können.|n|nIhr seid der Schütze. Feuert auf ihre Speerkanonen, um ihnen die Sicht zu nehmen und sie außer Kraft zu setzen. Sorgt dafür, dass alle meine Männer abgeworfen werden und der Transporter ganz bleibt.', },
    {'Bodentruppenkommandant Xutjja an der Kante des Gletschers im Norden von Ymirheim hat Euch befohlen, den Geschützturm der Kor\'kron zu benutzen, um den Truppentransporter der Kor\'kron lange genug in der Luft zu halten, bis alle abgeworfen wurden.', },
  },
  [13311] = {
    'Dämonenkartenset',
    {'Jetzt, da Ihr alle Dämonenkarten in einem Set gesammelt habt, erscheint eine weitere Karte. Sie zeigt einen Wahrsager, der Euch immer anzustarren scheint, egal wie Ihr die Karte haltet.|n|nIhr glaubt, dass man mithilfe der Karte womöglich mit irgendwem oder irgendetwas kommunizieren könnte.', },
    {'Beschwört mithilfe des Dämonenkartensets einen Wahrsager des Dunkelmond-Jahrmarkts und gebt ihm das Set.', },
  },
  [13312] = {
    'Das Eisenwallbollwerk',
    {'Das Eisenwallbollwerk blickt über das Tal der Gefallenen Helden westlich von Aldur\'thar. Vom Bollwerk aus kann man die Felder zu allen Seiten hin kontrollieren. Wir werden nicht weiter vorstoßen können, wenn das Bollwerk nicht genommen werden kann - doch es wird von Grimkor dem Boshaften und seinen Jüngern des Kults der Verdammten gehalten.|n|nWenn Ihr Grimkor schwächen könnt, werden unsere Streitkräfte wissen, was sie bei ihrem Vormarsch erwarten wird. Hier, nehmt diese Rune der Verzerrung. Seine Macht in der Nähe von Grimkors Kugel am Ende des Bollwerks freizusetzen, sollte genügen, um die Aufmerksamkeit der Nekromanten zu erregen.', },
    {'Besiegt Grimkor den Boshaften und kehrt zu Koltira Todesweber an Bord der Orgrims Hammer zurück.', },
  },
  [13313] = {
    'Die Augen im Himmel erblinden lassen',
    {'Die Allianz hat es irgendwie geschafft, eine Schwadron von Aufklärungsfahrzeugen über das Tal der Gefallenen Helden und den Eiskronengletscher zu entsenden, die weiten Gebiete westlich von Aldur\'thar.|n|nWir können ihnen nicht die Führung in diesem Kampf überlassen. Chefingenieur Kupferklammer hat mich mit der perfekten Waffe, um dieser Bedrohung Herr zu werden, ausgestattet. Er nennt seine neue Rakete die BGR-3. Ich habe seine Versicherung, dass sie die fliegenden Maschinen der Allianz mit einem einzigen Treffer ausschalten wird. Geht und benutzt diese Waffe dazu, uns die Oberhand zu verschaffen.', },
    {'Benutzt die BGR-3 um 6 Kampfaufklärer der Himmelsbrecher zu zerstören und erstattet dann dem Himmelshäscher Korm Schwarznarbe an Bord der Orgrims Hammer Bericht.', },
  },
  [13314] = {
    'Beschafft die Nachricht',
    {'Die Horde führt irgendetwas im Schilde - mir gefällt das nicht. Nach der verrückten Vorstellung, die sie an der Zerbrochenen Front geliefert haben, sind sie zu allem fähig, und es liegt an uns, sie aufzuhalten.|n|nEs herrscht viel Bewegung am Himmel über dem Eiskronengletscher westlich von Aldur\'thar und dem Eisenwallbollwerk. Späher und Boten der Horde auf Drachenfalken fliegen wie der Wind ein und aus - Berichte und Befehle bei sich tragend. Nehmt diese Pfeilpistole und tötet mit ihr die Späher der Orgrims Hammer. Am besten wird es wahrscheinlich dann funktionieren, wenn Ihr auch fliegt.', },
    {'Fangt 6 Sendungen der Orgrims Hammer von den Spähern der Orgrims Hammer ab und bringt sie zu Stabshauptmann Justin Bartlett an Bord der Himmelsbrecher.', },
  },
  [13315] = {
    'Vorschau',
    {'Wir machen Fortschritte. Uns steht eine vielversprechende Reihe von Taktiken zur Verfügung, die uns die Kontrolle über das Tor des Todes verschaffen sollten. Es wird zweifellos viele Verluste geben, doch am Ende sollten wir die Oberhand gewinnen, wenn sich die Horde, mit der Ihr Euch unbedingt messen wollt, nicht einmischen wird...|n|nWie dem auch sei: unser nächstes Ziel wird das Tor der Verwüstung sein. Fliegt hinunter und macht Euch mit der Konstruktion und den dort postierten Feinden vertraut.|n|nWenn Ihr wieder zurück seid, werde ich Eure Einsatzbeschreibungen vorbereitet haben.', },
    {'Thassarian an Bord der Himmelsbrecher möchte, dass Ihr hinunter zum Tor der Verwüstung fliegt und Euch den südlichen, zentralen, nördlichen und nordwestlichen Bereich des Tors anseht.', },
  },
  [13316] = {
    'Die Wächter von Corp\'rethar',
    {'Corp\'rethar, das Tor des Schreckens, ist das letzte Hindernis zwischen uns und der Eiskronenzitadelle. Es befindet sich südlich des Eisenwallbollwerks jenseits des Gletschers und des Großbrands. Wenn unsere Truppen erst einmal dort angekommen sind, werden sie erschöpft sein, falls ihnen nicht schon Schlimmeres zugestoßen ist.|n|nWir müssen seine Verteidigung schwächen, oder unsere Armee wird an seinen Mauern zugrunde gehen.|n|nDie Zinnen werden von einigen der stärksten und eifrigsten Dienern des Lichkönigs bemannt. Tut alles, was in Eurer Macht steht, um diese Wächter zu vernichten, und hofft, dass dies ausreicht.', },
    {'Koltira Todesweber an Bord der Orgrims Hammer wünscht, dass Ihr 5 Herolde des Schreckens und 5 Wächter von Corp\'rethar tötet.', },
  },
  [13318] = {
    'Gefährliche Gewandung',
    {'Der Kult der Verdammten hält das Tor der Verwüstung, wie? Wundert mich nicht.|n|nZeit, ein wenig Spaß zu haben. Ihr habt erwähnt, dass am südlichen Ende des Tores neue Kultisten ausgebildet werden. Sie haben mit Sicherheit einen besonderen Gegenstand bei sich, den alle neuen Initianden erhalten - eine Kugel der Illusion.|n|nDiese Artefakte dienen Kultanhängern zur Tarnung, um sich sicheren Durchgang durch feindliche Reihen zu verschaffen, um diese zu infiltrieren oder schlichtweg zwischen ihnen unterzutauchen.|n|nTötet diese Narren, bis Ihr eine von den Kugeln gefunden habt, $C, und wendet sie dann auf einen Unterwerfer an.', },
    {'Thassarian an Bord der Himmelsbrecher möchte, dass Ihr Kugeln der Illusion von bitteren Initianden in Aldur\'thar sammelt und sie dann auf 3 dunkle Unterwerfer anwendet.', },
  },
  [13319] = {
    'Befehlskette',
    {'Eurem Bericht und meinem Wissen über den Kult nach lassen sie einen Aufseher die Operation in jedem Lager am Tor leiten.|n|nIhre Anführer auszuschalten, wäre zwar nur ein vorübergehender Rückschlag für sie, doch es wird sie zumindest verlangsamen und aus dem Gleichgewicht bringen. Und das, $R, ist für den Augenblick gut genug.|n|nSucht nach diesen Aufsehern und kommt wieder zu mir zurück, wenn sie beseitigt wurden.', },
    {'Thassarian an Bord der Himmelsbrecher möchte, dass Ihr nach Aldur\'thar geht und Aufseher Faedris, Aufseher Savryn, Aufseher Veraj und Aufseher Jhaeqon besiegt.', },
  },
  [13320] = {
    'Kann nicht reproduziert werden',
    {'Ich kann ihre Kessel von hier aus riechen, doch was sie da zusammenbrauen, ist keine Seuche.|n|nDiejenigen, die dem Kult die Treue schwören, werden dazu gezwungen, ein Gemisch zu trinken, das ihren Willen raubt und sie für immer zu Sklaven des Lichkönigs macht.|n|nManche sagen, dass der Trank die verzerrte Seele eines Wesens beinhaltet, das gefoltert und schließlich gnadenlos getötet wurde, doch ich habe es noch nie geschafft, ihn zu reproduzieren...|n|nFüllt dieses Fläschchen mit Proben aus jedem der drei Kessel in der nordwestlichen Region des Tors auf und bringt sie zu Chefingenieur Bolzenschlüssel.', },
    {'Thassarian an Bord der Himmelsbrecher möchte, dass Ihr das unterteilte Fläschchen an jedem der 3 Kessel der Kultisten auffüllt und es anschließend zu Chefingenieur Bolzenschlüssel bringt.', },
  },
  [13321] = {
    'Jetzt neu testen',
    {'Das sollte seinen Zweck erfüllen!|n|nDiese verdrehten Hooligans suchen nach Seelen, die sie in ihren verrückten Saft mischen können? Dann lasst uns ihnen etwas aushelfen!|n|nNehmt einen Schluck hiervon - keine Sorge, ich habe es ausreichend verwässert... Der einzige Effekt wird sein, dass Ihr die Essenz der Kultisten werdet aufspüren können, sobald Ihr sie besiegt habt.|n|nSobald Ihr ein paar Essenzen habt, werft die sich windende Masse fehlgeleiteter Seelen in einen ihrer Kessel.|n|nWollen doch mal sehen, wie ihnen ihre eigene Medizin schmecken wird!', },
    {'Chefingenieur Bolzenschlüssel an Bord der Himmelsbrecher möchte, dass Ihr eine windende Masse in einen der Kessel in Aldur\'thar werft.', },
  },
  [13322] = {
    'Jetzt neu testen',
    {'Diese verdrehten Kultisten suchen nach Seelen, die sie in ihren verrückten Saft mischen können? Dann lasst uns ihnen etwas aushelfen!|n|nNehmt einen Schluck hiervon - keine Sorge, ich habe es ausreichend verwässert... Ich bin mir fast sicher, dass Ihr als Effekt die Essenzen der Kultisten aufspüren könnt.|n|nSobald Ihr ein paar davon habt, werft die sich windende Masse fehlgeleiteter Seelen in einen ihrer Kessel.|n|nWollen doch mal sehen, wie ihnen ihre eigene Medizin schmecken wird!', },
    {'Chefingenieur Bolzenschlüssel an Bord der Himmelsbrecher möchte, dass Ihr das verdünnte Kulttonikum trinkt, Kultisten in Aldur\'thar tötet und ihnen ihre besudelte Essenz abnehmt. Fügt danach 10 von den Essenzen zu einer windenden Masse zusammen und werft diese dann in einen ihrer Kessel.', },
  },
  [13323] = {
    'Gefährliche Gewandung',
    {'Es sieht aus, als würde die Zahl der Initianden wieder wachsen. Ihr wisst, was Ihr zu tun habt...|n|nDie neuen Kultisten werden am südlichen Ende des Tores eingewiesen. Sie haben mit Sicherheit einen besonderen Gegenstand bei sich, den alle neuen Initianden erhalten - eine Kugel der Illusion.|n|nDiese Artefakte dienen Kultanhängern zur Tarnung, um sich sicheren Durchgang durch feindliche Reihen zu verschaffen, um diese zu infiltrieren oder schlichtweg zwischen ihnen unterzutauchen.|n|nTötet diese Narren, bis Ihr einige davon habt, dann wendet sie auf die Unterwerfer dort an.', },
    {'Thassarian an Bord der Himmelsbrecher möchte, dass Ihr Kugeln der Illusion von bitteren Initianden in Aldur\'thar sammelt und sie dann auf 3 dunkle Unterwerfer anwendet.', },
  },
  [13324] = {
    'Prismenkartenset des Dunkelmond-Jahrmarkts',
    {'Jetzt, da Ihr alle Karten des Prismenkartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: "Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden." Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.', },
    {'Gebt das Prismenkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.', },
  },
  [13325] = {
    'Chaoskartenset des Dunkelmond-Jahrmarkts',
    {'Jetzt, da Ihr alle Karten des Chaoskartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: "Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden." Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.', },
    {'Gebt das Chaoskartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.', },
  },
  [13326] = {
    'Adligenkartenset des Dunkelmond-Jahrmarkts',
    {'Jetzt, da Ihr alle Karten des Adligenkartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: "Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden." Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.', },
    {'Gebt das Adligenkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.', },
  },
  [13327] = {
    'Untodeskartenset des Dunkelmond-Jahrmarkts',
    {'Jetzt, da Ihr alle Karten des Untodeskartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: "Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden." Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.', },
    {'Gebt das Untodeskartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.', },
  },
  [13328] = {
    'Einen Scherbenhaufen hinterlassen',
    {'Oberhalb der Schlachtfelder von Corp\'rethar haben die Günstlinge des Lichkönigs drei Kristalle aufgestellt, die Splitter des Schreckens, der Verzweiflung und des Leidens. Sollte es unseren Männern gelingen, die Mauern von Corp\'rethar zu erreichen, so wird er diese Waffen gegen unsere Armee einsetzen.|n|nVoll zum Einsatz gebracht, werden diese Kristalle den Geist unserer Männer peinigen und sie mit Schmerz und Angst lähmen. Dann wird es der Geißel ein Leichtes sein, sie einfach so niederzumetzeln.|n|nFindet diese Splitter, zerstört sie und bringt mir ihre zerbrochenen Überreste. Wir dürfen nicht zulassen, dass der Lichkönig diese Waffen einsetzt!', },
    {'Bringt Koltira Todesweber an Bord der Orgrims Hammer den zerbrochenen Splitter des Schreckens, den zerbrochenen Splitter der Verzweiflung und den zerbrochenen Splitter des Leidens.', },
  },
  [13329] = {
    'Vor dem Tor des Schreckens',
    {'Der Großbrand, das Gebiet vor Corp\'rethar südlich des Eisenwallbollwerks, ist der Ort, an dem sich die Elitesoldaten des Lichkönigs zur Verteidigung der Zitadelle formiert haben.|n|nDer Weg wird von einer Legion Skeletthäscher versperrt, angeführt von einem Todesritterkontingent. Ich befürchte, dass, selbst wenn die Häscher beseitigt werden sollten, die Geißel sie einfach wieder aufstellen und gegen uns in den Kampf schicken würde.|n|nIch habe zwar einen Plan entwickelt, wie wir sie davon abhalten können, bin mir jedoch nicht sicher, ob es funktionieren wird. Hier, nehmt diese Lösung und zersetzt mit ihr die Überreste der Häscher.', },
    {'Koltira Todesweber an Bord der Orgrims Hammer wünscht, dass Ihr mithilfe der flüchtigen Säure die Überreste von 6 Skeletthäschern zersetzt.', },
  },
  [13330] = {
    'Blut der Auserwählten',
    {'Diejenigen Vrykul, die beim Lichkönig hoch im Ansehen stehen, nennen sich selbst die Ymirjar. Sie bewohnen eine Stadt im Zentrum von Eiskrone. Wir haben eine Menge Aufgaben zu erledigen, bevor wir die Eiskronenzitadelle angreifen können, und diejenige, die uns nun bevorsteht, ist, diese so genannten "Auserwählten" des Lichkönigs plattzumachen.|n|nBegebt Euch in Ihre Stadt, Ymirheim, und schlachtet sie in ihren Häusern ab. Hinterlasst keine Zweifel darüber, wer hier die stärkeren Kämpfer hat.', },
    {'Kriegshetzer Davos Rabatz auf der Orgrims Hammer hat Euch entsandt, 20 Vrykul in Ymirheim zu töten.', },
  },
  [13331] = {
    'Der Allianz die Augen zuhalten',
    {'Die Allianz ist hartnäckig, so viel gestehe ich ihr zu, aber es bedarf mehr, um uns aufzuhalten. Nehmt diese BGR-3 und schießt erneut die Kampfaufklärer der Himmelsbrecher ab.|n|nIch bezweifele zwar, dass die Nachricht in ihre dicken Schädel reingeht, aber wir verfügen über genügend Raketen, um unseren Punkt deutlich zu machen. Geht und haltet über dem Tal der Gefallenen Helden, westlich von Aldur\'thar, nach ihren Aufklärern Ausschau. Und kommt nicht zurück, solange Ihr sie nicht in Trümmer gelegt habt.', },
    {'Benutzt die BGR-3 um 6 Kampfaufklärer der Himmelsbrecher zu zerstören und erstattet dann dem Himmelshäscher Korm Schwarznarbe an Bord der Orgrims Hammer Bericht.', },
  },
  [13332] = {
    'Errichtet die Barrikaden',
    {'Sobald unsere Truppen sich hinter Aldur\'thar befinden, werden sie verwundbar durch Attacken vom Eisenwallbollwerk oder dem breiten Gletscher darunter sein.|n|nWir haben weder die Zeit noch das Material, um Befestigungen zu bauen, aber wir können ein paar Barrikaden errichten, um unsere Männer vor Feuer zu schützen und Angriffe der Geißel abprallen zu lassen.|n|nNehmt diesen Barrikadenbausatz mit zum Tal der Gefallenen Helden. Findet die Markierungen, die ich dort gesetzt habe und benutzt den Bausatz, um dort Eure Barrikaden zu errichten.', },
    {'Thassarian an Bord der Himmelsbrecher möchte, dass Ihr 8 Barrikaden mithilfe Eures Barrikadenbausatzes errichtet.', },
  },
  [13333] = {
    'Mehr Sendungen abfangen',
    {'Trotz unserer Anstrengungen schickt die Horde weiterhin Späher in diese Gegend des Eiskronengletschers, westlich des Eisenwallbollwerks und Aldur\'thar.|n|nWir können es uns nicht leisten, der Horde bei dieser Erkundungsoperation die Oberhand zu lassen. Nehmt wieder diese Pfeilpistole mit Euch und zeigt den Spähern der Orgrims Hammer keine Gnade! Bringt die abgefangenen Sendungen zu mir.|n|nWir werden die Fehlschläge der Horde zu unseren Gunsten nutzen.', },
    {'Fangt 6 Sendungen der Orgrims Hammer von den Spähern der Orgrims Hammer ab und bringt sie zu Stabshauptmann Justin Bartlett an Bord der Himmelsbrecher.', },
  },
  [13334] = {
    'Blutbespritzte Banner',
    {'Im Tal der Gefallenen Helden und am Eiskronengletscher, im Westen Aldur\'thars, versucht die Geißel, die Gefallenen gegen uns zu verwenden. Die Kommandanten der Geißel haben die Toten aus dem Tal wiedererweckt und sie mit furchterregender Stärke und Leidenschaft erfüllt. Die Banner, die die Geißelanführer in der Gletschergegend bei sich tragen, sind die Quelle dieser Mächte. Tötet die Bannerträger und Ihr werdet die konvertierten Helden, die sie führen, schwächen.|n|nEs obliegt Euch, uns von diesem Hindernis zu befreien und zu testen, wie es um deren Widerstand steht, bevor die Hauptstreitmacht vorrücken kann.', },
    {'Thassarian auf der Himmelsbrecher möchte, dass Ihr 5 Bannerträger der Geißel, 5 Konvertierer der Geißel und 20 konvertierte Helden tötet.', },
  },
  [13335] = {
    'Vor dem Tor des Schreckens',
    {'Der Großbrand, das Gebiet vor Corp\'rethar südlich des Eisenwallbollwerks, ist der Ort, an dem sich die Elitesoldaten des Lichkönigs zur Verteidigung der Zitadelle formiert haben.|n|nDer Weg wird von einer Legion Skeletthäscher versperrt, angeführt von einem Todesritterkontingent. Ich befürchte, dass, selbst wenn die Häscher beseitigt werden sollten, die Geißel sie einfach wieder aufstellen und gegen uns in den Kampf schicken würde.|n|nIch habe zwar einen Plan entwickelt, wie wir sie davon abhalten können, bin mir jedoch nicht sicher, ob es funktionieren wird. Hier, nehmt diese Lösung und zersetzt mit ihr die Überreste der Häscher.', },
    {'Thassarian an Bord der Himmelsbrecher wünscht, dass Ihr mithilfe der flüchtigen Säure die Überreste von 6 Skeletthäschern zersetzt.', },
  },
  [13336] = {
    'Blut der Auserwählten',
    {'Diejenigen Vrykul, die beim Lichkönig hoch im Ansehen stehen, nennen sich selbst die Ymirjar. Sie bewohnen eine Stadt im Zentrum von Eiskrone. Wir haben eine Menge Aufgaben zu erledigen, bevor wir die Eiskronenzitadelle angreifen können, und diejenige, die uns nun bevorsteht, ist, diese so genannten "Auserwählten" des Lichkönigs plattzumachen.|n|nBegebt Euch in Ihre Stadt, Ymirheim, und schlachtet sie in ihren Häusern ab. Hinterlasst keine Zweifel darüber, wer hier die stärkeren Kämpfer hat.', },
    {'Kürassier Drosche auf der Himmelsbrecher hat Euch entsandt, 20 Vrykul in Ymirheim zu töten.', },
  },
  [13337] = {
    'Das Eisenwallbollwerk',
    {'Das Eisenwallbollwerk blickt über das Tal der Gefallenen Helden westlich von Aldur\'thar. Vom Bollwerk aus kann man die Felder zu allen Seiten hin kontrollieren. Wir werden nicht weiter vorstoßen können, wenn das Bollwerk nicht genommen werden kann - doch es wird von Grimkor dem Boshaften und seinen Jüngern des Kults der Verdammten gehalten.|n|nWenn Ihr Grimkor schwächen könnt, werden unsere Streitkräfte wissen, was sie bei ihrem Vormarsch erwarten wird. Hier, nehmt diese Rune der Verzerrung. Seine Macht in der Nähe von Grimkors Kugel am Ende des Bollwerks freizusetzen, sollte genügen, um die Aufmerksamkeit der Nekromanten zu erregen.', },
    {'Besiegt Grimkor den Boshaften und kehrt zu Thassarian an Bord der Himmelsbrecher zurück.', },
  },
  [13338] = {
    'Die Wächter von Corp\'rethar',
    {'Corp\'rethar, das Tor des Schreckens, ist das letzte Hindernis zwischen uns und der Eiskronenzitadelle. Es befindet sich südlich des Eisenwallbollwerks jenseits des Gletschers und des Großbrands. Wenn unsere Truppen erst einmal dort angekommen sind, werden sie erschöpft sein, falls ihnen nicht schon Schlimmeres zugestoßen ist.|n|nWir müssen seine Verteidigung schwächen, oder unsere Armee wird an seinen Mauern zugrunde gehen.|n|nDie Zinnen werden von einigen der stärksten und eifrigsten Dienern des Lichkönigs bemannt. Tut alles, was in Eurer Macht steht, um diese Wächter zu vernichten, und hofft, dass dies ausreicht.', },
    {'Thassarian an Bord der Himmelsbrecher wünscht, dass Ihr 5 Herolde des Schreckens und 5 Wächter von Corp\'rethar tötet.', },
  },
  [13339] = {
    'Einen Scherbenhaufen hinterlassen',
    {'Oberhalb der Schlachtfelder von Corp\'rethar haben die Günstlinge des Lichkönigs drei Kristalle aufgestellt, die Splitter des Schreckens, der Verzweiflung und des Leidens. Sollte es unseren Männern gelingen, die Mauern von Corp\'rethar zu erreichen, so wird er diese Waffen gegen unsere Armee einsetzen.|n|nVoll zum Einsatz gebracht, werden diese Kristalle den Geist unserer Männer peinigen und sie mit Schmerz und Angst lähmen. Dann wird es der Geißel ein Leichtes sein, sie einfach so niederzumetzeln.|n|nFindet diese Splitter, zerstört sie und bringt mir ihre zerbrochenen Überreste. Wir dürfen nicht zulassen, dass der Lichkönig diese Waffen einsetzt!', },
    {'Bringt Thassarian an Bord der Himmelsbrecher den zerbrochenen Splitter des Schreckens, den zerbrochenen Splitter der Verzweiflung und den zerbrochenen Splitter des Leidens.', },
  },
  [13340] = {
    'Schließt Euch dem Angriff an',
    {'Wir brauchen mehr Leute, die sich dem Hauptangriff auf Ymirheim anschließen.|n|nJeder Krieger mit einer halben Gehirnzelle kann Euch sagen, dass die Vrykul grimmige Krieger sind, die man nicht auf die leichte Schulter nehmen sollte. Das gilt erst recht für die Ymirjar. Sie haben uns bereits spüren lassen, warum der Lichkönig sie für würdig befunden hat.|n|nFeldkommandant Xutjja befehligt den Angriff. Die Stadt selber befindet sich im Zentrum von Eiskrone, und Xutjjas Truppen sind nahe der Kante des Gletschers im Norden der Stadt positioniert.', },
    {'Meldet Euch bei Feldkommandant Xutjja an der Kante des Gletschers im Norden von Ymirheim.', },
  },
  [13341] = {
    'Schließt Euch dem Angriff an',
    {'Wir brauchen mehr Leute, die sich dem Hauptangriff auf Ymirheim anschließen.|n|nJeder Krieger mit einer halben Gehirnzelle kann Euch sagen, dass die Vrykul grimmige Krieger sind, die man nicht auf die leichte Schulter nehmen sollte. Das gilt erst recht für die Ymirjar. Sie haben uns bereits spüren lassen, warum der Lichkönig sie für würdig befunden hat.|n|nFeldkommandant Koup befehligt den Angriff. Die Stadt selber befindet sich im Zentrum von Eiskrone, und Koups Truppen sind nahe der Kante des Gletschers im Osten der Stadt positioniert.', },
    {'Meldet Euch bei Feldkommandant Koup an der Kante des Gletschers im Osten von Ymirheim.', },
  },
  [13342] = {
    'Keine Wanze',
    {'So, $G mein Freund: meine Freundin;, es ist an der Zeit eine Wanze zu platzieren.|n|nBeruhigt Euch, es ist nicht wirklich eine Wanze, aber es wird unseren Zwecken dienlich sein.|n|nIm nördlichen Bereich von Aldur\'thar versklaven die Leerenbeschwörer des Kults dämonische Lakaien. Benutzt diese Rute, um den Körpern dieser versklavten Lakaien die dunkle Materie zu entziehen, und dann benutzt den Beschwörungskristall der Kultisten, um unseren kleinen Spion zu erschaffen.|n|nBis er entdeckt wird, wird unser Bote unsere Augen und Ohren sein und ganz diskret die Handlungen unseres Gegners überwachen.', },
    {'Thassarian an Bord der Himmelsbrecher möchte, dass Ihr 5 dunkle Materien sammelt und in Aldur\'thar einen dunklen Boten beschwört.', },
  },
  [13343] = {
    'Geheimnis der Ewigen, die 2.',
    {'Da seid Ihr ja! Oder haben wir gerade erst miteinander gesprochen?|n|n<Chromie denkt über die Vielfalt der temporalen Möglichkeiten nach.>|n|nWie dem auch sei, die Ewigen sind hinter Euch her! Nun, an und für sich sind sie nicht hinter Euch her, sondern eher hinter der vergangenen Version von Euch, die einst das Stundenglas der Ewigkeit verteidigte. Ihr könnt Euch noch daran erinnern, oder?|n|nIhr wart das damals, nur seid Ihr es jetzt auch wieder. Halt, das ist nicht so wichtig. Was wichtig ist, ist, dass Ihr zurück zum Bronzedrachenschrein geht und Euch und das Stundenglas vor ihren Angriffen schützt, bevor man Euch aus der Geschichte entfernt!', },
    {'Chromie auf der höchsten Ebene des Wyrmruhtempels wünscht, dass Ihr noch einmal zum Bronzedrachenschrein reist.|n|nSobald Ihr dort seid, sollt Ihr das Stundenglas der Ewigkeit auf den Boden stellen und Eurem vergangenen Selbst dabei helfen, es vor den Truppen des ewigen Drachenschwarms zu beschützen.', },
  },
  [13344] = {
    'Keine Wanze',
    {'Die Kultisten haben den letzten Boten, den Ihr beschworen habt, entdeckt, $R.|n|nEr hat uns zwar bereits sehr viele Informationen beschafft, aber es ist wichtig, dass wir weiter über jeden Schritt unserer Feinde informiert sind.|n|nBenutzt diese Rute, um den Körpern der versklavten Lakaien die dunkle Materie zu entziehen, und dann benutzt ihren Beschwörungskristall, um einen weiteren dunklen Boten zu erschaffen.|n|nBis er entdeckt wird, wird unser Bote unsere Augen und Ohren sein und ganz diskret die Handlungen unseres Gegners überwachen.', },
    {'Thassarian an Bord der Himmelsbrecher möchte, dass Ihr 5 dunkle Materien sammelt und in Aldur\'thar einen dunklen Boten beschwört.', },
  },
  [13345] = {
    'Brauche mehr Informationen',
    {'Der Kult der Verdammten ist dafür berühmt, grandiose Pläne auszuarbeiten, die letzten Endes allerdings selten erfolgreich sind. Diesmal allerdings scheint es anders zu sein...|n|nVielleicht ist es die Nähe zum Lichkönig, die ihre Inbrunst angefacht hat. Was immer es auch ist, sie scheinen selbstbewusster denn je. Wir müssen herausfinden, was ihren Eifer befeuert und dieses dann ganz schnell unterbinden!|n|nIch glaube, dass der Schlüssel dazu ihre Forscher sind. Findet heraus, was sie im Schilde führen und berichtet mir dann.', },
    {'Thassarian an Bord der Himmelsbrecher möchte, dass Ihr 3 Seiten Forschung der Kultisten von den Forschern der Kultisten in Aldur\'thar sammelt, um damit eine These über den Kult der Verdammten zu erstellen.', },
  },
  [13346] = {
    'Es kann der Böseste nicht in Frieden ruhen...',
    {'Die Dummköpfe sind übrigens über etwas gestolpert, das äußerst gefährlich für unsere Pläne werden könnte!|n|nAlumeth, der Anführer dieser Sekte, hat sich in einem Ritual selbst geopfert und nun versorgen seine Untergebenen seine Seele mit Macht.|n|nWenn wir ihn weiterhin in Ruhe lassen, werden sie ihn schon bald zu einem mächtigen Gegner machen.|n|nIn ihrer Kammer verteilt liegt sein Herz, Szepter, Schädel und seine Robe - kombiniert sie miteinander und benutzt das, was dabei rauskommt, in der Nähe der dortigen Kristalle.|n|nBeeilt Euch, $R! Vernichtet ihn, bevor er noch mächtiger wird!', },
    {'Thassarian an Bord der Himmelsbrecher möchte, dass Ihr Alumeth den Aufgestiegenen in Aldur\'thar vernichtet.', },
  },
  [13347] = {
    'Wiedergeboren aus der Asche',
    {'Unser Schicksal steht schon von Geburt an fest. Bolvars Fall, wenn auch tragisch, war unvermeidlich.|n|nAlles, was Ihr jetzt noch tun könnt, $N, ist, Eurem Helden die letzte Ehre zu erweisen. Geht zum Schlachtfeld, holt Euch Bolvars Schild und bringt ihn Eurem König. Übermittelt ihm bei der Übergabe diese Botschaft: "Nicht alles ist verloren. Aus der Asche der Gefallenen wird eine Macht emporsteigen, die Reiche vereinen und das Böse aus dieser Welt treiben wird."|n|nEr darf den Glauben nicht verlieren. Geht jetzt, $N. Euer Volk braucht einen Helden - es braucht Euch.', },
    {'Geht zum Schlachtfeld vor Angrathar, der Pforte des Zorns, findet Fordragons Schild und bringt ihn zu König Varian Wrynn nach Burg Sturmwind in Sturmwind.', },
  },
  [13348] = {
    'Sinnlosigkeit',
    {'Seht Ihr es nun? Eure Männer gegen die Armeen des Prinzen zu entsenden sorgt nur dafür, dass ihre Reihen weiter anwachsen.|n|nIch erwarte nicht, dass Ihr es versteht... Ihr werdet vermutlich auch wie die anderen enden. Am besten kehrt Ihr zu denjenigen zurück, die Euch entsandt haben. Sie werden sich Sorgen machen.', },
    {'Kehrt zu Koltira Todesweber an Bord der Orgrims Hammer zurück.', },
  },
  [13349] = {
    'Die Wiege der Frostbrut',
    {'Wir müssen unseren Vorteil ausnutzen und weitermachen. Lasst uns den Streitkräften der Geißel keine Pause gönnen.|n|nSindragosas Sturz liegt gleich östlich jenseits des Tals der Verlorenen Hoffnung. Der Kult der Verdammten operiert dort unter strenger Aufsicht der untoten Vrykullakaien des Lichkönigs.|n|nEs ist ein Ort großer Macht, möglicherweise ein Friedhof des blauen Drachenschwarms, in dem sie aus den Knochen blauer Drachen die gefürchtete Frostbrut erschaffen.|n|nEin Angriff dort würde es für den Feind erheblich schwieriger machen, an Frostwyrms heranzukommen. Was sagt Ihr dazu, $N?', },
    {'Koltira Todesweber an Bord der Orgrims Hammer möchte, dass Ihr 5 Wyrmwiedererwecker, 8 Verderber der Kultisten und 3 Nekrolords der Vrykul in Sindragosas Sturz tötet.', },
  },
  [13350] = {
    'Es kann der Böseste nicht in Frieden ruhen...',
    {'Es ist Alumeth... Seine Macht wächst wieder an. Ich kann es fühlen. Wieder versorgen seine Untergebenen seine Seele mit Energie.|n|nWenn wir zulassen, dass er sich weiter erholt, werden ihre Bemühungen ihn zu einem mächtigen Gegner machen.|n|nKehrt in seine Kammer im Norden von Aldur\'thar zurück. Sammelt sein Herz, seinen Schädel, sein Zepter und seine Kleider und wendet seine Überreste dann auf den Kristall dort an.|n|nEilt Euch, $R! Vernichtet ihn, bevor er noch mächtiger wird!', },
    {'Thassarian an Bord der Himmelsbrecher möchte, dass Ihr Alumeth den Aufgestiegenen in Aldur\'thar vernichtet.', },
  },
  [13351] = {
    'Vorschau',
    {'Wir machen Fortschritte. Uns steht eine vielversprechende Reihe von Taktiken zur Verfügung, die uns die Kontrolle über das Tor des Todes verschaffen sollten. Es wird zweifellos viele Verluste geben, doch am Ende sollten wir die Oberhand gewinnen - außer, die Allianz mischt sich ein.|n|nAls Nächstes werden wir uns auf Aldur\'thar, das Tor der Verwüstung, konzentrieren. Fliegt hinunter und macht Euch mit der Konstruktion und den dort postierten Feinden vertraut.|n|nWenn Ihr wieder zurück seid, werde ich Eure Einsatzbeschreibungen vorbereitet haben.', },
    {'Koltira an Bord der Orgrims Hammer möchte, dass Ihr hinunter zum Tor der Verwüstung fliegt und Euch den südlichen, zentralen, nördlichen und nordwestlichen Bereich des Tors anseht.', },
  },
  [13352] = {
    'Gefährliche Gewandung',
    {'Der Kult der Verdammten hält das Tor der Verwüstung, wie? Wundert mich nicht.|n|nZeit, ein wenig Spaß zu haben. Ihr habt erwähnt, dass am südlichen Ende des Tores neue Kultisten ausgebildet werden. Sie haben mit Sicherheit einen besonderen Gegenstand bei sich, den alle neuen Initianden erhalten - eine Kugel der Illusion.|n|nDiese Artefakte dienen Kultanhängern zur Tarnung, um sich sicheren Durchgang durch feindliche Reihen zu verschaffen, um diese zu infiltrieren oder schlichtweg zwischen ihnen unterzutauchen.|n|nTötet diese Narren, bis Ihr eine von den Kugeln gefunden habt, $C, und wendet sie dann auf einen Unterwerfer an.', },
    {'Koltira an Bord der Orgrims Hammer möchte, dass Ihr Kugeln der Illusion von bitteren Initianden in Aldur\'thar sammelt und sie dann auf 3 dunkle Unterwerfer anwendet.', },
  },
  [13353] = {
    'Gefährliche Gewandung',
    {'Es sieht aus, als würde die Zahl der Initianden wieder wachsen. Ihr wisst, was Ihr zu tun habt...|n|nDie neuen Kultisten werden am südlichen Ende des Tores eingewiesen. Sie haben mit Sicherheit einen besonderen Gegenstand bei sich, den alle neuen Initianden erhalten - eine Kugel der Illusion.|n|nDiese Artefakte dienen Kultanhängern zur Tarnung, um sich sicheren Durchgang durch feindliche Reihen zu verschaffen, um diese zu infiltrieren oder schlichtweg zwischen ihnen unterzutauchen.|n|nTötet diese Narren, bis Ihr einige davon habt, dann wendet sie auf die Unterwerfer dort an.', },
    {'Koltira an Bord der Orgrims Hammer möchte, dass Ihr Kugeln der Illusion von bitteren Initianden in Aldur\'thar sammelt und sie dann auf 3 dunkle Unterwerfer anwendet.', },
  },
  [13354] = {
    'Befehlskette',
    {'Eurem Bericht und meinem Wissen über den Kult nach lassen sie einen Aufseher die Operation in jedem Lager am Tor leiten.|n|nIhre Anführer auszuschalten, wäre zwar nur ein vorübergehender Rückschlag für sie, doch es wird sie zumindest verlangsamen und aus dem Gleichgewicht bringen. Und das, $R, ist für den Augenblick gut genug.|n|nSucht nach diesen Aufsehern und kommt wieder zu mir zurück, wenn sie beseitigt wurden.', },
    {'Koltira an Bord der Orgrims Hammer möchte, dass Ihr nach Aldur\'thar geht und Aufseher Faedris, Aufseher Savryn, Aufseher Veraj und Aufseher Jhaeqon besiegt.', },
  },
  [13355] = {
    'Kann nicht reproduziert werden',
    {'Ich kann ihre Kessel von hier aus riechen, doch was sie da zusammenbrauen, ist keine Seuche.|n|nDiejenigen, die dem Kult die Treue schwören, werden dazu gezwungen, ein Gemisch zu trinken, das ihren Willen raubt und sie für immer zu Sklaven des Lichkönigs macht.|n|nManche sagen, dass der Trank die verzerrte Seele eines Wesens beinhaltet, das gefoltert und schließlich gnadenlos getötet wurde, doch ich habe es noch nie geschafft, ihn zu reproduzieren...|n|nFüllt dieses Fläschchen mit Proben aus jedem der drei Kessel in der nordwestlichen Region des Tors auf und bringt sie zu Chefingenieur Kupferklammer.', },
    {'Koltira an Bord der Orgrims Hammer möchte, dass Ihr das unterteilte Fläschchen an jedem der 3 Kessel der Kultisten auffüllt und es anschließend zu Chefingenieur Kupferklammer bringt.', },
  },
  [13356] = {
    'Jetzt neu testen',
    {'Das sollte seinen Zweck erfüllen!|n|nDiese verdrehten Hooligans suchen nach Seelen, die sie in ihren Irren-Saft mischen können? Dann lasst uns ihnen etwas aushelfen!|n|nNehmt einen Schluck hiervon - keine Sorge, ich habe es ausreichend verwässert... Der einzige Effekt wird sein, dass Ihr die Essenz der Kultisten werdet aufspüren können, sobald Ihr sie besiegt habt.|n|nSobald Ihr ein paar Essenzen habt, werft die sich windende Masse fehlgeleiteter Seelen in einen ihrer Kessel.|n|nWollen doch mal sehen, wie ihnen ihre eigene Medizin schmecken wird!', },
    {'Chefingenieur Kupferklammer an Bord der Orgrims Hammer möchte, dass Ihr eine windende Masse in einen der Kessel in Aldur\'thar werft.', },
  },
  [13357] = {
    'Jetzt neu testen',
    {'Diese verdrehten Kultisten suchen nach Seelen, die sie in ihren verrückten Saft mischen können? Dann lasst uns ihnen etwas aushelfen!|n|nNehmt einen Schluck hiervon - keine Sorge, ich habe es ausreichend verwässert... Ich bin mir fast sicher, dass Ihr als Effekt die Essenzen der Kultisten aufspüren könnt.|n|nSobald Ihr ein paar davon habt, werft die sich windende Masse fehlgeleiteter Seelen in einen ihrer Kessel.|n|nWollen doch mal sehen, wie ihnen ihre eigene Medizin schmecken wird!', },
    {'Chefingenieur Kupferklammer an Bord der Orgrims Hammer möchte, dass Ihr eine windende Masse in einen der Kessel in Aldur\'thar werft.', },
  },
  [13358] = {
    'Keine Wanze',
    {'So, $G mein Freund: meine Freundin;, es ist an der Zeit eine Wanze zu platzieren.|n|nBeruhigt Euch, es ist nicht wirklich eine Wanze, aber es wird unseren Zwecken dienlich sein.|n|nIm nördlichen Bereich von Aldur\'thar versklaven die Leerenbeschwörer des Kults dämonische Lakaien. Benutzt diese Rute, um den Körpern dieser versklavten Lakaien die dunkle Materie zu entziehen, und dann benutzt den Beschwörungskristall der Kultisten, um unseren kleinen Spion zu erschaffen.|n|nBis er entdeckt wird, wird unser Bote unsere Augen und Ohren sein und ganz diskret die Handlungen unseres Gegners überwachen.', },
    {'Koltira an Bord der Orgrims Hammer möchte, dass Ihr 5 dunkle Materien sammelt und in Aldur\'thar einen dunklen Boten beschwört.', },
  },
  [13359] = {
    'Wo Drachen einst fielen',
    {'Einst fiel hier eine ganze Brut von blauen Drachen. Und nun wird jeder einzelne von ihnen von seinen Dienern wiedererweckt.|n|nDen größten von ihnen hat er selbst wiedererweckt. Bringt mir ein wenig Knochenstaub von ihren Welpen und ich werde Euch ganz genau zeigen, wie er das gemacht hat.', },
    {'Matthias Lehner in Sindragosas Sturz möchte, dass Ihr 6 Einheiten Welpenknochenstaub besorgt.', },
  },
  [13360] = {
    'Zeit für Antworten',
    {'Ihr habt viele Fragen, $N. Ihr seid $Gder Einzige, der:die Einzige, die; mich sehen kann, weil Ihr etwas berührt habt, das einst ihm gehörte... könnt Ihr Euch nicht mehr erinnern?|n|nIhr wisst nicht, was es ist? Nun, ich kann es Euch nicht einfach so sagen... das würde ihn ziemlich wütend machen. Er ist nicht mehr bloß ein Prinz... er ist jetzt der König!|n|nTrefft mich im Hof der Knochen nördlich der Eiskronenzitadelle und Ihr könnt es für Euch selbst sehen.', },
    {'Sprecht mit Matthias Lehner im Hof der Knochen.', },
  },
  [13361] = {
    'Der Jäger und der Prinz',
    {'Bevor der Prinz König wurde, schlug er viele Schlachten... doch nur bei einer wäre er beinahe gestorben.|n|nSie fand genau hier statt. Nachdem ich Euch gezeigt habe, was hier einst geschah, werdet Ihr verstehen.|n|nSucht nach einem blutbefleckten Stein und hebt ihn auf. Ihr werdet sehen, was einst geschah.', },
    {'Matthias Lehner im Hof der Knochen möchte, dass Ihr nach einem blutbefleckten Stein sucht und das Schicksal des Prinzen zu Ende bringt.', },
  },
  [13362] = {
    'Wissen ist eine schreckliche Bürde',
    {'Jetzt wisst Ihr, womit Ihr es zu tun habt, $N. Ein Gegner, der keinen Schmerz mehr kennt... keine Zweifel... und auch keine Menschlichkeit. Ein Gegner, der alles tun würde, um das zu bekommen, was er will.|n|nDas Herz war seine Schwachstelle und er weiß jetzt, dass Ihr es gefunden habt.|n|nWenn Ihr zurückwollt, um es zu holen, dann nehmt Euch besser Hilfe mit. Er wird es nicht noch einmal unbewacht lassen.', },
    {'Meldet Euch bei Koltira Todesweber an Bord der Orgrims Hammer.', },
  },
  [13363] = {
    'Hilfe vom Argentumkreuzzug',
    {'Es gab Gerüchte unter den Todesrittern über die Ereignisse, von denen Ihr gesprochen habt. Ich hatte immer gedacht, dass sie etwas... symbolischer gemeint wären.|n|nWir müssen die anderen warnen, aber diskret. Sobald der Lichkönig von unserem Aufbruch erfährt, wird er das Herz an einen anderen Ort bringen lassen - solch eine Chance werden wir nie wieder bekommen.|n|nDie Horde und die Allianz wurden schon zuvor vom Kult der Verdammten infiltriert. Die Schwarze Klinge operiert zu nah an der Geißel.|n|nWir müssen mit Tirion Fordring und seinem Argentumkreuzzug sprechen.', },
    {'Sprecht mit Hochlord Tirion Fordring auf dem Kreuzfahrerturm.', },
  },
  [13364] = {
    'Tirions Schachzug',
    {'Diesen Morgen haben mich meine Späher darüber informiert, dass eine Prozession des Kults der Verdammten mit einem Artefakt von der Eiskronenzitadelle in Richtung Kathedrale der Dunkelheit aufgebrochen ist.|n|nUnd nun wird mir gesagt, dass es sich hierbei um Arthas\' eigenes Herz handelt... ein Gegenstand, der den letzten Rest seiner Menschlichkeit enthält.|n|nDies ist ein Zeichen des Lichts. Solange solch ein Artefakt existiert, besteht eine Chance, dass Arthas Menethil wieder ein Mensch werden kann!|n|nTrefft mich am Eingang der Kathedrale. Bringt auf jeden Fall eine Kultistenverkleidung mit - wir gehen inkognito.', },
    {'Tirion Fordring auf dem Kreuzfahrerturm möchte, dass Ihr die Kultistenkapuze besorgt, diese anzieht und Euch mit ihm am Eingang zur Kathedrale der Dunkelheit nordwestlich der Eiskronenzitadelle trefft.', },
  },
  [13365] = {
    'Keine Wanze',
    {'Die Kultisten haben den letzten Boten, den Ihr beschworen habt, entdeckt, $R.|n|nEr hat uns zwar bereits sehr viele Informationen beschafft, aber es ist wichtig, dass wir weiter über jeden Schritt des Kultes informiert sind.|n|nBenutzt diese Rute, um den Körpern der versklavten Lakaien die dunkle Materie zu entziehen, und dann benutzt ihren Beschwörungskristall, um einen weiteren dunklen Boten zu erschaffen.|n|nBis er entdeckt wird, wird unser Bote unsere Augen und Ohren sein und ganz diskret die Handlungen unseres Gegners überwachen.', },
    {'Koltira an Bord der Orgrims Hammer möchte, dass Ihr 5 dunkle Materien sammelt und in Aldur\'thar einen dunklen Boten beschwört.', },
  },
  [13366] = {
    'Brauche mehr Informationen',
    {'Der Kult der Verdammten ist dafür berühmt, grandiose Pläne auszuarbeiten, die letzten Endes allerdings selten erfolgreich sind. Diesmal allerdings scheint es anders zu sein...|n|nVielleicht ist es die Nähe zum Lichkönig, die ihre Inbrunst angefacht hat. Was immer es auch ist, sie scheinen selbstbewusster denn je. Wir müssen herausfinden, was ihren Eifer befeuert und dieses dann ganz schnell unterbinden!|n|nIch glaube, dass der Schlüssel dazu ihre Forscher sind. Findet heraus, was sie im Schilde führen und berichtet mir dann.', },
    {'Koltira an Bord der Orgrims Hammer möchte, dass Ihr 3 Seiten Forschung der Kultisten von den Forschern der Kultisten in Aldur\'thar sammelt, um damit eine These über den Kult der Verdammten zu erstellen...', },
  },
  [13367] = {
    'Es kann der Böseste nicht in Frieden ruhen...',
    {'Die Dummköpfe sind übrigens über etwas gestolpert, das äußerst gefährlich für unsere Pläne werden könnte!|n|nAlumeth, der Anführer dieser Sekte, hat sich in einem Ritual selbst geopfert und nun versorgen seine Untergebenen seine Seele mit Macht.|n|nWenn wir ihn weiterhin in Ruhe lassen, werden sie ihn schon bald zu einem mächtigen Gegner machen.|n|nIn ihrer Kammer verteilt liegt sein Herz, Szepter, Schädel und seine Robe - kombiniert sie miteinander und benutzt das, was dabei rauskommt, in der Nähe der dortigen Kristalle.|n|nBeeilt Euch, $R! Vernichtet ihn, bevor er noch mächtiger wird!', },
    {'Koltira an Bord der Orgrims Hammer möchte, dass Ihr Alumeth den Aufgestiegenen in Aldur\'thar tötet.', },
  },
  [13368] = {
    'Es kann der Böseste nicht in Frieden ruhen...',
    {'Es ist Alumeth... Seine Macht wächst wieder an. Ich kann es fühlen. Wieder versorgen seine Untergebenen seine Seele mit Energie.|n|nWenn wir zulassen, dass er sich weiter erholt, werden ihre Bemühungen ihn zu einem mächtigen Gegner machen.|n|nKehrt in seine Kammer im Norden von Aldur\'thar zurück. Sammelt sein Herz, seinen Schädel, sein Zepter und seine Kleider und wendet seine Überreste dann auf den Kristall dort an.|n|nEilt Euch, $R! Vernichtet ihn, solange noch Zeit ist!', },
    {'Koltira an Bord der Orgrims Hammer möchte, dass Ihr Alumeth den Aufgestiegenen in Aldur\'thar tötet.', },
  },
  [13369] = {
    'Das Schicksal wendet sich gegen Euch',
    {'Auf Geheiß von Lady Prachtmeer werde ich eine diplomatische Mission nach Orgrimmar entsenden, um Thrall, dem Kriegshäuptling der Horde, ein paar Fragen zu stellen. Ihr werdet ihr auf dieser Reise zur Seite stehen und dafür sorgen, dass ihr nichts zustößt. Kehrt anschließend mit Nachricht aus Orgrimmar zu mir zurück.|n|nSprecht mit Jaina, wenn Ihr bereit seid zu gehen.', },
    {'Steht Lady Jaina Prachtmeer in Orgrimmar zur Seite. Sprecht mit Thrall, dem Kriegshäuptling der Horde in Orgrimmar auf dem Kontinent Kalimdor.', },
  },
  [13370] = {
    'Ein königlicher Coup',
    {'Euer Champion Bolvar ist bei der Verteidigung unserer Welt ums Leben gekommen. Die Horde ist vom Verlust eines solch großen Helden schwer getroffen, jedoch war sie für die feigen Angriffe Putress\' auf die Pforte des Zorns nicht verantwortlich. Wir haben auch Verluste unter unseren mächtigen Helden zu beklagen aufgrund dieses Verrats.|n|nSagt Eurem König, dass wir alles in unserer Macht Stehende tun werden, um diejenigen, die für diese feige Tat verantwortlich sind, zur Rechenschaft zu ziehen. Wir werden alles tun, um einen Konflikt mit der Allianz zu vermeiden, doch wir werden nicht zögern, uns zu verteidigen, sollte man uns provozieren.', },
    {'Benutzt das Portal in der Feste Grommash, um nach Burg Sturmwind zurückzukehren und Thralls Nachricht an König Varian Wrynn zu übergeben.', },
  },
  [13371] = {
    'Es ist Zeit, totzuschlagen',
    {'Bevor Ihr nach Orgrimmar aufgebrochen seid, habe ich Broll und Valeera nach Unterstadt entsandt. Um genau zu sein, sind sie gerade am Eingang zur Kanalisation stationiert und erwarten Befehl.|n|nLady Prachtmeer wird außerhalb der Unterstadt ein Portal für unsere Truppen erschaffen. Geht dorthin und meldet Euch bei Broll. Jaina und ich werden dicht hinter Euch sein.', },
    {'Benutzt das Portal nach Unterstadt im Inneren von Burg Sturmwind, um Euch nach Unterstadt zu teleportieren. Meldet Euch bei Broll Bärenfell, wenn Ihr am Zielort angekommen seid.', },
  },
  [13372] = {
    'Der Schlüssel der fokussierenden Iris',
    {'Ihr spürt und hört, wie ein lautes Dröhnen magischer Natur von dem augenförmigen Juwel ausgeht, das Saphiron in seinen Klauen hielt. Für die Ohren eines Sterblichen ist es schon beinahe eine Qual, in Gegenwart des Steins zu sein.|n|nSolch ein bedeutungsvoller Gegenstand kann auf jeden Fall nur zur Königin der Großdrachen, Alexstrasza der Lebensbinderin, gebracht werden. Geht zur höchsten Ebene des Wyrmruhtempels in der Drachenöde und ersucht sie um Rat.', },
    {'Liefert den Schlüssel zur fokussierenden Iris bei Alexstrasza der Lebensbinderin auf der höchsten Ebene des Wyrmruhtempels in der Drachenöde ab.', },
  },
  [13373] = {
    'Vorzüge der Grenzwissenschaft',
    {'Ich habe unsere Infragrüntechnologie in die beschlagnahmten Bomber eingebaut - das wird Euch auf eurer ersten Mission in Feindgebiet beschützen! Sprecht mit Rizzy Ratschenwackel, um einen Bomber zu bekommen, und fliegt dann zum Bombardement!|n|nIhr werdet Bomben, Raketen und Schilde haben. Sorgt dafür, dass Eure Schilde aufgeladen bleiben, und werft die Bomben auf die Diener der Geißel im Bombardement ab. Kommt zurück, nachdem Ihr Eure Ziele getroffen habt, und es wird Euch noch mehr Arbeit erwarten.', },
    {'Grenzwissenschaftsingenieurin Tezzla möchte, dass Ihr 40 Bombardementinfanteristen, 8 Bombardementhauptmänner und 15 Gargoylewegelagerer tötet.', },
  },
  [13374] = {
    'Bereit zur Revolte!',
    {'Grenzwissenschaftsingenieurin Tezzla möchte, dass Ihr Bombardementinfanteristen, Gargoylewegelagerer, Frostbrutspäher und Kriegsmaschinen der Geißel vernichtet.', },
    {'Grenzwissenschaftsingenieurin Tezzla möchte, dass Ihr Bombardementinfanteristen, Gargoylewegelagerer, Frostbrutspäher und Kriegsmaschinen der Geißel vernichtet.', },
  },
  [13375] = {
    'Der heroische Schlüssel der fokussierenden Iris',
    {'Ihr spürt und hört, wie ein lautes Dröhnen magischer Natur von dem augenförmigen Juwel ausgeht, das Saphiron in seinen Klauen hielt. Für die Ohren eines Sterblichen ist es schon beinahe eine Qual, in Gegenwart des Steins zu sein.|n|nSolch ein bedeutungsvoller Gegenstand kann auf jeden Fall nur zur Königin der Großdrachen, Alexstrasza der Lebensbinderin, gebracht werden. Geht zur höchsten Ebene des Wyrmruhtempels in der Drachenöde und ersucht sie um Rat.', },
    {'Liefert den heroischen Schlüssel zur fokussierenden Iris bei Alexstrasza der Lebensbinderin auf der höchsten Ebene des Wyrmruhtempels in der Drachenöde ab.', },
  },
  [13376] = {
    'Totale Vernichtung: Das Tal der Verlorenen Hoffnung!',
    {'$N, der Kampf geht weiter. Zu unserem Glück haben wir uns mit Bomben und Raketen eingedeckt! Zeit für eine weitere Bombenmission - diese hier ist eine längere: Es geht über das Bombardement hinweg und zum Tal der Verlorenen Hoffnung. Setzt Euch wieder in einen Infragrünbomber, fliegt hinaus und verarbeitet die Diener der Geißel in kleine Geißelstückchen!', },
    {'Grenzwissenschaftsingenieurin Tezzla möchte, dass Ihr 50 Bombardementinfanteristen, 20 Gargoylewegelagerer, 12 Frostbrutspäher und 12 Kriegsmaschinen der Geißel vernichtet.', },
  },
  [13377] = {
    'Die Schlacht um Unterstadt',
    {'Tief im Inneren von Unterstadt versteckt er sich: der Meuchelmörder, der für den Tod Bolvars und den Tod unserer mutigen Soldaten an der Pforte des Zorns verantwortlich ist.|n|nVarian hat die geballte Macht der Allianz mitgebracht, um dabei zu helfen, die Stadt auseinanderzunehmen. Schließt Euch ihm und Lady Prachtmeer auf ihrer Jagd an und verdient Euch Euren Platz unter den größten Champions der Allianz!|n|nSprecht mit König Varian Wrynn, wenn Ihr bereit seid.', },
    {'Helft König Varian Wrynn und Lady Jaina Prachtmeer, Großapotheker Putress zur Rechenschaft zu ziehen! Meldet Euch bei König Varian Wrynn, solltet Ihr erfolgreich sein.', },
  },
  [13378] = {
    'Chefingenieur Kupferklammer',
    {'Sprecht mit Chefingenieur Kupferklammer.', },
    {'Sprecht mit Chefingenieur Kupferklammer.', },
  },
  [13379] = {
    'Grüne Technologie',
    {'Tezzla ist diejenige, nach der Ihr sucht, genau... sie beherrscht nun eine neue Wellenlänge namens Infragrün und hält sich damit in der Nähe der Geißel versteckt! Nahe genug, um Bomben auf sie abzuwerfen!|n|nIch werde Euch Infragrünsicht verleihen, damit Ihr sie sehen könnt. Sie befindet sich über Aldur\'thar, dem Tor der Verwüstung. Geht, los, geht... ich weiß, dass sie Arbeit für mutige Helden hat, die scharf darauf sind, in die Luft zu fliegen! Äh, ich meine: die scharf darauf sind, die Geißel in die Luft fliegen zu lassen!|n|nUnd $N, die Allianz hat unsere Technologie gestohlen und ihren eigenen versteckten Flugplatz in der Nähe errichtet. Haltet Euch von der Plattform mit den Bannern der Allianz fern!', },
    {'Sprecht mit Grenzwissenschaftsingenieurin Tezzla.', },
  },
  [13380] = {
    'Den Angriff leiten',
    {'Infragrüntechnologie ermöglicht es uns, hier versteckt zu bleiben - direkt unter der Nase der Geißel! Außerdem haben wir spezielle Bomber mit Infragrüntechnologie ausgerüstet... doch nicht um sie zu tarnen, nein! Wir benutzen die Technologie, um sie zu schützen!|n|nSprecht mit Karen Nein und fordert einen Bomber an. Fliegt mit ihm zum Bombardement... benutzt seine Schilde und sein Geschütz, um Euch zu schützen, und seinen Bombenwerfer, um die Ziele der Geißel zu treffen. Trainiert gut, kommt dann wieder zu mir zurück und ich werde eine noch wichtigere Mission für Euch haben!', },
    {'Kibli Killohertz möchte, dass Ihr 40 Bombardementinfanteristen, 8 Bombardementkapitäne und 15 Gargoylewegelagerer tötet.', },
  },
  [13381] = {
    'Watt ist mein Ziel',
    {'Zieht Euch warm an, $N, und fangt an zu beten. Diese nächste Mission wird Euren Verstand und Eure innere Stärke auf die Probe stellen wie ein Besuch der Schwiegereltern!|n|nFordert einen weiteren Bomber von Karen Nein an. Fliegt mit ihm über das Bombardement und das Tal der Verlorenen Hoffnung hinweg. Diesmal habt Ihr mehr Ziele, am Boden und in der Luft. Sorgt dafür, dass Euer Schutzschild und Eure Munition geladen ist, $N! Ich werde Euch wiedertreffen, wenn die Sache vorbei ist.', },
    {'Kibli Killohertz wünscht, dass Ihr Bombardementinfanteristen, Gargoylewegelagerer, Frostbrutspäher und Kriegsmaschinen der Geißel vernichtet.', },
  },
  [13382] = {
    'Mission mit Hertz: Das Tal der Verlorenen Hoffnung',
    {'Der Kampf geht weiter! Eure neuen Befehle sind hier. Es handelt sich um eine Langstreckenbombenmission zum Bombardement und zum Tal der Verlorenen Hoffnung. Fragt Karen nach einem Bomber und macht der Geißel mit Euren Bomben und Raketen die Hölle heiß!', },
    {'Kibli Killohertz möchte, dass Ihr 50 Bombardementinfanteristen, 20 Gargoylewegelagerer, 12 Frostbrutspäher und 12 Kriegsmaschinen der Geißel vernichtet.', },
  },
  [13383] = {
    nil,
    {'Die Goblins hatten Glück: Sie haben eine neue Energie gefunden. Sie nennen sie Infragrün und ich soll ein einäugiger Oger sein, wenn diese Psychopathen damit keinen grünen Volltreffer gelandet haben.|n|nGeht und sucht nach Kibli Killohertz. Er befindet sich auf einem kleinen, versteckten Flugplatz der Allianz über Aldur\'thar, dem Tor der Verwüstung, und ist dort für die umgekehrten Ingenieursbestrebungen in Bezug auf die Infragrüntechnologie zuständig. Ich werde Euch Infragrünsicht geben, damit Ihr ihn finden könnt. Geht zur Kuppel, auf der unsere Banner der Allianz wehen. Falls Ihr in der Nähe des Flugplatzes der Horde herumfliegen solltet, dann seid Ihr in jeder Menge grünen Schwierigkeiten.', },
    {'Chefingenieur Bolzenschlüssel möchte, dass Ihr zum verborgenen Allianzflugplatz über Aldur\'thar, dem Tor der Verwüstung, fliegt und Kibli Killohertz aufsucht.', },
  },
  [13384] = {
    'Entscheidung im Auge der Ewigkeit',
    {'Es ist nun, da Ihr Zugang zur fokussierenden Iris habt, an der Zeit, dass Ihr vom Schlüssel Gebrauch macht.|n|nSo gerne ich Malygos wieder bei uns mit offenen Armen empfangen möchte, aber zu diesem Zeitpunkt wird dies einfach nicht möglich sein. Angesichts all dessen, was auf dem Spiel steht, haben sich die anderen Drachenaspekte dazu entschlossen, dass der Zauberwirker ausgeschaltet werden muss.|n|n<Krasus klingt sehr betroffen, als er diese letzten Worte ausspricht.>|n|n$N, macht Euch auf den Weg zum Auge der Ewigkeit, begegnet Malygos und kehrt mit dem Herzen der Magie zurück.', },
    {'Krasus auf der Spitze des Wyrmruhtempels in der Drachenöde möchte, dass Ihr mit dem Herzen der Magie zurückkehrt.|n|nDiese Quest ist für den normalen Modus, also für die 10-Mann-Version des Auges der Ewigkeit, gedacht.', },
  },
  [13385] = {
    'Heroische Entscheidung im Auge der Ewigkeit',
    {'Es ist nun, da Ihr Zugang zur fokussierenden Iris habt, an der Zeit, dass Ihr vom Schlüssel Gebrauch macht.|n|nSo gerne ich Malygos wieder bei uns mit offenen Armen empfangen möchte, aber zu diesem Zeitpunkt wird dies einfach nicht möglich sein. Angesichts all dessen, was auf dem Spiel steht, haben sich die anderen Drachenaspekte dazu entschlossen, dass der Zauberwirker ausgeschaltet werden muss.|n|n<Krasus klingt sehr betroffen, als er diese letzten Worte ausspricht.>|n|n$N, macht Euch auf den Weg zum Auge der Ewigkeit, begegnet Malygos und kehrt mit dem Herzen der Magie zurück.', },
    {'Krasus auf der Spitze des Wyrmruhtempels in der Drachenöde möchte, dass Ihr mit dem Herzen der Magie zurückkehrt.|n|nDiese Quest ist für den heroischen Modus, also für die 25-Mann-Version des Auges der Ewigkeit, gedacht.', },
  },
  [13386] = {
    'Ausnutzen einer Öffnung',
    {'Ich habe eine interessante Aufgabe für Euch, $N. Allerdings nur, wenn Ihr auf eine Herausforderung aus seid.|n|nWir haben von einer Öffnung unterhalb der Eiskronenzitadelle gehört. Unsere Ingenieure haben sie studiert und gehen davon aus, dass sie eine strukturelle Schwäche darstellt.|n|nWir haben ein paar Männer mit einer "geborgten" Ladung Saronitbomben dorthin entsandt. Sie stehen unter dem Kommando von Hauptmann Kendall.|n|nMit ein bisschen Hilfe könnten wir den Streitkräften der Geißel einen ordentlichen Schlag verpassen. Was sagt Ihr, $N?', },
    {'Redet mit Hauptmann Kendall unterhalb der Eiskronenzitadelle.', },
  },
  [13387] = {
    'Sicherung des Gebiets',
    {'Die Saronitbomben sind platziert, $N. Wir haben aber nur einen Versuch, also muss es unbedingt funktionieren.|n|nWir müssen für eine Weile die Kontrolle über das Gebiet haben, um eine sichere Detonation garantieren zu können. Lasst uns versuchen, die Anzahl der Geißel ein wenig zu reduzieren.', },
    {'Kapitän Kendall bei der Eiskronenzitadelle möchte, dass Ihr 10 bullige Schrecken tötet.', },
  },
  [13388] = {
    'Lasst sie hochgehen!',
    {'Das sieht doch schon mal alles recht gut aus. Also, gehen wir\'s an!|n|nDer Bombenstapel befindet sich gleich in der Nähe der Grube. Ich werde beginnen, die Männer zu evakuieren.', },
    {'Hauptmann Kendall unterhalb der Eiskronenzitadelle möchte, dass Ihr die Lunte an dem nahegelegenen Saronitbombenstapel anzündet.', },
  },
  [13389] = {
    'Eine kurze Lunte',
    {'Als Ihr die Lunte entzündet, merkt Ihr, dass sie viel schneller abbrennt, als Ihr erwartet hattet.|n|nDie Bomben sind kurz vor der Explosion und Eure beste Chance zu überleben ist, Euch nach vorne fallen zu lassen und zu hoffen, dass Euch der Sturz nicht tötet.', },
    {'Haltet nach Hinweisen Ausschau, wo auch immer der Sturz Euch hinführt.', },
  },
  [13390] = {
    'Eine Stimme im Dunklen',
    {'Das Objekt ist überhaupt kein Kristall, sondern etwas Organisches, das in Eis eingeschlossen ist.|n|nAls Ihr es berührt, zuckt Eure Hand vor Schmerz zurück. Es fühlt sich an, als hättet Ihr Euch in die Hand geschnitten, aber es ist keine Wunde zu sehen.|n|nAls Ihr Eure Gedanken sammelt, hört Ihr die Stimme eines Jungen in der Nähe.|n|n"Das hättet Ihr nicht tun sollen."', },
    {'Untersucht die nahe Stimme in Naz\'anak, den Vergessenen Tiefen.', },
  },
  [13391] = {
    'Zeit zum Verstecken',
    {'Ihr hättet das nicht berühren sollen. Nun, da Ihr es getan habt, wird er kommen und nach Euch suchen.|n|nUnd er wird Euch finden. Solange Ihr Euch nicht vor ihm versteckt.|n|nBringt mir Blut von den Gesichtslosen, wenn Ihr leben wollt.', },
    {'Matthias Lehner möchte, dass Ihr ihm 3 Proben Blut des Gesichtslosen bringt.', },
  },
  [13392] = {
    'Rückkehr an die Oberfläche',
    {'Ihr solltet nun gehen. Hinter mir findet Ihr ein Portal, das Euch an die Oberfläche bringen wird.|n|nWir werden uns wiedersehen. Er wird nach Euch suchen.|n|nEs ist nur eine Frage der Zeit, bis er Euch findet.', },
    {'Kehrt zu Thassarian an Bord der Himmelsbrecher zurück.', },
  },
  [13393] = {
    'Feldreparaturen',
    {'Alles klar. Lasst uns aber nicht zu früh feiern. Wir müssen aus dem Vorteil, den wir mit unserer kleinen Bombardierung errungen haben, Kapital schlagen.|n|nWir haben ein funktionierendes Katapult der Verwüster-Klasse von der Horde auf dem Feld unten entdeckt. Die Spuke scheinen es auseinanderzunehmen.|n|nWenn Ihr es wieder zusammensetzen könntet, wären wir in der Lage, den Armeen der Geißel im Tal ernstlichen Schaden zuzufügen.|n|nKlar, Ihr werdet ziemlich in der Unterzahl sein, aber ich setze großes Vertrauen in Euch.', },
    {'Thassarian an Bord der Himmelsbrecher möchte, dass Ihr 5 Verwüsterersatzteile von den aasfressenden Spuken sammelt und sie zu dem defekten Verwüster im Tal der Verlorenen Hoffnung bringt.', },
  },
  [13394] = {
    'Tut Euer Schlechtestes',
    {'Ihr werdet diese Maschine gegen die Geißel einsetzen? Auf diese Weise werdet Ihr nicht gegen sie gewinnen können.|n|nIhr könnt Hunderte... sogar Tausende von ihnen zerstören, doch gewinnen werdet Ihr nicht - nicht hier draußen.|n|nTrefft mich im Norden, wenn Ihr genug mit Eurer Maschine gespielt habt. Dort gibt es ein altes Militärlager. Was ich Euch zeigen werde, wird Euch einen kleinen Einblick darüber gewähren, wem wir uns hier gegenübersehen.', },
    {'Zerstört mithilfe des Runderneuerten Verwüsters 150 verrottete Ghule, 20 Frostschädelmagier und 2 Knochenriesen im Tal der Verlorenen Hoffnung. Sprecht mit Matthias Lehner im Vorhutslager der Ersten Legion, wenn Ihr die Aufgabe abgeschlossen habt.', },
  },
  [13395] = {
    'Armee der Verdammten',
    {'Ihr meint wohl, Ihr seid ziemlich stark... diese Untoten zu bekämpfen und ihre Knochen mit Euren Kriegsmaschinen zu zerquetschen.|n|nDas ist aber noch gar nichts, verglichen mit der Stärke, derer es bedarf, um sie zu erschaffen.|n|nIch habe selbst gesehen, wie der Prinz es gemacht hat. Ich kann Euch zeigen, wie das geschehen ist... wenn Ihr wollt.', },
    {'Matthias Lehner beim Vorhutslager der Ersten Legion möchte, dass Ihr eine Armee von 100 ghulischen Dienern aufstellt.', },
  },
  [13396] = {
    'Sinnlosigkeit',
    {'Seht Ihr es nun? Eure Männer gegen die Armeen des Prinzen zu entsenden sorgt nur dafür, dass ihre Reihen weiter anwachsen.|n|nIch erwarte nicht, dass Ihr es versteht... Ihr werdet vermutlich auch wie die anderen enden. Am besten kehrt Ihr zu denjenigen zurück, die Euch entsandt haben. Sie werden sich Sorgen machen.', },
    {'Kehrt zu Thassarian an Bord der Himmelsbrecher zurück.', },
  },
  [13397] = {
    'Sindragosas Sturz',
    {'Ihr seid ein echter Star, $N. Wisst Ihr, wenn ich einem der anderen Soldaten einen Auftrag erteile, stehen die Chancen, dass er ihn erfolgreich ausführt, etwa fünfzig zu fünfzig. Die Chancen, dass er lebend zurückkommt... nun, unwesentlich schlechter.|n|nAber bei Euch ist die Sache stets geritzt. Zuverlässig wie ein gnomisches Uhrwerk!|n|nWie dem auch sei, ich habe noch einen für Euch. Sindragosas Sturz, im Osten des Tals. Dort gehen verstärkte Aktivitäten der Kultisten vor sich, inklusive und sich nicht beschränkend auf die Erschaffung von Frostwyrms. Ich brauche Euch, um denen mal ordentlich die Zähne einzutreten.|n|nIch hasse Kultisten.', },
    {'Thassarian an Bord Himmelsbrecher möchte, dass Ihr 5 Wyrmwiedererwecker, 8 Verderber der Kultisten und 3 Nekrolords der Vrykul in Sindragosas Sturz tötet.', },
  },
  [13398] = {
    'Wo Drachen einst fielen',
    {'Einst fiel hier eine ganze Brut von blauen Drachen. Und nun wird jeder einzelne von ihnen von seinen Dienern wiedererweckt.|n|nDen größten von ihnen hat er selbst wiedererweckt. Bringt mir ein wenig Knochenstaub von ihren Welpen und ich werde Euch ganz genau zeigen, wie er das gemacht hat.', },
    {'Matthias Lehner in Sindragosas Sturz möchte, dass Ihr 6 Einheiten Welpenknochenstaub besorgt.', },
  },
  [13399] = {
    'Zeit für Antworten',
    {'Ihr habt viele Fragen, $N. Ihr seid $Gder Einzige, der:die Einzige, die; mich sehen kann, weil Ihr etwas berührt habt, das einst ihm gehörte... könnt Ihr Euch nicht mehr erinnern?|n|nIhr wisst nicht, was es ist? Nun, ich kann es Euch nicht einfach so sagen... das würde ihn ziemlich wütend machen. Er ist nicht mehr bloß ein Prinz... er ist jetzt der König!|n|nTrefft mich im Hof der Knochen nördlich der Eiskronenzitadelle und Ihr könnt es für Euch selbst sehen.', },
    {'Sprecht mit Matthias Lehner im Hof der Knochen.', },
  },
  [13400] = {
    'Der Jäger und der Prinz',
    {'Bevor der Prinz König wurde, schlug er viele Schlachten... doch nur bei einer wäre er beinahe gestorben.|n|nSie fand genau hier statt. Nachdem ich Euch gezeigt habe, was hier einst geschah, werdet Ihr verstehen.|n|nSucht nach einem blutbefleckten Stein und hebt ihn auf. Ihr werdet sehen, was einst geschah.', },
    {'Matthias Lehner im Hof der Knochen möchte, dass Ihr nach einem blutbefleckten Stein sucht und das Schicksal des Prinzen zu Ende bringt.', },
  },
  [13401] = {
    'Wissen ist eine schreckliche Bürde',
    {'Jetzt wisst Ihr, womit Ihr es zu tun habt, $N. Ein Gegner, der keinen Schmerz mehr kennt... keine Zweifel... und auch keine Menschlichkeit. Ein Gegner, der alles tun würde, um das zu bekommen, was er will.|n|nDas Herz war seine Schwachstelle und er weiß jetzt, dass Ihr es gefunden habt.|n|nWenn Ihr zurückwollt, um es zu holen, dann nehmt Euch besser Hilfe mit. Er wird es nicht noch einmal unbewacht lassen.', },
    {'Meldet Euch bei Thassarian an Bord der Himmelsbrecher.', },
  },
  [13402] = {
    'Tirions Hilfe',
    {'Es ist nicht das erste Mal, dass ich die Geschichte über Arthas und sein Herz gehört habe... habe immer gedacht, dass es eine erfundene Geschichte für gewöhnliche Soldaten wäre.|n|nWir müssen umgehend danach handeln. Leider müssen wir das Ganze geheim halten.|n|nArthas\' Agenten sind überall und wenn er es herausfindet, wäre unser Plan zunichte.|n|nWir müssen dies zum Argentumkreuzzug bringen. Jeder einzelne Paladin in dem Orden wurde von Tirion höchstpersönlich erlesen. Wenn irgendwer noch nicht von den Kultisten infiltriert wurde, dann sind es diese Jungs.', },
    {'Sprecht mit Hochlord Tirion Fordring auf dem Kreuzfahrerturm.', },
  },
  [13403] = {
    'Tirions Schachzug',
    {'Diesen Morgen haben mich meine Späher darüber informiert, dass eine Prozession des Kults der Verdammten mit einem Artefakt von der Eiskronenzitadelle in Richtung Kathedrale der Dunkelheit aufgebrochen ist.|n|nUnd nun wird mir gesagt, dass es sich hierbei um Arthas\' eigenes Herz handelt... ein Gegenstand, der den letzten Rest seiner Menschlichkeit enthält.|n|nDies ist ein Zeichen des Lichts. Solange solch ein Artefakt existiert, besteht eine Chance, dass Arthas Menethil wieder ein Mensch werden kann!|n|nTrefft mich am Eingang der Kathedrale. Bringt auf jeden Fall eine Kultistenverkleidung mit - wir gehen inkognito.', },
    {'Tirion Fordring auf dem Kreuzfahrerturm möchte, dass Ihr die Kultistenkapuze besorgt, diese anzieht und Euch mit ihm am Eingang zur Kathedrale der Dunkelheit nordwestlich der Eiskronenzitadelle trefft.', },
  },
  [13404] = {
    'Statische Schocktruppen: das Bombardement',
    {'Dies wird ein Kurzstreckeneinsatz, über das Bombardement. Gut zum warm werden. Bereit?', },
    {'Kibli Killohertz möchte, dass Ihr 50 Bombardementinfanteristen, 10 Bombardementkapitäne und 20 Gargoylewegelagerer tötet.', },
  },
  [13405] = {
    'Ruf zu den Waffen: Strand der Uralten',
    {'Wir kämpfen in Nordend nicht nur gegen die Armeen des Lichkönigs, sondern auch gegen die Armeen der Horde.|n|nAuf dem Strand der Uralten wurde ein mächtiges Titanenrelikt gefunden. Wie Ihr vielleicht schon wisst, sind wir Zwerge seit Jahren Hüter solcher Artefakte gewesen und sind deswegen auch ihre rechtmäßigen Besitzer.|n|nIn diesem Fall ist die Horde sehr scharf darauf, das Relikt aus den Titanenruinen zu klauen. Sie werden es sicherlich als Waffe gegen uns einsetzen - wir müssen sie also um jeden Preis aufhalten.', },
    {'Gewinnt eine Schlacht auf dem Strand der Uralten und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.', },
  },
  [13406] = {
    'Auf derselben Wellenlänge: Das Bombardement',
    {'Bereit, Euch mit einer kurzen Bombenmission aufzuwärmen? Ihr habt Eure Befehle und wir unsere Bomber - bestückt und bereit.', },
    {'Grenzwissenschaftsingenieurin Tezzla möchte, dass Ihr 50 Bombardementinfanteristen, 10 Bombardementhauptmänner und 20 Gargoylewegelagerer tötet.', },
  },
  [13407] = {
    'Ruf zu den Waffen: Strand der Uralten',
    {'Nur weil wir in Nordend einmarschieren, um die Geißel zu vernichten, muss das noch lange nicht heißen, dass wir der Allianz eine Pause gönnen.|n|nDie Zwerge von der Forscherliga haben ein mächtiges Titanenrelikt gefunden und der Blitz soll uns treffen, wenn wir es einfach der Allianz überlassen.|n|nGeht, $N, und vernichtet unsere Feinde. Sie sollen wissen, dass, egal wo wir uns auch begegnen, sie weiterhin unsere Todfeinde sind.', },
    {'Gewinnt eine Schlacht auf dem Strand der Uralten und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.', },
  },
  [13408] = {
    'Höllenfeuerbefestigungen',
    {'Die Höllenfeuerzitadelle steht im ständigen Kampf mit unseren Streitmächten. Wir halten uns wacker, aber wir können keinen richtigen Angriff gegen sie starten. Um dies zu tun, müssen wir weiter vorrücken.|n|nUnsere Späher haben drei Befestigungsanlagen in der Nähe der Höllenfeuerzitadelle entdeckt. Wir möchten, dass Ihr uns helft, diese drei Anlagen einzunehmen. Meldet Euch bei mir, sobald Ihr eine in Beschlag nehmen konntet.|n|nMöge das Glück in den vor Euch liegenden Kämpfen bei Euch sein, $N, denn Ihr werdet ohne Zweifel auf Streitkräfte der Horde treffen, die dasselbe im Schilde führen.', },
    {'Nehmt den Rundblick, das Stadion und die Trümmerbastion ein, und kehrt dann zu Stabsfeldwebel Tracy Stolzbrunn in der Ehrenfeste auf der Höllenfeuerhalbinsel zurück.', },
  },
  [13409] = {
    'Höllenfeuerbefestigungen',
    {'Die Höllenorcs der Höllenfeuerzitadelle müssen von unserem Heimatland entfernt werden! Um sie anzugreifen, müssen wir strategisch wichtige Punkte in der Nähe der Zitadelle einnehmen.|n|nUnsere Kundschafter haben drei Befestigungsanlagen ausgemacht, die für unsere Zwecke geeignet sind, aber die Allianz hatte dieselbe Idee und schickt schon Streitkräfte, um sie einzunehmen!|n|nWir möchten, dass Ihr die Allianz aufhaltet und die drei Forts einnehmt. Helft bei der Einnahme jeder Anlage und kehrt dann zu mir zurück.|n|nFür die Horde!', },
    {'Nehmt den Rundblick, das Stadion und die Trümmerbastion ein, und kehrt dann zu Kriegsherold Blauauge in Thrallmar zurück.', },
  },
  [13410] = {
    'Höllenfeuerbefestigungen',
    {'Die Höllenfeuerzitadelle steht im ständigen Kampf mit unseren Streitmächten. Wir halten uns wacker, aber wir können keinen richtigen Angriff gegen sie starten. Um dies zu tun, müssen wir weiter vorrücken.|n|nUnsere Späher haben drei Befestigungsanlagen in der Nähe der Höllenfeuerzitadelle entdeckt. Wir möchten, dass Ihr uns helft, diese drei Anlagen einzunehmen. Meldet Euch bei mir, sobald Ihr eine in Beschlag nehmen konntet.|n|nMöge das Glück in den vor Euch liegenden Kämpfen bei Euch sein, $N, denn Ihr werdet ohne Zweifel auf Streitkräfte der Horde treffen, die dasselbe im Schilde führen.', },
    {'Nehmt den Rundblick, das Stadion und die Trümmerbastion ein, und kehrt dann zu Stabsfeldwebel Tracy Stolzbrunn in der Ehrenfeste auf der Höllenfeuerhalbinsel zurück.', },
  },
  [13411] = {
    'Höllenfeuerbefestigungen',
    {'Die Höllenorcs der Höllenfeuerzitadelle müssen von unserem Heimatland entfernt werden! Um sie anzugreifen, müssen wir strategisch wichtige Punkte in der Nähe der Zitadelle einnehmen.|n|nUnsere Kundschafter haben drei Befestigungsanlagen ausgemacht, die für unsere Zwecke geeignet sind, aber die Allianz hatte dieselbe Idee und schickt schon Streitkräfte, um sie einzunehmen!|n|nWir möchten, dass Ihr die Allianz aufhaltet und die drei Forts einnehmt. Helft bei der Einnahme jeder Anlage und kehrt dann zu mir zurück.|n|nFür die Horde!', },
    {'Nehmt den Rundblick, das Stadion und die Trümmerbastion ein, und kehrt dann zu Kriegsherold Blauauge in Thrallmar zurück.', },
  },
  [13412] = {
    nil,
    {'Grüße, $C. Dürfte ich Euch um einen Gefallen bitten?|n|nCorastrasza ist die Schwester von Raelorasz - dem roten Drachen, der hier in unserem Außenposten das Sagen hat. Sie ist gegen seinen Willen zu einem der oberen Nexusringe geflogen, um ein paar blaue Drachen, die über fürchterliche Macht verfügen, zu beobachten.|n|nEr macht sich um sie Sorgen, obwohl er es nie zugeben wird, und würde jegliche Neuigkeiten über ihr Wohlergehen begrüßen.|n|nSeid so gut und sucht sie auf. Bittet sie, ihren Stolz beiseite zu legen und ihrem Bruder eine Nachricht zu schicken.', },
    {'Bibliothekarin Serrah möchte, dass Ihr mit Corastrasza in Kaltarra sprecht.', },
  },
  [13413] = {
    'Schlacht in den Wolken',
    {'Ihr besitzt den Mut, Euch so nah an Malygos\' Hort heranzuwagen, $GSterblicher:Sterbliche;? Oder ist es einfach nur Ignoranz? Bald werden wir es wissen...|n|nIch bin ein erfahrener Ausbilder der anmutigen Drachen des roten Drachenschwarms. Meine Aufgabe hier ist es, den Feind zu studieren und meinen kostbaren Begleitern die Taktiken beizubringen, die sich am effektivsten gegen den Meister der Blauen erweisen werden.|n|nDamit Ihr zeigen könnt, ob Ihr die Nerven und das Können besitzt, werde ich Euch erlauben, auf einem meiner Drachen in den Kampf gegen die Untergebenen des Feindes zu reiten.|n|nDie Möglichkeit besteht - Ihr müsst nur danach fragen...', },
    {'Corastrasza auf dem oberen Ring des Nexus in Kaltarra möchte, dass Ihr auf ihrem Drachen 5 Elitesoldaten der Eidschuppen tötet.', },
  },
  [13414] = {
    'Schlacht in den Wolken',
    {'So sehen wir uns wieder, $R. Ich muss zugeben, dass Ihr mir langsam ans Herz wachst.|n|nLiege ich richtig in der Annahme, dass Ihr gekommen seid, um Eure Luftkampffertigkeiten zu verbessern?|n|nMeine Begleiter stehen wie immer bereit, Ihr zerstörerisches Feuer über den Feind zu ergießen.|n|nSprecht nur ein Wort und sie werden Euch zur Verfügung stehen.', },
    {'Corastrasza auf dem oberen Ring des Nexus in Kaltarra möchte, dass Ihr auf ihrem Drachen 5 Elitesoldaten der Eidschuppen tötet.', },
  },
  [13415] = {
    'Die Bibliothekenkonsole',
    {'Norgannons Schale liegt in Reichweite, $N. Bringt die Scheibe des Erfinders ins Innere der Bücherei. Dort sollte sich eine Konsole befinden, die Ihr mithilfe der Scheibe aktivieren könnt. Ich kann mir vorstellen, dass Mimir dort mehr als nur Norgannons Schale versteckt hat. Es befinden sich wahrscheinlich genug Schemata dort, um die Ingenieure von Eisenschmiede über Jahre hinweg zu beschäftigen!|n|nJedenfalls sollt Ihr die Scheibe dazu benutzen, um die Schale zu besorgen. Hoffentlich hat Mimir sich nicht dazu entschlossen, noch mehr Hindernisse in Euren Weg zu stellen.', },
    {'Bringt die Scheibe des Erfinders zur Bibliothekenkonsole des Erfinders im Inneren der Bibliothek des Erfinders.', },
  },
  [13416] = {
    'Die Bibliothekenkonsole',
    {'Norgannons Schale liegt in Reichweite, $N. Bringt die Scheibe des Erfinders ins Innere der Bücherei. Dort sollte sich eine Konsole befinden, die Ihr mithilfe der Scheibe aktivieren könnt. Ich kann mir vorstellen, dass Mimir dort mehr als nur Norgannons Schale versteckt hat. Es befinden sich wahrscheinlich genug Schemata dort, um die Ingenieure von Eisenschmiede über Jahre hinweg zu beschäftigen!|n|nJedenfalls sollt Ihr die Scheibe zur Konsole bringen. Hoffentlich hat Mimir sich nicht dazu entschlossen, noch mehr Hindernisse in Euren Weg zu stellen.', },
    {'Bringt die Scheibe des Erfinders zur Bibliothekenkonsole des Erfinders im Inneren der Bibliothek des Erfinders.', },
  },
  [13417] = {
    'Die Gebrüder Bronzebart',
    {'Das war\'s! Wir haben endlich den Schlüsselstein... Er ist schön! Ich bin schon mehr als einmal um die ganze Welt gereist, aber wegen diesem Ding war ich wieder so aufgeregt wie ein kleines Kind. Allerdings dürfte jetzt wohl nicht der richtige Zeitpunkt sein, um durchzuatmen und den Stein zu bewundern. Wir müssen von hier verschwinden.|n|nSteigt auf meine Flugmaschine und sorgt für Deckung, damit wir bei unserer Flucht vor diesen Eisenzwergen geschützt sind!', },
    {'Begleitet Brann Bronzebart und seine Flugmaschine zur Eisfestung.', },
  },
  [13418] = {
    'Kriegsvorbereitung',
    {'Ihr da!|n|nIhr seht aus, als hättet Ihr etwas auf dem Kasten. Wir könnten ein paar fähigere Leute in Eiskrone gebrauchen.|n|nIhr habt vielleicht die Gerüchte über unseren fehlgeschlagenen Bodenangriff auf den Gletscher gehört, doch lasst mich Euch beruhigen. Wir führen unseren Angriff jetzt von einem der fortgeschrittensten Gefährte aus, die es in Azeroth gibt: die Himmelsbrecher. Die Horde hat keine Chance und auch Arthas nicht.|n|nSagt mir Bescheid, wenn Ihr bereit seid, aufzubrechen.', },
    {'Sprecht mit Offizier Van Rossem, um Euch sicher zur Himmelsbrecher in Eiskrone bringen zu lassen, und meldet Euch dann bei Stabshauptmann Justin Bartlett.', },
  },
  [13419] = {
    'Kriegsvorbereitung',
    {'Ihr da!|n|nIhr seht aus, als hättet Ihr etwas auf dem Kasten. Wir könnten ein paar fähigere Leute in Eiskrone gebrauchen.|n|nDie Hunde von der Allianz sind vor uns nach Eiskrone geeilt, unvorbereitet, und haben für ihre Ungeduld genau das bekommen, was sie verdienen. Wir haben uns Zeit gelassen, haben uns vorbereitet und schon bald werden wir den echten Angriff starten - von einem der fortgeschrittensten Gefährte in ganz Azeroth aus: der Orgrims Hammer. Die Allianz hat keine Chance und auch Arthas nicht.|n|nSagt mir Bescheid, wenn Ihr bereit seid, aufzubrechen und zu helfen.', },
    {'Sprecht mit Himmelshäscher Klum, um Euch sicher zur Orgrims Hammer in Eiskrone bringen zu lassen, und meldet Euch dann bei Himmelshäscher Korm Schwarznarbe.', },
  },
  [13420] = {
    'Immerfrost',
    {'Dieses Stück Eis war enormen Kräften und natürlicher Magie aus den Tiefen der Erde ausgesetzt. Zusammen haben diese Effekte ein Eis geschaffen, das niemals schmelzen wird.|n|nDa Ihr Euch in solchen Dingen nur wenig auskennt, entschließt Ihr Euch, die Probe zurück nach Dun Niffelem zu bringen. Dort muss es irgendjemanden geben, der mit dessen Eigenschaften vertraut ist.', },
    {'Ihr müsst nach Dun Niffelem zurückkehren und Euch bei Calder über das Stück Immerfrost erkundigen.', },
  },
  [13421] = {
    'Vergesst das Immerfrosteis nicht!',
    nil,
    nil,
  },
  [13422] = {
    'Disziplin bewahren',
    {'Ihr habt das geschafft, woran andere gescheitert sind. Doch auf Euren Lorbeeren könnt Ihr Euch noch nicht ausruhen.|n|nIhr müsst anderen zeigen, was Stärke und Engagement wirklich bedeuten.|n|nDie Aufsässigen in der verlorenen Mine müssen wieder einmal diszipliniert werden. Zeigt es ihnen, Schwester... zeigt ihnen, was es bedeutet, uns nicht zu gehorchen.', },
    {'Gretta die Schiedsfrau aus Brunnhildar möchte, dass Ihr die Disziplinarrute auf 6 erschöpfte Vrykul in der Verlassenen Mine anwendet.', },
  },
  [13423] = {
    'Euren Titel verteidigen',
    {'Alle sind von Eurer Leistung beeindruckt, Schwester. Doch lasst Eure Deckung nicht sinken. Jeder neue größenwahnsinnige Herausforderer wird jetzt herauskommen und sich Euren Titel als Hyldskvinnar schnappen wollen.|n|nZeigt diesen Emporkömmlingen, aus welchem Holz Ihr geschnitzt seid.', },
    {'Gretta die Schiedsfrau in Brunnhildar wünscht, dass Ihr 6 siegreiche Herausforderinnen besiegt.', },
  },
  [13424] = {
    'Zurück in die Grube',
    {'Um auch weiterhin wirklich gut reiten zu können, werdet Ihr Euch jeden Tag gegen die Hyldnir beweisen müssen.|n|nBegebt Euch zurück zur Reißzahngrube und zeigt ihnen, wozu Ihr fähig seid. Sie werden dankbar sein, gegen jemanden zu verlieren, der so geschickt ist wie Ihr.', },
    {'Gretta die Schiedsfrau aus Brunnhildar möchte, dass Ihr in die Reißzahngrube geht und mit den Zügeln der Eisschlundmatriarchin 6 Kriegsbären des Hildarthings besiegt.', },
  },
  [13425] = {
    'Die Missgeburten müssen sterben',
    {'Euer Können unter Euresgleichen zu beweisen, ist nicht genug. Ihr müsst auch gegen unsere Feinde kämpfen, liebe Schwester.|n|nDie Valkyrionverräter verhöhnen weiterhin unsere edlen Drachenreittraditionen, indem sie verseuchte Protodrachen großziehen.|n|nKommt in den Besitz ihres Frostöls, das sie bei sich tragen, und benutzt es, um ihre widerwärtigen verseuchten Eier einzufrieren.', },
    {'Gretta die Schiedsfrau in Brunnhildar möchte, dass Ihr nach Valkyrion geht und Phiolen mit Frostöl von den Streiterinnen von Valkyrions besorgt. Nutzt die Phiolen dann, um 30 verseuchte Eier der Protodrachen zu zerstören.', },
  },
  [13426] = {
    'Der Zeuge Xarantaur',
    {'Scheint, als wären wir nicht die einzigen Besucher dieser Gegend. Ein Kurier hat eine Nachricht von einem Tauren namens Xarantaur weitergeleitet, der gemeint hat, er habe ein Taunkadorf namens Camp Tunka\'lo besucht. Der Zettel war zwar etwas kryptisch geschrieben, doch es scheint, als sei dieser Xarantaur in die Sturmgipfel gegangen, um der Geschichte einer Taunkalegende nachzugehen.|n|nTrefft Euch mit ihm, $N. Seht nach, ob das, was er weiß, uns in irgendeiner Art und Weise behilflich sein kann. Seiner Beschreibung nach befindet sich Camp Tunka\'lo weit gen Osten, jenseits der Terrasse der Schöpfer und nördlich von Dun Niffelem.', },
    {'Sprecht mit Xarantaur im Camp Tunka\'lo.', },
  },
  [13427] = {
    'Ruf zu den Waffen: Alteractal',
    nil,
    nil,
  },
  [13428] = {
    'Ruf zu den Waffen: Alteractal',
    {'Es scheint, als stünden wir kurz davor, die Sturmlanzeninvasoren aus dem Alteractal zu vertreiben. Momentan verlegen wir all unsere Verstärkungstruppen ins Tal, um die Frostwölfe in ihrem Kampf zu unterstützen.|n|nEin vollständiger Sieg im Alteractal würde uns genug Freiraum verschaffen, um mit den freigewordenen Truppen den Allianzabschaum auch an anderen Fronten zu schlagen.|n|nGeht nun, $N. Ehrt Euch selbst und folgt dem Schlachtruf der kühnen Frostwolfkrieger.', },
    {'Gewinnt eine Schlacht im Alteractal und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, Tausendwinter, in Dalaran oder Shattrath.', },
  },
  [13429] = {
    'Ein Ablenkungsmanöver für Akama',
    {'<Licht pulsiert um Xi\'ri herum während die Streitkräfte der Aldor und der Seher seine Befehle ausführen. Xi\'ris Armee ist bereit, Illidans Streitkräfte zurückzudrängen und Akama das nötige Ablenkungsmanöver zu verschaffen. Der Naaru wartet auf Eure Aufforderung den Angriff durchzuführen.>', },
    {'Stellt sicher, dass Akama und Maiev den Schwarzen Tempel betreten, nachdem Xi\'ris Streitkräfte ihr Ablenkungsmanöver durchgeführt haben.', },
  },
  [13430] = {
    'Die Prüfung der Naaru: Magtheridon',
    {'Ihr müsst vier Prüfungen bestehen, bevor Ihr von den Naaru als würdig genug erachtet werdet.|n|nEs bleibt nur noch eine übrig, $GSterblicher:Sterbliche;. Sammelt eine Armee und reist zu Magtheridons Kammer tief in der Höllenfeuerzitadelle. Kämpft Euch bis zur Mitte der Kammer durch und vernichtet diesen miesen Verderber!', },
    {'A\'dal in Shattrath möchte, dass Ihr Magtheridon vernichtet.', },
  },
  [13431] = {
    'Der Knüppel von Kar\'desh',
    {'Bringt mir die Elementarsiegel, die ich für den Knüppel brauche!|n|nDas Erdensiegel befindet sich im Besitz von Gruul dem Drachenschlächter. Ihr findet ihn in seinem Unterschlupf im Schergrat.|n|nDas zweite Siegel ist das flammende Herz einer Kreatur, die als Schrecken der Nacht bekannt ist. Diese mystische Kreatur soll sich angeblich in den geheiligten Hallen des Propheten Medivh aufhalten.|n|nBeeilt Euch!', },
    {'Nar\'biss der Ketzer in den heroischen Sklavenunterkünften des Echsenkessels möchte, dass Ihr ihm das Erdensiegel und das Flammensiegel bringt.', },
  },
  [13432] = {
    'Die Phiolen der Ewigkeit',
    {'Illidan entnahm sieben Phiolen aus dem Brunnen der Ewigkeit. Drei davon leerte er in den See auf dem Berg Hyjal, wodurch ein zweiter Brunnen der Ewigkeit entstand. Jahrelang glaubte man den Rest verloren.|n|nSeit der Öffnung des Dunklen Portals haben wir erfahren, dass er seinen Leutnants Kael\'thas und Vashj je eine Phiole gegeben hat. Holt zurück, was von den Phiolen noch übrig ist. Wir brauchen sie als Fokus, um ein Tor zu den Geschehnissen, seien sie aktuell oder vergangen, am Berg Hyjal zu öffnen. Das Ergebnis der Schlacht um den Berg Hyjal muss erhalten bleiben.', },
    {'Soridormi in den Höhlen der Zeit möchte, dass Ihr die Überreste von Vashjs Phiole im Echsenkessel und die Überreste von Kaels Phiole von Kael\'thas Sonnenwanderer in der Festung der Stürme besorgt.', },
  },
