  [13501] = {
    'Eimer mit Süßigkeiten',
    nil,
    nil,
  },
  [13502] = {
    'Einen Korb bekommen!',
    {'Hier... nehmt diesen Eierkorb und geht nach bunt gefärbten Eiern suchen. Kehrt zu mir zurück, sobald Ihr zehn Nobelgartenschokoladen gesammelt habt.', },
    {'Der Nobelgartenverkäufer möchte, dass Ihr 10 Nobelgartenschokoladen sammelt und ihm zusammen mit dem Eierkorb zurückbringt.', },
  },
  [13503] = {
    'Einen Korb bekommen!',
    {'Hier... nehmt diesen Eierkorb und geht nach bunt gefärbten Eiern suchen. Kehrt zu mir zurück, sobald Ihr zehn Nobelgartenschokoladen gesammelt habt.', },
    {'Der Nobelgartenhändler möchte, dass Ihr 10 Nobelgartenschokoladen sammelt und ihm zusammen mit dem Eierkorb zurückbringt.', },
  },
  [13524] = {
    'Flucht aus Silberwasser',
    {'Ihr... Ihr seid keiner von ihnen? Schnell! Lasst mich raus!|n|nWir müssen schleunigst zur Ammertannhütte! Wenn Leutnant Dumont erst einmal herausfindet, wer diese Leute wirklich sind, dann wird diese Stadt in Schutt und Asche gelegt werden!', },
    {'Öffnet den hölzernen Käfig und helft dem befreiten Späher der Allianz, aus Silberwasser zu entkommen. Meldet Euch bei Leutnant Dumont, sobald Ihr die Ammertannhütte erreicht habt.', },
  },
  [13538] = {
    'Sabotage aus dem Süden',
    {'Die drei Türme südlich des Tausendwinterflusses entziehen der Festung Energie!|n|nMacht den Schattenblickturm, den Flammenaugenturm oder den Wintersturzturm dem Erdboden gleich und erstattet mir dann Bericht. Denkt dran, nur Belagerungsmaschinen können einen Turm beschädigen, deshalb müsst Ihr sie gut vor der Horde beschützen!', },
    {'Zerstört den Schattenblickturm, den Flammenaugenturm oder den Wintersturzturm und kehrt zu Taktikoffizier Ahbramis in Tausendwinter zurück.', },
  },
  [13539] = {
    'Einstürzende Turmbauten',
    {'Während die Allianz gegen unsere Türen hämmert, schaut ein wahrer Taktiker über das Offensichtliche hinaus.|n|n"Greif ihn an, wo er unvorbereitet ist, erscheine, wo du nicht erwartest wirst."|n|n$N, überquert den Tausendwinterfluss und macht einen der drei Türme im Süden dem Erdboden gleich. Unsere Hexenmeister berichten, dass die Türme Energie abziehen, die wir benutzen könnten, um unsere eigenen Truppen zu stärken.|n|nKehrt zu mir zurück, sobald Ihr einen Turm zerstört habt.', },
    {'Zerstört den Schattenblickturm, den Flammenaugenturm oder den Wintersturzturm und kehrt zu Taktikoffizier Kilrath in Tausendwinter zurück.', },
  },
  [13548] = {
    'Eimer mit Süßigkeiten',
    nil,
    nil,
  },
  [13549] = {
    'Männchen oder Weibchen?',
    {'Ich bin daran interessiert, neben den Artefakten der Drakkari auch ein paar Tiere von Zul\'Drak mit mir zurück nach Zandalar zu bringen. Männchen der Frostleoparden und Eispfotenbären habe ich schon – ich brauche aber Weibchen!|n|nZu dumm, dass mein Fallensteller in einem überaus unglücklichen Unfall ums Leben kam. Wäret Ihr vielleicht dazu bereit, für ihn einzuspringen?|n|nSchläfert die Leoparden und Bären mit diesem Blasrohr ein und vergewissert Euch, dass es auch Weibchen sein werden, die Ihr dann zu mir zurückbringt, wenn Ihr so nett wärt. Finden könnt Ihr sie an den Altären von Rhunok, Quetz\'lun und Har\'koa.', },
    {'Chronist To\'kini in Zim\'Torga möchte, dass Ihr mit To\'kinis Blasrohr Frostleoparden und Eispfotenbären einschläfert. Kehrt mit jeweils 3 Weibchen zu ihm zurück.', },
  },
  [13556] = {
    'Eier für Dubra\'Jin',
    {'Wie geht\'s, Mann? Was meinst du, kannst du mir helfen? Bah\'Kini braucht \'ne Menge Raptoreier, um sie Dubra\'Jin zu opfern.|n|nWas denkst du denn, wieso uns die Drakkari noch nicht überrannt haben?! Ja weil Dubra\'Jin uns hilft!|n|nDu musst für uns die Raptoreier sammeln - die sind hier in Gundrak bei den Bäumen. Manchmal tragen die Raptoren sie auch rum, damit sie warm bleiben.', },
    {'Ha\'wana in Dubra\'Jin möchte, dass Ihr 12 Raptoreier von Gundrak sammelt.', },
  },
  [13559] = {
    'Hodirs Tribut',
    nil,
    nil,
  },
  [13571] = {
    'Fletchers Fundbüro',
    nil,
    nil,
  },
  [13592] = {
    'Feldübungen eines Recken',
    {'Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Neben der Verfeinerung Eurer Fertigkeiten solltet Ihr auch Eure Bissigkeit im Kampf gegen Euren Gegner schärfen.|n|nReist in die Gegend südwestlich des Tals der Gefallenen Helden und nördlich von Corp\'rethar. Die Geißel lässt dort tote Helden auferstehen und wiegelt sie gegen uns auf. Besiegt diese Diener der Geißel, macht unseren Verbündeten alle Ehre und haltet Euch bereit für den Kampf.', },
    {'Sir Marcus Barlow beim Argentumturnierplatz möchte, dass Ihr 10 konvertierte Helden tötet.', },
  },
  [13593] = {
    'Recke von Sturmwind',
    {'Seid willkommen, Champion. Ich habe schon von Euren Heldentaten gehört. Wollt Ihr der Turniersdelegation von Sturmwind beitreten?|n|nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch wenn man Euch zum Champion von Sturmwind ernannt hat, wird Euer Knappe die Möglichkeit haben, unser Banner in die Schlacht zu tragen.', },
    {'Sprecht wieder mit Marschall Jacob Alerius, falls Ihr ein Recke von Sturmwind werden wollt.', },
  },
  [13600] = {
    'Eine würdige Waffe',
    {'Ausgerechnet jetzt so ein Unglück!|n|nIch habe meine Turnierklinge verloren. Ich habe von Barden gehört, dass früher Reisende einer einsamen Maid Winterhyazinthen vorbeibrachten und dafür im Gegenzug etwas geschenkt bekamen. Diese Hyazinthen wachsen nur auf dem Eis, das vom Eisenwalldamm kommt, an der Nordwestgrenze des Kristallsangwalds zur Eiskrone. Pflückt ein paar der Blumen und bringt sie zum Kreis aus Laternen im Drak\'Marsee in der nordöstlichen Drachenöde, nahe der Grenze zu Zul\'Drak und den Grizzlyhügeln. Bittet die einsame Maid um eine würdige Klinge.', },
    {'Bringt Marschall Jacob Alerius beim Argentumturnierplatz die Klinge von Drak\'Mar.', },
  },
  [13603] = {
    'Eine Klinge, eines Champions würdig',
    {'Guter, ehrlicher, fein geschliffener Stahl mag nicht immer ausreichen, um den Sieg zu sichern. Die anderen Kämpfer benutzen verzauberte Klingen und ich bin nun ins Hintertreffen geraten - aber noch ist nicht alles verloren.|n|nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, $N. Ansonsten fangt Ihr Euch Warzen ein.', },
    {'Besorgt Eschenbrand und bringt es Marschall Jacob Alerius beim Argentumturnierplatz.', },
  },
  [13604] = {
    'Datenscheibe des Archivums',
    {'Diese Platinscheibe ist überraschend symmetrisch und frei von jedweden Kratzern und Unebenheiten. An ihrer Seite steht in auffallenden Runen eingeprägt das Wort "ARCHIVUM".|n|nIn Ulduar muss es eine Vorrichtung geben, mit welcher sich die Informationen auf der Scheibe lesen lassen.', },
    {'Bringt die Datenscheibe des Archivums zur Archivumkonsole in Ulduar.', },
  },
  [13606] = {
    'Freyas Siegel',
    {'Ich fürchte, Freyas Siegel zu erlangen, wird eine der schwierigeren Aufgaben sein.|n|nLaut dem Archivum ist die Essenz des Siegels mit ihren drei Dienern verbunden, den Ältesten Hellblatt, Eisenast und Steinrinde. Sollte einer der Ältesten zu Schaden kommen, ist die Unversehrtheit des Siegels gefährdet.|n|nDie Ältesten zu verschonen bedeutet jedoch, dass Freya mehr Macht haben wird, wenn Ihr Euch ihr stellen werdet.|n|nWas soll ich sagen, $N, das ist eine ganz schöne Zwickmühle, in der wir da stecken.', },
    {'Ausgrabungsleiter Doren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Freyas Siegel gelangt.|n|nUm mehr darüber herauszufinden, wie Ihr Freyas Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.', },
  },
  [13607] = {
    'Das Himmlische Planetarium',
    {'Hört mal, $GKumpel:Mädel;! Das Schicksal von Azeroth steht hier auf dem Spiel.|n|nUnsere einzige Chance ist es, rechtzeitig das Himmlische Planetarium zu erreichen, um diesen Algalon zu finden und ihn davon abzuhalten, irgendwelche Nachrichten an seine titanischen Herren abzusetzen.|n|nFindet das Himmlische Planetarium und beschafft so viele Informationen wie möglich. Uns könnte noch immer ein wenig Zeit bleiben, uns auf Algalons Ankunft vorzubereiten.', },
    {'Ausgrabungsleiter Doren im Archivum in Ulduar möchte, dass Ihr den Eingang zum Himmlischen Planetarium findet.', },
  },
  [13609] = {
    'Hodirs Siegel',
    {'Es wird nicht einfach sein, Hodirs Siegel zu beschaffen. Ihr müsst nämlich nicht nur Hodir selbst vernichten, sondern es auch noch tun, bevor er die Truhe zerstört, in der es sich befindet!|n|nSchaut Euch die Archivumkonsole an, falls Ihr weitere Informationen benötigt. Das Ding umfasst mehr Wissen als alle Bibliotheken der Welt zusammen!', },
    {'Ausgrabungsleiter Doren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Hodirs Siegel gelangt.|n|nUm mehr darüber herauszufinden, wie Ihr Hodirs Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.', },
  },
  [13610] = {
    'Thorims Siegel',
    {'Thorim ist nicht er selbst, $N. Er ist das Opfer einer dunklen Macht geworden, die ihn nun steuert.|n|nDas Opfer von etwas Bösem, das ihm die Illusion vorspielt, seine verstorbene Frau Sif zu sein.|n|nIhr dürft nicht zulassen, dass der Zauber dieses Betrügers ihn überwältigt. Denn sollte es so kommen, wird das Wissen um die Lage des Siegels für immer verloren sein!|n|nIhr müsst ihn zur Vernunft bringen und zwar schnell.|n|nWie immer wird Euch die Archivumkonsole mit allen schmutzigen Details versorgen... selbst mit denen, die Euch nicht gefallen.', },
    {'Ausgrabungsleiter Doren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Thorims Siegel gelangt.|n|nUm mehr darüber herauszufinden, wie Ihr Thorims Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.', },
  },
  [13611] = {
    'Mimirons Siegel',
    {'Mimiron ist ein ganz Schlauer. Sein gesamter Sitz ist mit einer Art Selbstzerstörungsmechanismus ausgestattet.|n|nUnglücklicherweise wird es ein Wettlauf gegen die Zeit werden, um sein Siegel zu bekommen. Befragt die Archivumkonsole, um Näheres darüber zu erfahren, falls nötig.', },
    {'Ausgrabungsleiter Doren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Mimirons Siegel gelangt.|n|nUm mehr darüber herauszufinden, wie Ihr Mimirons Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.', },
  },
  [13614] = {
    nil,
    {'Ihr habt es wirklich geschafft, $N. Bringt die Siegel zur Archivumkonsole und seht zu, ob Ihr Zugang zum Himmlischen Planetarium erhaltet.|n|nIhr beeilt Euch besser, $GKumpel:Mädchen;. Die Zeit drängt.', },
    {'Bringt die Siegel der Wächter zur Archivumkonsole in Ulduar.', },
  },
  [13616] = {
    'Auf Winters Schneide',
    {'Verflucht soll dieser Todesritter dafür sein, mein Schwert zerbrochen zu haben!|n|nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.|n|nBringt sie zur Mitte des Winterhauchsees im Norden des Heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.|n|nZeigt, was Ihr wert seid und verdient Euch die Waffe, die sie nun schon so lange bewacht, $N.', },
    {'Marschall Jacob Alerius beim Argentumturnierplatz möchte, dass Ihr ihm die Winterschneide beschafft.', },
  },
  [13622] = {
    'Uralte Geschichten',
    {'Die Stücke lassen sich zu einem eleganten Hammer zusammenfügen. Seine Bauweise erweckt den Eindruck, zumindest teilweise von titanischer Natur zu sein.|n|nWomöglich könnte man über die Konsole im Archivum mehr über dieses Artefakt erfahren.', },
    {'Bringt die zerschmetterten Fragmente von Val\'anyr zur Archivumkonsole im Archivum in Ulduar.', },
  },
  [13625] = {
    'Reitgrundlagen',
    {'Die meisten Wettkämpfe des Turniers verlangen von den Wettstreitern, dass sie den Kampf auf einem Reittier beherrschen. Um Euch mit dem berittenen Kampf vertraut zu machen, haben wir überall im nördlichen Teil des Turnierplatzes Trainingsattrappen aufgestellt.|n|nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und steigt auf das Streitross der Quel\'dorei. Macht Euch mit den verfügbaren Taktiken vertraut und besiegt anschließend die drei verschiedenen Arten von Trainingsattrappen.', },
    {'Trefft ein Nahkampfziel fünfmal mit der Fähigkeit "Zustoßen" und wendet die Fähigkeit "Schildbrecher" auf 2 ungeschützte Distanzziele sowie die Fähigkeit "Sturmangriff" auf 2 ungeschützte Sturmangriffsziele an. Kehrt anschließend zu Späherin Shalyndria beim Argentumturnierplatz zurück.|n|nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.', },
  },
  [13627] = {
    'Wie die Axt im Walde',
    {'Kommt näher. Nein, nicht zu nah. Wir wollen doch keinen Grund für unnötige Verdächtigungen geben, nicht wahr?|n|nDiese Turnierhalle benötigt mehr Holz, als wir auf Lager haben, und die Kosten für einen Ferntransport von den Grizzlyhügeln werde ich auf keinen Fall zahlen. Im Westen des Kristallsangwaldes, in der Nähe des Großen Baumes, wachsen etliche junge Kristallsangeichen. Das wäre genau das Holz, das wir zum Bauen und als Gerüstmaterial bräuchten. Nehmt dieses Beil, schlagt einige Bäume und haut daraus ein paar Hölzer. Aber lasst Euch dabei bloß nicht erwischen!', },
    {'Bringt 12 grob gehauene Bauhölzer zu Stumpi Sprengbolz beim Argentumturnierplatz.', },
  },
  [13629] = {
    'Val\'anyr, Hammer der Uralten Könige',
    {'Die Archivumkonsole hat eine Möglichkeit angedeutet, wie die Fragmente von Val\'anyr wieder zusammengefügt werden können: Ihr müsst die Fragmente ins Innere der körperlichen Form des Wesens namens Yogg-Saron bekommen.|n|nEs mag vielleicht aussichtslos klingen, doch Ihr denkt, dass ein Artefakt von solcher Macht das Risiko wert sein könnte.', },
    {'Werft die zerschmetterten Teile von Val\'anyr in Yogg-Sarons Schlund, während er den Zauber \'Ohrenbetäubendes Gebrüll\' wirkt, und vernichtet ihn, um den neugeschmiedeten Hammer der Uralten Könige zu erhalten.|n|nDies kann nur auf dem Schwierigkeitsgrad "Heroisch" beendet werden und nur dann, wenn Ihr von maximal drei Wächtern von Ulduar unterstützt werdet.', },
  },
  [13631] = {
    'Ende gut, alles gut',
    {'Wir sollten uns jetzt besser beeilen, $N. Wir müssen den Antwortcode von Dalaran aus übermitteln.|n|nBringt ihn zu Rhonin. Ich treffe Euch dort.', },
    {'Überbringt Rhonin in Dalaran den Antwortcode Alpha.', },
  },
  [13633] = {
    'Der schwarze Ritter von Westfall?',
    {'Zweifellos habt Ihr bereits die beunruhigenden Gerüchte gehört, die einen Teilnehmer betreffen, der der schwarze Ritter genannt wird. Es heißt, dass jeder Reiter, der sich ihm im Kampf stellen musste, ein vorzeitiges Ende gefunden hätte.|n|nNatürlich haben wir nichts in der Hand, aber es kann ja nicht schaden, sich den Hintergrund dieses Ritters mal näher anzusehen.|n|nEr behauptet, der Cooperfamilie in Westfall zu entstammen. Würdet Ihr Euch aufmachen und den Wohnsitz der Familie in Mondbruch in Westfall aufsuchen? Vielleicht lässt sich dort ein Beweis für seine Geschichte finden.', },
    {'Überprüft die Angaben des Schwarzen Ritters und kehrt mit den Informationen zu Kreuzfahrerin Rhydalla beim Argentumturnierplatz zurück.', },
  },
  [13634] = {
    'Der schwarze Ritter von Silberwald?',
    {'Zweifellos habt Ihr bereits die beunruhigenden Gerüchte gehört, die einen Teilnehmer betreffen, der der schwarze Ritter genannt wird. Es heißt, dass jeder Reiter, der sich ihm im Kampf stellen musste, ein vorzeitiges Ende gefunden hätte.|n|nNatürlich haben wir nichts in der Hand, aber es kann ja nicht schaden, sich den Hintergrund dieses Ritters mal näher anzusehen.|n|nEr behauptet, aus Valgans Feld im Silberwald zu stammen, einem kleinen Gehöft an der westlichen Küste des Lordameresees. Könntet Ihr dem Hof einen Besuch abstatten und mich wissen lassen, ob seine Geschichte der Wahrheit entspricht?', },
    {'Überprüft die Angaben des Schwarzen Ritters und kehrt mit den Informationen zu Kreuzfahrerin Rhydalla beim Argentumturnierplatz zurück.', },
  },
  [13641] = {
    'Der Seherkristall',
    {'Jetzt, da wir wissen, dass der Schwarze Ritter nicht die Wahrheit spricht, müssen wir einen Weg finden, seine Verbindung zu den toten Rittern nachzuweisen.|n|nIch kenne einen Weg um die Wahrheit über ihren Tod aufzudecken, doch er benötigt ein seltenes Material. Wir müssen einen Seherkristall auftreiben, der nur bei den unbändigen Sehern gefunden werden kann, die sich in der Nähe der Nachtelfenruinen in den Trostlosen Wäldern im Zentrum des Kristallsangwaldes versammeln. Findet einen dieser Seher, $N, und bringt mir die Kristalle, die er bei sich trägt.', },
    {'Bringt einen Seherkristall zu Kreuzfahrerin Rhydalla beim Argentumturnierplatz.', },
  },
  [13643] = {
    'Die Geschichten toter Männer',
    {'Die Kristalle werden die Wahrheit darüber ans Tageslicht bringen, wie drei der Turnierteilnehmer gestorben sind. Bringt ihn zum Friedhof östlich des Turnierplatzes und benutzt ihn bei den Gräbern von Sir Wendell Balfour, Lorien Sonnenfeuer und Conall Eisengriff.|n|nWenn diese Männer wirklich ermordet worden sind, dann müssen wir einen Weg finden, eine Verbindung zum Schwarzen Ritter herzustellen, bevor er wieder zuschlägt. Beobachtet genau, was der Kristall Euch zu sagen hat, $N, denn wir müssen sicher sein, dass diese Todesfälle keine Zufälle gewesen sind.', },
    {'Benutzt den Seherkristall an den Gräbern von Sir Wendell Balfour, Lorien Sonnenfeuer und Conall Eisengriff, um herauszufinden, wie sie gestorben sind, und kehrt anschließend zu Kreuzfahrerin Rhydalla zurück.', },
  },
  [13649] = {
    'Justins spaßiger Test',
    {'He da! Ihr seht aus, als könntet Ihr gut mit Bier umgehen. Doch wie gut könnt Ihr mit Eurem Trinkkrug umgehen? |n|nDie Dunkeleisenzwerge sind zurückgekommen, um unsere Feier zu ruinieren, und das nicht zu wenig. Sie mit Krügen zu bewerfen ist die beste Möglichkeit, sie aufzuhalten. Doch erst einmal wollen wir schauen, ob Ihr einen auf die alte A.L.K. hier werfen könnt.|n|nEs ist ganz leicht, nehmt einen Freibierkrug und trinkt. Geht dabei nur sicher, dass Ihr A.L.K. anseht. Sprecht mich wieder an, wenn Ihr sie fünfmal getroffen habt.', },
    {'Benutzt den Freibierkrug, um A.L.K. fünfmal zu treffen, und sprecht dann mit Boxey Bolzdreher.', },
  },
  [13654] = {
    'Etwas ist mit dem Knappen',
    {'Jeden Tag macht der Knappe des Schwarzen Ritters Maloric eine große Sache daraus, wie er mit der Axt auf seiner Schulter in Richtung Kristallsangwald aufbricht. Er will uns weismachen, er hacke Holz, nur kehrt er niemals mit mehr als nur ein paar Zweigen zurück.|n|nNormalerweise geht er in Richtung Ruinen südwestlich des Zwielichtspiegels. Er verbringt viel Zeit dort draußen, selbst für einen Knappen, der seinem Ritter gegenüber Pflichten hat.|n|nFindet einen Weg, ihn entweder abzulenken oder außer Gefecht zu setzen, und durchsucht ihn. Sollte er etwas im Schilde führen, dann werden wir es wissen.', },
    {'Beschafft einen großen Oberschenkelknochen eines skelettierten Holzfällers und setzt damit Maloric außer Gefecht. Durchsucht ihn nach Beweisen und meldet Euch anschließend bei Kreuzfahrerin Rhydalla beim Argentumturnierplatz.', },
  },
  [13662] = {
    'Anerkennung erlangen',
    nil,
    nil,
  },
  [13663] = {
    'Die Befehle des Schwarzen Ritters',
    {'Wir müssen herausfinden, wer den Schwarzen Ritter zum Turnier geschickt hat und was sich sein Meister daraus erhofft, die Konkurrenz zu töten.|n|nDie Kirin Tor haben in dieser Angelegenheit ihre Unterstützung angeboten und uns ein Werkzeug zur Verfügung gestellt, dass uns in unserer Suche helfen wird.|n|nBringt dieses verzauberte Zaumzeug zum Lager des Schwarzen Ritters am östlichen Rand des Turniergeländes und benutzt es, um Kontrolle über den Greifen des Schwarzen Ritters zu erhalten. Die Verzauberung des Zaumzeugs wird das Tier zwingen, Euch zum Wohnort seines Meisters zu bringen. Durchsucht ihn und bringt alles zurück, was Ihr finden könnt.', },
    {'Erhaltet mithilfe des verzauberten Zaumzeugs Kontrolle über den Greifen des Schwarzen Ritters und reitet auf seinem Rücken zum Zielort. Beschafft Euch die gestohlene Einladung zum Turnier und die Befehle des Schwarzen Ritters, sobald Ihr dort angekommen seid, und bringt sie zurück zu Kreuzfahrerin Rhydalla beim Argentumturnierplatz.', },
  },
  [13664] = {
    'Der Sturz des Schwarzen Ritters',
    {'Wir müssen den finsteren Plänen des Schwarzen Ritters ein Ende setzen und unseren Widersachern zeigen, dass wir nicht untätig daneben stehen und zusehen, wie unsere Champions ermordet werden.|n|nEr wird mittlerweile annehmen, dass ihm jemand auf den Fersen ist. Fordert ihn am helllichten Tage zum Kampf heraus, $N - wenn er nicht ablehnen oder jemanden im Dunklen ermorden kann.|n|nNehmt mein Argentumstreitross für den Kampf. Es steht in den Stallungen, in der Nähe des Argentumpavillons.|n|nSprecht dann mit Knappe Cavin im Ring der Champions. Der Knappe wird den Schwarzen Ritter zum Kampf rufen und Ihr werdet ihn für seine Taten büßen lassen.', },
    {'Besiegt den Schwarzen Ritter und sprecht anschließend mit Kreuzfahrerin Rhydalla beim Argentumturnierplatz.', },
  },
  [13665] = {
    'Der große Arenakampf',
    {'Der große Arenakampf ist der wichtigste Wettkampf des Turniers. Die Bürger von Sturmwind lieben ihre Ritter über alles und freuen sich darauf, uns gewinnen zu sehen. Damit das auch geschieht, haben wir im Kampf gegen die Recken der anderen Allianzhauptstädte an unseren Fähigkeiten gefeilt.|n|nIch schlage vor, dass Ihr es ihnen gleichtut.|n|nGeht zu den Reittieren außerhalb des Pavillons, nehmt Eure Lanze, steigt auf das Streitross aus Sturmwind, das dort steht, und fordert die Recken heraus. Sie warten im Ring der Recken der Allianz gleich außerhalb unseres Zelts.', },
    {'Bringt 3 Male des Recken zu Hauptmann Joseph Holley beim Argentumturnierplatz.|n|nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.', },
  },
  [13666] = {
    'Eine Klinge, eines Champions würdig',
    {'Einige der Champions glauben, dass eine uralte Waffe aus Nordend ihnen auf dem Turnier Glück bringen wird. Nun habe ich meine Zustimmung gegeben, ihnen bei der Suche nach diesen Waffen zu helfen.|n|nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, $N. Ansonsten fangt Ihr Euch Warzen ein.', },
    {'Besorgt Eschenbrand und bringt es Arkanist Taelis beim Argentumturnierplatz.', },
  },
  [13667] = {
    'Das Argentumturnier',
    {'Wir haben Euch hierher eingeladen, damit Ihr Euer Können und Euren Wagemut mit anderen messt, die sich der Geißel tapfer widersetzt haben. Wir hatten viele Meinungsverschiedenheiten, doch nun ist die Zeit gekommen, dass sich Helden aller Lager im Schwertkampf gegenseitig auf die Probe stellen, um sich auf die Begegnung mit unserem gemeinsamen Feind vorzubereiten.|n|nArkanist Taelis ist der Repräsentant des Silberbunds in diesem Turnier. Er wird Euch in die Schriftrollen eintragen und Euer Training beginnen lassen. Ihr findet ihn im großen Zelt der Allianz im nordöstlichen Teil des Geländes.', },
    {'Sprecht mit Arkanist Taelis beim Argentumturnierplatz, um Euch für das Turnier anzumelden.', },
  },
  [13668] = {
    'Das Argentumturnier',
    {'Wir haben Euch hierher eingeladen, damit Ihr Euer Können und Euren Wagemut mit anderen messt, die sich der Geißel tapfer widersetzt haben. Wir hatten viele Meinungsverschiedenheiten, doch nun ist die Zeit gekommen, dass sich Helden aller Lager im Schwertkampf gegenseitig auf die Probe stellen, um sich auf die Begegnung mit unserem gemeinsamen Feind vorzubereiten.|n|nMagister Edien Sonnental ist der Repräsentant der Sonnenhäscher in diesem Turnier. Er wird Euch in die Schriftrollen eintragen und Euer Training beginnen lassen. Ihr findet ihn im großen Zelt der Horde im südöstlichen Teil des Geländes.', },
    {'Sprecht mit Magister Edien Sonnental beim Argentumturnierplatz, um Euch für das Turnier anzumelden.', },
  },
  [13669] = {
    'Eine würdige Waffe',
    {'Unsere Champions haben Gefallen an uralten Waffen gefunden, die hier in Nordend hergestellt werden.|n|nDie Barden erzählen Geschichten von Reisenden, die einer einsamen Maid Winterhyazinthen anbieten und dafür Geschenke bekommen. Diese Hyazinthen wachsen nur auf dem Eis, das vom Eisenwalldamm kommt, an der Nordwestgrenze des Kristallsangwalds zur Eiskrone. Sammelt die Blumen und bringt sie zum Lampenkreis auf dem Drak\'Marsee im Nordosten der Drachenöde in der Nähe von Zul\'Drak und den Grizzlyhügeln. Bittet die einsame Maid um eine würdige Klinge.', },
    {'Bringt die Klinge von Drak\'Mar zu Arkanist Taelis beim Argentumturnierplatz.', },
  },
  [13670] = {
    'Auf Winters Schneide',
    {'Der Knappe des Großchampions von Eisenschmiede hat mir eine interessante Geschichte erzählt.|n|nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.|n|nBringt sie zur Mitte des Winterhauchsees im Norden des Heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.|n|nZeigt, was Ihr wert seid und verdient Euch die Waffe, die sie nun schon so lange bewacht, $N.', },
    {'Arkanist Taelis beim Argentumturnierplatz möchte, dass Ihr ihm Winterschneide bringt.', },
  },
  [13671] = {
    'Feldübung',
    {'Das Turnier ist eine Gelegenheit, Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Vergesst nicht, auf Eurem Weg zur Beherrschung des berittenen Kampfes auch die Fähigkeiten zu trainieren, die Euch all die Jahre über gut gedient haben. Zeigt uns, dass Ihr der Geißel mit Ehre und Tapferkeit begegnen könnt, und Ihr werdet Euch das Recht verdienen, auf diesem Turnier anzutreten.|n|nReist nach Eiskrone und tötet jeden Diener der Geißel, den Ihr dort seht.', },
    {'Avareth Flinkstoß beim Argentumturnierplatz möchte, dass Ihr 8 Diener der Geißel von Eiskrone tötet. Dazu zählen alle Diener der Geißel im Bereich von Eiskrone, abgesehen vom Bombardement.', },
  },
  [13672] = {
    'Der Herausforderung gewachsen',
    {'Wenn Ihr die Fähigkeiten des Streiters gemeistert habt, könnt Ihr Euch dazu entscheiden, die Herausforderung des Streiters anzunehmen. Sie wird Euer Können im berittenen Kampf auf die Probe stellen und messen, ob Ihr bereit seid, ein Recke zu werden oder nicht. Solltet Ihr bestehen, werdet Ihr der Delegation Eurer Hauptstadt als Recke beitreten können.|n|nKehrt wieder zu mir zurück, wenn Ihr bereit seid, die Herausforderung anzutreten.', },
    {'Überreicht Arkanist Taelis beim Argentumturnierplatz 15 Siegel des Streiters, um zu zeigen, dass Ihr bereit seid, Euch der Herausforderung des Streiter zu unterziehen.', },
  },
  [13673] = {
    'Eine Klinge, eines Champions würdig',
    {'Einige der Champions glauben, dass eine uralte Waffe aus Nordend ihnen auf dem Turnier Glück bringen wird. Nun habe ich meine Zustimmung gegeben, ihnen bei der Suche nach diesen Waffen zu helfen.|n|nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, $N. Ansonsten fangt Ihr Euch Warzen ein.', },
    {'Besorgt Eschenbrand und bringt es Magister Edien Sonnental beim Argentumturnierplatz.', },
  },
  [13674] = {
    'Eine würdige Waffe',
    {'Unsere Champions haben Gefallen an uralten Waffen gefunden, die hier in Nordend hergestellt werden.|n|nDie Barden erzählen Geschichten von Reisenden, die einer einsamen Maid Winterhyazinthen anbieten und dafür Geschenke bekommen. Diese Hyazinthen wachsen nur auf dem Eis, das vom Eisenwalldamm kommt, an der Nordwestgrenze des Kristallsangwalds zur Eiskrone. Sammelt die Blumen und bringt sie zum Lampenkreis auf dem Drak\'Marsee im Nordosten der Drachenöde in der Nähe von Zul\'Drak und den Grizzlyhügeln. Bittet die einsame Maid um eine würdige Klinge.', },
    {'Bringt die Klinge von Drak\'Mar zu Magister Edien Sonnental beim Argentumturnierplatz.', },
  },
  [13675] = {
    'Auf Winters Schneide',
    {'Einer der Recken von Orgrimmar hat mir eine interessante Geschichte erzählt.|n|nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.|n|nBringt sie zur Mitte des Winterhauchsees im Norden des Heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.|n|nZeigt, was Ihr wert seid und verdient Euch die Waffe, die sie nun schon so lange bewacht, $N.', },
    {'Magister Edien Sonnental beim Argentumturnierplatz möchte, dass Ihr ihm Winterschneide bringt.', },
  },
  [13676] = {
    'Feldübung',
    {'Das Turnier ist eine Gelegenheit, Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Vergesst nicht, auf Eurem Weg zur Beherrschung des berittenen Kampfes auch die Fähigkeiten zu trainieren, die Euch all die Jahre über gut gedient haben. Zeigt uns, dass Ihr der Geißel mit Ehre und Tapferkeit begegnen könnt, und Ihr werdet Euch das Recht verdienen, auf diesem Turnier anzutreten.|n|nReist nach Eiskrone und tötet jeden Diener der Geißel, den Ihr dort seht.', },
    {'Amariel Sonnenschwur beim Argentumturnierplatz möchte, dass Ihr 8 Diener der Geißel von Eiskrone tötet. Dazu zählen alle Diener der Geißel im Bereich von Eiskrone, abgesehen vom Bombardement.', },
  },
  [13677] = {
    'Reitgrundlagen',
    nil,
    {'Trefft ein Nahkampfziel fünfmal mit der Fähigkeit \'Zustoßen\' und wendet die Fähigkeit \'Schildbrecher\' auf 2 ungeschützte Distanzziele sowie die Fähigkeit \'Sturmangriff\' auf 2 ungeschützte Sturmangriffsziele an. Kehrt anschließend zu Galathia Morgenglanz beim Argentumturnierplatz zurück.|n|nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.', },
  },
  [13678] = {
    'Der Herausforderung gewachsen',
    {'Wenn Ihr die Fähigkeiten des Streiters gemeistert habt, könnt Ihr Euch dazu entscheiden, die Herausforderung des Streiters anzunehmen. Sie wird Euer Können im berittenen Kampf auf die Probe stellen und messen, ob Ihr bereit seid, ein Recke zu werden oder nicht. Solltet Ihr bestehen, werdet Ihr der Delegation Eurer Hauptstadt als Recke beitreten können.|n|nKehrt wieder zu mir zurück, wenn Ihr bereit seid, die Herausforderung anzutreten.', },
    {'Überreicht Magister Edien Sonnental beim Argentumturnierplatz 15 Siegel des Streiters, um zu zeigen, dass Ihr bereit seid, Euch der Herausforderung des Streiters zu unterziehen.', },
  },
  [13679] = {
    'Die Herausforderung des Streiters',
    {'Ihr habt hart trainiert, $GStreiter:Streiters; $N, und nun ist die Zeit gekommen, Euer Können im berittenen Kampf gegen einen geschickten Gegner auf die Probe zu stellen.|n|nNehmt Eure Lanze, geht dann zu den angebundenen Reittieren außerhalb des Pavillons und steigt auf das Streitross der Quel\'dorei, das dort untergebracht ist.|n|nIm Ring der Streiter auf der nördlichen Seite des Turnierplatzes werdet Ihr Knappe David vorfinden. Er wird sich vergewissern, dass Ihr bereit seid zu kämpfen, und Euren Widersacher herbeirufen.|n|nViel Glück, $N. Möget Ihr stets sicher im Sattel sitzen und Eure Pfeile ins Schwarze treffen.', },
    {'Sprecht mit Knappe David und ruft Euren Widersacher herbei. Kehrt zu Arkanist Taelist beim Argentumturnierplatz zurück, sobald Ihr den Argentumrecken besiegt habt.|n|nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.', },
  },
  [13680] = {
    'Die Herausforderung des Streiters',
    {'Ihr habt hart trainiert, $GStreiter:Streiterin; $N, und nun ist die Zeit gekommen, Euer Können im berittenen Kampf gegen einen erfahrenen Gegner auf die Probe zu stellen.|n|nNehmt Eure Lanze, geht dann zu den angebundenen Reittieren außerhalb des Pavillons und steigt auf den Falkenschreiter der Sonnenhäscher.|n|nIm Ring der Streiter auf der nördlichen Seite des Turnierplatzes werdet Ihr ein Menschenkind, einen Knappen namens David, vorfinden. Er wird sich vergewissern, dass Ihr bereit seid zu kämpfen, und Euren Widersacher herbeirufen.|n|nViel Glück, $N. Möget Ihr sicher im Sattel sitzen und Euer Pferd gleichmäßig reiten.', },
    {'Sprecht mit Knappe David und ruft Euren Widersacher herbei. Kehrt zu Magister Edien Sonnental beim Argentumturnierplatz zurück, sobald Ihr den Argentumrecken besiegt habt.', },
  },
  [13681] = {
    'Wie der Block so der Splitter',
    {'Stein für diesen Job zu besorgen war der reinste Alptraum, das kann ich Euch sagen! Es gibt in den Ruinen sichere Orte, an denen es tonnenweise Stein zu finden gibt, doch diese selbstgerechten Paladine wollen einfach nicht zugreifen. Hat was mit unbezahlbaren Artefakten zu tun, oder so was.|n|nWie dem auch sei: Darüber zu jammern wird auch nicht helfen, diesen Ort aufzubauen. In den Fußmarschen und der Bibliothek des Erfinders in den Sturmgipfeln gibt es eine ganze Reihe Titanenruinen. Nehmt meinen, ähm, \'Meißel\' mit und seht, ob Ihr diese riesigen Blöcke nicht in brauchbare Stücke zerhauen könnt.', },
    {'Bringt 15 kleine Steinblöcke zu Stümpi Sprengbolz beim Argentumturnierplatz.', },
  },
  [13682] = {
    'Bedrohung von oben',
    {'Hochlord Tirion Fordring hat die Wachen verdoppelt, seitdem Ihr den Spitzel des Kults der Verdammten entlarvt habt. Seiner Meinung nach werden sie nicht aufhören, nur weil ihr Schwarzer Ritter besiegt wurde.|n|nUnsere Späher der Himmelsklauen haben davon berichtet, einen Frostwyrm namens Frostschlund gesichtet zu haben, der einen Stoßtrupp des Kults anführen soll. Wenn wir sie nicht abfangen, werden sie das Turnier angreifen. Laut den Berichten der Späher fliegt Frostschlund gen Südwesten und patrouilliert das Gebiet zwischen dem Eisenwallbollwerk und Aldur\'thar.', },
    {'Eadric der Reine beim Argentumturnierplatz möchte, dass Ihr Frostschlund und 3 Kultistenbombenschützen besiegt.', },
  },
  [13684] = {
    'Ein Recke von Sturmwind',
    {'Ihr habt Euch als würdig erwiesen, unter dem Banner von Sturmwind anzutreten, $N. Nun solltet Ihr mit Marschall Jacob Alerius sprechen, der Sturmwinds Wettkämpfer anführt. Als Großchampion von Sturmwind wird er Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.|n|nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, $N, und ich wünsche Euch Glück im bevorstehenden Wettkampf.', },
    {'Sprecht mit Marschall Jacob Alerius beim Argentumturnierplatz, um ein Recke von Sturmwind zu werden.', },
  },
  [13685] = {
    'Ein Recke von Eisenschmiede',
    {'Ihr habt Euch als würdig erwiesen, unter dem Banner von Eisenschmiede anzutreten, $N. Nun solltet Ihr mit Lana Starkhammer sprechen, die die Wettkämpfer von Eisenschmiede anführt. Als Großchampion der Stadt wird sie Euch in ihrem Namen für das Turnier anmelden. Außerdem wird sie Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.|n|nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, $N, und ich wünsche Euch Glück im bevorstehenden Wettkampf.', },
    {'Sprecht mit Lana Starkhammer beim Argentumturnierplatz, um ein Recke von Eisenschmiede zu werden.', },
  },
