  [13718] = {
    'Das Wappen des Recken',
    {'In Eurer Ausbildung zum Recken habt Ihr die Möglichkeit, Euer Können gegen Recken der anderen Städte auf die Probe zu stellen. Obwohl diese Kämpfe nicht zum formalen Teil des Wettkampfes gehören, werdet Ihr wertvolle Lektionen in Sachen Kampfstil erhalten und Schwächen Eurer Widersacher entdecken.|n|nRecken sind ein beherzter Haufen - sie konkurrieren untereinander um Ehre und Ruf.|n|nFührt Eure Ausbildung so lange fort, bis Ihr von Eurem Können überzeugt seid und all Eure Gegner schlagen könnt, um mir dann die Siegel zu bringen, die Ihr errungen habt.', },
    {'Bringt 25 Siegel des Recken zu Marschall Jacob Alerius beim Argentumturnierplatz.', },
  },
  [13719] = {
    'Das Wappen des Recken',
    {'In Eurer Ausbildung zum Recken habt Ihr die Möglichkeit, Euer Können gegen Recken der anderen Städte auf die Probe zu stellen. Obwohl diese Kämpfe nicht zum formalen Teil des Wettkampfes gehören, werdet Ihr wertvolle Lektionen in Sachen Kampfstil erhalten und Schwächen Eurer Widersacher entdecken.|n|nRecken sind ein beherzter Haufen - sie konkurrieren untereinander um Ehre und Ruf.|n|nFührt Eure Ausbildung so lange fort, bis Ihr von Eurem Können überzeugt seid und all Eure Gegner schlagen könnt, um mir dann die Siegel zu bringen, die Ihr errungen habt.', },
    {'Bringt 25 Siegel des Recken zu Zul\'tore beim Argentumturnierplatz.', },
  },
  [13720] = {
    'Das Wappen des Recken',
    {'In Eurer Ausbildung zum Recken habt Ihr die Möglichkeit, Euer Können gegen Recken der anderen Städte auf die Probe zu stellen. Obwohl diese Kämpfe nicht zum formalen Teil des Wettkampfes gehören, werdet Ihr wertvolle Lektionen in Sachen Kampfstil erhalten und Schwächen Eurer Widersacher entdecken.|n|nRecken sind ein beherzter Haufen - sie konkurrieren untereinander um Ehre und Ruf.|n|nFührt Eure Ausbildung so lange fort, bis Ihr von Eurem Können überzeugt seid und all Eure Gegner schlagen könnt, um mir dann die Siegel zu bringen, die Ihr errungen habt.', },
    {'Bringt 25 Siegel des Recken zu Runok Wildmähne beim Argentumturnierplatz.', },
  },
  [13721] = {
    'Das Wappen des Recken',
    {'In Eurer Ausbildung zum Recken habt Ihr die Möglichkeit, Euer Können gegen Recken der anderen Städte auf die Probe zu stellen. Obwohl diese Kämpfe nicht zum formalen Teil des Wettkampfes gehören, werdet Ihr wertvolle Lektionen in Sachen Kampfstil erhalten und Schwächen Eurer Widersacher entdecken.|n|nRecken sind ein beherzter Haufen - sie konkurrieren untereinander um Ehre und Ruf.|n|nFührt Eure Ausbildung so lange fort, bis Ihr von Eurem Können überzeugt seid und all Eure Gegner schlagen könnt, um mir dann die Siegel zu bringen, die Ihr errungen habt.', },
    {'Bringt 25 Siegel des Recken zu Todespirscher Visceri beim Argentumturnierplatz.', },
  },
  [13722] = {
    'Das Wappen des Recken',
    {'In Eurer Ausbildung zum Recken habt Ihr die Möglichkeit, Euer Können gegen Recken der anderen Städte auf die Probe zu stellen. Obwohl diese Kämpfe nicht zum formalen Teil des Wettkampfes gehören, werdet Ihr wertvolle Lektionen in Sachen Kampfstil erhalten und Schwächen Eurer Widersacher entdecken.|n|nRecken sind ein beherzter Haufen - sie konkurrieren untereinander um Ehre und Ruf.|n|nFührt Eure Ausbildung so lange fort, bis Ihr von Eurem Können überzeugt seid und all Eure Gegner schlagen könnt, um mir dann die Siegel zu bringen, die Ihr errungen habt.', },
    {'Bringt 25 Siegel des Recken zu Eressea Morgensänger beim Argentumturnierplatz.', },
  },
  [13723] = {
    'Die Herausforderung des Recken',
    {'Ihr seid fast bereit, im Namen Gnomeregans beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr würdig seid, im Namen unserer Stadt in die Listen aufgenommen zu werden, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.|n|nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Übungsring der Recken am westlichen Rand des Platzes. Er wird dann Euren Gegner herbeirufen, sobald Ihr bereit seid.|n|nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.', },
    {'Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Ambrose Bolzenfunk beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.|n|nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.', },
  },
  [13724] = {
    'Die Herausforderung des Recken',
    {'Ihr seid fast bereit, im Namen der Exodar beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr würdig seid, im Namen unserer Stadt in die Listen aufgenommen zu werden, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.|n|nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Ring der Recken des Argentumkreuzzugs. Er wird dann Euren Gegner herbeirufen, sobald Ihr bereit seid.|n|nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.', },
    {'Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Kolosos beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.|n|nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.', },
  },
  [13725] = {
    'Die Herausforderung des Recken',
    {'Ihr seid fast bereit, im Namen Darnassus beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr würdig seid, im Namen unserer Stadt in die Listen aufgenommen zu werden, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.|n|nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Übungsring der Recken am westlichen Rand des Platzes. Er wird Euren Gegner herbeirufen, sobald Ihr bereit seid.|n|nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.', },
    {'Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Jaelyne Abendlied beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.|n|nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.', },
