  [13778] = {
    'Eine Klinge, eines Champions würdig',
    {'Ich habe gehört, dass die Champions der Allianz auf der Suche nach uralten Klingen für ihre Krieger sind. Wir können es uns nicht leisten, ihnen solch einen Vorteil zu überlassen.|n|nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, $N. Ansonsten fangt Ihr Euch Warzen ein.', },
    {'Besorgt Eschenbrand und bringt es Todespirscher Visceri beim Argentumturnierplatz.', },
  },
  [13779] = {
    'Eine würdige Waffe',
    {'Ausgerechnet jetzt so ein Unglück!|n|nIch habe meine Turnierklinge verloren. Ich habe von Barden gehört, dass früher Reisende einer einsamen Maid Winterhyazinthen vorbeibrachten und dafür im Gegenzug etwas geschenkt bekamen. Diese Hyazinthen wachsen nur auf dem Eis, das vom Eisenwalldamm kommt, an der Nordwestgrenze des Kristallsangwalds zur Eiskrone. Pflückt ein paar der Blumen und bringt sie zum Kreis aus Laternen im Drak\'Marsee in der nordöstlichen Drachenöde, nahe der Grenze zu Zul\'Drak und den Grizzlyhügeln. Bittet die einsame Maid um eine würdige Klinge.', },
    {'Bringt Todespirscher Visceri beim Argentumturnierplatz die Klinge von Drak\'Mar.', },
  },
  [13780] = {
    'Auf Winters Schneide',
    {'Verflucht soll dieser Todesritter dafür sein, mein Schwert zerbrochen zu haben!|n|nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.|n|nBringt sie zur Mitte des Winterhauchsees im Norden des Heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.|n|nZeigt, was Ihr wert seid und verdient Euch die Waffe, die sie nun schon so lange bewacht, $N.', },
    {'Todespirscher Visceri beim Argentumturnierplatz möchte, dass Ihr ihm Winterschneide bringt.', },
  },
  [13781] = {
    'Feldübungen eines Recken',
    {'Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Neben der Verfeinerung Eurer Fertigkeiten solltet Ihr auch Eure Bissigkeit im Kampf gegen Euren Gegner schärfen.|n|nReist in die Gegend südwestlich des Tals der Gefallenen Helden und nördlich von Corp\'rethar. Die Geißel lässt dort tote Helden auferstehen und wiegelt sie gegen uns auf. Besiegt diese Diener der Geißel, macht unseren Verbündeten alle Ehre und haltet Euch bereit für den Kampf.', },
    {'Sarah Chalke beim Argentumturnierplatz möchte, dass Ihr 10 konvertierte Helden tötet.', },
  },
  [13782] = {
    'Der große Arenakampf',
    {'Der große Arenakampf ist der wichtigste Wettkampf des Turniers. Der Sieg wird nicht leicht zu erringen sein, doch ich bin überzeugt, dass wir gewinnen werden. Ihr müsst so lange mit Eurem Reittier trainieren, bis Ihr eins mit ihm seid.|n|nEs wird helfen, Euch auf die Härte des Kampfes vorzubereiten.|n|nGeht zu den Reittieren außerhalb des Pavillon, nehmt Eure Lanze, steigt auf das Schlachtross der Verlassenen, das dort steht, und fordert die Recken heraus. Sie warten im Ring der Recken der Horde gleich außerhalb unseres Zelts.', },
    {'Bringt 3 Male des Recken zu Tierführer Dretch beim Argentumturnierplatz.|n|nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.', },
  },
  [13783] = {
    'Eine Klinge, eines Champions würdig',
    {'Ich habe gehört, dass die Champions der Allianz auf der Suche nach uralten Klingen für ihre Krieger sind. Wir können es uns nicht leisten, ihnen solch einen Vorteil zu überlassen.|n|nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, $N. Ansonsten fangt Ihr Euch Warzen ein.', },
    {'Besorgt Eschenbrand und bringt es Eressea Morgensänger beim Argentumturnierplatz.', },
  },
  [13784] = {
    'Eine würdige Waffe',
    {'Ausgerechnet jetzt so ein Unglück!|n|nIch habe meine Turnierklinge verloren. Ich habe von Barden gehört, dass früher Reisende einer einsamen Maid Winterhyazinthen vorbeibrachten und dafür im Gegenzug etwas geschenkt bekamen. Diese Hyazinthen wachsen nur auf dem Eis, das vom Eisenwalldamm kommt, an der Nordwestgrenze des Kristallsangwalds zur Eiskrone. Pflückt ein paar der Blumen und bringt sie zum Kreis aus Laternen im Drak\'Marsee in der nordöstlichen Drachenöde, nahe der Grenze zu Zul\'Drak und den Grizzlyhügeln. Bittet die einsame Maid um eine würdige Klinge.', },
    {'Bringt Eressea Morgensänger beim Argentumturnierplatz die Klinge von Drak\'Mar.', },
  },
  [13785] = {
    'Auf Winters Schneide',
    {'Verflucht soll dieser Todesritter dafür sein, mein Schwert zerbrochen zu haben!|n|nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.|n|nBringt sie zur Mitte des Winterhauchsees im Norden des Heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.|n|nZeigt, was Ihr wert seid und verdient Euch die Waffe, die sie nun schon so lange bewacht, $N.', },
    {'Eressea Morgensänger beim Argentumturnierplatz möchte, dass Ihr ihr Winterschneide bringt.', },
  },
  [13786] = {
    'Feldübungen eines Recken',
    {'Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Neben der Verfeinerung Eurer Fertigkeiten solltet Ihr auch Eure Bissigkeit im Kampf gegen Euren Gegner schärfen.|n|nReist in die Gegend südwestlich des Tals der Gefallenen Helden und nördlich von Corp\'rethar. Die Geißel lässt dort tote Helden auferstehen und wiegelt sie gegen uns auf. Besiegt diese Diener der Geißel, macht unseren Verbündeten alle Ehre und haltet Euch bereit für den Kampf.', },
    {'Kethiel Sonnenlanze beim Argentumturnierplatz möchte, dass Ihr 10 konvertierte Helden tötet.', },
  },
  [13787] = {
    'Der große Arenakampf',
    {'Der große Arenakampf ist der wichtigste Wettkampf des Turniers. Der Sieg wird nicht leicht zu erringen sein, doch ich bin überzeugt, dass wir gewinnen werden. Ihr müsst so lange mit Eurem Reittier trainieren, bis Ihr eins mit ihm seid.|n|nEs wird helfen, Euch auf die Härte des Turnierkampfes vorzubereiten.|n|nGeht zu den Reittieren außerhalb des Pavillons, nehmt Eure Lanze, steigt auf den Falkenschreiter von Silbermond, der dort steht, und fordert die Recken heraus. Sie warten im Ring der Recken der Horde gleich außerhalb unseres Zelts.', },
    {'Bringt 3 Male des Recken zu Aneera Thuron beim Argentumturnierplatz.|n|nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.', },
  },
  [13788] = {
    'Bedrohung von oben',
    {'Der Argentumkreuzzug hat die Wachen verdoppelt, seitdem Ihr den Spitzel des Kults der Verdammten entlarvt habt. Man weiß dort, dass die Kultisten nicht eher halt machen werden, bis dieser Ort hier vernichtet und verhindert wurde, dass das Turnier stattfindet.|n|nDie Kundschafter des Argentumkreuzzugs haben davon berichtet, einen Frostwyrm namens Frostschlund gesichtet zu haben, der einen Stoßtrupp des Kults anführen soll.|n|nIhr müsst sie abfangen und beseitigen, bevor sie angreifen. Laut den Berichten der Späher fliegt Frostschlund gen Südwesten im Gebiet zwischen dem Eisenwallbollwerk und Aldur\'thar herum.', },
    {'Crok Geißelbann beim Argentumturnierplatz möchte, dass Ihr Frostschlund und 3 Kultistenbombenschützen besiegt.', },
  },
  [13789] = {
    'Die Schlacht zum Gegner tragen',
    {'Das Kolosseum befindet sich im gefährlichsten Teil der Welt, $N. Blut und Qualen waren der Preis, den wir bezahlen mussten, um dieses Gebiet der Geißel abzunehmen; trotzdem schlägt unser Gegner mit einer scheinbar unerschöpflichen Armee weiterhin zurück. Und was die Sache noch schlimmer macht, ist, dass diese untote Armee von sterblichen Sympathisanten unterstützt wird - dem Kult der Verdammten.|n|nGeht nach Eiskrone und tötet jeden Kultisten, der Euch in die Quere kommt.', },
    {'Cellian Tagesanbruch beim Argentumturnierplatz möchte, dass Ihr 15 Anhänger des Kults der Verdammten tötet. Dazu zählen alle Anhänger des Kults der Verdammten im Bereich von Eiskrone.', },
  },
  [13790] = {
    'Unter Champions',
    {'Bringt 4 Male des Champions zu Luuri beim Argentumturnierplatz.|n|nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.', },
    {'Bringt 4 Male des Champions zu Luuri beim Argentumturnierplatz.|n|nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.', },
  },
  [13791] = {
    'Die Schlacht zum Gegner tragen',
    {'Es wird gut tun, bei all unseren Scheinkämpfen nicht zu vergessen, dass wir vom wahren Feind umgeben werden. Der Argentumkreuzzug möchte über einen Wettbewerb die besten Kämpfer ausfindig machen, doch das wäre schon mit denjenigen getan, die von der Schlacht zurückkehren. Lasst uns den Paladinen zeigen, dass wir willens sind, die Schlacht zum Kult der Verdammten zu tragen, selbst während wir uns auf das Turnier vorbereiten.|n|nGeht nach Eiskrone und tötet jeden Kultisten, dem Ihr begegnet. Sie sind besonders stark um Aldur\'thar und Todessprechers Wacht vertreten.', },
    {'Zor\'be der Blutvergießer beim Argentumturnierplatz möchte, dass Ihr 15 Anhänger des Kults der Verdammten tötet. Dazu zählen alle Kultisten im Bereich von Eiskrone.', },
  },
  [13793] = {
    'Unter Champions',
    {'Als Champion habt Ihr die Kunst des berittenen Kampfes zur Vollendung gebracht, habt Herausforderer aller Klassen besiegt. Ihr müsst Euch sicher sein, dass Ihr jeden besiegen könnt, dem Ihr auf dem Turnier entgegentreten werdet.|n|nIhr solltet weiterhin an Euren eigenen Fertigkeiten feilen und mehr über die Schwächen Eurer Gegner erfahren. Champions aller Städte üben im Ring der Champions in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon. Geht dorthin, nehmt Eure Lanze, wählt irgendein Euch zur Verfügung stehendes Reittier aus und fordert sie heraus.', },
    {'Bringt 4 Male des Champions zu Illyrie Nachtlauer beim Argentumturnierplatz.|n|nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.', },
  },
  [13794] = {
    'Eadric der Reine',
    {'Ich habe meine Brüder des Argentumkreuzzugs gebeten, eng mit denjenigen zusammenzuarbeiten, die zum Champion aufsteigen. Eadric der Reine, der Großchampion unserer Bruderschaft, hilft dabei, die Trainingsübungen für Champions aller Städte zu beaufsichtigen und sie bei ihren letzten Vorbereitungen für den Turnierwettkampf zu unterstützen.|n|nBitte geht nun und stellt Euch ihm vor. Ich bin mir sicher, dass er begierig darauf sein wird, Eure Bekanntschaft zu machen und Euch auf Eurem Weg zum Wettkampf mit Azeroths größten Champions zu begleiten.', },
    {'Sprecht mit Eadric dem Reinen beim Argentumturnierplatz.', },
  },
  [13795] = {
    'Der Geißelbann',
    {'Der Delegationsanführer der Ritter der Schwarzen Klinge hat darum gebeten, mit Euch zu sprechen, $C. Crok Geißelbann ist ein äußerst furchterregender Kämpfer und ich hege keine Zweifel daran, dass er viel von Euch fordern wird.|n|nDie Ritter der Schwarzen Klinge haben auf der Nordseite des Turnierplatzes ihr Lager aufgeschlagen, westlich der Zeltbehausungen der Allianzdelegationen.', },
    {'Sprecht mit Crok Geißelbann beim Argentumturnierplatz.', },
  },
  [13807] = {
    'Kennzeichnung: Turniereinladung',
    nil,
    nil,
  },
  [13809] = {
    'Bedrohung von oben',
    {'Hochlord Tirion Fordring hat die Wachen verdoppelt, seitdem Ihr den Spitzel des Kults der Verdammten entlarvt habt. Seiner Meinung nach werden sie nicht aufhören, nur weil ihr Schwarzer Ritter besiegt wurde.|n|nUnsere Späher der Himmelsklauen haben davon berichtet, einen Frostwyrm namens Frostschlund gesichtet zu haben, der einen Stoßtrupp des Kults anführen soll. Wenn wir sie nicht abfangen, werden sie das Turnier angreifen. Laut den Berichten der Späher fliegt Frostschlund gen Südwesten und patrouilliert das Gebiet zwischen dem Eisenwallbollwerk und Aldur\'thar.', },
    {'Eadric der Reine beim Argentumturnierplatz möchte, dass Ihr Frostschlund und 3 Kultistenbombenschützen besiegt.', },
  },
  [13810] = {
    'Die Schlacht zum Gegner tragen',
    {'Das Kolosseum befindet sich im gefährlichsten Teil der Welt, $N. Blut und Qualen waren der Preis, den wir bezahlen mussten, um dieses Gebiet der Geißel abzunehmen; trotzdem schlägt unser Gegner mit einer scheinbar unerschöpflichen Armee weiterhin zurück. Und was die Sache noch schlimmer macht, ist, dass diese untote Armee von sterblichen Sympathisanten unterstützt wird - dem Kult der Verdammten.|n|nGeht nach Eiskrone und tötet jeden Kultisten, der Euch in die Quere kommt.', },
    {'Cellian Tagesanbruch beim Argentumturnierplatz möchte, dass Ihr 15 Anhänger des Kults der Verdammten tötet. Dazu zählen alle Kultisten im Bereich von Eiskrone.', },
  },
  [13811] = {
    'Unter Champions',
    {'Als Champion habt Ihr die Kunst des berittenen Kampfes zur Vollendung gebracht, habt Herausforderer aller Klassen bezwungen. Ihr müsst Euch sicher sein, dass Ihr jeden besiegen könnt, dem Ihr auf dem Turnier entgegentreten werdet.|n|nIhr solltet weiterhin an Euren eigenen Fertigkeiten feilen und von Euren Gegnern lernen. Champions aller Städte üben im Ring der Champions. Nehmt Eure Lanze, steigt auf irgendeins der angebundenen Reittiere, die Euch am Silberbundpavillon zur Verfügung stehen, und fordert sie heraus.', },
    {'Bringt 4 Male des Champions zu Luuri beim Argentumturnierplatz.|n|nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.', },
  },
  [13812] = {
    'Bedrohung von oben',
    {'Der Argentumkreuzzug hat die Wachen verdoppelt, seitdem Ihr den Spitzel des Kults der Verdammten entlarvt habt. Man weiß dort, dass die Kultisten nicht eher halt machen werden, bis dieser Ort hier vernichtet und verhindert wurde, dass das Turnier stattfindet.|n|nDie Kundschafter des Argentumkreuzzugs haben davon berichtet, einen Frostwyrm namens Frostschlund gesichtet zu haben, der einen Stoßtrupp des Kults anführen soll.|n|nIhr müsst sie abfangen und beseitigen, bevor sie angreifen. Laut den Berichten der Späher fliegt Frostschlund gen Südwesten im Gebiet zwischen dem Eisenwallbollwerk und Aldur\'thar herum.', },
    {'Crok Geißelbann beim Argentumturnierplatz möchte, dass Ihr Frostschlund und 3 Kultistenbombenschützen besiegt.', },
  },
  [13813] = {
    'Die Schlacht zum Gegner tragen',
    {'Es wird gut tun, bei all unseren Scheinkämpfen nicht zu vergessen, dass wir vom wahren Feind umgeben werden. Der Argentumkreuzzug möchte über einen Wettbewerb die besten Kämpfer ausfindig machen, doch das wäre schon mit denjenigen getan, die von der Schlacht zurückkehren. Lasst uns den Paladinen zeigen, dass wir willens sind, die Schlacht zum Kult der Verdammten zu tragen, selbst während wir uns auf das Turnier vorbereiten.|n|nGeht nach Eiskrone und tötet jeden Kultisten, dem Ihr begegnet. Sie sind besonders stark um Aldur\'thar und Todessprechers Wacht vertreten.', },
    {'Zor\'be der Blutvergießer beim Argentumturnierplatz möchte, dass Ihr 15 Anhänger des Kults der Verdammten tötet. Dazu zählen alle Kultisten im Bereich von Eiskrone.', },
  },
  [13814] = {
    'Unter Champions',
    {'Als Champion habt Ihr die Kunst des berittenen Kampfes zur Vollendung gebracht, habt Herausforderer aller Klassen bezwungen. Ihr müsst Euch sicher sein, dass Ihr jeden besiegen könnt, dem Ihr auf dem Turnier entgegentreten werdet.|n|nIhr solltet weiterhin an Euren eigenen Fertigkeiten feilen und mehr über die Schwächen Eurer Gegner erfahren. Champions aller Städte üben im Ring der Champions in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon. Geht dorthin, nehmt Eure Lanze, wählt Euch irgendein zur Verfügung stehendes aus und fordert die Champions zu Übungskämpfen heraus.', },
    {'Bringt 4 Male des Champions zu Illyrie Nachtlauer beim Argentumturnierplatz.|n|nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.', },
  },
  [13816] = {
    'Heroisch: Das Himmlische Planetarium',
    {'Hört mal, $GKumpel:Mädel;! Das Schicksal von Azeroth steht hier auf dem Spiel.|n|nUnsere einzige Chance ist es, rechtzeitig das Himmlische Planetarium zu erreichen, um diesen Algalon zu finden und ihn davon abzuhalten, irgendwelche Nachrichten an seine titanischen Herren abzusetzen.|n|nFindet das Himmlische Planetarium und beschafft so viele Informationen wie möglich. Uns könnte noch immer ein wenig Zeit bleiben, uns auf Algalons Ankunft vorzubereiten.', },
    {'Ausgrabungsleiterin Loren im Archivum möchte, dass Ihr den Eingang zum Himmlischen Planetarium findet.', },
  },
  [13817] = {
    'Heroisch: Datenscheibe des Archivums',
    {'Diese Platinscheibe ist überraschend symmetrisch und frei von jedweden Kratzern und Unebenheiten. An ihrer Seite steht in auffallenden Runen eingeprägt das Wort "ARCHIVUM".|n|nIn Ulduar muss es eine Vorrichtung geben, mit welcher sich die Informationen auf der Scheibe lesen lassen.', },
    {'Bringt die Datenscheibe des Archivums zur Archivumkonsole in Ulduar.', },
  },
  [13818] = {
    'Heroisch: Algalon',
    {'Ihr habt es wirklich geschafft, $N. Bringt die Siegel zur Archivumkonsole und seht zu, ob Ihr Zugang zum Himmlischen Planetarium erhaltet.|n|nIhr beeilt Euch besser, $GKumpel:Mädchen;. Die Zeit drängt.', },
    {'Bringt die Siegel der Wächter zur Archivumkonsole in Ulduar.', },
  },
  [13819] = {
    'Heroisch: Ende gut, alles gut',
    {'Wir sollten uns jetzt besser beeilen, $N. Wir müssen den Antwortcode von Dalaran aus übermitteln.|n|nBringt ihn zu Rhonin. Ich treffe Euch dort.', },
    {'Überbringt Rhonin in Dalaran den Antwortcode Alpha.', },
  },
  [13820] = {
    'Die Gebrüder Sprengbolz',
    {'Der Hochlord hat mich damit beauftragt, das Kolosseum so schnell wie möglich fertig zu stellen. Wir haben unsere Bauarbeiter an das Projekt gesetzt, aber wir mussten sehr schnell feststellen, dass wir Hilfe bei der Beschaffung von Materialien brauchten. Ich habe ein paar Goblins angeheuert, Stumpi Sprengbolz und seinen Bruder Stümpi.|n|nSie beaufsichtigen die Arbeiten am südöstlichen Ende des Turniergeländes. Sprecht mit Stumpi und findet heraus, ob er und sein Bruder noch weitere Hilfe dabei brauchen, das benötigte Baumaterial zu beschaffen.', },
    {'Sprecht mit Stumpi Sprengbolz am Argentumturnierplatz.', },
  },
  [13821] = {
    'Heroisch: Freyas Siegel',
    {'Ich fürchte, Freyas Siegel zu erlangen, wird eine der schwierigeren Aufgaben sein.|n|nLaut dem Archivum ist die Essenz des Siegels mit ihren drei Dienern verbunden, den Ältesten Hellblatt, Eisenast und Steinrinde. Sollte einer der Ältesten zu Schaden kommen, ist die Unversehrtheit des Siegels gefährdet.|n|nDie Ältesten zu verschonen bedeutet jedoch, dass Freya mehr Macht haben wird, wenn Ihr Euch ihr stellen werdet.|n|nWas soll ich sagen, $N, das ist eine ganz schöne Zwickmühle, in der wir da stecken.', },
    {'Ausgrabungsleiterin Loren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Freyas Siegel gelangt.|n|nUm mehr darüber herauszufinden, wie Ihr Freyas Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.', },
  },
  [13822] = {
    'Heroisch: Hodirs Siegel',
    {'Es wird nicht einfach sein, Hodirs Siegel zu beschaffen. Ihr müsst nämlich nicht nur Hodir selbst vernichten, sondern es auch noch tun, bevor er die Truhe zerstört, in der es sich befindet!|n|nSchaut Euch die Archivumkonsole an, falls Ihr weitere Informationen benötigt. Das Ding umfasst mehr Wissen als alle Bibliotheken der Welt zusammen!', },
    {'Ausgrabungsleiterin Loren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Hodirs Siegel gelangt.|n|nUm mehr darüber herauszufinden, wie Ihr Hodirs Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.', },
  },
  [13823] = {
    'Heroisch: Thorims Siegel',
    {'Thorim ist nicht er selbst, $N. Er ist das Opfer einer dunklen Macht geworden, die ihn nun steuert.|n|nDas Opfer von etwas Bösem, das ihm die Illusion vorspielt, seine verstorbene Frau Sif zu sein.|n|nIhr dürft nicht zulassen, dass der Zauber dieses Betrügers ihn überwältigt. Denn sollte es so kommen, wird das Wissen um die Lage des Siegels für immer verloren sein!|n|nIhr müsst ihn zur Vernunft bringen und zwar schnell.|n|nWie immer wird Euch die Archivumkonsole mit allen schmutzigen Details versorgen... selbst mit denen, die Euch nicht gefallen.', },
    {'Ausgrabungsleiterin Loren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Thorims Siegel gelangt.|n|nUm mehr darüber herauszufinden, wie Ihr Thorims Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.', },
  },
  [13824] = {
    'Heroisch: Mimirons Siegel',
    {'Mimiron ist ein ganz Schlauer. Sein gesamter Sitz ist mit einer Art Selbstzerstörungsmechanismus ausgestattet.|n|nUnglücklicherweise wird es ein Wettlauf gegen die Zeit werden, um sein Siegel zu bekommen. Befragt die Archivumkonsole, um Näheres darüber zu erfahren, falls nötig.', },
    {'Ausgrabungsleiter Doren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Mimirons Siegel gelangt.|n|nUm mehr darüber herauszufinden, wie Ihr Mimirons Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.', },
  },
  [13825] = {
    'Muschelette Surprise',
    nil,
    nil,
  },
  [13826] = {
    'Nat Pagle, Extremangler',
    nil,
    nil,
  },
  [13828] = {
    'Den Nahkampf beherrschen',
    {'Der Mittelpunkt des Turnierwettkampfes ist der berittene Nahkampf. Nehmt diese Lanze und steigt auf das Streitross der Quel\'dorei, das gleich außerhalb des Pavillons abgestellt ist.|n|nSprecht mit Jeran Waldesruh, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Jeran wird Euch beibringen, wie man sich im Nahkampf verteidigen kann.', },
    {'Nehmt Eure Lanze und steigt auf das abgestellte Streitross der Quel\'dorei außerhalb des Pavillons. Sprecht mit Jeran Waldesruh und wendet fünfmal die Fähigkeit \'Zustoßen\' gegen ein Nahkampfziel an. Kehrt anschließend zu Arkanist Taelis beim Argentumturnierplatz zurück.', },
  },
  [13829] = {
    'Den Nahkampf beherrschen',
    {'Der Mittelpunkt des Turnierwettkampfes ist der berittene Nahkampf. Nehmt diese Lanze und steigt auf den Falkenschreiter der Sonnenhäscher, der gleich außerhalb des Pavillons abgestellt ist.|n|nSprecht mit Jeran Waldesruh, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Jeran wird Euch beibringen, wie man sich im Nahkampf verteidigen kann.', },
    {'Nehmt Eure Lanze und steigt auf den abgestellten Falkenschreiter der Sonnenhäscher außerhalb des Pavillons. Sprecht mit Jeran Waldesruh und wendet fünfmal die Fähigkeit \'Zustoßen\' auf ein Nahkampfziel an. Kehrt anschließend zu Magister Edien Sonnental beim Argentumturnierplatz zurück.', },
  },
  [13830] = {
    'Der Geisterfisch',
    {'Jeder Angler in Nordend, der sein Geld wert ist, weiß über den Pygmäenschiffshalter Bescheid. Er ist nicht essbar, manchmal jedoch für Alchemisten nützlich.|n|nEs gibt jedoch einen Fisch, einen etwas verstohleneren, der sich zwischen den Schiffshaltern im Flussnabel im Sholazarbecken versteckt: der Phantomgeisterfisch. Außerhalb des Wassers werden sie zunehmend lichtdurchlässig, bis sie schließlich ganz verschwinden. Einige nehmen an, dass sie nach Sholazar zurückkehren, andere wiederum sind etwas... abergläubischer.|n|nIch möchte, dass Ihr diesen Fisch fangt und um jeden Preis hinter sein Geheimnis kommt!', },
    {'Marcia Balzer in Dalaran möchte, dass Ihr hinter das Geheimnis des Phantomgeisterfischs kommt.', },
  },
  [13832] = {
    'Perle der Kanalisation',
    {'Schwer zu glauben, dass die meisten Leute, wenn sie zum Angeln in die Kanalisation von Dalaran gehen, nach Riesenratten und mutierten Fischen suchen. Besonders dann, wenn im Wasser Unmengen unbezahlbarer Juwelen zu finden sind - von gebrochenen Herzen, Dieben und achtlosen Trunkenbolden weggeworfen.|n|nDer Trick bei der Sache ist, Euren Haken am Boden entlang zu ziehen, und wenn Ihr etwas gefunden habt, beim Hochziehen nicht zu viel Kraft zu verwenden. Versucht es einmal, $N. Ich wäre dazu bereit, was auch immer Ihr findet gegen ein paar meiner eigenen Schmuckstücke einzutauschen.', },
    {'Marcia Balzer in Dalaran möchte, dass Ihr ihr korrodierten Schmuck bringt.', },
  },
  [13833] = {
    'Blut ist dicker',
    {'Der Blutzahnfrenzy ist ein quirliger kleiner Fisch, der für ein Rezept zur Heilung von infizierten Wunden verwendet wird. Wir könnten ein paar von ihnen gebrauchen, wenn Ihr helfen wollt.|n|nWie der Name schon sagt, trinken sie gerne Blut. Die einzige mir bekannte Art und Weise, die kleinen Teufel zu fangen, ist, Blut ins Wasser zu schütten und dann darin zu angeln.|n|nBeschmiert Euch also mit Blut... Tötet dazu einfach eine der Bestien in der Boreanischen Tundra und springt anschließend ins Wasser. Ihr werdet im Nu den perfekten Köder haben.', },
    {'Marcia Balzer in Dalaran möchte, dass Ihr ihr 5 Blutzahnfrenzys bringt.', },
  },
  [13834] = {
    'Gefährlich köstlich',
    {'Die besten Angelplätze sind oft die gefährlichsten. Für diejenigen, die dreist genug sind, bietet sich Tausendwinter an - dort sind großzügige Fänge zu machen.|n|nGenau genommen ist es der einzige Ort, wo man den sagenhaften Schreckensfisch fangen kann - ein Fisch, tödlich und köstlich zugleich. Bringt mir ein paar und wir können weiterreden.', },
    {'Marcia Balzer in Dalaran möchte, dass Ihr ihr 10 Schreckensfische bringt.', },
  },
  [13835] = {
    'Den Schildbrecherangriff beherrschen',
    {'Ihr werdet lernen müssen, wie man die Verteidigung Eures Gegners durchbrechen kann, um im berittenen Kampf erfolgreich zu sein. Nehmt diese Lanze und steigt auf das angebundene Streitross der Quel\'dorei gleich außerhalb des Pavillons.|n|nSprecht mit Valis Windhetzer, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Valis wird Euch die Grundlagen des Schildbrecherangriffs beibringen und wie man mit ihm ein Distanzziel verwundbar macht.', },
    {'Nehmt Eure Lanze und steigt auf das abgestellte Streitross der Quel\'dorei außerhalb des Pavillons. Sprecht mit Valis Windhetzer und wendet die Fähigkeit "Schildbrecher" gegen 2 ungeschützte Distanzziele an. Kehrt anschließend zu Späherin Shalyndria beim Argentumturnierplatz zurück.', },
  },
  [13836] = {
    'Arm dran, Arm ab!',
    {'Ich habe von einem tragischen Zwischenfall im Gefängnis von Dalaran gehört; ein besonders brutaler Insasse hat einer Wache einen Arm abgerissen und ihn ins Wasser geworfen. Die Leute von der "Ersten Hilfe"-Station haben versprochen, dass sie den Arm wieder annähen können, falls wir ihn zurückbringen.|n|nIhr angelt einfach lange genug im Wasser vor der Violetten Festung, und ich verwette meine Lieblingsangelrute darauf, dass der Arm auftaucht. Findet ihn und bringt ihn zu Olisarra der Gütigen hier in Dalaran. Sie wird wissen, was zu tun ist.', },
    {'Olisarra die Gütige in Dalaran möchte, dass Ihr ihr den abgetrennten Arm bringt.', },
  },
  [13837] = {
    'Den Ansturmangriff beherrschen',
    {'Euer stärkster Angriff im berittenen Kampf ist zweifellos \'Sturmangriff\'. Nehmt diese Lanze und steigt auf das Streitross der Quel\'dorei, das gleich außerhalb des Pavillons abgestellt ist.|n|nSprecht mit Rugan Stahlbauch, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Rugan wird Euch sagen, wie diese mächtige Fähigkeit zu verwenden ist und Euch ein paar grundlegende Strategien beibringen.', },
    {'Nehmt Eure Lanze und steigt auf das abgestellte Streitross der Quel\'dorei außerhalb des Pavillons. Sprecht mit Rugan Stahlbauch und wendet die Fähigkeit \'Sturmangriff\' gegen 2 ungeschützte Sturmangriffsziele an. Kehrt anschließend zu Avareth Flinkstoß beim Argentumturnierplatz zurück.', },
  },
  [13838] = {
    'Den Schildbrecherangriff beherrschen',
    {'Ihr werdet lernen müssen, wie man durch die Verteidigung Eures Gegners brechen kann, um im berittenen Kampf erfolgreich zu sein. Nehmt diese Lanze und steigt auf den abgestellten Falkenschreiter der Sonnenhäscher gleich außerhalb des Pavillons.|n|nSprecht mit Valis Windhetzer, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Valis wird Euch die Grundlagen des Schildbrecherangriffs beibringen und wie man mit ihm ein Distanzziel verwundbar macht.', },
    {'Nehmt Eure Lanze und steigt auf den abgestellten Falkenschreiter der Sonnenhäscher. Sprecht mit Valis Windhetzer und wendet die Fähigkeit \'Schildbrecher\' gegen 2 ungeschützte Distanzziele an. Kehrt anschließend zu Galathia Morgenglanz beim Argentumturnierplatz zurück.', },
  },
  [13839] = {
    'Den Ansturmangriff beherrschen',
    {'Euer stärkster Angriff im berittenen Kampf ist zweifellos \'Sturmangriff\'. Nehmt diese Lanze und steigt auf das Streitross der Quel\'dorei, das gleich außerhalb des Pavillons abgestellt ist.|n|nSprecht mit Rugan Stahlbauch, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Rugan wird Euch sagen, wie diese mächtige Fähigkeit zu verwenden ist, und Euch ein paar grundlegende Strategien beibringen.', },
    {'Nehmt Eure Lanze und steigt auf den angebundenen Falkenschreiter der Sonnenhäscher außerhalb des Pavillons. Sprecht mit Rugan Stahlbauch und wendet die Fähigkeit \'Sturmangriff\' gegen 2 ungeschützte Sturmangriffsziele an. Kehrt anschließend zu Amariel Sonnenschwur beim Argentumturnierplatz zurück.', },
  },
  [13843] = {
    'Das Konstruktionsset: Schrottbot',
    {'Ihr durchsucht die Datenbanken der Prototypenkonsole und findet dabei ein Schema für ein Schrottbotkonstruktionsset. Mit Eurer Ingenieursfertigkeit könntet Ihr lernen, Konstruktionssets wie dieses selbst herzustellen.', },
    {'Benutzt die Prototypenkonsole in der Bibliothek des Erfinders.', },
  },
  [13845] = {
    'Versiegelte Giftphiole',
    {'Diese Giftphiole sieht besonders gefährlich aus. Womöglich könnte jemand in Dalaran daran interessiert sein.', },
    {'Bringt die versiegelte Giftphiole zu Alchemist Cinesra in die Kanalisation von Dalaran.', },
  },
  [13846] = {
    'Einen Beitrag leisten',
    {'Die besten der Champions kommen jeden Tag zur Kapelle, um der Argentumbeichtpatin zuzuhören.|n|nIhr solltet sehen, wie sehr sie von ihr inspiriert werden, $N. Sie ziehen nicht nur für den Argentumkreuzzug in den Kampf, sondern geben auch noch sehr viel Geld in den Klingenbeutel, wenn ich ihn herumtrage.|n|nWollt Ihr womöglich auch einen Beitrag leisten?', },
    {'Sprecht mit Knappe Artie, um einen Beitrag von 10 Gold an den Argentumkreuzzug zu leisten.', },
  },
  [13847] = {
    'Vor den Toren des Feindes',
    {'Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.|n|nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp\'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.|n|nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, $N, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.', },
    {'Hauptmann Joseph Holley beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.', },
  },
  [13850] = {
    'Gifttoleranz',
    {'Ihr wollt eine Gifthaut reiten? Dann hab\' ich schlechte Neuigkeiten für Euch.|n|nDie Gifthautravasaurier, die bestehen aus nichts als Gift: giftiges Blut, giftiger Speichel, giftige Haut. Ihr steigt auf einen drauf und fallt nach ein paar Stunden tot runter.|n|nIhr müsstet zuerst gegen ihre Gifte resistent werden, bevor ich Euch einen verkaufe, und das dauert ganz schön lange... Ihr müsstet mit ihrem giftigem Blut bespritzt werden, wenn Ihr sie bekämpft. Und zwar sehr oft. Wenn Ihr wirklich daran interessiert seid: Die Gifthäute bevorzugen die nördliche Gegend der Marschen nordwestlich von hier.', },
    {'Mor\'vek im Krater von Un\'Goro behauptet, dass wenn man 20-mal von dem Blut eines Gifthautravasauriers vergiftet wurde, auf einem reiten könnte, ohne zu sterben. Greift die Saurier an, um vielleicht vergiftet zu werden.', },
  },
  [13851] = {
    'Vor den Toren des Feindes',
    {'Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.|n|nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp\'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.|n|nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, $N, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.', },
    {'Clara Torkelbräu beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.', },
  },
