  [13861] = {
    'Schlacht vor der Zitadelle',
    {'Während einige von uns auf dem Turnier alles geben, bereiten unsere Brüder den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.|n|nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp\'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross im Lager und vernichtet die Kommandanten des Lichkönigs.|n|nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, $N, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.', },
    {'Eadric der Reine beim Argentumturnierplatz möchte, dass Ihr 3 Kommandanten der Knochenwache tötet.', },
  },
  [13862] = {
    'Schlacht vor der Zitadelle',
    {'Während einige von uns auf dem Turnier alles geben, bereiten unsere Brüder den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.|n|nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp\'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross im Lager und vernichtet die Kommandanten des Lichkönigs.|n|nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, $N, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.', },
