  [24848] = {
    'Feuerwerk bei der Güldenen Rose',
    {'Kind, hier geht es um mehr als bloß Parfüm. In dieser Kiste waren ein paar Raketen und sie sind mit irgend einer chemischen Ladung gefüllt. Hier kann ich sie nicht analysieren, aber ich werde Euch den Weg ins Labor ersparen.|n|nIhr müsst nur den Typ aufspüren, der sie hergestellt hat. Ich kenne das Brandzeichen. Flenni Rostrakete.|n|nIch habe einen Tipp von einer vertrauenswürdigen Quelle erhalten, dass er sich hier in Sturmwind aufhält und es sich in der Güldenen Rose gut gehen lässt. Er soll sogar eine Dame bei sich haben, mit Namen Marion Sutton. Macht Euch auf zur Güldenen Rose und findet heraus, was sie weiß.', },
    {'Redet mit Marion Sutton in der Güldenen Rose im Handelsdistrikt von Sturmwind.', },
  },
  [24849] = {
    'Auf den Fersen',
    {'Ich fange am besten von vorne an. Es war Liebe auf den ersten Blick, $N. Da war einfach etwas Besonderes an diesem Goblin, schon als meine Augen ihn das erste Mal erblickten.|n|nNachdem wir eine wundervolle Woche miteinander verbracht hatten, meinte Flenni, dass er an eine Menge Geld gekommen sei und mich auf eine Reise in die Südlichen Meere mitnehmen wolle! Könnt Ihr Euch das vorstellen?|n|nWie auch immer, er meinte, ich solle meine Sachen packen, während er noch zur Bank, zum Auktionshaus und zum Barbier müsse. Aber er ist nie wieder aufgetaucht! Ich fange langsam an zu glauben, dass er einfach nur ein großer Lügner ist!', },
    {'Sucht Flenni Rostrakete im Zählhaus von Sturmwind, im Auktionshaus und beim Barbier von Sturmwind.', },
  },
  [24850] = {
    'Flennis Flamme',
    {'$GJunge:Mädel;, hier geht es um mehr als bloß Parfüm. In dieser Kiste waren ein paar Raketen und sie sind mit irgend einer chemischen Ladung gefüllt. Hier kann ich sie nicht analysieren, aber ich werde Euch den Weg ins Labor ersparen.|n|nIhr müsst nur den Typ aufspüren, der sie hergestellt hat. Ich kenne das Zeichen des Herstellers. Flenni Rostrakete.|n|nIch habe gehört, dass er es sich hier in Orgrimmar gut gehen lässt. Und es kommt noch besser, er soll sogar eine Freundin haben... eine Orc-Dame mit Namen Roka. Sie will sich mit ihm bei Gotris Reiseausstattung in der Gasse treffen, bevor sie ihre Flucht antreten.', },
    {'Redet mit Roka bei Gotris Reiseausstattung in der Gasse in Orgrimmar.', },
  },
  [24851] = {
    'Auf den Fersen',
    {'Ich fange am besten von vorne an. Es war Liebe auf den ersten Blick, $N. Da war einfach etwas Besonderes an diesem Goblin, schon als meine Augen ihn das erste Mal erblickten.|n|nNachdem wir eine wundervolle Woche miteinander verbracht hatten, meinte Flenni, dass er an eine Menge Geld gekommen sei und mich auf eine Reise in die Südlichen Meere mitnehmen wolle! Könnt Ihr Euch das vorstellen?|n|nWie auch immer, er meinte, ich solle meine Sachen packen, während er noch zur Bank, zum Auktionshaus und zum Barbier müsse. Aber er ist nie wieder aufgetaucht! Ich fange langsam an zu glauben, dass er einfach nur ein großer Lügner ist!', },
    {'Sucht Flenni Rostrakete in der Bank von Orgrimmar im Tal der Stärke, dem Auktionshaus und dem Barbier von Orgrimmar.', },
  },
  [24857] = {
    'Angriff auf Camp Narache',
    {'Nachdem Ihr die Karte sorgfältig studiert habt, erkennt Ihr, dass Ihr die Pläne für eine ausgeweitete Belagerung von Camp Narache entdeckt habt, die von dem Kriegshäuptling der Borstennacken entworfen wurden.|n|nHäuptling Falkenwind kann mit dieser Information sicher einiges anfangen!', },
    {'Bringt die Angriffspläne der Borstennacken zu Häuptling Falkenwind in Camp Narache.', },
  },
  [24869] = {
    'Entprogrammieren',
    {'Wir hatten gehofft, einen Mann in den Reihen des Kults der Verdammten platzieren zu können, um einen besseren Eindruck von den Machenschaften des Lichkönigs zu bekommen, aber wir... haben die Überredungskünste von Arthas und seiner dunklen Gesandten, Lady Todeswisper, unterschätzt.|n|nUnser Mann, Darnavan, ist jetzt einer von ihnen.|n|nWenn Ihr vorhabt, Euch einen Weg durch das Oratorium vor uns zu bahnen, so haltet Eure Augen bitte nach Darnavan auf. Wenn Ihr ihn uns lebend übergeben könntet, könnten wir versuchen, die Hirnwäsche des Kults rückgängig zu machen.', },
    {'Bezwingt Lady Todeswisper, aber stellt dabei sicher, dass Darnavan überlebt.', },
  },
  [24870] = {
    'Sicherung des Bollwerks',
    {'Als wenn es hier oben nicht schon genug wie im Irrenhaus zuginge, mit einer Zwei-Fronten-Schlacht, die Geißel auf der einen und diese verfluchten Allianzhunde auf der anderen Seite!|n|nWir sind hier, um einen sicheren Landeplatz für unsere Schiffe zu sichern, aber ein gewaltiger Riese auf der anderen Seite des Bollwerks schleudert ständig Geröll auf alles, was sich nähert, und hält damit unsere kleineren Schiffe auf Abstand.|n|nIch will ehrlich sein... er ist eine Nummer zu groß für uns, aber Ihr und Eure Begleiter seht aus, als wäre das eine Kleinigkeit für Euch.', },
    {'Erledigt den verrottenden Frostriesen.', },
  },
  [24871] = {
    'Sicherung des Bollwerks',
    {'Als wenn es hier oben nicht schon genug wie im Irrenhaus zuginge, mit einer Zwei-Fronten-Schlacht, die Geißel auf der einen und diese verfluchten Hunde von der Horde auf der anderen Seite!|n|nWir sind hier, um einen sicheren Landeplatz für unsere Schiffe zu sichern, aber ein gewaltiger Riese auf der anderen Seite des Bollwerks schleudert ständig Geröll auf alles, was sich nähert, und hält damit unsere kleineren Schiffe auf Abstand.|n|nIch will ehrlich sein... er ist eine Nummer zu groß für uns, aber Ihr und Eure Begleiter seht aus, als wäre das eine Kleinigkeit für Euch.', },
    {'Erledigt den verrottenden Frostriesen.', },
  },
  [24872] = {
    'Frieden für eine geschundene Seele',
    {'Nehmt diesen Kristall des Lebens, und auch Eure Gefährten sollten einen nehmen. Er enthält mächtige Energien aus dem tiefgrünen Drachenschrein in der Drachenöde, und es war mein eigenes Geheimnis, um den dunklen Magien dieses Ortes so lange widerstehen zu können.|n|nWenn Ihr Sindragosa gegenübertretet, bekämpft sie, bis sie geschwächt ist, und dann sollten Eure Gefährten diese Kristalle benutzen, um die Essenz herauszulocken, die in ihr schläft. Wenn Ihr sie dann besiegt, solltet Ihr in der Lage sein, die Essenz aufzunehmen und zum Wyrmruhtempel in der Drachenöde zurückzubringen.', },
    {'Benutzt die Lebenskristall, um Sindragosas Essenz zu erhalten.', },
  },
  [24873] = {
    'Wandelnder Wirt',
    {'Professor Seuchenmord ist in sein fauliges Labor eingeschlossen worden, wo er immer tödlichere Kulturen der Seuche gegen uns entwickelt. Wenn wir nur einige reine Proben dieser Gifte in die Finger bekommen könnten, dann könnten unsere Forscher ein Antidot enwickeln und unzählige Leben retten.|n|nEs gibt nur einen Haken... eine nützliche Probe müsste aus zwei aktiven Stämmen bestehen, die sich in einem lebenden Wirt verbinden. Sollte Euch das... Missgeschick... widerfahren, solch ein Wirt zu werden, dann kommt bitte sofort hier her, sodass wir Euch für unsere Studien abernten können.', },
    {'Kehrt zu Alchemistin Adrianna zurück, während Ihr mit der orangenen und der grünen Seuche infiziert seid.', },
  },
  [24874] = {
    'Erhöhter Blutdruck',
    {'Diese Geißel-Blutsauger - San\'layn nennen sie sich - sind mir nicht geheuer. Wir haben einen unserer besten Männer eingesetzt, um ein Auge auf sie zu halten. Aber diesen Morgen ist er unvorsichtig geworden und hat sich erwischen lassen. Er wird gerade von der Königin persönlich verhört, und seine Schreie gellen durch die Blutroten Hallen. Bitte, rettet ihn, bevor es zu spät ist.', },
    {'Rettet den Spitzel Minchar, bevor er hingerichtet wird.', },
  },
  [24875] = {
    'Entprogrammieren',
    {'Wir hatten gehofft, einen Mann in den Reihen des Kults der Verdammten platzieren zu können, um einen besseren Eindruck von den Machenschaften des Lichkönigs zu bekommen, aber wir... haben die Überredungskünste von Arthas und seiner dunklen Gesandten, Lady Todeswisper, unterschätzt.|n|nUnser Mann, Darnavan, ist jetzt einer von ihnen.|n|nWenn Ihr vorhabt, Euch einen Weg durch das Oratorium vor uns zu bahnen, so haltet Eure Augen bitte nach Darnavan auf. Wenn Ihr ihn uns lebend übergeben könntet, könnten wir versuchen, die Hirnwäsche des Kults rückgängig zu machen.', },
    {'Bezwingt Lady Todeswisper, aber stellt dabei sicher, dass Darnavan überlebt.', },
  },
  [24876] = {
    'Sicherung des Bollwerks',
    {'Als wenn es hier oben nicht schon genug wie im Irrenhaus zuginge, mit einer Zwei-Fronten-Schlacht, die Geißel auf der einen und diese verfluchten Hunde von der Horde auf der anderen Seite!|n|nWir sind hier, um einen sicheren Landeplatz für unsere Schiffe zu sichern, aber ein gewaltiger Riese auf der anderen Seite des Bollwerks schleudert ständig Geröll auf alles, was sich nähert, und hält damit unsere kleineren Schiffe auf Abstand.|n|nIch will ehrlich sein... er ist eine Nummer zu groß für uns, aber Ihr und Eure Begleiter seht aus, als wäre das eine Kleinigkeit für Euch.', },
    {'Erledigt den verrottenden Frostriesen.', },
  },
  [24877] = {
    'Sicherung des Bollwerks',
    {'Als wenn es hier oben nicht schon genug wie im Irrenhaus zuginge, mit einer Zwei-Fronten-Schlacht, die Geißel auf der einen und diese verfluchten Allianzhunde auf der anderen Seite!|n|nWir sind hier, um einen sicheren Landeplatz für unsere Schiffe zu sichern, aber ein gewaltiger Riese auf der anderen Seite des Bollwerks schleudert ständig Geröll auf alles, was sich nähert, und hält damit unsere kleineren Schiffe auf Abstand.|n|nIch will ehrlich sein... er ist eine Nummer zu groß für uns, aber Ihr und Eure Begleiter seht aus, als wäre das eine Kleinigkeit für Euch.', },
    {'Erledigt den verrottenden Frostriesen.', },
  },
  [24878] = {
    'Wandelnder Wirt',
    {'Professor Seuchenmord ist in sein fauliges Labor eingeschlossen worden, wo er immer tödlichere Kulturen der Seuche gegen uns entwickelt. Wenn wir nur einige reine Proben dieser Gifte in die Finger bekommen könnten, dann könnten unsere Forscher ein Antidot enwickeln und unzählige Leben retten.|n|nSolltet Ihr zufällig über ein lebendiges Exemplar stolpern, so bringt es bitte sofort hierher, damit wir es analysieren können.', },
    {'Kehrt zu Alchemistin Adrianna zurück, während Ihr mit der orangenen und der grünen Seuche infiziert seid.', },
  },
  [24879] = {
    'Erhöhter Blutdruck',
    {'Diese Geißel-Blutsauger - San\'layn nennen sie sich - sind mir nicht geheuer. Wir haben einen unserer besten Männer eingesetzt, um ein Auge auf sie zu halten. Aber diesen Morgen ist er unvorsichtig geworden und hat sich erwischen lassen. Er wird gerade von der Königin persönlich verhört, und seine Schreie gellen durch die Blutroten Hallen. Bitte, rettet ihn, bevor es zu spät ist.', },
    {'Rettet den Spitzel Minchar, bevor er hingerichtet wird.', },
  },
  [24880] = {
    'Frieden für eine geschundene Seele',
    {'Nehmt diesen Kristall des Lebens, und auch Eure Gefährten sollten einen nehmen. Er enthält mächtige Energien aus dem tiefgrünen Drachenschrein in der Drachenöde, und es war mein eigenes Geheimnis, um den dunklen Magien dieses Ortes so lange widerstehen zu können.|n|nWenn Ihr Sindragosa gegenübertretet, bekämpft sie, bis sie geschwächt ist, und dann sollten Eure Gefährten diese Kristalle benutzen, um die Essenz herauszulocken, die in ihr schläft. Wenn Ihr sie dann besiegt, solltet Ihr in der Lage sein, die Essenz aufzunehmen und zum Wyrmruhtempel in der Drachenöde zurückzubringen.', },
    {'Benutzt die Lebenskristall, um Sindragosas Essenz zu erhalten.', },
  },
