  [25283] = {
    'Die Rede vorbereiten',
    {'Hochtüftler Mekkadrill hat mich gebeten, eine Rede zu schreiben, die er vor Beginn der Schlacht halten kann. Aber ich kann mich nicht mehr daran erinnern, welche Rede gut ist und welche total daneben.|n|nKönntet Ihr ein paar davon an den örtlichen gnomischen Anwohnern ausprobieren? Dieses Gerät erschafft ein Bild von Mekkadrill, das einige Zeilen aus jeder meiner Reden spricht.|n|nLasst mich wissen, welche funktioniert, ja?', },
    {'Benutzt das Gnomische Abspielgerät vor Ozzie Wechselvolt nördlich von Kharanos, Milli Federpfiff bei Stahlrosts Depot und Tog Rostspross vor der Gaststätte in Kharanos. Kehrt zu Toby Zeigrad zurück, wenn alle Reden gehalten wurden.', },
  },
  [25285] = {
    'Rein und Raus',
    {'Diese neuen Mechanopanzer müssen für den Angriff fertiggemacht werden. Bereit, eine dieser Höllenmaschinen zu testen?! Klar seid Ihr das!|n|nAls erstes müssen wir sicherstellen, dass Ihr wieder rauskommt, wenn Ihr erstmal drin seid. Wenn Ihr in der Schlacht glaubt, dass Euer Panzer gleich explodieren wird, dann raus! Ich hab schon viele Gnome gesehen, die bis zum bitteren Ende dringeblieben sind ... der Panzer explodiert, und sie gleich mit.|n|nAlso, ich habe diesen Panzer mit einem Schleudersitz ausgestattet. Probiert ihn für mich aus, ja?', },
    {'Testet den Schleudersitz des Mechanopanzers mit Schleudersitzsystem.', },
  },
  [25286] = {
    'Wortübermittlung',
    {'Das ist es. Das ist die Rede, $N! Sie hat alles, was einen guten Auftakt zur Schlacht ausmacht... sie inspiriert, ist eloquent und spricht den einfachen Gnom direkt an. Noch nie wurde eine bessere Rede geschrieben!|n|nGebt das hier bei Hauptmann Tret Funkdüse ab und besorgt euch einen Transport zu Hochtüftler Mekkadrill!', },
    {'Gebt die Rede Hauptmann Tret Funkdüse bei Stahlrosts Depot.', },
  },
  [25287] = {
    'Wortübermittlung',
    {'In Ordnung, Soldat. Zeit, Euch zu beweisen!|n|nNehmt diese Rede und geht an Bord der Flugmaschine "Donnerschlag". Sie ist der schnellste Weg zu Hochtüftler Mekkadrill, und er wartet nur noch auf diese Rede, bevor er Operation: Gnomeregan beginnt.|n|nGeht! Jetzt!', },
    {'Benutzt die Flugmaschine "Donnerschlag" bei Stahlrosts Depot, um zu Hochtüftler Mekkadrill zu fliegen, und stellt ihm Tobys Rede zu.', },
  },
  [25289] = {
    'Ein Schritt nach vorn...',
    {'Jetzt, da das Schleudersitzsystem funktioniert, sind wir bereit, Bewegungen zu testen. Dieser Panzer hat eine Besonderheit: Automatische Ausweichmanöver!|n|nIch möchte, dass Ihr die Servomotoren am linken Bein und am rechten Bein sowie das Automatische Ausweichmanöversystem ausprobiert.|n|nEs ist ganz einfach, also sollte es nicht lange dauern.', },
    {'Testet die Manövrierbarkeit des krabbelnden Mechanopanzers.', },
  },
  [25293] = {
    'Die Vermissten',
    {'Abgesehen von den Unruhen und der Paranoia, die der Kult verbreitet, werden wir mit Vermisstmeldungen überschwemmt. Mütter, Väter, Brüder und Schwestern sind scheinbar verschwunden, aber ich habe das Gefühl, dass sie in einem der Kultistenlager außerhalb der Stadt zu finden sind. Wenn ich Euch die Namen einiger Vermisster gebe, würdet Ihr versuchen, sie in dem Kultistenlager beim Scheckeneberhof südlich von Orgrimmar zu finden? Um dort nicht aufzufallen, braucht Ihr eine Robe von einem der Weltuntergangsverkünder in der Gasse.', },
    {'Sprecht, während Ihr Eure Kultistenverkleidung tragt, mit Kultist Kagarn, Kultist Agtar, Kultistin Tokka und Kultistin Rokaga auf dem Scheckeneberhof in Durotar.', },
  },
  [25295] = {
    'Feuer drücken',
    {'Sicherheitssysteme bereit! Motorfunktion funktioniert! Jetzt müssen wir nur noch sicherstellen, dass die Geschütze feuern.|n|nDas sollte nicht schwer sein, $N. Der Mechanopanzer auf dem Hügel hinter uns ist mit harmlosen Geschossen geladen worden. Feuert einfach ein paar Schüsse auf die Ziele in der Nähe und erstattet mir dann Bericht.', },
    {'Testet die Waffensysteme des schießenden Mechanopanzers an den Zielen in der Nähe.', },
  },
  [25306] = {
    'Ihr seid jetzt in der Gnarmee!',
    {'Krieg!', },
    {'Beschreibung', },
  },
  [25393] = {
    nil,
    {'Jetzt sollte jeden Augenblick der Multiphasenangriff auf Gnomeregan beginnen, der Robogenieur Thermadraht und seine Leute ihrer gerechten Strafe zuführen wird! Zu lange schon war es Thermadraht möglich, in den Tiefen unserer Heimat zu gären, verteidigt von einer korrupten und verstrahlten Armee.|n|nDer Angriff beginnt in einem Augenblick! Seid bereit, Rekrut, dieser Kampf wird nichts für zaghafte Gemüter.', },
    {'Helft König Mekkadrill beim Angriff auf Gnomeregan.', },
  },
  [25444] = {
    'Die perfekten Spione',
    {'Es wär dumm, hia blind zu arbeiten, also mach\' ich \'n paar winzige Spione, die für Vol\'jin Informationen sammeln soll\'n. Er muss wissen, was drüben auf den Inseln passiat.|n|nIch könnt\' die Hilfe brauch\'n, wenn Euch danach is. Ich sag\' Euch, was zu tun is. East müsst Iah die Frösche fang\'n. Sie bleim gean im Schatten dea Palmen um Sen\'jin rum.|n|nWenn Iah die Frösche habt, bringtse hia rüber zu mei\'m Totem des Wachens un\' stimmt se auf meine Sicht ab.', },
    {'Fangt 5 Frösche aus Sen\'jin und stimmt sie bei Vaniras Totem des Wachens auf ihre Sicht ab.', },
  },
  [25445] = {
    'Zalazanes Sturz',
    {'Die Zeit zum Kämpfen ist jetzt! Schon bald brechen wir auf zu den Inseln, halt dich also bereit.|n|nZalazane hat nicht mehr viel Zeit.', },
    {'Helft Vol\'jin die Echoinseln zurückzuerobern und Zalazane zu töten.', },
  },
  [25446] = {
    'Frösche frei!',
    {'Nu, wo die Frösche startklar sin\', brauch\' ich Eure Hilfe, um sie rüba auf die Inseln zu schick\'n.|n|nIm Osten von Sen\'jin is Tiaführer Marnlek. Eah füaht die Fledamäuse für Vol\'jins Späher und kann Euch \'ne Fledermaus leih\'n, um raus zu den Inseln zu kommen.|n|nNehmt den Sack Frösche hia mit. Ich hab\' die Geista um Hilfe gebeten. Sie ham Rauch geschickt, um Euch zu zeig\'n, wo ich die Augen am meisten brauch. Wenn Iah auf\'er Fledermaus sitzt, greift in\'n Sack un\' werft die Frösche in\'n weißen Rauch.', },
    {'Benutzt, während Ihr Euch auf dem Rücken einer Fledermaus befindet, den Sack Frösche, um 12 abgestimmte Frösche bei den Markierungen auf den Echoinseln zu platzieren.', },
  },
  [25461] = {
    'Freiwillige Trolle vor!',
    {'Vol\'jin hat mir seine Kriegstrommeln gegeben und mia die Verantwortung für die Ausbildung von den neuen Rekruten hia übageben. Das Dumme is nur, dass wia keine neuen Rekruten ham.|n|nWenn ich Euch diese Trommel leih\'n wüade, wüadet Iah füa Vol\'jin nach Klingenhügel gehn un da den Kriegsruf vabreiten? Wenn Iah auch nua n paar Trolle dazu inspirian könntet, sich anzuschließn, wüade das schon nen Untaschied machen. Wenn Iah sie übazeugt habt, sich freiwillig zu meld\'n, bringt sie zu mia zum Ausbilden zurück. Geht rüba zu Tiaführer Marnlek im Süd\'n. Eah kann Euch eine Fledamaus für den Flug nach Klingenhügel leih\'n.', },
    {'Benutzt Vol\'jins Kriegstrommeln, um 5 Trollbürger in Klingenhügel zu rekrutieren.|n|nIhr könnt mit Tierführer Marnlek sprechen, um eine Fledermaus nach Klingenhügel zu bekommen.', },
  },
  [25470] = {
    'Herrin der Tiger',
    {'Erinnat Iah Euch an die Frösche, die Iah zu mein\'n Augen un\' Ohren gemacht habt? Tja, die ham was Intressantes gefund\'n.|n|nAuf \'ner Insel im Südosten ham sie \'nen Tiger entdeckt, den soga die andern Katzen fürcht\'n. Diesa Tiger, so was hab\'ich noch nie geseh\'n.|n|nDea jagt mit\'m Instinkt von \'ner Katze, aber dem Vastand von \'ner Person. Könnte \'n mächtiger Geist sein, und \'n starka Vabündeta.|n|nIch ruf den Geist vom Tiger auf Euch runter. Benutzt seine Talente, um die Katze zu find\'n un\' rauszufordern. Seht zu, dass Iah ihre Hilfe in unserm Kampf um die Inseln gewinnt.', },
    {'Lockt die Tigermatriarchin aus ihrem Versteck, während Ihr vom Geist des Tigers erfüllt seid, und benutzt Eure neuen Fähigkeiten, um sie im Kampf zu besiegen.', },
  },
  [25480] = {
    'Tanz der Geister',
    {'Die Zeit ist reif, über den Angriff nachzudenken. Champion Uru\'zin sagt, seine Männer wären bereit. Ihr und Vanira habt gute Arbeit geleistet, indem ihr Informationen gesammelt und uns neue Verbündete gefunden habt.|n|nJetzt lesen wir die Omen. Wir müssen rausfinden, wann wir den Angriff starten können.|n|nFindet Hexendoktor Hez\'tok beim Kreis der Ritualtänzer. Er wird das Ritual anfangen, sobald Ihr bereit seid.', },
    {'Sprecht beim Kreis der Ritualtänzer außerhalb von Sen\'jin mit Hexendoktor Hez\'tok, wenn Ihr bereit seid, die Omen zu konsultieren.', },
  },
  [25495] = {
    'Vorbereitung auf die Schlacht',
    {'Vol\'jin macht seine Ausrüstung klar und die Kriega bereit. Er hat mich gebet\'n, Euch zu sag\'n, dass Iah ihn und Vanira auf dea Insel im Osten treffen sollt.|n|nVon da werd\'n er un die Krieger Zalazane angreif\'n. Die Vorfahr\'n soll\'n Euch beisteh\'n, $N. Ohne Euch wär\' diese Sache nur\'n Schatten von dem, was sie is. Redet mit Tierführer Marnlek im Süden, un\' er wird Euch \'ne Fledermaus geben, die Euch zum Sammelpunkt fliegt.', },
    {'Sprecht mit Tierführer Marnlek, um einen Flug zum Sammelpunkt zu bekommen. Trefft Euch auf der Insel östlich des Kriegslagers mit Vol\'jin.', },
  },
  [25500] = {
    'Wortübermittlung',
    {'Da haben wir sie. Das ist die Rede, $N!|n|nSie hat alles, was ein guter Schlachtauftakt braucht: sie ist inspirierend, benutzt eloquente Sprache und spricht den einfachen Gnom direkt an. Nie wurde eine bessere Rede geschrieben!|n|nGebt sie Hauptmann Tret Funkdüse und fragt ihn, ob er noch etwas von Euch braucht.', },
    {'Gebt die Rede Hauptmann Tret Funkdüse bei Stahlrosts Depot.', },
  },
  [26012] = {
    'Ärger im Wyrmruhtempel',
    {'Mein alter Freund Krasus berichtet von grässlichen Vorkommnissen im Wyrmruhtempel in der Drachenöde. Sein Schreiben war kurz, doch es scheint, dass eine Art Angriff auf das Rubinsanktum unterhalb des Tempels stattgefunden hat.|n|nDringende Angelegenheiten hier in Dalaran halten mich davon ab, mich persönlich um die Sache zu kümmern, doch sind mir Berichte Eurer Heldentaten in der Zitadelle des Lichkönigs zu Ohren gekommen und Ihr seid zweifellos dieser Aufgabe gewachsen - vielleicht könntet Ihr an meiner statt Krasus behilflich sein?', },
    {'Sprecht mit Krasus im Wyrmruhtempel in der Drachenöde.', },
  },
  [26013] = {
    'Angriff auf das Sanktum',
    {'$R, etwas Schreckliches ist im Rubinsanktum unterhalb des Tempels geschehen.|n|nDer Eingang zum Sanktum liegt in Ruinen und seine Wächter sind auf grausame Art und Weise erschlagen worden. Wir haben Kundschafter ausgesandt, um der Sache auf den Grund zu gehen, aber sie sind nicht zurückgekommen. Nun befürchte ich das Schlimmste.|n|nBetretet das Rubinsanktum und bringt in Erfahrung, was in der Heimat meines Schwarmes passiert ist. Sobald wir mehr Informationen haben, können wir unsere nächsten Schritte entsprechend planen.', },
    {'Untersucht das Rubinsanktum unterhalb des Wyrmruhtempels.', },
  },
  [26034] = {
    'Der Zwielichtzerstörer',
    {'Dies war kein leichtfertiger Angriff, sondern vielmehr ein sorgsam inszenierter Schlag gegen das Herz des roten Drachenschwarms.|n|nZarithrian, der sich auf dem Felsvorsprung dort drüben befindet, überwacht den Angriff, doch ist der wahre Anführer ein dreister und mächtiger Zwielichtdrache namens Halion. Seit Dargonax ist kein ausgewachsenes Exemplar der Brut aus Sinestras verdorbenen Experimenten mehr gesichtet worden.|n|nTötet ihn, $N. Sobald es Euch gelungen ist, diese Invasion zurückzudrängen, meldet Ihr Euch bei Krasus und berichtet ihm, was Ihr hier gesehen habt.', },
    {'Besiegt Halion und drängt die Invasion des Rubinsanktums zurück.', },
  },
}
